INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87991, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b191c03-bb58-4047-9fd1-b5a24eda03ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87991, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "着数是下棋时走的步子，或者做事的办法。", "primary_collocate": null, "pronunciation": "zhāo shù", "ipa": "tʂɑʊ˥ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "这步棋的着数很妙，对方没想到。", "target_word": "着数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想了很久，才决定用这个着数。", "target_word": "着数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们几个下棋的着数。", "target_word": "着数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下棋时这个着数太险了，你会输的。", "target_word": "着数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的着数很多，总有办法解决问题。", "target_word": "着数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这盘棋，他每个着数都想得很清楚。", "target_word": "着数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有什么着数能让他同意？", "target_word": "着数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷看我走错了棋，说这个着数不好。", "target_word": "着数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做生意要有好着数，不能乱来。", "target_word": "着数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用了一个新着数，终于说服了妈妈。", "target_word": "着数", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "下棋时走的步子，引申指做事的办法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4e08ad9-0b97-4081-94ef-5f5d51ef7e8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87991, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "着数", "is_correct": true, "explanation": "正确。“着数”指下棋的步子，“这步棋的着数很妙”符合语境，对方没想到。"}, {"text": "棋盘", "is_correct": false, "explanation": "语义：棋盘是放棋子的器具，本身不会“妙”，与“这步棋”的走法不符。"}, {"text": "棋钟", "is_correct": false, "explanation": "语义：棋钟是计时的器具，不能用来形容“这步棋”的妙处。"}, {"text": "棋盒", "is_correct": false, "explanation": "语义：棋盒是装棋子的盒子，“这步棋的棋盒很妙”说不通。"}], "explanations": {"着数": "正确。“着数”指下棋的步子，“这步棋的着数很妙”符合语境，对方没想到。", "棋盘": "语义：棋盘是放棋子的器具，本身不会“妙”，与“这步棋”的走法不符。", "棋钟": "语义：棋钟是计时的器具，不能用来形容“这步棋”的妙处。", "棋盒": "语义：棋盒是装棋子的盒子，“这步棋的棋盒很妙”说不通。"}, "sentence_index": 0, "correct_answer": "着数"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用了一把着数，终于说服了妈妈。", "explanation": "这里应该用〈个〉。“把”用于有柄的东西，不能修饰办法，“着数”指办法时要用〈个〉。"}, {"text": "这碗面的着数很香。", "explanation": "这里应该用〈味道〉。“着数”指下棋的步子或做事的办法，不指食物的味道，应说〈味道〉。"}, {"text": "他在着数里找到了钥匙。", "explanation": "“着数”是抽象的步子或办法，不是可以容纳东西的地点，不能说“在着数里”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b191c03-bb58-4047-9fd1-b5a24eda03ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87991, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "着数", "is_correct": true, "explanation": "正确。“着数”指办法或手段，“你有什么着数能让他同意”符合语境。"}, {"text": "棋谱", "is_correct": false, "explanation": "语义：棋谱是记录棋步的书，不能用来让人同意。"}, {"text": "棋局", "is_correct": false, "explanation": "语义：棋局指一盘棋的局面，不能用来说服别人。"}, {"text": "棋盘", "is_correct": false, "explanation": "语义：棋盘是摆棋的平面，不能用来让人同意，“你有什么棋盘能让他同意”说不通。"}], "explanations": {"着数": "正确。“着数”指办法或手段，“你有什么着数能让他同意”符合语境。", "棋谱": "语义：棋谱是记录棋步的书，不能用来让人同意。", "棋局": "语义：棋局指一盘棋的局面，不能用来说服别人。", "棋盘": "语义：棋盘是摆棋的平面，不能用来让人同意，“你有什么棋盘能让他同意”说不通。"}, "sentence_index": 6, "correct_answer": "着数"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的着数很好看。", "explanation": "这里应该用〈款式〉。“着数”指下棋的步子或做事的办法，不指衣服的样式，应说〈款式〉。"}, {"text": "这座楼的着数很独特。", "explanation": "这里应该用〈设计〉。“着数”不指建筑的造型或设计，应说〈设计〉。"}, {"text": "他走路的着数很稳。", "explanation": "这里应该用〈步伐〉。“着数”指棋步或办法，不能用来形容走路的步子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b191c03-bb58-4047-9fd1-b5a24eda03ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87991, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只着数很巧妙，他一下子就明白了。", "corrected_sentence": "这个着数很巧妙，他一下子就明白了。", "error_description": "错误形式：“这只着数”；正确形式：“这个着数”。“着数”指办法时用量词〈个〉，〈只〉多用于动物或成对的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b191c03-bb58-4047-9fd1-b5a24eda03ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87991, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他想出了一根好着数。", "corrected_sentence": "他想出了一个好着数。", "error_description": "错误形式：“一根好着数”；正确形式：“一个好着数”。“根”多用于细长的东西，“着数”指办法时应用量词〈个〉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b191c03-bb58-4047-9fd1-b5a24eda03ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
