INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87992, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b191c03-bb58-4047-9fd1-b5a24eda03ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87992, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "下棋时的步数，也比喻办法、手段。", "primary_collocate": null, "pronunciation": "zhāo shù", "ipa": "tʂɑʊ˥ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "他只用了三个着数，就吃掉了我的车。", "target_word": "着数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下棋时，每个着数都要小心。", "target_word": "着数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他最后的着数让我很吃惊。", "target_word": "着数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个着数我以前没见过。", "target_word": "着数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛前，教练想出了一个新着数。", "target_word": "着数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想让孩子早睡，妈妈有自己的着数。", "target_word": "着数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的着数很厉害，一下子就把问题解决了。", "target_word": "着数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几个着数都没用，我们再想想别的。", "target_word": "着数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "棋手一看这个着数，就知道会输。", "target_word": "着数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用了一个小着数，让大家都笑了。", "target_word": "着数", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "下棋的步数，比喻办法、手段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4e08ad9-0b97-4081-94ef-5f5d51ef7e8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87992, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "着数", "is_correct": true, "explanation": "正确。“着数”指下棋的步数，“他只用了三个着数，就吃掉了我的车”符合语境。"}, {"text": "棋钟", "is_correct": false, "explanation": "语义：棋钟是计时器，不能用来“吃掉”棋子，与“吃掉了我的车”冲突。"}, {"text": "棋盘", "is_correct": false, "explanation": "语义：棋盘是放棋子的器具，本身不能吃子，与语境冲突。"}, {"text": "棋盒", "is_correct": false, "explanation": "语义：棋盒是装棋子的盒子，不能用来“吃掉”棋子，“他只用了三个棋盒，就吃掉了我的车”说不通。"}], "explanations": {"着数": "正确。“着数”指下棋的步数，“他只用了三个着数，就吃掉了我的车”符合语境。", "棋钟": "语义：棋钟是计时器，不能用来“吃掉”棋子，与“吃掉了我的车”冲突。", "棋盘": "语义：棋盘是放棋子的器具，本身不能吃子，与语境冲突。", "棋盒": "语义：棋盒是装棋子的盒子，不能用来“吃掉”棋子，“他只用了三个棋盒，就吃掉了我的车”说不通。"}, "sentence_index": 0, "correct_answer": "着数"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用一把着数赢了比赛。", "explanation": "这里应该用〈个〉。“把”用于有柄的东西，不能修饰办法，“着数”指办法时要用〈个〉。"}, {"text": "这首歌的着数很好听。", "explanation": "这里应该用〈旋律〉。“着数”指下棋的步数或做事的办法，不指歌曲的曲调，应说〈旋律〉。"}, {"text": "他把钥匙藏在着数里了。", "explanation": "“着数”是抽象的步数或办法，不是可以藏东西的地点，不能说“藏在着数里”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b191c03-bb58-4047-9fd1-b5a24eda03ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87992, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "着数", "is_correct": true, "explanation": "正确。“着数”指办法或手段，“他的着数很厉害，一下子就把问题解决了”符合语境。"}, {"text": "字体", "is_correct": false, "explanation": "语义：字体是文字的样式，“他的字体很厉害，一下子就把问题解决了”说不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是外貌特征，不能用来解决问题，与语境冲突。"}, {"text": "鞋码", "is_correct": false, "explanation": "语义：鞋码是鞋的尺寸，与“一下子就把问题解决了”毫无关系。"}], "explanations": {"着数": "正确。“着数”指办法或手段，“他的着数很厉害，一下子就把问题解决了”符合语境。", "字体": "语义：字体是文字的样式，“他的字体很厉害，一下子就把问题解决了”说不通。", "身高": "体貌：身高是外貌特征，不能用来解决问题，与语境冲突。", "鞋码": "语义：鞋码是鞋的尺寸，与“一下子就把问题解决了”毫无关系。"}, "sentence_index": 6, "correct_answer": "着数"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份报告的着数很沉，拿起来很费力。", "explanation": "这里应该用〈分量〉。“着数”指下棋的步数或做事的办法，不指报告的重量，应说〈分量〉。"}, {"text": "这种鞋子的着数很时尚。", "explanation": "这里应该用〈款式〉。“着数”指下棋的步数或做事的办法，不指鞋子的样式，应说〈款式〉。"}, {"text": "他跳舞的着数很优美。", "explanation": "这里应该用〈动作〉。“着数”指棋步或办法，不能用来形容舞蹈的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b191c03-bb58-4047-9fd1-b5a24eda03ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87992, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我以前没见过这把着数。", "corrected_sentence": "我以前没见过这个着数。", "error_description": "错误形式：“这把着数”；正确形式：“这个着数”。“着数”指办法时应用量词〈个〉，〈把〉用于有柄的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b191c03-bb58-4047-9fd1-b5a24eda03ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87992, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条小着数让对方很意外。", "corrected_sentence": "这个小着数让对方很意外。", "error_description": "错误形式：“这条小着数”；正确形式：“这个小着数”。“条”多用于细长的东西，“着数”指办法时应用量词〈个〉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b191c03-bb58-4047-9fd1-b5a24eda03ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
