INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87993, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84db387b-9851-407c-b28e-aebbf04c37ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87993, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "表示前面所说的情况已成事实或已知，后面据此引出结论或要求，相当于“既然”。", "primary_collocate": null, "pronunciation": "jì", "ipa": "tɕi˥˩", "syllable_count": 1, "sentences": [{"text": "你既答应了他，就一定要做到。", "target_word": "既", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "既是朋友，就不用这么客气。", "target_word": "既", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "事情既已这样，生气也没有用。", "target_word": "既", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你既来了，就多住几天吧。", "target_word": "既", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他既不想去，我们就别勉强他了。", "target_word": "既", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你既说有急事，我就不留你了。", "target_word": "既", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "钱既花了，后悔也来不及了。", "target_word": "既", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他既已决定留学，家人也只好支持他。", "target_word": "既", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你既觉得累，就先回去休息吧。", "target_word": "既", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你既把话说出口，就得对大家负责。", "target_word": "既", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "既然", "label": "复合"}], "register": "书面语", "sense_fingerprint": "既：前面说已成事实或已知情况，后面用「就」引出结论或要求（既然）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81d15118-0c81-46f0-82ea-032f2bef765b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87993, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "既", "is_correct": true, "explanation": "正确答案：既（jì），表示已成事实。"}, {"text": "机", "is_correct": false, "explanation": "jī（第一声）与 jì（第四声）声调不同，意思是机器。"}, {"text": "进", "is_correct": false, "explanation": "jìn 与 jì 只差韵尾 -n，意思是前进。"}, {"text": "戏", "is_correct": false, "explanation": "xì 与 jì 声母不同，意思是戏剧。"}, {"text": "挤", "is_correct": false, "explanation": "jǐ（第三声）与 jì（第四声）声调不同，意思是拥挤。"}], "explanations": {"既": "正确答案：既（jì），表示已成事实。", "机": "jī（第一声）与 jì（第四声）声调不同，意思是机器。", "进": "jìn 与 jì 只差韵尾 -n，意思是前进。", "戏": "xì 与 jì 声母不同，意思是戏剧。", "挤": "jǐ（第三声）与 jì（第四声）声调不同，意思是拥挤。"}, "sentence_index": null, "correct_answer": "既"}, "level_3": {"options": [{"text": "既", "is_correct": true, "explanation": "“既”表示已成事实，与后面“就一定要做到”的结论相呼应，符合句意。"}, {"text": "而", "is_correct": false, "explanation": "搭配：“而”是并列或转折连词，不能放在主语“你”后作状语。"}, {"text": "却", "is_correct": false, "explanation": "语义：“却”表示转折，与“就一定要做到”的顺承关系相矛盾。"}, {"text": "所以", "is_correct": false, "explanation": "搭配：“所以”表示结果，不能放在主语后直接修饰动词。"}], "explanations": {"既": "“既”表示已成事实，与后面“就一定要做到”的结论相呼应，符合句意。", "而": "搭配：“而”是并列或转折连词，不能放在主语“你”后作状语。", "却": "语义：“却”表示转折，与“就一定要做到”的顺承关系相矛盾。", "所以": "搭配：“所以”表示结果，不能放在主语后直接修饰动词。"}, "sentence_index": 0, "correct_answer": "既"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你既答应了他，又一定要做到。", "explanation": "这里应该用〈就〉。表示“既然”时，“既”要与“就”配合引出结论；用“又”会变成并列，句意不通。"}, {"text": "他没吃饭既，就不饿了。", "explanation": "“既”是连词，须放在分句句首，不能放在句末，此句语序错误。"}, {"text": "这件事既的确定，你就别着急。", "explanation": "“既”是连词，后面不能直接接“的”字结构，此句结构错误。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84db387b-9851-407c-b28e-aebbf04c37ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87993, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "既", "is_correct": true, "explanation": "正确答案：既（jì），表示已成事实。"}, {"text": "鸡", "is_correct": false, "explanation": "jī（第一声）与 jì（第四声）声调不同，意思是鸡。"}, {"text": "近", "is_correct": false, "explanation": "jìn 与 jì 只差韵尾 -n，意思是靠近。"}, {"text": "系", "is_correct": false, "explanation": "xì 与 jì 声母不同，意思是系统。"}], "explanations": {"既": "正确答案：既（jì），表示已成事实。", "鸡": "jī（第一声）与 jì（第四声）声调不同，意思是鸡。", "近": "jìn 与 jì 只差韵尾 -n，意思是靠近。", "系": "xì 与 jì 声母不同，意思是系统。"}, "sentence_index": null, "correct_answer": "既"}, "level_3": {"options": [{"text": "既", "is_correct": true, "explanation": "“既”引出已成事实，与“花了”相呼应，符合句意。"}, {"text": "但", "is_correct": false, "explanation": "搭配：“但”是转折连词，不能连接“钱”与动词。"}, {"text": "和", "is_correct": false, "explanation": "搭配：“和”连接名词，不能连接“钱”与动词“花”。"}, {"text": "或", "is_correct": false, "explanation": "语义：“或”表示选择，与“钱已经花了”的已成事实不符。"}], "explanations": {"既": "“既”引出已成事实，与“花了”相呼应，符合句意。", "但": "搭配：“但”是转折连词，不能连接“钱”与动词。", "和": "搭配：“和”连接名词，不能连接“钱”与动词“花”。", "或": "语义：“或”表示选择，与“钱已经花了”的已成事实不符。"}, "sentence_index": 6, "correct_answer": "既"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你既来了，又多住几天吧。", "explanation": "这里应该用〈就〉。表示“既然”时，“既”要与“就”配合引出要求；用“又”会变成并列，句意不通。"}, {"text": "他没到既，我们就先开始吧。", "explanation": "“既”是连词，须放在分句句首，不能放在句末，此句语序错误。"}, {"text": "这次比赛既的还没开始，大家就先休息吧。", "explanation": "“既”是连词，后面不能直接接“的”字结构，此句结构错误。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84db387b-9851-407c-b28e-aebbf04c37ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87993, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你既有空，又来帮我一下吧。", "corrected_sentence": "你既有空，就来帮我一下吧。", "error_description": "搭配错误：“既”表示“既然”时，要与“就”配合引出要求。用“又”会变成并列，句意不通。正确说法是“你既有空，就来帮我一下吧。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84db387b-9851-407c-b28e-aebbf04c37ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87993, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "机票已既买好，我们就出发吧。", "corrected_sentence": "机票既已买好，我们就出发吧。", "error_description": "语序错误：“既已”是固定词序，“既”要放在“已”之前，不能放在“已”之后。正确说法是“机票既已买好，我们就出发吧”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84db387b-9851-407c-b28e-aebbf04c37ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
