INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87994, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，与“又”“也”配合，表示两种情况同时存在。", "primary_collocate": null, "pronunciation": "jì", "ipa": "tɕi˥˩", "syllable_count": 1, "sentences": [{"text": "这家饭馆的菜既好吃又便宜。", "target_word": "既", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她既聪明又努力。", "target_word": "既", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个房子既大又亮。", "target_word": "既", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他既会唱歌，又会跳舞。", "target_word": "既", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这本书既有意思，又有用。", "target_word": "既", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "坐地铁既快又方便。", "target_word": "既", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他既是我的老师，也是我的朋友。", "target_word": "既", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件衣服既好看又不贵。", "target_word": "既", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这里的夏天既热又湿。", "target_word": "既", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "新手机既轻又薄，我很喜欢。", "target_word": "既", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "既：与「又」「也」配合，并列两种性质或情况同时存在（既……又……）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81d15118-0c81-46f0-82ea-032f2bef765b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87994, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "既", "is_correct": true, "explanation": "既读 jì，表示两种情况同时存在，与听到的音一致。"}, {"text": "机", "is_correct": false, "explanation": "jī（第一声）与 jì（第四声）声调不同，意思是机器。"}, {"text": "己", "is_correct": false, "explanation": "jǐ（第三声）与 jì（第四声）声调不同，意思是自己。"}, {"text": "气", "is_correct": false, "explanation": "qì 与 jì 声母不同（q 与 j），声调相同，意思是空气。"}, {"text": "戏", "is_correct": false, "explanation": "xì 与 jì 声母不同（x 与 j），声调相同，意思是戏剧。"}], "explanations": {"既": "既读 jì，表示两种情况同时存在，与听到的音一致。", "机": "jī（第一声）与 jì（第四声）声调不同，意思是机器。", "己": "jǐ（第三声）与 jì（第四声）声调不同，意思是自己。", "气": "qì 与 jì 声母不同（q 与 j），声调相同，意思是空气。", "戏": "xì 与 jì 声母不同（x 与 j），声调相同，意思是戏剧。"}, "sentence_index": null, "correct_answer": "既"}, "level_3": {"options": [{"text": "既", "is_correct": true, "explanation": "“既”与“又”配合，表示两种性质同时存在，“好吃又便宜”符合句意。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示因果，后句应是结果，“好吃又便宜”不能作为原因。"}, {"text": "或者", "is_correct": false, "explanation": "语义：“或者”表示二者选一，与“好吃又便宜”同时具备的意思相矛盾。"}, {"text": "而", "is_correct": false, "explanation": "句法：“而”连接前后并列成分，此处前面是主语“这家饭馆的菜”，“而”不能直接接“好吃又便宜”。"}], "explanations": {"既": "“既”与“又”配合，表示两种性质同时存在，“好吃又便宜”符合句意。", "所以": "语义：“所以”表示因果，后句应是结果，“好吃又便宜”不能作为原因。", "或者": "语义：“或者”表示二者选一，与“好吃又便宜”同时具备的意思相矛盾。", "而": "句法：“而”连接前后并列成分，此处前面是主语“这家饭馆的菜”，“而”不能直接接“好吃又便宜”。"}, "sentence_index": 0, "correct_answer": "既"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家饭馆的菜既好吃，但便宜。", "explanation": "这里应该用〈又〉。“既”要与“又”或“也”配合表示两种情况并存，与转折词“但”搭配会变成转折，此处表示并列应用“又”。"}, {"text": "他既会唱歌。", "explanation": "这里应该用〈只〉。“既”要与“又”或“也”配合，连接两种情况；此处只说一种情况，表示“仅仅”应用“只”。"}, {"text": "这个城市既很安静。", "explanation": "这里应该用〈也〉。“既”需要与“又”配合连接两种情况，不能单独修饰形容词；此处表示“同样”应用“也”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84db387b-9851-407c-b28e-aebbf04c37ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87994, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "既", "is_correct": true, "explanation": "既读 jì，表示两种情况同时存在，与听到的音一致。"}, {"text": "几", "is_correct": false, "explanation": "jǐ（第三声）与 jì（第四声）声调不同，意思是几个。"}, {"text": "集", "is_correct": false, "explanation": "jí（第二声）与 jì（第四声）声调不同，意思是聚集。"}, {"text": "挤", "is_correct": false, "explanation": "jǐ（第三声）与 jì（第四声）声调不同，意思是拥挤。"}, {"text": "鸡", "is_correct": false, "explanation": "jī（第一声）与 jì（第四声）声调不同，意思是鸡。"}], "explanations": {"既": "既读 jì，表示两种情况同时存在，与听到的音一致。", "几": "jǐ（第三声）与 jì（第四声）声调不同，意思是几个。", "集": "jí（第二声）与 jì（第四声）声调不同，意思是聚集。", "挤": "jǐ（第三声）与 jì（第四声）声调不同，意思是拥挤。", "鸡": "jī（第一声）与 jì（第四声）声调不同，意思是鸡。"}, "sentence_index": null, "correct_answer": "既"}, "level_3": {"options": [{"text": "既", "is_correct": true, "explanation": "“既”与“也”配合，表示两种身份同时存在，符合句意。"}, {"text": "因此", "is_correct": false, "explanation": "语义：“因此”引出结果，后句应是结论，“也是我的朋友”不能作为结果。"}, {"text": "与其", "is_correct": false, "explanation": "搭配：“与其”要与“不如”配合表示取舍比较，不能与“也”搭配。"}, {"text": "或", "is_correct": false, "explanation": "语域：“或”是书面语，且表示选择，与口语句中的“也是”并列不通顺。"}], "explanations": {"既": "“既”与“也”配合，表示两种身份同时存在，符合句意。", "因此": "语义：“因此”引出结果，后句应是结论，“也是我的朋友”不能作为结果。", "与其": "搭配：“与其”要与“不如”配合表示取舍比较，不能与“也”搭配。", "或": "语域：“或”是书面语，且表示选择，与口语句中的“也是”并列不通顺。"}, "sentence_index": 6, "correct_answer": "既"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他既很累，还是坚持跑完了。", "explanation": "这里应该用〈虽然〉。“既”要与“又”或“也”配合表示两种情况并存，不表示让步；表示让步应用“虽然”。"}, {"text": "新手机轻既薄，我很喜欢。", "explanation": "语序错误：“既”要放在第一项前，与“又”配合，应说“既轻又薄”。"}, {"text": "这家店的菜既便宜，好吃。", "explanation": "这里应该用〈并且〉。“既”要与“又”或“也”成对使用，缺少“又”时不能连接两种情况；表示并列应用“并且”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84db387b-9851-407c-b28e-aebbf04c37ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87994, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个城市既安静但干净。", "corrected_sentence": "这个城市既安静又干净。", "error_description": "连词错误：“既”要与“又”配合表示两种情况并存，与“但”搭配会变成转折，应为“既安静又干净”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84db387b-9851-407c-b28e-aebbf04c37ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87994, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们既要学习，但要工作。", "corrected_sentence": "我们既要学习，又要工作。", "error_description": "“又”被换成“但”：“既”要与“又”或“也”配合，表示两种情况并存；与“但”配合会变成转折，应改为“又要工作”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84db387b-9851-407c-b28e-aebbf04c37ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87996, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bf9f4a-2139-4935-8242-9082b6980e5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87996, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bf9f4a-2139-4935-8242-9082b6980e5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87996, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "四周；周围各处。", "primary_collocate": null, "pronunciation": "sì xià", "ipa": "sz̩˥˩ ɕja˥˩", "syllable_count": 2, "sentences": [{"text": "半夜醒来，四下一片黑。", "target_word": "四下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我四下望了望，不知道该往哪儿走。", "target_word": "四下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯一关，四下都黑了。", "target_word": "四下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林里四下无人。", "target_word": "四下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风一吹，四下的树叶都沙沙地响。", "target_word": "四下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗在房间里四下闻着。", "target_word": "四下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他四下张望，想找一个坐的地方。", "target_word": "四下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雾里，四下什么都看不清。", "target_word": "四下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车一停，孩子们就四下散开了。", "target_word": "四下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了村口，四下都是田。", "target_word": "四下", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "所在地点的四周，周围各处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3aa1c745-16a8-430c-a276-d96c4b94600f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87996, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "四下", "is_correct": true, "explanation": "「四下」指周围各处，与「一片黑」一起描写环境的黑暗，符合语境。"}, {"text": "早上", "is_correct": false, "explanation": "语义：「早上」是白天的时段，与开头的「半夜醒来」时间矛盾。"}, {"text": "中午", "is_correct": false, "explanation": "语义：「中午」阳光很亮，不会一片黑，与「半夜醒来」的语境也对不上。"}, {"text": "白天", "is_correct": false, "explanation": "搭配：「一片黑」形容夜里的黑暗，不与「白天」搭配。"}], "explanations": {"四下": "「四下」指周围各处，与「一片黑」一起描写环境的黑暗，符合语境。", "早上": "语义：「早上」是白天的时段，与开头的「半夜醒来」时间矛盾。", "中午": "语义：「中午」阳光很亮，不会一片黑，与「半夜醒来」的语境也对不上。", "白天": "搭配：「一片黑」形容夜里的黑暗，不与「白天」搭配。"}, "sentence_index": 0, "correct_answer": "四下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场比赛四下只用了三十分钟。", "explanation": "这里不能用〈四下〉表示时长，「四下」只指空间的周围，应改用〈一共〉。"}, {"text": "这个班四下有五十个学生。", "explanation": "这里不能用〈四下〉表示人数，「四下」只指周围的地方，应改用〈一共〉。"}, {"text": "他四下向北走了一百米。", "explanation": "这里不能用〈四下〉，它指四面八方，与单一方向“向北”矛盾，应改用〈往北〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bf9f4a-2139-4935-8242-9082b6980e5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87996, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "四下", "is_correct": true, "explanation": "「四下」指周围各处，与「张望」搭配，表示向四周看。"}, {"text": "东边", "is_correct": false, "explanation": "搭配：「东边」只指一个方向，不能与「张望」连用表示环顾四周。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：「钥匙」是物件，不指位置或方向，不能用来环顾四周，与「张望」不搭配。"}, {"text": "书桌", "is_correct": false, "explanation": "语义：「书桌」是家具，不指可以环顾的范围，「书桌张望」不成立。"}], "explanations": {"四下": "「四下」指周围各处，与「张望」搭配，表示向四周看。", "东边": "搭配：「东边」只指一个方向，不能与「张望」连用表示环顾四周。", "钥匙": "语义：「钥匙」是物件，不指位置或方向，不能用来环顾四周，与「张望」不搭配。", "书桌": "语义：「书桌」是家具，不指可以环顾的范围，「书桌张望」不成立。"}, "sentence_index": 6, "correct_answer": "四下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈四下很生气，一直不说话。", "explanation": "这里不能用〈四下〉表示心情，「四下」只指空间，应直接说〈妈妈很生气〉。"}, {"text": "这个月的工资四下涨了一倍。", "explanation": "这里不能用〈四下〉表示数额增长，「四下」指周围各处，应改用〈增加〉。"}, {"text": "我的书包四下很重，背不动。", "explanation": "这里不能用〈四下〉修饰轻重，「四下」只指周围的地方，应直接说〈书包很重〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bf9f4a-2139-4935-8242-9082b6980e5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87996, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我四下找了找四下，想找一个出口。", "corrected_sentence": "我四下找了找，想找一个出口。", "error_description": "错误形式：「找了找四下」，句末多出一个「四下」。正确形式：「我四下找了找」，「四下」只出现一次，放在动词前作状语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bf9f4a-2139-4935-8242-9082b6980e5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87996, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两个人四下了打听，才找到地址。", "corrected_sentence": "两个人四下打听，才找到地址。", "error_description": "「四下」后面不能直接加「了」，「了」应放在动词之后，应为「两个人四下打听」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bf9f4a-2139-4935-8242-9082b6980e5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87998, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "早", "is_correct": true, "explanation": "正确。「早」与「晚」在「早于或迟于规定时间」这一意义上互为反义。"}, {"text": "快", "is_correct": false, "explanation": "快指速度，与时间的早晚无关，不与「晚」构成反义。"}, {"text": "远", "is_correct": false, "explanation": "远指距离，与「晚」不构成反义关系。"}, {"text": "高", "is_correct": false, "explanation": "高指高度，与「晚」不构成反义关系。"}], "correct_answer": "早", "explanations": {"早": "正确。「早」与「晚」在「早于或迟于规定时间」这一意义上互为反义。", "快": "快指速度，与时间的早晚无关，不与「晚」构成反义。", "远": "远指距离，与「晚」不构成反义关系。", "高": "高指高度，与「晚」不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '928d444e-332c-4916-9537-84ebd85376e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87998, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "早", "is_correct": true, "explanation": "正确。「早」与「晚」在「早于或迟于规定时间」这一意义上互为反义。"}, {"text": "轻", "is_correct": false, "explanation": "轻指重量，与时间的早晚无关，不与「晚」构成反义。"}, {"text": "深", "is_correct": false, "explanation": "深指深浅，与「晚」不构成反义关系。"}, {"text": "厚", "is_correct": false, "explanation": "厚指厚薄，与「晚」不构成反义关系。"}], "correct_answer": "早", "explanations": {"早": "正确。「早」与「晚」在「早于或迟于规定时间」这一意义上互为反义。", "轻": "轻指重量，与时间的早晚无关，不与「晚」构成反义。", "深": "深指深浅，与「晚」不构成反义关系。", "厚": "厚指厚薄，与「晚」不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '928d444e-332c-4916-9537-84ebd85376e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87998, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "在规定或预期的时间之后；时间靠后的。", "primary_collocate": null, "pronunciation": "wǎn", "ipa": "wan˨˩˦", "syllable_count": 1, "sentences": [{"text": "对不起，我来晚了。", "target_word": "晚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天的飞机晚了一个小时。", "target_word": "晚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在去还不晚。", "target_word": "晚", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他起得很晚。", "target_word": "晚", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "火车晚到了十分钟。", "target_word": "晚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你怎么这么晚才回家？", "target_word": "晚", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "比赛开始得太晚了。", "target_word": "晚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太晚了，快去睡觉吧。", "target_word": "晚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他来得不晚，会还没开始。", "target_word": "晚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在学汉语一点也不晚。", "target_word": "晚", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "晚了", "label": "体标"}, {"form": "晚点", "label": "复合"}], "register": "中性", "sense_fingerprint": "迟于规定或预期的时间，时间靠后", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e9987eb-5886-4587-85c6-5e6350eb4adf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87998, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "晚", "is_correct": true, "explanation": "正确答案。晚读作 wǎn，指迟于规定或预期的时间。"}, {"text": "玩", "is_correct": false, "explanation": "wán（第二声）与 wǎn（第三声）只声调不同，玩是玩耍的意思。"}, {"text": "万", "is_correct": false, "explanation": "wàn（第四声）与 wǎn（第三声）只声调不同，万是数词「一万」。"}, {"text": "满", "is_correct": false, "explanation": "mǎn 与 wǎn 声母不同（m/w），满是「充满、满足」的意思。"}, {"text": "往", "is_correct": false, "explanation": "wǎng 与 wǎn 韵母不同（ng/n），往是「朝向、去」的意思。"}], "explanations": {"晚": "正确答案。晚读作 wǎn，指迟于规定或预期的时间。", "玩": "wán（第二声）与 wǎn（第三声）只声调不同，玩是玩耍的意思。", "万": "wàn（第四声）与 wǎn（第三声）只声调不同，万是数词「一万」。", "满": "mǎn 与 wǎn 声母不同（m/w），满是「充满、满足」的意思。", "往": "wǎng 与 wǎn 韵母不同（ng/n），往是「朝向、去」的意思。"}, "sentence_index": null, "correct_answer": "晚"}, "level_3": {"options": [{"text": "晚", "is_correct": true, "explanation": "正确答案。「我来晚了」表示到得迟，与「对不起」相合。"}, {"text": "高", "is_correct": false, "explanation": "搭配：「来高了」不成立，「高」指高度，不能表示到达的时间。"}, {"text": "久", "is_correct": false, "explanation": "语义：「久」说时间长，不能表示到达的迟早。"}, {"text": "慢", "is_correct": false, "explanation": "搭配：「来慢了」说的是速度慢，表示迟到应说「来晚了」。"}], "explanations": {"晚": "正确答案。「我来晚了」表示到得迟，与「对不起」相合。", "高": "搭配：「来高了」不成立，「高」指高度，不能表示到达的时间。", "久": "语义：「久」说时间长，不能表示到达的迟早。", "慢": "搭配：「来慢了」说的是速度慢，表示迟到应说「来晚了」。"}, "sentence_index": 0, "correct_answer": "晚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的成绩很晚。", "explanation": "这里应该用〈好〉或〈差〉。晚指时间靠后，评价成绩的好坏不能用晚。"}, {"text": "这里离车站很晚。", "explanation": "这里应该用〈远〉。晚指时间，形容距离要用远。"}, {"text": "这盏灯很晚。", "explanation": "这里应该用〈亮〉或〈暗〉。晚指时间，形容灯光要用亮、暗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '928d444e-332c-4916-9537-84ebd85376e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87998, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "晚", "is_correct": true, "explanation": "正确答案。晚读作 wǎn，指迟于规定或预期的时间。"}, {"text": "完", "is_correct": false, "explanation": "wán（第二声）与 wǎn（第三声）只声调不同，完是「结束、完成」的意思。"}, {"text": "网", "is_correct": false, "explanation": "wǎng 与 wǎn 韵母不同（ng/n），网是网络或渔网的意思。"}, {"text": "弯", "is_correct": false, "explanation": "wān（第一声）与 wǎn（第三声）只声调不同，弯是「不直、弯曲」的意思。"}], "explanations": {"晚": "正确答案。晚读作 wǎn，指迟于规定或预期的时间。", "完": "wán（第二声）与 wǎn（第三声）只声调不同，完是「结束、完成」的意思。", "网": "wǎng 与 wǎn 韵母不同（ng/n），网是网络或渔网的意思。", "弯": "wān（第一声）与 wǎn（第三声）只声调不同，弯是「不直、弯曲」的意思。"}, "sentence_index": null, "correct_answer": "晚"}, "level_3": {"options": [{"text": "晚", "is_correct": true, "explanation": "正确答案。「比赛开始得太晚了」表示开始的时间迟。"}, {"text": "重", "is_correct": false, "explanation": "搭配：「开始得太重」不成立，「重」不能描述开始的时间。"}, {"text": "深", "is_correct": false, "explanation": "搭配：「深」不能修饰「开始」的时间，「开始得太深」不成立。"}, {"text": "长", "is_correct": false, "explanation": "语义：「开始得太长」说不通，比较开始时间的先后应用「晚」。"}], "explanations": {"晚": "正确答案。「比赛开始得太晚了」表示开始的时间迟。", "重": "搭配：「开始得太重」不成立，「重」不能描述开始的时间。", "深": "搭配：「深」不能修饰「开始」的时间，「开始得太深」不成立。", "长": "语义：「开始得太长」说不通，比较开始时间的先后应用「晚」。"}, "sentence_index": 6, "correct_answer": "晚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这根绳子很晚。", "explanation": "这里应该用〈长〉。晚指时间，形容长度要用长。"}, {"text": "这个箱子很晚。", "explanation": "这里应该用〈重〉。晚指时间，形容轻重要用重。"}, {"text": "这口井很晚。", "explanation": "这里应该用〈深〉。晚指时间，形容深浅要用深。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '928d444e-332c-4916-9537-84ebd85376e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87998, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我今天起了晚。", "corrected_sentence": "我今天起晚了。", "error_description": "「晚」作补语时，「了」放在句末，应说「起晚了」，不能说「起了晚」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '928d444e-332c-4916-9537-84ebd85376e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87998, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我弟弟昨天起很晚。", "corrected_sentence": "我弟弟昨天起得很晚。", "error_description": "「起」后带程度补语「晚」时，中间要用「得」，应说「起得很晚」，不能省略「得」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '928d444e-332c-4916-9537-84ebd85376e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
