INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87999, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "虚构是想出来的，不是真的发生过。", "primary_collocate": null, "pronunciation": "xū gòu", "ipa": "ɕy˥ koʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这个故事是虚构的，别当真。", "target_word": "虚构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小说里的事都是虚构的。", "target_word": "虚构", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他虚构了一次旅行，骗了朋友。", "target_word": "虚构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部电影里的人名都是虚构的。", "target_word": "虚构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我没去过那里，是我虚构的。", "target_word": "虚构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她虚构了一段爱情，写进书里。", "target_word": "虚构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事根本没发生，是有人虚构的。", "target_word": "虚构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们虚构一个故事。", "target_word": "虚构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他为了面子虚构过很多经历。", "target_word": "虚构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故事里的地名是作者虚构的。", "target_word": "虚构", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "虚构了", "label": "体标（完成）"}, {"form": "虚构过", "label": "体标（经验）"}, {"form": "虛構", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "想出来的，并非真实发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968af400-236c-4070-b1b0-1aaf52250aaf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87999, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "虚构", "is_correct": true, "explanation": "正确：“虚构”说明故事是编出来的，所以才说“别当真”。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象是食物，不能说“煮的故事”。"}, {"text": "种", "is_correct": false, "explanation": "搭配：“种”的对象是植物或作物，不能用于“故事”。"}, {"text": "测量", "is_correct": false, "explanation": "语义：“测量”指用仪器量取数据，与“故事”不相称。"}], "explanations": {"虚构": "正确：“虚构”说明故事是编出来的，所以才说“别当真”。", "煮": "搭配：“煮”的对象是食物，不能说“煮的故事”。", "种": "搭配：“种”的对象是植物或作物，不能用于“故事”。", "测量": "语义：“测量”指用仪器量取数据，与“故事”不相称。"}, "sentence_index": 0, "correct_answer": "虚构"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "建筑师虚构了一座大桥。", "explanation": "这里应该用〈设计〉。虚构只指编造不存在的人或事；大桥要先设计再建造，应说“设计”。"}, {"text": "工匠虚构了一只瓷碗。", "explanation": "这里应该用〈烧制〉。虚构不用于制作真实的器物，瓷碗要说“烧制”。"}, {"text": "工厂虚构了一批啤酒。", "explanation": "这里应该用〈酿造〉。虚构不用于生产真实的饮品，啤酒要说“酿造”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd49623de-62a6-46c9-80de-54d676cd0681') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87999, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "虚构", "is_correct": true, "explanation": "正确：编造出来的事，与“根本没发生”相符。"}, {"text": "熬", "is_correct": false, "explanation": "搭配：“熬”多用于粥、药等，不能说“熬一件事”。"}, {"text": "拆", "is_correct": false, "explanation": "语义：“拆”指拆开或拆除有形之物，与“事件”不符。"}, {"text": "烤", "is_correct": false, "explanation": "搭配：“烤”的对象是食物等，不能用于“事情”。"}], "explanations": {"虚构": "正确：编造出来的事，与“根本没发生”相符。", "熬": "搭配：“熬”多用于粥、药等，不能说“熬一件事”。", "拆": "语义：“拆”指拆开或拆除有形之物，与“事件”不符。", "烤": "搭配：“烤”的对象是食物等，不能用于“事情”。"}, "sentence_index": 6, "correct_answer": "虚构"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈虚构了一顿晚饭。", "explanation": "这里应该用〈做〉。虚构指编造不存在的事物，晚饭是真实做出来的，应说“做”。"}, {"text": "我们虚构了那座古老的寺庙。", "explanation": "这里应该用〈参观〉。虚构指编造不存在的事物，寺庙真实存在，去看它要说“参观”。"}, {"text": "工人虚构了那台机器。", "explanation": "这里应该用〈修理〉。虚构不用于处理真实存在的机器，修机器要说“修理”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd49623de-62a6-46c9-80de-54d676cd0681') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87999, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个传说是后人虚构地。", "corrected_sentence": "那个传说是后人虚构的。", "error_description": "错误：虚构地。正确：虚构的。“是……的”句式中，修饰成分要用“的”，不能用“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd49623de-62a6-46c9-80de-54d676cd0681') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87999, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个人物是作家虚构的过。", "corrected_sentence": "这个人物是作家虚构过的。", "error_description": "错误：虚构的过。正确：虚构过的。“过”表示经历，要紧跟动词，不能放在“的”后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd49623de-62a6-46c9-80de-54d676cd0681') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
