INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88000, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "凭想象编造出不存在的事物。", "primary_collocate": null, "pronunciation": "xū gòu", "ipa": "ɕy˥ koʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这位作家虚构了一个小镇。", "target_word": "虚构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在小说里虚构了很多人物。", "target_word": "虚构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个故事是她虚构的，不是真事。", "target_word": "虚构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他虚构了一段从未发生过的经历，骗过了大家。", "target_word": "虚构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子喜欢虚构一个朋友陪自己玩。", "target_word": "虚构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他虚构了一个身份，骗我说他是医生。", "target_word": "虚构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作者虚构了一场大雨，让故事更有意思。", "target_word": "虚构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个人虚构过自己的经历。", "target_word": "虚构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的村子是导演虚构出来的。", "target_word": "虚构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "记者不能虚构新闻，必须写真事。", "target_word": "虚构", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "虚构了", "label": "体标（完成）"}, {"form": "虚构过", "label": "体标（经验）"}, {"form": "虛構", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "凭想象编造不存在的人或事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968af400-236c-4070-b1b0-1aaf52250aaf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88000, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "虚构", "is_correct": true, "explanation": "正确：“虚构”指凭想象编造不存在的事物，与作家写出一个小镇相符。"}, {"text": "酿造", "is_correct": false, "explanation": "搭配：“酿造”多用于酒、醋等，不能搭配“小镇”。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：“拆除”指拆掉已存在的建筑，与“小镇”是凭空编出来的不相符。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲等，不能说“唱一个小镇”。"}], "explanations": {"虚构": "正确：“虚构”指凭想象编造不存在的事物，与作家写出一个小镇相符。", "酿造": "搭配：“酿造”多用于酒、醋等，不能搭配“小镇”。", "拆除": "语义：“拆除”指拆掉已存在的建筑，与“小镇”是凭空编出来的不相符。", "唱": "搭配：“唱”的对象是歌曲等，不能说“唱一个小镇”。"}, "sentence_index": 0, "correct_answer": "虚构"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "爱迪生虚构了电灯，改变了世界。", "explanation": "这里应该用〈发明〉。虚构指凭想象编造不存在的人或事，电灯是真实存在的器物，应说“发明”。"}, {"text": "这家工厂每天虚构几百辆汽车。", "explanation": "这里应该用〈制造〉。虚构不用于生产真实的产品，汽车要说“制造”。"}, {"text": "农民每年虚构一片新稻田。", "explanation": "这里应该用〈开垦〉。虚构不用于开辟真实的土地，新田要说“开垦”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd49623de-62a6-46c9-80de-54d676cd0681') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88000, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "虚构", "is_correct": true, "explanation": "正确：编造出来的一场大雨，与“让故事更有意思”相符。"}, {"text": "拦截", "is_correct": false, "explanation": "搭配：“拦截”用于阻挡来袭的人或物，不能说“拦截一场大雨”。"}, {"text": "陪伴", "is_correct": false, "explanation": "语义：“陪伴”指与人相伴，大雨不是人，句意不通。"}, {"text": "清扫", "is_correct": false, "explanation": "搭配：“清扫”用于清除地面或场所的脏物，不能搭配“大雨”。"}], "explanations": {"虚构": "正确：编造出来的一场大雨，与“让故事更有意思”相符。", "拦截": "搭配：“拦截”用于阻挡来袭的人或物，不能说“拦截一场大雨”。", "陪伴": "语义：“陪伴”指与人相伴，大雨不是人，句意不通。", "清扫": "搭配：“清扫”用于清除地面或场所的脏物，不能搭配“大雨”。"}, "sentence_index": 6, "correct_answer": "虚构"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人虚构了一条新铁路，通到山里。", "explanation": "这里应该用〈修建〉。虚构不用于建造真实的工程，铁路是实际修建的，应说“修建”。"}, {"text": "这位果农虚构了一大片果树。", "explanation": "这里应该用〈种植〉。虚构不用于栽种真实的植物，果树要说“种植”。"}, {"text": "这位厨师虚构了一桌好菜。", "explanation": "这里应该用〈烹饪〉。虚构指编造不存在的事物，做菜是真实的过程，应说“烹饪”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd49623de-62a6-46c9-80de-54d676cd0681') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88000, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他虚构了着一座小岛。", "corrected_sentence": "他虚构了一座小岛。", "error_description": "错误：虚构了着。正确：虚构了。“了”表示完成，“着”表示持续，两者不能同时用在动词后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd49623de-62a6-46c9-80de-54d676cd0681') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88000, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "作家虚构了出一个王国。", "corrected_sentence": "作家虚构出了一个王国。", "error_description": "错误：虚构了出。正确：虚构出了。结果补语“出”要紧跟动词，“了”放在补语之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd49623de-62a6-46c9-80de-54d676cd0681') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
