INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88001, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "求是很想得到一样东西，去请别人给自己。", "primary_collocate": null, "pronunciation": "qiú", "ipa": "tɕʰiou˧˥", "syllable_count": 1, "sentences": [{"text": "他向朋友求一个好办法。", "target_word": "求", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想向老先生求一幅字。", "target_word": "求", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人们去庙里求平安。", "target_word": "求", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他跪在地上求原谅。", "target_word": "求", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她天天拜佛，求好运。", "target_word": "求", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我想向他求一本旧书。", "target_word": "求", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他向邻居求了一碗米。", "target_word": "求", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他口渴了，向路人求一杯水。", "target_word": "求", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈去寺里给我求了一个平安符。", "target_word": "求", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他求遍了朋友，也没借到钱。", "target_word": "求", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "求了", "label": "体标"}, {"form": "求过", "label": "体标"}, {"form": "求求", "label": "重叠"}, {"form": "请求", "label": "复合"}], "register": "中性", "sense_fingerprint": "很想得到某物，向人或神明讨要", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe9756ff-4b06-4a9a-9345-22a235fc21d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88001, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "扔", "is_correct": false, "explanation": "语义：“扔”是抛掷，不能以“好办法”为对象，句意不通。"}, {"text": "求", "is_correct": true, "explanation": "求：恳切地向人讨要，与“向朋友”和“好办法”的语境相合。"}, {"text": "踢", "is_correct": false, "explanation": "语义：“踢”是用脚击打，与“好办法”不合，句意不通。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”是用牙齿咬，与“好办法”不合，句意不通。"}], "explanations": {"扔": "语义：“扔”是抛掷，不能以“好办法”为对象，句意不通。", "求": "求：恳切地向人讨要，与“向朋友”和“好办法”的语境相合。", "踢": "语义：“踢”是用脚击打，与“好办法”不合，句意不通。", "咬": "语义：“咬”是用牙齿咬，与“好办法”不合，句意不通。"}, "sentence_index": 0, "correct_answer": "求"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他去商店求了一件衣服，付了五十块钱。", "explanation": "这里应该用〈买〉。求是请求讨要，不指付钱购买东西；这里既说求又说付钱，应该用买。"}, {"text": "强盗求了路人的钱。", "explanation": "这里应该用〈抢〉。求是恳切地请求，不指强行夺取；抢劫钱财不能用求。"}, {"text": "公司求他出差，却要求他立刻出发，不许拒绝。", "explanation": "这里应该用〈派〉。求是恳切地请托，与“不许拒绝”的强制安排不符；公司安排员工出差要用派。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54eb874-fdd6-49ea-9453-a002bd5ff0d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88001, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "擦", "is_correct": false, "explanation": "配价：“擦”的宾语应是桌面、物体，不能与“一碗米”搭配。"}, {"text": "求", "is_correct": true, "explanation": "求：恳切地向人讨要，与“向邻居”和“一碗米”的语境相合。"}, {"text": "摘", "is_correct": false, "explanation": "配价：“摘”的对象是果实、花叶，不能用于“米”。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”是用牙齿咬，与“向邻居”讨要一碗米的语境不合。"}], "explanations": {"擦": "配价：“擦”的宾语应是桌面、物体，不能与“一碗米”搭配。", "求": "求：恳切地向人讨要，与“向邻居”和“一碗米”的语境相合。", "摘": "配价：“摘”的对象是果实、花叶，不能用于“米”。", "咬": "语义：“咬”是用牙齿咬，与“向邻居”讨要一碗米的语境不合。"}, "sentence_index": 6, "correct_answer": "求"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用网在院子里求了一只小鸟。", "explanation": "这里应该用〈捉〉。求是向别人讨要，不能表示自己用网抓住小鸟；亲手抓住动物要用捉。"}, {"text": "他去树上求了一个苹果。", "explanation": "这里应该用〈摘〉。求是讨要，不能用于从树上取果实。"}, {"text": "公司每月发三万块工资，求了一个司机。", "explanation": "这里应该用〈雇〉。求是请求讨要，不指付薪聘用；公司付工资聘司机要用雇。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54eb874-fdd6-49ea-9453-a002bd5ff0d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88001, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他曾经向朋友求了过一个好办法。", "corrected_sentence": "他曾经向朋友求过一个好办法。", "error_description": "“了”和“过”不能同时用在“求”后面，表示曾经的经历只用“求过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54eb874-fdd6-49ea-9453-a002bd5ff0d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88001, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在老师求了一本好书。", "corrected_sentence": "她向老师求了一本好书。", "error_description": "“求”的对象要用介词“向”引出，“在”不能直接接人，应说“向老师求”，把“在”改为“向”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54eb874-fdd6-49ea-9453-a002bd5ff0d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
