INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88002, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "请求；恳切地希望得到。", "primary_collocate": null, "pronunciation": "qiú", "ipa": "tɕʰiou˧˥", "syllable_count": 1, "sentences": [{"text": "我求你帮我一个忙。", "target_word": "求", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他求老师再给他一次机会。", "target_word": "求", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小女孩求妈妈带她去公园。", "target_word": "求", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我求了他很久，他才同意。", "target_word": "求", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友有难，他来求我帮忙。", "target_word": "求", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你别走，我求你了。", "target_word": "求", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子哭着求爸爸买玩具。", "target_word": "求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他求大家不要告诉老师。", "target_word": "求", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她求医生快点儿救她的孩子。", "target_word": "求", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你有事就直说，不用求人。", "target_word": "求", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "求了", "label": "体标"}, {"form": "求过", "label": "体标"}, {"form": "求求", "label": "重叠"}, {"form": "请求", "label": "复合"}], "register": "中性", "sense_fingerprint": "恳切地请别人做某事或帮忙", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe9756ff-4b06-4a9a-9345-22a235fc21d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88002, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "训斥", "is_correct": false, "explanation": "搭配：“训斥”是责备，不能带“帮我一个忙”这样的请求。"}, {"text": "求", "is_correct": true, "explanation": "求：恳切地请人帮忙，与“帮我一个忙”的语境相合。"}, {"text": "祝", "is_correct": false, "explanation": "语义：“祝”表示祝愿，与句中的请托不合。"}, {"text": "逗", "is_correct": false, "explanation": "语义：“逗”指逗弄取乐，与“帮我一个忙”的请求不合。"}], "explanations": {"训斥": "搭配：“训斥”是责备，不能带“帮我一个忙”这样的请求。", "求": "求：恳切地请人帮忙，与“帮我一个忙”的语境相合。", "祝": "语义：“祝”表示祝愿，与句中的请托不合。", "逗": "语义：“逗”指逗弄取乐，与“帮我一个忙”的请求不合。"}, "sentence_index": 0, "correct_answer": "求"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我自己求这个周末去爬山。", "explanation": "这里应该用〈打算〉。求是恳切地请别人做事，必须有请求的对象；说自己的计划要用打算。"}, {"text": "我每月付他三千块，求他当我的专职司机。", "explanation": "这里应该用〈雇〉。求是请求帮忙，不指付薪聘人；每月付薪聘用司机要用雇。"}, {"text": "他在路上求到了一百块钱，不知道是谁丢的。", "explanation": "这里应该用〈捡〉。求是恳切地请别人帮忙，不指在地上拾到东西；拾到别人丢的钱要用捡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54eb874-fdd6-49ea-9453-a002bd5ff0d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88002, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "批评", "is_correct": false, "explanation": "搭配：“批评”的对象是人的错误，不能带“买玩具”这样的请求。"}, {"text": "求", "is_correct": true, "explanation": "求：恳切地请求，与“哭着”和“买玩具”的语境相合。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”是用牙齿咬，与“买玩具”的请求不合，句意不通。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”与哭着恳求的情境相反，不合。"}], "explanations": {"批评": "搭配：“批评”的对象是人的错误，不能带“买玩具”这样的请求。", "求": "求：恳切地请求，与“哭着”和“买玩具”的语境相合。", "咬": "语义：“咬”是用牙齿咬，与“买玩具”的请求不合，句意不通。", "嘲笑": "语义：“嘲笑”与哭着恳求的情境相反，不合。"}, "sentence_index": 6, "correct_answer": "求"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "张大爷每天都去菜市场求菜。", "explanation": "这里应该用〈买〉。求是恳切地请求，不指花钱购买蔬菜；去菜市场买菜要用买。"}, {"text": "将军求士兵冲锋，语气冰冷，毫不商量。", "explanation": "这里应该用〈命令〉。求是恳切地请托，与“语气冰冷、毫不商量”的上级指令不符；对下属发出指令要用命令。"}, {"text": "老板求他去开会，态度冷漠地发了一通脾气。", "explanation": "这里应该用〈吩咐〉。求是恳切地请托，与“态度冷漠地发脾气”的口吻不符；老板交代员工事务要用吩咐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54eb874-fdd6-49ea-9453-a002bd5ff0d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88002, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他急着很求我帮他找钥匙。", "corrected_sentence": "他急着求我帮他找钥匙。", "error_description": "“很”是程度副词，不能放在“着”和动词“求”之间，应删去“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54eb874-fdd6-49ea-9453-a002bd5ff0d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88002, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他曾经求了过我一次。", "corrected_sentence": "他曾经求过我一次。", "error_description": "“了”和“过”不能同时用在“求”后面，表示曾经的经历只用“求过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54eb874-fdd6-49ea-9453-a002bd5ff0d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
