INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88003, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "四更是古时候夜里快天亮的时候。", "primary_collocate": null, "pronunciation": "sì gēng", "ipa": "sɨ˥˩ kɤŋ˥", "syllable_count": 2, "sentences": [{"text": "古时候，四更的时候天快亮了。", "target_word": "四更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打更人敲响了四更的锣，天快亮了。", "target_word": "四更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说，四更过后，天就快亮了。", "target_word": "四更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古人四更就起床，准备去赶路。", "target_word": "四更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了四更，窗外已经有鸟叫声了。", "target_word": "四更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他读书读到四更，天都快亮了。", "target_word": "四更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代的商人四更起来，在天亮前出发。", "target_word": "四更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到四更的鼓声，母亲起来做早饭。", "target_word": "四更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前农村人四更起床，天亮前就下地了。", "target_word": "四更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小说里的侠客在四更动身，天亮前到了城外。", "target_word": "四更", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "四更天", "label": "复合"}], "register": "书面", "sense_fingerprint": "古时夜里将近天亮的时辰", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '167a7954-97b5-4a26-941f-142692a13d69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88003, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "四更", "is_correct": true, "explanation": "正确：四更指古时夜里快天亮的时候，与“天快亮了”相符。"}, {"text": "正午", "is_correct": false, "explanation": "语义：正午是中午十二点，与“天快亮”正好相反。"}, {"text": "黄昏", "is_correct": false, "explanation": "语义：黄昏是傍晚，天色渐暗，与“天快亮”矛盾。"}, {"text": "子夜", "is_correct": false, "explanation": "语义：子夜指半夜十二点前后，离天亮还远，与“天快亮了”不符。"}], "explanations": {"四更": "正确：四更指古时夜里快天亮的时候，与“天快亮了”相符。", "正午": "语义：正午是中午十二点，与“天快亮”正好相反。", "黄昏": "语义：黄昏是傍晚，天色渐暗，与“天快亮”矛盾。", "子夜": "语义：子夜指半夜十二点前后，离天亮还远，与“天快亮了”不符。"}, "sentence_index": 0, "correct_answer": "四更"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们今天四更下班，比平时早。", "explanation": "这里应该用〈四点〉。四更是古时夜里快天亮的时段，不用来说下班的钟点。"}, {"text": "我们四更吃晚饭，然后去看电影。", "explanation": "这里应该用〈晚上八点〉。四更指快天亮的时候，不能用来指晚饭时间。"}, {"text": "中午的时候，他四更才起床。", "explanation": "这里应该用〈上午十点〉。四更是夜里快天亮的时段，不能指白天的时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03082593-bfae-47ac-8eda-e4b23f65def1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88003, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "四更", "is_correct": true, "explanation": "正确：四更指快天亮的时候，商人在这个时候起来、天亮前出发，符合句意。"}, {"text": "日暮", "is_correct": false, "explanation": "语义：日暮指傍晚，与“在天亮前出发”矛盾。"}, {"text": "正午", "is_correct": false, "explanation": "语义：正午是中午十二点，与“天亮前出发”矛盾。"}, {"text": "日出", "is_correct": false, "explanation": "语义：日出是太阳升起的时候，已在天亮之后，与“天亮前出发”矛盾。"}], "explanations": {"四更": "正确：四更指快天亮的时候，商人在这个时候起来、天亮前出发，符合句意。", "日暮": "语义：日暮指傍晚，与“在天亮前出发”矛盾。", "正午": "语义：正午是中午十二点，与“天亮前出发”矛盾。", "日出": "语义：日出是太阳升起的时候，已在天亮之后，与“天亮前出发”矛盾。"}, "sentence_index": 6, "correct_answer": "四更"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在四更时分吃晚饭。", "explanation": "这里应该用〈傍晚〉。四更是快天亮的时段，不能用来指傍晚进餐的时间。"}, {"text": "中午的时候，村子里的鸡四更开始叫了。", "explanation": "这里应该用〈清晨〉。四更是快天亮的时段，白天的中午不能说四更。"}, {"text": "太阳下山了，他们四更才吃完晚饭。", "explanation": "这里应该用〈傍晚〉。四更是夜里快天亮的时段，太阳下山、吃晚饭的时候不能说四更。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03082593-bfae-47ac-8eda-e4b23f65def1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88003, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "古时候的书生四更的起床，点灯读书。", "corrected_sentence": "古时候的书生四更就起床，点灯读书。", "error_description": "错误：「四更的起床」；正确：「四更就起床」。时间词「四更」作状语，后接副词「就」，「的」不能连接状语和动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03082593-bfae-47ac-8eda-e4b23f65def1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88003, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古代的渔夫的四更就出门，摸黑下船。", "corrected_sentence": "古代的渔夫四更就出门，摸黑下船。", "error_description": "错误：「渔夫的四更」；正确：「渔夫四更」。时间词「四更」前不能加「的」，它直接作状语修饰「就出门」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03082593-bfae-47ac-8eda-e4b23f65def1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
