INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88004, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03082593-bfae-47ac-8eda-e4b23f65def1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88004, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "旧时把一夜分为五更，四更约在凌晨一点到三点。", "primary_collocate": null, "pronunciation": "sì gēng", "ipa": "sɨ˥˩ kɤŋ˥", "syllable_count": 2, "sentences": [{"text": "旧时候，四更大约是现在凌晨一点到三点。", "target_word": "四更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我查过了，古书里的四更约在夜里一点到三点。", "target_word": "四更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在凌晨两点左右，就是旧时的四更。", "target_word": "四更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说已经四更了，也就是凌晨一点到三点之间。", "target_word": "四更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里写四更，我们今天会说凌晨两三点。", "target_word": "四更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，一夜分五更，四更在凌晨。", "target_word": "四更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代把一夜分成五更，四更排在第四。", "target_word": "四更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小说里说四更，就是现在的凌晨两点多。", "target_word": "四更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "四更对应现在的凌晨一点到三点。", "target_word": "四更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凌晨两点的时候，古人会说这是四更。", "target_word": "四更", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "四更天", "label": "复合"}], "register": "书面", "sense_fingerprint": "旧时五更中的第四更，约凌晨一点到三点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '167a7954-97b5-4a26-941f-142692a13d69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88004, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "四更", "is_correct": true, "explanation": "正确：四更是旧时五更中的第四更，大约是现在的凌晨一点到三点，与句意相符。"}, {"text": "午夜", "is_correct": false, "explanation": "语义：午夜指零点前后，与“凌晨一点到三点”不符。"}, {"text": "清晨", "is_correct": false, "explanation": "语义：清晨指天亮后的早上，不在凌晨一点到三点之间。"}, {"text": "亥时", "is_correct": false, "explanation": "语义：亥时指夜里九点到十一点，与“凌晨一点到三点”不符。"}], "explanations": {"四更": "正确：四更是旧时五更中的第四更，大约是现在的凌晨一点到三点，与句意相符。", "午夜": "语义：午夜指零点前后，与“凌晨一点到三点”不符。", "清晨": "语义：清晨指天亮后的早上，不在凌晨一点到三点之间。", "亥时": "语义：亥时指夜里九点到十一点，与“凌晨一点到三点”不符。"}, "sentence_index": 0, "correct_answer": "四更"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "四更十二点，我们还在工作。", "explanation": "这里应该用〈午夜〉。四更是凌晨一点到三点，不指十二点。"}, {"text": "四更六点，工人们开始上班了。", "explanation": "这里应该用〈清晨〉。四更约在凌晨一点到三点，六点已是清晨。"}, {"text": "晚上七点，我们四更就吃了晚饭。", "explanation": "这里应该用〈傍晚〉。四更约在凌晨一点到三点，与用餐时间无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03082593-bfae-47ac-8eda-e4b23f65def1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88004, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "四更", "is_correct": true, "explanation": "正确：四更排在第四，与“一夜分成五更”的说法相符。"}, {"text": "三更", "is_correct": false, "explanation": "语义：三更是第三更，与“排在第四”矛盾。"}, {"text": "五更", "is_correct": false, "explanation": "语义：五更是第五更，与“排在第四”矛盾。"}, {"text": "子时", "is_correct": false, "explanation": "语义：子时是十二时辰的名称，不是五更中的一更，与“排在第四”不符。"}], "explanations": {"四更": "正确：四更排在第四，与“一夜分成五更”的说法相符。", "三更": "语义：三更是第三更，与“排在第四”矛盾。", "五更": "语义：五更是第五更，与“排在第四”矛盾。", "子时": "语义：子时是十二时辰的名称，不是五更中的一更，与“排在第四”不符。"}, "sentence_index": 6, "correct_answer": "四更"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "早上八点，学生们四更就到学校了。", "explanation": "这里应该用〈早上〉。四更约在凌晨一点到三点，早上八点不是四更。"}, {"text": "下午三点，他说这是四更，我们去街上玩。", "explanation": "这里应该用〈凌晨〉。四更约在凌晨一点到三点，不是下午的时间。"}, {"text": "他在早市上买了一个四更。", "explanation": "这里应该用〈烧饼〉。四更是夜里的时段，不指可以买的食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03082593-bfae-47ac-8eda-e4b23f65def1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88004, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老先生常在四更的读书，直到天亮。", "corrected_sentence": "老先生常在四更读书，直到天亮。", "error_description": "错误：「常在四更的读书」；正确：「常在四更读书」。时间词「四更」作状语修饰动词，中间不能加「的」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03082593-bfae-47ac-8eda-e4b23f65def1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88004, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他四更的起来，去赶路。", "corrected_sentence": "他四更起来，去赶路。", "error_description": "错误：“四更的起来”；正确：“四更起来”。时间词“四更”作状语修饰动词，与动词之间不能加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03082593-bfae-47ac-8eda-e4b23f65def1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
