INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88005, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "有所是有一点，不是很多。", "primary_collocate": null, "pronunciation": "yǒu suǒ", "ipa": "jou˨˩˦ swo˨˩˦", "syllable_count": 2, "sentences": [{"text": "今天的天气有所好转。", "target_word": "有所", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个月的价格有所下降。", "target_word": "有所", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃了药以后，他的病情有所好转。", "target_word": "有所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最近学习压力有所减轻。", "target_word": "有所", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经过努力，他的成绩有所提高。", "target_word": "有所", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这几天，路上的车有所减少。", "target_word": "有所", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听了老师的话，他的态度有所改变。", "target_word": "有所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比起去年，今年的收入有所增加。", "target_word": "有所", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨停了以后，空气有所改善。", "target_word": "有所", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的汉语比以前有所进步。", "target_word": "有所", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "有所：程度很轻，后接动词，表示有一点变化，不是很多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6ba22e3-4e03-4c26-838e-beb10be1ee6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88005, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有所", "is_correct": true, "explanation": "正确：「有所」表示程度轻微的变化，可以与“好转”搭配。"}, {"text": "严重", "is_correct": false, "explanation": "搭配：“严重”只修饰负面状况，不能用来修饰“好转”。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”多用于否定句，肯定句里不能说“从来好转”。"}, {"text": "一共", "is_correct": false, "explanation": "语义：“一共”表示总计，不能用来描述天气的变化。"}], "explanations": {"有所": "正确：「有所」表示程度轻微的变化，可以与“好转”搭配。", "严重": "搭配：“严重”只修饰负面状况，不能用来修饰“好转”。", "从来": "搭配：“从来”多用于否定句，肯定句里不能说“从来好转”。", "一共": "语义：“一共”表示总计，不能用来描述天气的变化。"}, "sentence_index": 0, "correct_answer": "有所"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今年公司的利润有所翻了十倍。", "explanation": "语义：“有所”表示程度轻微的变化，“翻了十倍”是大幅变化，这里应该用〈大幅〉。"}, {"text": "他的病一夜之间有所痊愈了。", "explanation": "语义：“有所”只表示有一点变化，“痊愈”是彻底恢复，这里应该用〈彻底〉。"}, {"text": "他的口语有所进步，一年内从零基础到能主持节目。", "explanation": "语义：“有所”只表示有一点变化，“从零基础到能主持节目”是巨大变化，两者矛盾，这里应该用〈飞速〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd76affc5-5d36-4fee-9032-b922d0c0d656') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88005, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有所", "is_correct": true, "explanation": "正确：「有所」表示变化的程度轻微，与“改变”搭配自然。"}, {"text": "始终", "is_correct": false, "explanation": "语义：“始终”表示一直不变，与“改变”的变化义矛盾。"}, {"text": "仍然", "is_correct": false, "explanation": "语义：“仍然”表示维持原来的状态，与“改变”矛盾。"}, {"text": "十分", "is_correct": false, "explanation": "搭配：“十分”修饰形容词或心理动词，不能修饰“改变”这样的动词。"}], "explanations": {"有所": "正确：「有所」表示变化的程度轻微，与“改变”搭配自然。", "始终": "语义：“始终”表示一直不变，与“改变”的变化义矛盾。", "仍然": "语义：“仍然”表示维持原来的状态，与“改变”矛盾。", "十分": "搭配：“十分”修饰形容词或心理动词，不能修饰“改变”这样的动词。"}, "sentence_index": 6, "correct_answer": "有所"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次会议以后，大家的工作热情有所高涨，人人都加班到深夜。", "explanation": "语义：“有所”只表示有一点变化，“人人都加班到深夜”说明热情大大高涨，两者矛盾，这里应该用〈空前〉。"}, {"text": "这次改革让公司的销量有所翻倍。", "explanation": "语义：“有所”只表示有一点变化，“翻倍”是数量成倍增加，两者矛盾；应去掉“有所”，说“销量翻了一倍”。"}, {"text": "他的体重有所增加，一个月里胖了二十公斤。", "explanation": "语义：“有所”只表示有一点变化，“一个月胖了二十公斤”是大幅变化，这里应该用〈大幅〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd76affc5-5d36-4fee-9032-b922d0c0d656') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88005, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的成绩有所了下降。", "corrected_sentence": "他的成绩有所下降。", "error_description": "插入错误：“有所”是副词，直接修饰动词，中间不能插入“了”。应说“有所下降”，不能说“有所了下降”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd76affc5-5d36-4fee-9032-b922d0c0d656') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88005, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的脾气有所的改变。", "corrected_sentence": "他的脾气有所改变。", "error_description": "插入错误：“有所”是副词，直接修饰动词，中间不能加“的”。应说“有所改变”，不能说“有所的改变”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd76affc5-5d36-4fee-9032-b922d0c0d656') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
