INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88007, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "行期是要出门走的那一天。", "primary_collocate": null, "pronunciation": "xíng qī", "ipa": "ɕiŋ³⁵ tɕʰi⁵⁵", "syllable_count": 2, "sentences": [{"text": "他的行期定在下周一。", "target_word": "行期", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "行期快到了，她还没收拾行李。", "target_word": "行期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为下雪，我们把行期往后推了两天。", "target_word": "行期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问我行期定了没有。", "target_word": "行期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都想知道你的行期。", "target_word": "行期", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "行期临近，妈妈给我准备了很多吃的。", "target_word": "行期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司通知他行期提前，明天就得走。", "target_word": "行期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的行期是几号？", "target_word": "行期", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "朋友的行期改了，我们没能去送行。", "target_word": "行期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "行期定下来，我就订机票。", "target_word": "行期", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "要出门走的那一天，指动身的日子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d977b55-e838-4148-b0e4-160dae9a063e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88007, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "行期", "is_correct": true, "explanation": "行期（xíng qī）指出发、动身的日子，是本词的读音和意思。"}, {"text": "星期", "is_correct": false, "explanation": "xīng（第一声）与 xíng（第二声）声调不同，意思是星期（周）。"}, {"text": "兴起", "is_correct": false, "explanation": "xīng（第一声）与 xíng（第二声）声调不同，qǐ（第三声）与 qī（第一声）声调不同，意思是兴起、兴盛。"}, {"text": "行棋", "is_correct": false, "explanation": "qí（第二声）与 qī（第一声）声调不同，意思是下棋时走子。"}], "explanations": {"行期": "行期（xíng qī）指出发、动身的日子，是本词的读音和意思。", "星期": "xīng（第一声）与 xíng（第二声）声调不同，意思是星期（周）。", "兴起": "xīng（第一声）与 xíng（第二声）声调不同，qǐ（第三声）与 qī（第一声）声调不同，意思是兴起、兴盛。", "行棋": "qí（第二声）与 qī（第一声）声调不同，意思是下棋时走子。"}, "sentence_index": null, "correct_answer": "行期"}, "level_3": {"options": [{"text": "行期", "is_correct": true, "explanation": "行期是出发的日子，与“他的……定在下周一”的语境相符。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“定在下周一”说的是日期，不能说体重定在某一天。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是人的体貌特征，不能被“定在下周一”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以事先定下来的日子，与句意不符。"}], "explanations": {"行期": "行期是出发的日子，与“他的……定在下周一”的语境相符。", "体重": "搭配：“定在下周一”说的是日期，不能说体重定在某一天。", "身高": "体貌：身高是人的体貌特征，不能被“定在下周一”。", "天气": "语义：天气不是可以事先定下来的日子，与句意不符。"}, "sentence_index": 0, "correct_answer": "行期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次会议的行期定在下周一。", "explanation": "这里应该用〈日期〉。行期只指出发、动身的日子，会议不需要出发，应说“会议日期”。"}, {"text": "我们的考试行期定在下周一。", "explanation": "这里应该用〈时间〉。行期只用于出行的日子，考试不是出发，应说“考试时间”。"}, {"text": "这次旅行的行期很长，我们走了两个星期。", "explanation": "这里应该用〈行程〉。行程指整段旅途，可以说长短；行期只是出发的那一天，不能说“很长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a169f408-7f3b-4f23-b06f-b4e4a7f7c625') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88007, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "行期", "is_correct": true, "explanation": "行期指动身的日子，与“公司通知他……提前”的语境相符。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温不能“提前”，与“公司通知……提前，明天就得走”的语境不符。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“提前”一般搭配时间、日期或计划，不能搭配名字。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气不会“提前”，句子说的是时间安排。"}], "explanations": {"行期": "行期指动身的日子，与“公司通知他……提前”的语境相符。", "体温": "语义：体温不能“提前”，与“公司通知……提前，明天就得走”的语境不符。", "名字": "搭配：“提前”一般搭配时间、日期或计划，不能搭配名字。", "脾气": "语义：脾气不会“提前”，句子说的是时间安排。"}, "sentence_index": 6, "correct_answer": "行期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场比赛的行期定在周六下午。", "explanation": "这里应该用〈时间〉。行期只指出门动身的日子，比赛不是出发，应说“比赛时间”。"}, {"text": "这次旅行的行期很长，一共走了十天。", "explanation": "这里应该用〈行程〉。行程指整段旅途，可以说长短；行期只是动身的那一天。"}, {"text": "妈妈的生日行期是三月五号。", "explanation": "这里应该用〈日期〉或直接说“生日”。行期只用于出门动身的日子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a169f408-7f3b-4f23-b06f-b4e4a7f7c625') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88007, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的行期定了在下个月三号。", "corrected_sentence": "她的行期定在下个月三号。", "error_description": "体标误用。“定在”中间不能插入“了”，结果补语“在”要紧跟动词。错误形式是“定了在”，正确形式是“定在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a169f408-7f3b-4f23-b06f-b4e4a7f7c625') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88007, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "行期推迟在下个星期三。", "corrected_sentence": "行期推迟到下个星期三。", "error_description": "介词用错。“推迟”后引出新的时间要用“到”，不能用“在”。错误形式是“推迟在”，正确形式是“推迟到”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a169f408-7f3b-4f23-b06f-b4e4a7f7c625') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
