INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88010, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "介词，表示目的或原因；为了。", "primary_collocate": null, "pronunciation": "wèi zhe", "ipa": "weɪ˥˩ tʂə", "syllable_count": 2, "sentences": [{"text": "为着考上好大学，她每天学习到十二点。", "target_word": "为着", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们为着明年的比赛，现在就开始练习。", "target_word": "为着", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他为着多挣一点钱，又找了一份工作。", "target_word": "为着", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为着保护环境，很多人不用塑料袋。", "target_word": "为着", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司为着省钱，把旧电脑修了一下。", "target_word": "为着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为着早点到家，他坐了最快的火车。", "target_word": "为着", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民为着多收粮食，天不亮就下地了。", "target_word": "为着", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为着不迟到，我六点就起床了。", "target_word": "为着", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她为着学好中文，去了北京。", "target_word": "为着", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为着让孩子睡好，大家说话都很小声。", "target_word": "为着", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "介词，引出行动的目的，相当于“为了”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7334b5cb-6336-4b25-86db-f1f85bdb5c03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88010, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "为着", "is_correct": true, "explanation": "为着 wèi zhe，介词，表示行动的目的，相当于“为了”。"}, {"text": "围着", "is_correct": false, "explanation": "wéi（第二声）与 wèi（第四声）声调不同，意思是围绕，不是为着。"}, {"text": "偎着", "is_correct": false, "explanation": "wēi（第一声）与 wèi（第四声）声调不同，意思是靠近、依偎。"}, {"text": "问着", "is_correct": false, "explanation": "wèn 与 wèi 的韵母不同（-en 与 -ei），意思是询问。"}, {"text": "背着", "is_correct": false, "explanation": "bèi 与 wèi 的声母不同（b 与 w），意思是背负。"}, {"text": "配着", "is_correct": false, "explanation": "pèi 与 wèi 的声母不同（p 与 w），意思是搭配。"}], "explanations": {"为着": "为着 wèi zhe，介词，表示行动的目的，相当于“为了”。", "围着": "wéi（第二声）与 wèi（第四声）声调不同，意思是围绕，不是为着。", "偎着": "wēi（第一声）与 wèi（第四声）声调不同，意思是靠近、依偎。", "问着": "wèn 与 wèi 的韵母不同（-en 与 -ei），意思是询问。", "背着": "bèi 与 wèi 的声母不同（b 与 w），意思是背负。", "配着": "pèi 与 wèi 的声母不同（p 与 w），意思是搭配。"}, "sentence_index": null, "correct_answer": "为着"}, "level_3": {"options": [{"text": "为着", "is_correct": true, "explanation": "正确：“为着”表示为了考上好大学，与句意相合。"}, {"text": "被", "is_correct": false, "explanation": "配价：“被”要接动词表示被动，“被考上好大学”不成立。"}, {"text": "跟", "is_correct": false, "explanation": "语义：“跟”引出一起行动的对象，不能表示学习的目的。"}, {"text": "向", "is_correct": false, "explanation": "语义：“向”表示方向或对象，不能引出学习的目的。"}], "explanations": {"为着": "正确：“为着”表示为了考上好大学，与句意相合。", "被": "配价：“被”要接动词表示被动，“被考上好大学”不成立。", "跟": "语义：“跟”引出一起行动的对象，不能表示学习的目的。", "向": "语义：“向”表示方向或对象，不能引出学习的目的。"}, "sentence_index": 0, "correct_answer": "为着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "为着努力，他考上了大学。", "explanation": "这里应该用〈凭着〉。表示靠某种手段做成某事要用〈凭着〉，“为着”表示为了某个目的，不表示凭借。"}, {"text": "为着年龄增长，他变得更成熟了。", "explanation": "这里应该用〈随着〉。表示伴随某种变化而发展要用〈随着〉，“为着”表示目的或原因，不表示伴随。"}, {"text": "为着一个月，他瘦了五斤。", "explanation": "这里应该用〈经过〉。表示时间的推移要用〈经过〉，“为着”表示为了某个目的，不表示时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08bae48c-bdbd-4008-9ada-ec916504e82b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88010, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "为着", "is_correct": true, "explanation": "正确：“为着”表示为了多收粮食，与句意相合。"}, {"text": "从", "is_correct": false, "explanation": "语义：“从”表示起点或来源，不表示目的，“从多收粮食”说不通。"}, {"text": "把", "is_correct": false, "explanation": "配价：“把”后要接动词构成处置式，“把多收粮食”之后没有谓语。"}, {"text": "对", "is_correct": false, "explanation": "语义：“对”引出对象或态度，不能表示为了多收粮食。"}], "explanations": {"为着": "正确：“为着”表示为了多收粮食，与句意相合。", "从": "语义：“从”表示起点或来源，不表示目的，“从多收粮食”说不通。", "把": "配价：“把”后要接动词构成处置式，“把多收粮食”之后没有谓语。", "对": "语义：“对”引出对象或态度，不能表示为了多收粮食。"}, "sentence_index": 6, "correct_answer": "为着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈为着厨房做饭。", "explanation": "这里应该用〈在〉。表示在什么地方做事要用〈在〉，“为着”表示为了某个目的，不表示地点。"}, {"text": "他为着图书馆看书。", "explanation": "这里应该用〈在〉。表示在哪里做事要用〈在〉，“为着”不表示地点。"}, {"text": "她为着半小时，写了三页作业。", "explanation": "这里应该用〈用〉。表示花费时间去做事要用〈用〉，“为着”表示为了某个目的，不表示用时。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08bae48c-bdbd-4008-9ada-ec916504e82b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88010, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈为着了孩子，推迟了假期。", "corrected_sentence": "妈妈为着孩子，推迟了假期。", "error_description": "错误形式：“为着”后多加“了”，写成“为着了孩子”。正确形式：“为着孩子”，表示为了孩子；介词“为着”后不能直接加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08bae48c-bdbd-4008-9ada-ec916504e82b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88010, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爸爸很为着女儿，每天早起做饭。", "corrected_sentence": "爸爸为着女儿，每天早起做饭。", "error_description": "错误形式：程度副词“很”修饰了介词“为着”，写成“很为着女儿”。正确形式：“爸爸为着女儿”，“为着”是介词，不能被“很”修饰。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08bae48c-bdbd-4008-9ada-ec916504e82b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
