INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88012, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "境况或程度（多指不好的）。", "primary_collocate": null, "pronunciation": "dì bù", "ipa": "ti˥˩ pu˥˩", "syllable_count": 2, "sentences": [{"text": "没想到他的病已经到了这个地步。", "target_word": "地步", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你怎么把自己弄到这种地步？", "target_word": "地步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们吵到了动手打人的地步。", "target_word": "地步", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "事情都到了这个地步，别再说了。", "target_word": "地步", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他忙到了几天没睡觉的地步。", "target_word": "地步", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他最近瘦得厉害，已经到了让人担心的地步。", "target_word": "地步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家小店生意差到了快关门的地步。", "target_word": "地步", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的关系还没有坏到这种地步。", "target_word": "地步", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他生气到了说不出话的地步。", "target_word": "地步", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他怕老师怕到了不敢上课的地步。", "target_word": "地步", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "境况或程度，多指不好的，常用在「到这个地步」「到了……的地步」中", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3aa1c745-16a8-430c-a276-d96c4b94600f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88012, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地步", "is_correct": true, "explanation": "「地步」指病情发展到的境况，与「到了这个」搭配，表示病已到这种程度。"}, {"text": "地方", "is_correct": false, "explanation": "语义：「地方」指场所，病不能「到了这个地方」。"}, {"text": "年纪", "is_correct": false, "explanation": "搭配：「年纪」说岁数，不能与「病」搭配。"}, {"text": "位置", "is_correct": false, "explanation": "语义：「位置」指所在的地点或职位，不能表示病情的状况。"}], "explanations": {"地步": "「地步」指病情发展到的境况，与「到了这个」搭配，表示病已到这种程度。", "地方": "语义：「地方」指场所，病不能「到了这个地方」。", "年纪": "搭配：「年纪」说岁数，不能与「病」搭配。", "位置": "语义：「位置」指所在的地点或职位，不能表示病情的状况。"}, "sentence_index": 0, "correct_answer": "地步"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个地步很安静，适合看书。", "explanation": "这里应该用〈地方〉。「地步」指事情的境况或程度，不指场所。"}, {"text": "这家店有三个地步。", "explanation": "这里不能用〈地步〉计数，「地步」指情况，应改用〈三种情况〉。"}, {"text": "我们认识的地步很久了。", "explanation": "这里不能用〈地步〉表示时间的长短，「地步」指程度，应改用〈时间〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bf9f4a-2139-4935-8242-9082b6980e5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88012, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地步", "is_correct": true, "explanation": "「地步」指生意差到的程度，与「快关门」相合。"}, {"text": "身份", "is_correct": false, "explanation": "语义：「身份」指人的资格，不能用来说生意的状况。"}, {"text": "气候", "is_correct": false, "explanation": "语义：「气候」指天气的长期情况，与「生意差」无关。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：「脾气」说人的性格，不用来形容生意。"}], "explanations": {"地步": "「地步」指生意差到的程度，与「快关门」相合。", "身份": "语义：「身份」指人的资格，不能用来说生意的状况。", "气候": "语义：「气候」指天气的长期情况，与「生意差」无关。", "脾气": "搭配：「脾气」说人的性格，不用来形容生意。"}, "sentence_index": 6, "correct_answer": "地步"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这里的地步很平，适合打篮球。", "explanation": "这里不能用〈地步〉指地面，「地步」指境况或程度，应改用〈场地〉。"}, {"text": "这双鞋的地步很贵。", "explanation": "这里不能用〈地步〉表示价格，「地步」指境况或程度，应改用〈价格〉。"}, {"text": "妈妈的地步很开心。", "explanation": "这里不能用〈地步〉形容人的心情，「地步」指事情的境况，应直接说〈妈妈很开心〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bf9f4a-2139-4935-8242-9082b6980e5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88012, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的脾气坏了这个地步。", "corrected_sentence": "他的脾气坏到了这个地步。", "error_description": "「坏到了」中的「到」不能省，应为「坏到了这个地步」。缺少「到」是常见错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bf9f4a-2139-4935-8242-9082b6980e5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88012, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这场病拖到了无法治疗的一只地步。", "corrected_sentence": "这场病拖到了无法治疗的地步。", "error_description": "「地步」前面不能用量词「只」，这里的「一只」是错误的量词，应去掉，写成「无法治疗的地步」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bf9f4a-2139-4935-8242-9082b6980e5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
