INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88013, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "裁定是有权的人看过事情以后，决定谁对谁错。", "primary_collocate": null, "pronunciation": "cái dìng", "ipa": "tsʰai˧˥ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "裁判裁定这个球不算进。", "target_word": "裁定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师看完以后，裁定小李是对的。", "target_word": "裁定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "委员会裁定这次比赛有效。", "target_word": "裁定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长裁定，错的是小王。", "target_word": "裁定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家吵了很久，最后由主任裁定。", "target_word": "裁定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "裁判看了录像，裁定他犯规了。", "target_word": "裁定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理听完两个人的话，裁定小张没错。", "target_word": "裁定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家小组裁定这幅画是真的。", "target_word": "裁定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们请老人来裁定这件事。", "target_word": "裁定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "协会已经裁定这场比赛结果有效。", "target_word": "裁定", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "裁定了", "label": "体标"}, {"form": "裁定过", "label": "体标"}, {"form": "裁定书", "label": "复合"}], "register": "书面", "sense_fingerprint": "有权的人了解情况后判定谁对谁错", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3cfd08e-3d21-43ff-b039-b447ed2d2985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88013, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "裁定", "is_correct": true, "explanation": "正确：裁判对进球是否有效作出判断，符合「裁定……不算进」的用法。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：「吃」的对象是食物，「这个球」不能被吃。"}, {"text": "生病", "is_correct": false, "explanation": "配价：「生病」是不及物动词，不能带「这个球」作宾语。"}, {"text": "参加", "is_correct": false, "explanation": "语义：「参加」针对活动或集体，不能用来判断球算不算进。"}], "explanations": {"裁定": "正确：裁判对进球是否有效作出判断，符合「裁定……不算进」的用法。", "吃": "搭配：「吃」的对象是食物，「这个球」不能被吃。", "生病": "配价：「生病」是不及物动词，不能带「这个球」作宾语。", "参加": "语义：「参加」针对活动或集体，不能用来判断球算不算进。"}, "sentence_index": 0, "correct_answer": "裁定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师裁定小李的作文打了九十分。", "explanation": "这里应该用〈评定〉。裁定用于判断谁对谁错、是否有效；给作文打分、评定等级要用评定。"}, {"text": "老师裁定这个班一共有四十个学生。", "explanation": "这里应该用〈统计〉。裁定是对谁对谁错作出判断，说明班里有多少学生要用统计。"}, {"text": "老师裁定今天的午饭很好吃。", "explanation": "这里应该用〈评论〉。裁定用于判断对错或是否有效，对午饭好不好吃的看法要用评论。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd21417dd-c9f1-4c61-b777-aa96f07bf1b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88013, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "裁定", "is_correct": true, "explanation": "正确：「裁定」指判断谁对谁错，「经理……裁定小张没错」自然。"}, {"text": "翻译", "is_correct": false, "explanation": "搭配：「翻译」的对象是文字或话语，不能带「小张没错」这样的判断。"}, {"text": "站", "is_correct": false, "explanation": "配价：「站」是不及物动词，不能带「小张」作宾语。"}, {"text": "梦见", "is_correct": false, "explanation": "语义：「梦见」指睡梦中见到，与听完两人的话后作判断无关。"}], "explanations": {"裁定": "正确：「裁定」指判断谁对谁错，「经理……裁定小张没错」自然。", "翻译": "搭配：「翻译」的对象是文字或话语，不能带「小张没错」这样的判断。", "站": "配价：「站」是不及物动词，不能带「小张」作宾语。", "梦见": "语义：「梦见」指睡梦中见到，与听完两人的话后作判断无关。"}, "sentence_index": 6, "correct_answer": "裁定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "协会裁定明天的股价会上涨。", "explanation": "这里应该用〈预测〉。裁定是判断对错或是否有效，对未来股价走势的推测要用预测。"}, {"text": "老师裁定这幅画的颜色很漂亮。", "explanation": "这里应该用〈评价〉。裁定用于判断对错或是否有效，对画面颜色好坏的看法要用评价。"}, {"text": "协会裁定今天的天气很好。", "explanation": "这里应该用〈预报〉。裁定用于判断对错或是否有效，天气情况要用预报。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd21417dd-c9f1-4c61-b777-aa96f07bf1b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88013, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "裁判了裁定这次进球无效。", "corrected_sentence": "裁判裁定这次进球无效。", "error_description": "错误：「了」放在动词「裁定」前面，位置不对。「了」是动态助词，应放在动词后，即「裁判裁定了这次进球无效」；不带「了」时应说「裁判裁定这次进球无效」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd21417dd-c9f1-4c61-b777-aa96f07bf1b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88013, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "仲裁委员会裁定着双方的合同有效。", "corrected_sentence": "仲裁委员会裁定双方的合同有效。", "error_description": "错误：「着」表示动作持续或状态保持，但「裁定」是一次性作出的判断，不能加「着」。应去掉「着」，说「仲裁委员会裁定双方的合同有效」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd21417dd-c9f1-4c61-b777-aa96f07bf1b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
