INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88014, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd21417dd-c9f1-4c61-b777-aa96f07bf1b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88014, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "法院或有权机关对案件或争议作出判断和决定。", "primary_collocate": null, "pronunciation": "cái dìng", "ipa": "tsʰai˧˥ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "法院裁定冻结这家公司的银行存款。", "target_word": "裁定", "complexity_tier": "T3", "furigana": "fǎyuàn cáidìng dòngjié zhè jiā gōngsī de yínháng cúnkuǎn", "sentence_source": "generated"}, {"text": "法官昨天裁定，这个案子重新审理。", "target_word": "裁定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院裁定驳回他的上诉。", "target_word": "裁定", "complexity_tier": "T3", "furigana": "fǎyuàn cáidìng bóhuí tā de shàngsù", "sentence_source": "generated"}, {"text": "对这件事，法院还没有裁定。", "target_word": "裁定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院裁定中止本案审理。", "target_word": "裁定", "complexity_tier": "T3", "furigana": "fǎyuàn cáidìng zhōngzhǐ běn àn shěnlǐ", "sentence_source": "generated"}, {"text": "法院裁定准许他撤回起诉。", "target_word": "裁定", "complexity_tier": "T3", "furigana": "fǎyuàn cáidìng zhǔnxǔ tā chèhuí qǐsù", "sentence_source": "generated"}, {"text": "法院裁定撤销原判，发回重审。", "target_word": "裁定", "complexity_tier": "T3", "furigana": "fǎyuàn cáidìng chèxiāo yuánpàn, fāhuí chóngshěn", "sentence_source": "generated"}, {"text": "法院裁定后，他马上交了钱。", "target_word": "裁定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院裁定驳回了被告的申请。", "target_word": "裁定", "complexity_tier": "T3", "furigana": "fǎyuàn cáidìng bóhuí le bèigào de shēnqǐng", "sentence_source": "generated"}, {"text": "法院以前裁定过这样的争议。", "target_word": "裁定", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "裁定了", "label": "体标"}, {"form": "裁定过", "label": "体标"}, {"form": "裁定书", "label": "复合"}], "register": "书面", "sense_fingerprint": "法院等机关对案件、争议作出判断和决定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3cfd08e-3d21-43ff-b039-b447ed2d2985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88014, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "裁定", "is_correct": true, "explanation": "正确：法院对冻结存款这类程序性事项作出裁定，符合「法院裁定冻结」的用法。"}, {"text": "批评", "is_correct": false, "explanation": "语义：「批评」针对人或行为发表意见，法院不能用它来冻结银行存款。"}, {"text": "购买", "is_correct": false, "explanation": "搭配：「购买」的对象是商品，「银行存款」不能被购买。"}, {"text": "弄", "is_correct": false, "explanation": "语域：「弄」是口语，法律文书中表示法院的强制措施时不用它。"}], "explanations": {"裁定": "正确：法院对冻结存款这类程序性事项作出裁定，符合「法院裁定冻结」的用法。", "批评": "语义：「批评」针对人或行为发表意见，法院不能用它来冻结银行存款。", "购买": "搭配：「购买」的对象是商品，「银行存款」不能被购买。", "弄": "语域：「弄」是口语，法律文书中表示法院的强制措施时不用它。"}, "sentence_index": 0, "correct_answer": "裁定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "法院裁定他犯了盗窃罪，判处三年有期徒刑。", "explanation": "这里应该用〈判决〉。裁定只处理程序问题，对被告定罪和判处刑罚要用判决。"}, {"text": "裁缝用这块布裁定了一件外套。", "explanation": "这里应该用〈裁剪〉。裁定指法院或有权机关作出判断，裁剪是把布料剪开做衣服。"}, {"text": "法院裁定这家店的饭很好吃。", "explanation": "这里应该用〈评论〉。裁定只能用于案件或争议的判断，对饭菜好吃与否的看法要用评论。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd21417dd-c9f1-4c61-b777-aa96f07bf1b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88014, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "裁定", "is_correct": true, "explanation": "正确：「裁定」用于撤销原判、发回重审这类程序决定。"}, {"text": "申请", "is_correct": false, "explanation": "语义：「申请」是当事人提出请求，法院不会「申请」撤销原判。"}, {"text": "发生", "is_correct": false, "explanation": "配价：「发生」是不及物动词，不能带「撤销原判」作宾语。"}, {"text": "逮捕", "is_correct": false, "explanation": "搭配：「逮捕」的对象是人，「原判」不能被逮捕。"}], "explanations": {"裁定": "正确：「裁定」用于撤销原判、发回重审这类程序决定。", "申请": "语义：「申请」是当事人提出请求，法院不会「申请」撤销原判。", "发生": "配价：「发生」是不及物动词，不能带「撤销原判」作宾语。", "逮捕": "搭配：「逮捕」的对象是人，「原判」不能被逮捕。"}, "sentence_index": 6, "correct_answer": "裁定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "法院裁定这部电影很好看。", "explanation": "这里应该用〈评价〉。裁定用于判断案件或争议的是非，对电影好看与否的看法要用评价。"}, {"text": "法院裁定他无罪，当场释放。", "explanation": "这里应该用〈宣判〉。裁定处理程序问题；对被告有罪或无罪的结论要用宣判或判决。"}, {"text": "法院裁定今天会下雨。", "explanation": "这里应该用〈预报〉。裁定用于对案件或争议作出决定，对天气作预测要用预报。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd21417dd-c9f1-4c61-b777-aa96f07bf1b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88014, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "法院了裁定驳回原告的请求。", "corrected_sentence": "法院裁定驳回原告的请求。", "error_description": "错误：「了」放在动词「裁定」前面，位置不对。「了」是动态助词，只能放在动词之后，不能放在动词之前；本句应直接说「法院裁定驳回原告的请求」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd21417dd-c9f1-4c61-b777-aa96f07bf1b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88014, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "法院发出了一只裁定，准许原告撤诉。", "corrected_sentence": "法院发出了一份裁定，准许原告撤诉。", "error_description": "错误：「裁定」指裁定书时，量词应用「份」，不用「只」。「只」用于动物或成对物品中的单个，不用于文件。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd21417dd-c9f1-4c61-b777-aa96f07bf1b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
