INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88016, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "互联网上网页的地址。", "primary_collocate": null, "pronunciation": "wǎng zhǐ", "ipa": "wɑŋ˨˩ ʈʂʅ˨˩", "syllable_count": 2, "sentences": [{"text": "请把你的网址发给我。", "target_word": "网址", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个网址我记不住，太长了。", "target_word": "网址", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你在这里输入网址，就能打开网页。", "target_word": "网址", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上写了学校的网址。", "target_word": "网址", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我用手机扫一下，就能看到这个网址。", "target_word": "网址", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个网址打不开，你再试一下。", "target_word": "网址", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "名片上有公司的电话和网址。", "target_word": "网址", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把新网站的网址告诉了朋友。", "target_word": "网址", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "浏览器上面的网址是错的。", "target_word": "网址", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把网址复制到这个空格里。", "target_word": "网址", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "网址栏", "label": "复合词"}, {"form": "網址", "label": "繁体"}], "register": "中性", "sense_fingerprint": "互联网上某个网页的地址", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc845970-b582-4cbd-8bfb-d42e50e4b40f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88016, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "网址", "is_correct": true, "explanation": "正确：“发给我”的可以是网址，网址是网页的地址，可以发送给别人。"}, {"text": "座位", "is_correct": false, "explanation": "语义：座位是实际的座椅位置，不能像消息一样“发给”别人。"}, {"text": "眼镜", "is_correct": false, "explanation": "语义：眼镜是实物，不能像消息一样发过去。"}, {"text": "脚印", "is_correct": false, "explanation": "语义：脚印是走过留下的痕迹，不能被发送。"}], "explanations": {"网址": "正确：“发给我”的可以是网址，网址是网页的地址，可以发送给别人。", "座位": "语义：座位是实际的座椅位置，不能像消息一样“发给”别人。", "眼镜": "语义：眼镜是实物，不能像消息一样发过去。", "脚印": "语义：脚印是走过留下的痕迹，不能被发送。"}, "sentence_index": 0, "correct_answer": "网址"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在信封上写了我家的网址。", "explanation": "这里应该用〈地址〉。写在信封上的是住址，网址指网页的地址，不能指家的位置。"}, {"text": "他忘了带网址，进不了门。", "explanation": "这里应该用〈钥匙〉。钥匙用来开门；网址是网页的地址，不能用来开门。"}, {"text": "这间教室的网址是三楼二号。", "explanation": "这里应该用〈门牌号〉。门牌号标明房间的位置；网址是网页的地址，不能用来指教室。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fbc760a-f0a4-4dab-8306-53e9ab979a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88016, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "网址", "is_correct": true, "explanation": "正确：名片上印的电话和网址都是联系方式，网址与“电话”并列。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不属于联系方式，不会与电话一起印在名片上。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄不是名片上的联系信息。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高不是联系信息，不会与电话并列印在名片上。"}], "explanations": {"网址": "正确：名片上印的电话和网址都是联系方式，网址与“电话”并列。", "颜色": "语义：颜色不属于联系方式，不会与电话一起印在名片上。", "年龄": "语义：年龄不是名片上的联系信息。", "身高": "语义：身高不是联系信息，不会与电话并列印在名片上。"}, "sentence_index": 6, "correct_answer": "网址"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个网址很重，我一个人抬不动。", "explanation": "这里应该用〈包裹〉。包裹有重量，可以很重；网址是网页的地址，没有重量，不能用“很重”形容。"}, {"text": "这件衣服的网址是两百块钱。", "explanation": "这里应该用〈价格〉。说多少钱要用价格；网址是网页的地址，不能用来表示钱数。"}, {"text": "这辆车的网址很好记。", "explanation": "这里应该用〈车牌号〉。车牌号是车辆的编号，可以好记；网址是网页的地址，不能用来指车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fbc760a-f0a4-4dab-8306-53e9ab979a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88016, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请把这本网址输入到网址栏里。", "corrected_sentence": "请把这个网址输入到网址栏里。", "error_description": "量词错误：网址的量词是“个”，应说“这个网址”；“本”用于书册，不能修饰网址。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fbc760a-f0a4-4dab-8306-53e9ab979a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88016, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我已经把这本网址复制到笔记本上了。", "corrected_sentence": "我已经把这个网址复制到笔记本上了。", "error_description": "量词错误：网址的量词是“个”，应说“这个网址”；“本”用于书册，不能修饰网址。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fbc760a-f0a4-4dab-8306-53e9ab979a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
