INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88017, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "均分是把东西分成一样多的几份。", "primary_collocate": null, "pronunciation": "jūn fēn", "ipa": "tɕyn˥ fən˥", "syllable_count": 2, "sentences": [{"text": "我们把蛋糕均分成了四份。", "target_word": "均分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把一块巧克力均分成两半。", "target_word": "均分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把这瓶水均分成三杯。", "target_word": "均分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把一张纸均分成了六小块。", "target_word": "均分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条绳子要均分成五段。", "target_word": "均分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥把西瓜均分成三块。", "target_word": "均分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把披萨均分了，每人两块。", "target_word": "均分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把这些糖均分成四堆吧。", "target_word": "均分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把二十本书均分成四摞。", "target_word": "均分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把这块地均分成两块。", "target_word": "均分", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "均分了", "label": "完成体"}, {"form": "均分过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "均分·把一个东西切分成相等的几份", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03c657c1-bea8-4c65-833c-a2de6b45be3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88017, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "均分", "is_correct": true, "explanation": "正确答案。“均分成了四份”指把蛋糕平均分成四份，与句意相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能带“成了四份”这种分割结果补语，“吃成四份”不成话。"}, {"text": "合", "is_correct": false, "explanation": "语义：“合”指合拢，与“分成四份”的方向相反，不合句意。"}, {"text": "买", "is_correct": false, "explanation": "搭配：“买”不能带“成了四份”这种分割结果，“买成四份”不通。"}], "explanations": {"均分": "正确答案。“均分成了四份”指把蛋糕平均分成四份，与句意相符。", "吃": "搭配：“吃”不能带“成了四份”这种分割结果补语，“吃成四份”不成话。", "合": "语义：“合”指合拢，与“分成四份”的方向相反，不合句意。", "买": "搭配：“买”不能带“成了四份”这种分割结果，“买成四份”不通。"}, "sentence_index": 0, "correct_answer": "均分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把一块蛋糕均分了，一大块给了哥哥，一小块给了弟弟。", "explanation": "这里各份不等，应该用〈切开〉。均分要求各份相等，不能用于这种分法。"}, {"text": "他们把两个吵架的孩子均分开了。", "explanation": "这里应该用〈拉开〉。均分指把同一事物平均分成几份，不能用于把人分开。"}, {"text": "他把这块饼均分了，但哥哥拿得比弟弟多。", "explanation": "这里份额不均，应该用〈分〉，不能用均分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'baba176c-b06f-47ee-846e-bf158efe36e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88017, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "均分", "is_correct": true, "explanation": "正确答案。“他们把披萨均分了”指把披萨平均分给大家，与“每人两块”相符。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”表示丢弃，与“每人两块”的分配结果矛盾。"}, {"text": "浪费", "is_correct": false, "explanation": "语义：“浪费”指白白耗费，与“每人两块”的分配语境不合。"}, {"text": "烧", "is_correct": false, "explanation": "搭配：“烧”指加热或烧毁，不与“每人两块”这类分配结果搭配。"}], "explanations": {"均分": "正确答案。“他们把披萨均分了”指把披萨平均分给大家，与“每人两块”相符。", "扔": "语义：“扔”表示丢弃，与“每人两块”的分配结果矛盾。", "浪费": "语义：“浪费”指白白耗费，与“每人两块”的分配语境不合。", "烧": "搭配：“烧”指加热或烧毁，不与“每人两块”这类分配结果搭配。"}, "sentence_index": 6, "correct_answer": "均分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我想把这个人均分成两块。", "explanation": "这里应该用〈分开〉，不能用均分来指把人切成几份。"}, {"text": "我想把这块地均分成一块。", "explanation": "这里只剩一份，应该用〈保留〉，不能用均分。"}, {"text": "我想把这块地均分给我自己一个人。", "explanation": "这里应该用〈全部给〉，不能用均分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'baba176c-b06f-47ee-846e-bf158efe36e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88017, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈把这块布均分成了三段，每段都不一样长。", "corrected_sentence": "妈妈把这块布均分成了三段，每段都一样长。", "error_description": "“均分”要求各份相等，“每段都不一样长”与之矛盾。应改为“每段都一样长”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'baba176c-b06f-47ee-846e-bf158efe36e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88017, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把这条绳子均分了五段。", "corrected_sentence": "他把这条绳子均分成了五段。", "error_description": "“均分”表示分成几份时要带结果补语“成”，应说“均分成了五段”。错误形式：均分了五段；正确形式：均分成了五段。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'baba176c-b06f-47ee-846e-bf158efe36e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
