INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88018, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把钱、利润、任务等平均分配给众人。", "primary_collocate": null, "pronunciation": "jūn fēn", "ipa": "tɕyn˥ fən˥", "syllable_count": 2, "sentences": [{"text": "兄弟俩把父母留下的钱均分了。", "target_word": "均分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔奖金由大家均分。", "target_word": "均分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司把利润均分给每个员工。", "target_word": "均分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把工作均分，每人做一半。", "target_word": "均分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房租由三个人均分。", "target_word": "均分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把比赛的奖金均分了。", "target_word": "均分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "活动费用我们五个人均分吧。", "target_word": "均分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家务活儿应该夫妻均分。", "target_word": "均分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些任务请你们三个人均分。", "target_word": "均分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把这次的收入均分给大家。", "target_word": "均分", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "均分了", "label": "完成体"}, {"form": "均分过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "均分·把钱、利润、任务等平均分配给众人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03c657c1-bea8-4c65-833c-a2de6b45be3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88018, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "均分", "is_correct": true, "explanation": "正确答案。“均分”指平均分配，兄弟俩分父母留下的钱，与句意相符。"}, {"text": "独占", "is_correct": false, "explanation": "语义：“独占”指一人全部占有，与“兄弟俩”两人共享的语境矛盾。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”指烧毁，兄弟俩不会把父母留下的钱烧了来分，与句意不合。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”指丢弃，与兄弟俩分配父母留下的钱的语境不合。"}], "explanations": {"均分": "正确答案。“均分”指平均分配，兄弟俩分父母留下的钱，与句意相符。", "独占": "语义：“独占”指一人全部占有，与“兄弟俩”两人共享的语境矛盾。", "烧": "语义：“烧”指烧毁，兄弟俩不会把父母留下的钱烧了来分，与句意不合。", "扔": "语义：“扔”指丢弃，与兄弟俩分配父母留下的钱的语境不合。"}, "sentence_index": 0, "correct_answer": "均分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们把奖金均分了，老板拿得最多。", "explanation": "这里份额不等，应该用〈分配〉，不能用均分。"}, {"text": "他一个人把奖金均分了。", "explanation": "这里应该用〈独吞〉。均分需要分给多人，不能用于一人独得。"}, {"text": "老板把利润均分给了自己，员工一分钱也没拿到。", "explanation": "这里应该用〈独占〉，不能用均分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'baba176c-b06f-47ee-846e-bf158efe36e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88018, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "均分", "is_correct": true, "explanation": "正确答案。“活动费用我们五个人均分吧”指五人平摊费用，与句意相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“费用”不能“吃”，与分摊费用的语境不合。"}, {"text": "睡", "is_correct": false, "explanation": "搭配：“睡”是不及物动作，不能以“活动费用”为对象。"}, {"text": "免", "is_correct": false, "explanation": "配价：“免”需要说明免除什么，这里“免吧”缺少对象，不成句。"}], "explanations": {"均分": "正确答案。“活动费用我们五个人均分吧”指五人平摊费用，与句意相符。", "吃": "搭配：“费用”不能“吃”，与分摊费用的语境不合。", "睡": "搭配：“睡”是不及物动作，不能以“活动费用”为对象。", "免": "配价：“免”需要说明免除什么，这里“免吧”缺少对象，不成句。"}, "sentence_index": 6, "correct_answer": "均分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "把这次的收入均分成一份，交给大家。", "explanation": "这里只有一整份，应该用〈整笔〉，不能用均分。"}, {"text": "把这次的收入均分给老板。", "explanation": "这里应该用〈全部交给〉，不能用均分。"}, {"text": "把这次的收入均分给大家，但有人一分钱也没拿到。", "explanation": "这里份额不均，应该用〈随便分〉，不能用均分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'baba176c-b06f-47ee-846e-bf158efe36e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88018, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校把这笔补助均分了给每个班。", "corrected_sentence": "学校把这笔补助均分给了每个班。", "error_description": "“了”表示动作已完成，应放在“给”之后，说“均分给了”。错误形式：均分了给；正确形式：均分给了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'baba176c-b06f-47ee-846e-bf158efe36e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88018, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们把这笔奖金均分每个人。", "corrected_sentence": "他们把这笔奖金均分给了每个人。", "error_description": "“均分”带接受者时要用“均分给”，漏了“给”，“均分每个人”不成句。错误形式：均分每个人；正确形式：均分给（了）每个人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'baba176c-b06f-47ee-846e-bf158efe36e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
