INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88019, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "见报是事情登在报纸上，大家都能看到。", "primary_collocate": null, "pronunciation": "jiàn bào", "ipa": "tɕi̯ɛn˥˩ pɑʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "这件事见报以后，全城的人都知道了。", "target_word": "见报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做的好事见报了，邻居们都夸他。", "target_word": "见报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的故事见报后，很多人都来学校看他。", "target_word": "见报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王的消息见报了，大家都在谈论。", "target_word": "见报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事情一见报，电话就响个不停。", "target_word": "见报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说这件小事不用见报。", "target_word": "见报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个好办法见报以后，大家都来学。", "target_word": "见报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那件事昨天见报，今天大家都在说。", "target_word": "见报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她救人的事见报了，很多人都很感动。", "target_word": "见报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想让这件丑事见报。", "target_word": "见报", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "见报了", "label": "体标"}, {"form": "见过报", "label": "体标"}], "register": "书面", "sense_fingerprint": "事情登在报纸上，让大家都能看到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c338676-2383-4c9c-9a7a-bdb10f081010') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88019, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下班", "is_correct": false, "explanation": "搭配：“下班”的主语只能是人，事情不能“下班”"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：事情不会“咳嗽”，句子读不通"}, {"text": "见报", "is_correct": true, "explanation": "正确：“这件事见报以后，全城的人都知道了”指事情登在报纸上，大家都看到了"}, {"text": "失眠", "is_correct": false, "explanation": "语义：事情不会“失眠”，与句意无关"}], "explanations": {"下班": "搭配：“下班”的主语只能是人，事情不能“下班”", "咳嗽": "语义：事情不会“咳嗽”，句子读不通", "见报": "正确：“这件事见报以后，全城的人都知道了”指事情登在报纸上，大家都看到了", "失眠": "语义：事情不会“失眠”，与句意无关"}, "sentence_index": 0, "correct_answer": "见报"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这些作品昨天在展厅见报。", "explanation": "这里应该用〈展示〉。见报指在报纸上刊出，作品在展厅里陈列要说展示，不能说见报"}, {"text": "这份名单已在食堂见报。", "explanation": "这里应该用〈公示〉。见报指在报纸上刊出，食堂里张贴的名单要说公示，不能说见报"}, {"text": "这首歌在电台见报。", "explanation": "这里应该用〈播出〉。电台通过广播播出节目，不通过报纸，所以不能说见报"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88019, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出差", "is_correct": false, "explanation": "语义：好办法不能去外地“出差”，句意不通"}, {"text": "结婚", "is_correct": false, "explanation": "搭配：“结婚”的主语只能是人，办法不能“结婚”"}, {"text": "见报", "is_correct": true, "explanation": "正确：“这个好办法见报以后，大家都来学”指好办法登在报纸上，让大家看到"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：办法不会“睡觉”，与句子的因果关系不合"}], "explanations": {"出差": "语义：好办法不能去外地“出差”，句意不通", "结婚": "搭配：“结婚”的主语只能是人，办法不能“结婚”", "见报": "正确：“这个好办法见报以后，大家都来学”指好办法登在报纸上，让大家看到", "睡觉": "语义：办法不会“睡觉”，与句子的因果关系不合"}, "sentence_index": 6, "correct_answer": "见报"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "考试成绩已在大厅见报。", "explanation": "这里应该用〈张榜〉。见报指在报纸上刊登，贴在大厅的成绩要说张榜"}, {"text": "这段视频在网上迅速见报。", "explanation": "这里应该用〈传播〉。见报只指报纸刊登，网上视频的扩散要说传播"}, {"text": "这部电视剧下个月见报。", "explanation": "这里应该用〈开播〉。电视剧通过屏幕播放，不通过报纸，应说开播"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88019, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事明天见报了，大家都会关注。", "corrected_sentence": "这件事明天见报，大家都会关注。", "error_description": "错误在“见报”后多了“了”。“明天”是将来，“了”表示已经完成，二者不合，应去掉“了”，写作“明天见报”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88019, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他不想让这件事见报着，怕被人知道。", "corrected_sentence": "他不想让这件事见报，怕被人知道。", "error_description": "错误在“见报”后多了“着”。“见报”是一次性的动作，不能带“着”表示持续，应去掉“着”，写作“不想让这件事见报”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
