INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88020, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在报纸上刊登出来。", "primary_collocate": null, "pronunciation": "jiàn bào", "ipa": "tɕi̯ɛn˥˩ pɑʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "这条新闻明天会见报。", "target_word": "见报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写的文章昨天见报了。", "target_word": "见报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的照片见报了，朋友都看到了。", "target_word": "见报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好消息什么时候能见报？", "target_word": "见报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事今天上午就见报了。", "target_word": "见报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的小说第一次见报，他高兴极了。", "target_word": "见报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者说，这篇文章后天见报。", "target_word": "见报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写过很多文章，却从未见报。", "target_word": "见报", "complexity_tier": "T3", "furigana": "jiàn bào", "sentence_source": "generated"}, {"text": "稿子已经交了，下周应该会见报。", "target_word": "见报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那张照片见报以后，很多人来问他。", "target_word": "见报", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "见报了", "label": "体标"}, {"form": "见过报", "label": "体标"}], "register": "书面", "sense_fingerprint": "文章、消息等在报纸上刊登出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c338676-2383-4c9c-9a7a-bdb10f081010') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88020, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出差", "is_correct": false, "explanation": "语义：新闻不能去外地“出差”，句意不通"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：新闻不会“咳嗽”，句子读不通"}, {"text": "见报", "is_correct": true, "explanation": "正确：“这条新闻明天会见报”指新闻明天将在报纸上刊登出来"}, {"text": "结婚", "is_correct": false, "explanation": "搭配：“结婚”的主语必须是人，新闻不能“结婚”"}], "explanations": {"出差": "语义：新闻不能去外地“出差”，句意不通", "咳嗽": "语义：新闻不会“咳嗽”，句子读不通", "见报": "正确：“这条新闻明天会见报”指新闻明天将在报纸上刊登出来", "结婚": "搭配：“结婚”的主语必须是人，新闻不能“结婚”"}, "sentence_index": 0, "correct_answer": "见报"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书去年在北京见报。", "explanation": "这里应该用〈出版〉。见报只指文章、消息在报纸上刊出，书籍要说出版"}, {"text": "这幅画下个月在展览馆见报。", "explanation": "这里应该用〈展出〉。见报只指文章、消息在报纸上刊出，画作在展览馆陈列要说展出，不能说见报"}, {"text": "他的论文刚在核心期刊见报。", "explanation": "这里应该用〈发表〉。见报只用于报纸，学术论文在期刊上要说发表"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88020, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下班", "is_correct": false, "explanation": "搭配：“下班”的主语只能是人，文章不能“下班”"}, {"text": "失眠", "is_correct": false, "explanation": "语义：文章不会“失眠”，句子无法理解"}, {"text": "见报", "is_correct": true, "explanation": "正确：“记者说，这篇文章后天见报”指文章后天将在报纸上刊登"}, {"text": "睡觉", "is_correct": false, "explanation": "搭配：“睡觉”的主语是有生命的人或动物，文章不能“睡觉”"}], "explanations": {"下班": "搭配：“下班”的主语只能是人，文章不能“下班”", "失眠": "语义：文章不会“失眠”，句子无法理解", "见报": "正确：“记者说，这篇文章后天见报”指文章后天将在报纸上刊登", "睡觉": "搭配：“睡觉”的主语是有生命的人或动物，文章不能“睡觉”"}, "sentence_index": 6, "correct_answer": "见报"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的丑闻在朋友圈见报后，很多人都在谈论。", "explanation": "这里应该用〈曝光〉。见报指在报纸上刊出，网络上公开的信息要说曝光"}, {"text": "这档节目每周六晚上见报。", "explanation": "这里应该用〈播出〉。见报只指报纸刊登，电视节目通过屏幕播出，不能说见报"}, {"text": "这部电影下周在全国见报。", "explanation": "这里应该用〈上映〉。见报用于报纸上的文章和消息，电影要在影院上映，应说上映"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88020, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这篇稿子下周会见报了。", "corrected_sentence": "这篇稿子下周会见报。", "error_description": "错误在“见报”后多了“了”。“下周”和“会”都表示将来，不能再用表示完成的“了”，应去掉“了”，写作“下周会见报”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88020, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "记者说，这篇文章下周见报过。", "corrected_sentence": "记者说，这篇文章下周见报。", "error_description": "错误在“见报”后多了“过”。“过”表示已经发生过的经历，而“下周”是将来，应去掉“过”，写作“下周见报”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
