INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88021, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "自己人是和我们很亲，不是外人。", "primary_collocate": null, "pronunciation": "zì jǐ rén", "ipa": "tsɿ˥˩ tɕi˨˩˦ ʐən˧˥", "syllable_count": 3, "sentences": [{"text": "别客气，我们都是自己人。", "target_word": "自己人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你放心说，这里都是自己人。", "target_word": "自己人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对我们像对自己人一样好。", "target_word": "自己人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都把他当成自己人。", "target_word": "自己人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事只能告诉自己人。", "target_word": "自己人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "在这家店吃饭，老板把我们当自己人。", "target_word": "自己人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对自己人，他从来不说假话。", "target_word": "自己人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "来，坐吧，这儿没有外人，都是自己人。", "target_word": "自己人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "跟自己人谈事情，不用那么客气。", "target_word": "自己人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们是自己人，有话就直说吧。", "target_word": "自己人", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "和自己关系亲近、不必见外的人，与外人相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b08fec9-be23-4df3-b23e-efdc278f5158') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88021, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自己人", "is_correct": true, "explanation": "正确：“我们都是自己人”指彼此亲近、不见外，与“别客气”的语境相合。"}, {"text": "外人", "is_correct": false, "explanation": "语义：外人与自己人相对。“别客气，我们都是外人”与亲近的语境矛盾。"}, {"text": "敌人", "is_correct": false, "explanation": "语义：敌人是对立关系，不能和“别客气”一起描述“我们”的关系。"}, {"text": "坏人", "is_correct": false, "explanation": "语义：坏人不可信任，“我们都是坏人”与“别客气”的亲近语气矛盾。"}], "explanations": {"自己人": "正确：“我们都是自己人”指彼此亲近、不见外，与“别客气”的语境相合。", "外人": "语义：外人与自己人相对。“别客气，我们都是外人”与亲近的语境矛盾。", "敌人": "语义：敌人是对立关系，不能和“别客气”一起描述“我们”的关系。", "坏人": "语义：坏人不可信任，“我们都是坏人”与“别客气”的亲近语气矛盾。"}, "sentence_index": 0, "correct_answer": "自己人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家来了一件自己人。", "explanation": "这里应该用〈个〉。自己人指人，要用“个”或“位”来数，“件”用于物品，不能用来数人。"}, {"text": "这个邻居是我们的自己人，天天半夜来偷我家的东西。", "explanation": "这里应该用〈小偷〉。自己人意味着可以信任，与“半夜来偷东西”的行为矛盾，应说小偷。"}, {"text": "开会时，大家都把他请出去了，因为他是我们的自己人。", "explanation": "这里应该用〈外人〉。自己人是可以信任、可以留下的人，因“是自己人”而被请出去的说法与语境矛盾，应说外人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85f4f39b-4a90-4385-8473-0c6242caa654') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88021, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自己人", "is_correct": true, "explanation": "正确：“对自己人，他从来不说假话”表示对亲近的人守信，符合语境。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会听话，“对石头从来不说假话”没有意义。"}, {"text": "空气", "is_correct": false, "explanation": "配价：“说假话”需要能听的对象，空气不能作为听话的人。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“对……说假话”的对象应是人，“桌子”与这一搭配不合。"}], "explanations": {"自己人": "正确：“对自己人，他从来不说假话”表示对亲近的人守信，符合语境。", "石头": "语义：石头不会听话，“对石头从来不说假话”没有意义。", "空气": "配价：“说假话”需要能听的对象，空气不能作为听话的人。", "桌子": "搭配：“对……说假话”的对象应是人，“桌子”与这一搭配不合。"}, "sentence_index": 6, "correct_answer": "自己人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是我们的自己人，却专门骗路人的钱。", "explanation": "这里应该用〈骗子〉。自己人意味着可以信任，与“专门骗路人的钱”的行为矛盾，应说骗子。"}, {"text": "路上的自己人走得很快。", "explanation": "这里应该用〈行人〉。自己人指亲近、可信任的人，路上不相识的人只能说行人。"}, {"text": "在地铁上，一个自己人一直盯着我看，我很不舒服。", "explanation": "这里应该用〈陌生人〉。自己人指亲近、可信任的人，在地铁上盯着我看的素不相识的人应说陌生人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85f4f39b-4a90-4385-8473-0c6242caa654') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88021, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是我们的一只自己人，大家都信任他。", "corrected_sentence": "他是我们的一个自己人，大家都信任他。", "error_description": "错误：量词“只”用错。自己人指人，应该用“个”，“只”多用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85f4f39b-4a90-4385-8473-0c6242caa654') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88021, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在我们眼里是头自己人。", "corrected_sentence": "他在我们眼里是个自己人。", "error_description": "错误：量词“头”用错。自己人指人，应该用“个”，“头”用于牲畜。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85f4f39b-4a90-4385-8473-0c6242caa654') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88022, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85f4f39b-4a90-4385-8473-0c6242caa654') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88022, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85f4f39b-4a90-4385-8473-0c6242caa654') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88022, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指自家的人；关系密切、可以信任的人。", "primary_collocate": null, "pronunciation": "zì jǐ rén", "ipa": "tsɿ˥˩ tɕi˨˩˦ ʐən˧˥", "syllable_count": 3, "sentences": [{"text": "他们都是自己人，不用担心。", "target_word": "自己人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过年的时候，只有自己人在家吃饭。", "target_word": "自己人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这笔钱交给自己人，我才放心。", "target_word": "自己人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司里的重要工作，他只让自己人做。", "target_word": "自己人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在外面工作，遇到自己人特别高兴。", "target_word": "自己人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我哥哥帮我，当然是自己人帮自己人。", "target_word": "自己人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁是自己人，谁是外人，他看得很清楚。", "target_word": "自己人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个秘密，我只告诉过自己人。", "target_word": "自己人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们帮了我很多，我把他们当自己人。", "target_word": "自己人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司小，所以大家像自己人一样。", "target_word": "自己人", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "自家人或同一方、可以信任的人，与外人相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b08fec9-be23-4df3-b23e-efdc278f5158') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88022, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自己人", "is_correct": true, "explanation": "正确：“他们都是自己人，不用担心”表示彼此信任，符合语境。"}, {"text": "敌人", "is_correct": false, "explanation": "语义：敌人会让人担心，与“不用担心”的安心语境相反。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：小偷让人警惕，“他们都是小偷，不用担心”与语境冲突。"}, {"text": "骗子", "is_correct": false, "explanation": "语义：骗子让人警惕，“他们都是骗子，不用担心”与语境矛盾。"}], "explanations": {"自己人": "正确：“他们都是自己人，不用担心”表示彼此信任，符合语境。", "敌人": "语义：敌人会让人担心，与“不用担心”的安心语境相反。", "小偷": "语义：小偷让人警惕，“他们都是小偷，不用担心”与语境冲突。", "骗子": "语义：骗子让人警惕，“他们都是骗子，不用担心”与语境矛盾。"}, "sentence_index": 0, "correct_answer": "自己人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "街上走来一个自己人，我们都提高了警惕。", "explanation": "这里应该用〈陌生人〉。自己人指可以信任的人，对走来的陌生人应说陌生人，并且要提高警惕。"}, {"text": "公司派了一只自己人去谈判。", "explanation": "这里应该用〈个〉。自己人指人，要用“个”或“位”来数，“只”用于动物。"}, {"text": "这个会议只对自己人开放，他是我们的自己人，所以不能进去。", "explanation": "这里应该用〈外人〉。自己人指可以信任、可以让其进入的人，“只对自己人开放”的语境中，他是自己人却不能进去，应说外人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85f4f39b-4a90-4385-8473-0c6242caa654') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88022, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自己人", "is_correct": true, "explanation": "正确：“谁是自己人，谁是外人”形成对照，符合语境。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不分内外，“谁是石头”与语境不符。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气没有内外之分，不能与“外人”对照。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“谁是……”要求指人，“桌子”与这一搭配不合。"}], "explanations": {"自己人": "正确：“谁是自己人，谁是外人”形成对照，符合语境。", "石头": "语义：石头不分内外，“谁是石头”与语境不符。", "空气": "语义：空气没有内外之分，不能与“外人”对照。", "桌子": "搭配：“谁是……”要求指人，“桌子”与这一搭配不合。"}, "sentence_index": 6, "correct_answer": "自己人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个人是我的自己人，我从不信任他，每次见面都要提防他。", "explanation": "这里应该用〈仇人〉。自己人意味着可以信任，与“从不信任、每次见面都要提防”的语境矛盾，对需要提防的人应说仇人。"}, {"text": "街上的自己人走得很快，我们都追不上。", "explanation": "这里应该用〈行人〉。自己人指亲近、可信任的人，街上不相识的人只能说行人。"}, {"text": "这个自己人专门骗老人的钱。", "explanation": "这里应该用〈骗子〉。自己人意味着可以信任，与“专门骗钱”的行为矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85f4f39b-4a90-4385-8473-0c6242caa654') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88022, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是我的一条自己人。", "corrected_sentence": "他是我的一个自己人。", "error_description": "错误：量词“条”用错。自己人指人，应该用“个”，“条”用于细长的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85f4f39b-4a90-4385-8473-0c6242caa654') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88022, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是我们的一台自己人。", "corrected_sentence": "他是我们的一位自己人。", "error_description": "错误：量词“台”用错。自己人指人，应该用“位”或“个”，“台”用于机器。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85f4f39b-4a90-4385-8473-0c6242caa654') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88023, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "舒畅", "is_correct": true, "explanation": "舒畅：心情愉快、没有憋闷，与压抑相反。"}, {"text": "勤快", "is_correct": false, "explanation": "勤快：做事积极、不偷懒，与压抑的感受无关。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚：明白、不模糊，与压抑的感受无关。"}, {"text": "精确", "is_correct": false, "explanation": "精确：准确无误，与压抑的感受无关。"}], "correct_answer": "舒畅", "explanations": {"舒畅": "舒畅：心情愉快、没有憋闷，与压抑相反。", "勤快": "勤快：做事积极、不偷懒，与压抑的感受无关。", "清楚": "清楚：明白、不模糊，与压抑的感受无关。", "精确": "精确：准确无误，与压抑的感受无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'baba176c-b06f-47ee-846e-bf158efe36e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88023, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "轻松", "is_correct": true, "explanation": "轻松：没有负担、心情愉快，与压抑的感受相反。"}, {"text": "清晰", "is_correct": false, "explanation": "清晰：明白、有条理，与压抑的感受无关。"}, {"text": "精致", "is_correct": false, "explanation": "精致：精巧细致，与压抑的感受无关。"}, {"text": "整齐", "is_correct": false, "explanation": "整齐：排列有序，与压抑的感受无关。"}], "correct_answer": "轻松", "explanations": {"轻松": "轻松：没有负担、心情愉快，与压抑的感受相反。", "清晰": "清晰：明白、有条理，与压抑的感受无关。", "精致": "精致：精巧细致，与压抑的感受无关。", "整齐": "整齐：排列有序，与压抑的感受无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'baba176c-b06f-47ee-846e-bf158efe36e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88023, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "压抑是心里有话说不出，很难受。", "primary_collocate": null, "pronunciation": "yā yì", "ipa": "ja˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "在这个家里，我觉得很压抑。", "target_word": "压抑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他心里很压抑，却不知道对谁说。", "target_word": "压抑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会时气氛特别压抑。", "target_word": "压抑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不能说真话的日子让她很压抑。", "target_word": "压抑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间又小又黑，让人感到压抑。", "target_word": "压抑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他整天不说话，心情十分压抑。", "target_word": "压抑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听了这个消息，大家都觉得压抑。", "target_word": "压抑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太压抑了，我想出去走走。", "target_word": "压抑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们之间的气氛有点压抑。", "target_word": "压抑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作压力太大，我常常觉得压抑。", "target_word": "压抑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "压抑感", "label": "复合词"}], "register": "中性", "sense_fingerprint": "压抑·心里憋闷、有话说不出的难受感觉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03c657c1-bea8-4c65-833c-a2de6b45be3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88023, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "压抑", "is_correct": true, "explanation": "压抑 yā yì：心里有话说不出，很难受。"}, {"text": "压力", "is_correct": false, "explanation": "后一音节声母不同：lì 与 yì，意思是压力。"}, {"text": "牙医", "is_correct": false, "explanation": "声调不同：yá yī 与 yā yì 的声调都不同，意思是牙科医生。"}, {"text": "押韵", "is_correct": false, "explanation": "后一音节韵母不同：yùn 与 yì，意思是诗词句末的韵脚相同。"}], "explanations": {"压抑": "压抑 yā yì：心里有话说不出，很难受。", "压力": "后一音节声母不同：lì 与 yì，意思是压力。", "牙医": "声调不同：yá yī 与 yā yì 的声调都不同，意思是牙科医生。", "押韵": "后一音节韵母不同：yùn 与 yì，意思是诗词句末的韵脚相同。"}, "sentence_index": null, "correct_answer": "压抑"}, "level_3": {"options": [{"text": "压抑", "is_correct": true, "explanation": "压抑：心里有话说不出、很难受，与“我觉得很”搭配。"}, {"text": "锋利", "is_correct": false, "explanation": "搭配：“锋利”形容刀刃等物体，不能用来形容“我”的感觉。"}, {"text": "清脆", "is_correct": false, "explanation": "语义：“清脆”形容声音清亮，与心里的感受不合。"}, {"text": "坚硬", "is_correct": false, "explanation": "语义：“坚硬”形容物体的质地，与“我觉得”所表达的心理感受不合。"}], "explanations": {"压抑": "压抑：心里有话说不出、很难受，与“我觉得很”搭配。", "锋利": "搭配：“锋利”形容刀刃等物体，不能用来形容“我”的感觉。", "清脆": "语义：“清脆”形容声音清亮，与心里的感受不合。", "坚硬": "语义：“坚硬”形容物体的质地，与“我觉得”所表达的心理感受不合。"}, "sentence_index": 0, "correct_answer": "压抑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把这份报告压抑成了一页纸。", "explanation": "这里应该用〈压缩〉。压抑指心里憋闷，文字篇幅变短要用压缩。"}, {"text": "他把帽檐压抑得很低，看不清脸。", "explanation": "这里应该用〈压低〉。压抑指心里憋闷的感受，帽檐往下按要用压低。"}, {"text": "他把纸箱压抑得扁扁的。", "explanation": "这里应该用〈压扁〉。压抑指心里憋闷的感受，物体被压变形要用压扁。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'baba176c-b06f-47ee-846e-bf158efe36e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88023, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "压抑", "is_correct": true, "explanation": "压抑 yā yì：心里有话说不出，很难受。"}, {"text": "亚裔", "is_correct": false, "explanation": "第一音节声调不同：yà 与 yā，意思是亚洲血统的人。"}, {"text": "押运", "is_correct": false, "explanation": "后一音节韵母不同：yùn 与 yì，意思是护送并运输物资。"}, {"text": "压印", "is_correct": false, "explanation": "后一音节韵母不同：yìn 与 yì，意思是用压力印出图案或文字。"}], "explanations": {"压抑": "压抑 yā yì：心里有话说不出，很难受。", "亚裔": "第一音节声调不同：yà 与 yā，意思是亚洲血统的人。", "押运": "后一音节韵母不同：yùn 与 yì，意思是护送并运输物资。", "压印": "后一音节韵母不同：yìn 与 yì，意思是用压力印出图案或文字。"}, "sentence_index": null, "correct_answer": "压抑"}, "level_3": {"options": [{"text": "压抑", "is_correct": true, "explanation": "压抑：心里憋闷、有话说不出，与“大家都觉得”搭配。"}, {"text": "雪白", "is_correct": false, "explanation": "搭配：“雪白”形容颜色，不能用来形容大家的感受。"}, {"text": "粗糙", "is_correct": false, "explanation": "搭配：“粗糙”形容表面质地，不能用于心理感受。"}, {"text": "瘦小", "is_correct": false, "explanation": "语义：“瘦小”形容人的体型，与“大家都觉得”后面的心理感受不合。"}], "explanations": {"压抑": "压抑：心里憋闷、有话说不出，与“大家都觉得”搭配。", "雪白": "搭配：“雪白”形容颜色，不能用来形容大家的感受。", "粗糙": "搭配：“粗糙”形容表面质地，不能用于心理感受。", "瘦小": "语义：“瘦小”形容人的体型，与“大家都觉得”后面的心理感受不合。"}, "sentence_index": 6, "correct_answer": "压抑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块木板很压抑，锯起来很费力。", "explanation": "这里应该用〈厚实〉。压抑只用于心理感受，描述木板的厚度要用厚实。"}, {"text": "他背着压抑的行李，走得很慢。", "explanation": "这里应该用〈沉重〉。压抑只用于心理感受，描述物体的重量要用沉重。"}, {"text": "这块蛋糕很压抑，又香又甜。", "explanation": "这里应该用〈松软〉。压抑只用于心理感受，描述蛋糕的口感要用松软。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'baba176c-b06f-47ee-846e-bf158efe36e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88023, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些年的生活让他觉得很压抑过。", "corrected_sentence": "这些年的生活让他觉得很压抑。", "error_description": "错误在“过”：形容词“压抑”后面不能加“过”，应删去，说“很压抑”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'baba176c-b06f-47ee-846e-bf158efe36e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88023, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屋子里有一股压抑地气氛。", "corrected_sentence": "屋子里有一股压抑的气氛。", "error_description": "错误在修饰语的结构助词：“压抑”修饰名词“气氛”，要用“的”，不能用“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'baba176c-b06f-47ee-846e-bf158efe36e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88024, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "发泄", "is_correct": true, "explanation": "发泄：把感情宣泄出来，与“压抑”的意思相反。"}, {"text": "欣赏", "is_correct": false, "explanation": "欣赏：对美好事物表示赞赏，与压抑感情没有反义关系。"}, {"text": "观察", "is_correct": false, "explanation": "观察：仔细察看事物，与压抑感情不构成反义。"}, {"text": "参加", "is_correct": false, "explanation": "参加：加入某项活动，与压抑感情不构成反义。"}], "correct_answer": "发泄", "explanations": {"发泄": "发泄：把感情宣泄出来，与“压抑”的意思相反。", "欣赏": "欣赏：对美好事物表示赞赏，与压抑感情没有反义关系。", "观察": "观察：仔细察看事物，与压抑感情不构成反义。", "参加": "参加：加入某项活动，与压抑感情不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'baba176c-b06f-47ee-846e-bf158efe36e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
