INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88024, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对感情、情绪加以克制，使不能发泄。", "primary_collocate": null, "pronunciation": "yā yì", "ipa": "ja˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "他努力压抑着心中的愤怒。", "target_word": "压抑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她压抑不住内心的激动。", "target_word": "压抑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把难过压抑在心里，没有哭。", "target_word": "压抑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不要总是压抑自己的感情。", "target_word": "压抑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他压抑着心里的不满，继续工作。", "target_word": "压抑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李一直压抑着想哭的冲动。", "target_word": "压抑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她压抑了很久的情绪终于爆发了。", "target_word": "压抑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她压抑着心里的委屈，没有说话。", "target_word": "压抑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她总是压抑自己的想法，不敢说出来。", "target_word": "压抑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他压抑着笑，不敢出声。", "target_word": "压抑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "压抑了", "label": "完成体"}, {"form": "压抑着", "label": "持续体"}, {"form": "压抑过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "压抑·克制感情、情绪，不让发泄（压抑愤怒/压抑不住）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03c657c1-bea8-4c65-833c-a2de6b45be3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88024, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "压抑", "is_correct": true, "explanation": "压抑 yā yì：克制感情、不让发泄，或使人感到沉闷。"}, {"text": "压力", "is_correct": false, "explanation": "后一音节声母不同：lì 与 yì，意思是压力。"}, {"text": "牙医", "is_correct": false, "explanation": "声调不同：yá yī 与 yā yì 的声调都不同，意思是牙科医生。"}, {"text": "押韵", "is_correct": false, "explanation": "后一音节韵母不同：yùn 与 yì，意思是诗词句末的韵脚相同。"}], "explanations": {"压抑": "压抑 yā yì：克制感情、不让发泄，或使人感到沉闷。", "压力": "后一音节声母不同：lì 与 yì，意思是压力。", "牙医": "声调不同：yá yī 与 yā yì 的声调都不同，意思是牙科医生。", "押韵": "后一音节韵母不同：yùn 与 yì，意思是诗词句末的韵脚相同。"}, "sentence_index": null, "correct_answer": "压抑"}, "level_3": {"options": [{"text": "压抑", "is_correct": true, "explanation": "压抑：克制情绪、不让发泄，与“努力”和“愤怒”搭配。"}, {"text": "享受", "is_correct": false, "explanation": "搭配：“享受”的对象是生活、待遇等，不能说享受心中的愤怒。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：“欣赏”用于风景、作品等美好的事物，愤怒不能被欣赏。"}, {"text": "挥霍", "is_correct": false, "explanation": "搭配：“挥霍”用于钱财、时间、精力，不能用于愤怒这类情绪。"}], "explanations": {"压抑": "压抑：克制情绪、不让发泄，与“努力”和“愤怒”搭配。", "享受": "搭配：“享受”的对象是生活、待遇等，不能说享受心中的愤怒。", "欣赏": "搭配：“欣赏”用于风景、作品等美好的事物，愤怒不能被欣赏。", "挥霍": "搭配：“挥霍”用于钱财、时间、精力，不能用于愤怒这类情绪。"}, "sentence_index": 0, "correct_answer": "压抑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政府压抑了这次游行。", "explanation": "这里应该用〈压制〉。压抑用于感情、情绪，对游行这类集体活动的阻止要用压制。"}, {"text": "他把这封信压抑在抽屉里。", "explanation": "这里应该用〈隐藏〉。压抑针对感情、情绪，信件这类实物要用隐藏。"}, {"text": "他用手压抑着纸，怕它被风吹走。", "explanation": "这里应该用〈压住〉。压抑只用于感情、情绪的克制，用手按住纸要用压住。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'baba176c-b06f-47ee-846e-bf158efe36e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88024, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "压抑", "is_correct": true, "explanation": "压抑 yā yì：克制感情、不让发泄，或使人感到沉闷。"}, {"text": "亚裔", "is_correct": false, "explanation": "第一音节声调不同：yà 与 yā，意思是亚洲血统的人。"}, {"text": "押运", "is_correct": false, "explanation": "后一音节韵母不同：yùn 与 yì，意思是护送并运输物资。"}, {"text": "压印", "is_correct": false, "explanation": "后一音节韵母不同：yìn 与 yì，意思是用压力印出图案或文字。"}], "explanations": {"压抑": "压抑 yā yì：克制感情、不让发泄，或使人感到沉闷。", "亚裔": "第一音节声调不同：yà 与 yā，意思是亚洲血统的人。", "押运": "后一音节韵母不同：yùn 与 yì，意思是护送并运输物资。", "压印": "后一音节韵母不同：yìn 与 yì，意思是用压力印出图案或文字。"}, "sentence_index": null, "correct_answer": "压抑"}, "level_3": {"options": [{"text": "压抑", "is_correct": true, "explanation": "压抑：克制感情、不让发泄，与“很久”和“终于爆发”的情节相合。"}, {"text": "品尝", "is_correct": false, "explanation": "搭配：“品尝”用于食物、饮品，不能说品尝情绪。"}, {"text": "清洗", "is_correct": false, "explanation": "搭配：“清洗”用于物体，情绪不能被清洗。"}, {"text": "翻阅", "is_correct": false, "explanation": "语义：“翻阅”是看书报、文件，与情绪无关。"}], "explanations": {"压抑": "压抑：克制感情、不让发泄，与“很久”和“终于爆发”的情节相合。", "品尝": "搭配：“品尝”用于食物、饮品，不能说品尝情绪。", "清洗": "搭配：“清洗”用于物体，情绪不能被清洗。", "翻阅": "语义：“翻阅”是看书报、文件，与情绪无关。"}, "sentence_index": 6, "correct_answer": "压抑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工厂把废气压抑成液体后再运走。", "explanation": "这里应该用〈压缩〉。压抑只用于感情、情绪，气体加压变小要用压缩。"}, {"text": "商家把价格压抑到最低，只为抢生意。", "explanation": "这里应该用〈压低〉。压抑只用于感情、情绪，降低价格要用压低。"}, {"text": "这台机器能把整块废铁压抑碎。", "explanation": "这里应该用〈压碎〉。压抑只用于感情、情绪，把物体压成碎块要用压碎。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'baba176c-b06f-47ee-846e-bf158efe36e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88024, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我一直压抑了着自己的眼泪。", "corrected_sentence": "我一直压抑着自己的眼泪。", "error_description": "错误在“压抑”的体标：“了”和“着”不能同时用在同一个动词后。表示持续应当用“压抑着”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'baba176c-b06f-47ee-846e-bf158efe36e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88024, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把委屈压抑心底，一句话也没说。", "corrected_sentence": "她把委屈压抑在心底，一句话也没说。", "error_description": "“压抑”后面表示处所的“在心底”不能省略，应为“压抑在心底”。错误形式：压抑心底；正确形式：压抑在心底。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'baba176c-b06f-47ee-846e-bf158efe36e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
