INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88027, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "外星人是住在别的星球上的人，可能是想出来的。", "primary_collocate": null, "pronunciation": "wài xīng rén", "ipa": "wai̯˥˩ ɕiŋ˥ ɻən˧˥", "syllable_count": 3, "sentences": [{"text": "我小时候以为外星人住在月亮上。", "target_word": "外星人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影讲的是外星人来到地球的故事。", "target_word": "外星人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟说他昨天晚上看见了外星人。", "target_word": "外星人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你相信世界上有外星人吗？", "target_word": "外星人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们画了一个绿色的外星人。", "target_word": "外星人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外星人会说我们的话吗？", "target_word": "外星人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里的外星人长得很奇怪。", "target_word": "外星人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想知道外星人吃什么。", "target_word": "外星人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我梦见自己和外星人做了朋友。", "target_word": "外星人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了一个外星人的故事。", "target_word": "外星人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}], "register": "中性", "sense_fingerprint": "想象中住在别的星球上的人（儿童故事、电影）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be7a67a-0052-4629-80f6-eca6c3881ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88027, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外星人", "is_correct": true, "explanation": "正确。外星人住在别的星球上，正好与“住在月亮上”的童话想象相合。"}, {"text": "石头", "is_correct": false, "explanation": "配价：“住”要求有生命的施事，石头不能住在月亮上。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“住”说人或动物，不说家用电器住在某处。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳是恒星，不是能居住的生物，这句话说不通。"}], "explanations": {"外星人": "正确。外星人住在别的星球上，正好与“住在月亮上”的童话想象相合。", "石头": "配价：“住”要求有生命的施事，石头不能住在月亮上。", "冰箱": "搭配：“住”说人或动物，不说家用电器住在某处。", "太阳": "语义：太阳是恒星，不是能居住的生物，这句话说不通。"}, "sentence_index": 0, "correct_answer": "外星人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上开外星人去公司上班。", "explanation": "这里应该用〈汽车〉。“开”的宾语应是车辆，外星人是生物，不能用来驾驶。"}, {"text": "我们暑假准备去外星人旅游，看看月亮。", "explanation": "这里应该用〈外星球〉。“外星人”指生物，不能作为旅游的地点；表示地点要用“外星球”。"}, {"text": "他每天中午都吃外星人。", "explanation": "这里应该用〈面条〉。“外星人”指生物，不能用作食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de6260c-2a6c-410a-9af0-ba6c08bfd103') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88027, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外星人", "is_correct": true, "explanation": "正确。外星人的外貌奇怪，正好符合“长得很奇怪”。"}, {"text": "空气", "is_correct": false, "explanation": "体貌：空气没有固定的形状，不能说“长得很奇怪”。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“长得”说事物的外形，不说颜色长得怎样。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“长得”描写外形，不用于气味、味道。"}], "explanations": {"外星人": "正确。外星人的外貌奇怪，正好符合“长得很奇怪”。", "空气": "体貌：空气没有固定的形状，不能说“长得很奇怪”。", "颜色": "搭配：“长得”说事物的外形，不说颜色长得怎样。", "味道": "搭配：“长得”描写外形，不用于气味、味道。"}, "sentence_index": 6, "correct_answer": "外星人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把外星人放进书包，背着去上学。", "explanation": "这里应该用〈课本〉。“外星人”指想象中的生物，不是能放进书包带去上学的学习用品。"}, {"text": "妈妈用外星人炒了一盘菜。", "explanation": "这里应该用〈鸡蛋〉。“外星人”指想象中的生物，不能当作做菜的食材。"}, {"text": "这家工厂每天能制造出几十个外星人。", "explanation": "这里应该用〈玩具〉。外星人是想象中的生物，不是工厂批量生产的产品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de6260c-2a6c-410a-9af0-ba6c08bfd103') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88027, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "电视里突然出现了一棵外星人。", "corrected_sentence": "电视里突然出现了一个外星人。", "error_description": "错误：量词“棵”用于树木，不能修饰外星人。正确：“一个外星人”，外星人是生物，用“个”计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de6260c-2a6c-410a-9af0-ba6c08bfd103') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88027, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一个外星人们来到了地球。", "corrected_sentence": "一个外星人来到了地球。", "error_description": "错误：“一个”表示单数，不能与复数后缀“们”同用。正确：去掉“们”，即“一个外星人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de6260c-2a6c-410a-9af0-ba6c08bfd103') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
