INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88030, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "词和短语的总称。", "primary_collocate": null, "pronunciation": "cí yǔ", "ipa": "tsʰɨ˧˥ y˨˩˦", "syllable_count": 2, "sentences": [{"text": "词语包括词和短语。", "target_word": "词语", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书里有很多常用词语。", "target_word": "词语", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "词语是词和短语的总称。", "target_word": "词语", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们写出十个新词语。", "target_word": "词语", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汉语的词语有的是一个字，有的是两个字。", "target_word": "词语", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在词典里查不到这个词语。", "target_word": "词语", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学外语要多记词语。", "target_word": "词语", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个词语的意思我不太懂。", "target_word": "词语", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章用了很多四个字的词语。", "target_word": "词语", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把新学的词语写在本子上。", "target_word": "词语", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "词语表", "label": "复合"}], "register": "通用", "sense_fingerprint": "词和短语的总称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3cfd08e-3d21-43ff-b039-b447ed2d2985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88030, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "词语", "is_correct": true, "explanation": "正确答案。词语 cíyǔ 指词和短语的总称。"}, {"text": "赐予", "is_correct": false, "explanation": "cì（第四声）与 cí（第二声）声调不同，赐予意思是给予。"}, {"text": "刺鱼", "is_correct": false, "explanation": "cìyú 与 cíyǔ 两个字的声调都不同；刺鱼是一种身上带刺的小鱼。"}, {"text": "雌鱼", "is_correct": false, "explanation": "yú（第二声）与 yǔ（第三声）声调不同，雌鱼意思是母鱼。"}], "explanations": {"词语": "正确答案。词语 cíyǔ 指词和短语的总称。", "赐予": "cì（第四声）与 cí（第二声）声调不同，赐予意思是给予。", "刺鱼": "cìyú 与 cíyǔ 两个字的声调都不同；刺鱼是一种身上带刺的小鱼。", "雌鱼": "yú（第二声）与 yǔ（第三声）声调不同，雌鱼意思是母鱼。"}, "sentence_index": null, "correct_answer": "词语"}, "level_3": {"options": [{"text": "词语", "is_correct": true, "explanation": "正确：「词语包括词和短语」，词语是词和短语的总称。"}, {"text": "数字", "is_correct": false, "explanation": "语义：数字指数目，不包括词和短语。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：「包括」要求主语是能够包含词和短语的类别，颜色不能这样用。"}, {"text": "汉字", "is_correct": false, "explanation": "语义：汉字是书写的单位，与词和短语不是包含关系。"}], "explanations": {"词语": "正确：「词语包括词和短语」，词语是词和短语的总称。", "数字": "语义：数字指数目，不包括词和短语。", "颜色": "搭配：「包括」要求主语是能够包含词和短语的类别，颜色不能这样用。", "汉字": "语义：汉字是书写的单位，与词和短语不是包含关系。"}, "sentence_index": 0, "correct_answer": "词语"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的词语叫李明。", "explanation": "这里应该用〈名字〉。词语指词和短语，不能用来称呼人。"}, {"text": "这件衣服的词语很便宜。", "explanation": "这里应该用〈价钱〉。词语不能用来说明价格。"}, {"text": "他会说三种词语。", "explanation": "这里应该用〈语言〉。词语是词和短语的总称，不能说成会说的语言。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd21417dd-c9f1-4c61-b777-aa96f07bf1b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88030, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "词语", "is_correct": true, "explanation": "正确：「学外语要多记词语」，词语指需要记忆的词和短语。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是需要记忆的语言材料，句子说不通。"}, {"text": "星座", "is_correct": false, "explanation": "语义：星座属于占星或天文的内容，不是外语学习要记的对象。"}, {"text": "鸡蛋", "is_correct": false, "explanation": "语义：鸡蛋不是需要记忆的语言材料，句子说不通。"}], "explanations": {"词语": "正确：「学外语要多记词语」，词语指需要记忆的词和短语。", "石头": "语义：石头不是需要记忆的语言材料，句子说不通。", "星座": "语义：星座属于占星或天文的内容，不是外语学习要记的对象。", "鸡蛋": "语义：鸡蛋不是需要记忆的语言材料，句子说不通。"}, "sentence_index": 6, "correct_answer": "词语"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的词语有一米八。", "explanation": "这里应该用〈身高〉。词语指词和短语，不能用来说明人的身高。"}, {"text": "这碗汤的词语很鲜。", "explanation": "这里应该用〈味道〉。词语是词和短语的总称，不能用来形容食物的味道。"}, {"text": "这箱子的词语是二十公斤。", "explanation": "这里应该用〈重量〉。词语不能用来称量物体的重量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd21417dd-c9f1-4c61-b777-aa96f07bf1b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88030, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本词语很常用。", "corrected_sentence": "这个词语很常用。", "error_description": "量词错误：「本」用于书册，词语应用量词「个」，应改为「这个词语很常用」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd21417dd-c9f1-4c61-b777-aa96f07bf1b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88030, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我记住了一条新词语。", "corrected_sentence": "我记住了一个新词语。", "error_description": "量词错误：「条」用于细长的东西，词语应用量词「个」，应改为「一个新词语」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd21417dd-c9f1-4c61-b777-aa96f07bf1b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
