INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88031, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "主题是一篇文章或一场活动最主要要说的事。", "primary_collocate": null, "pronunciation": "zhǔ tí", "ipa": "ʈʂu˨˩ tʰi˧˥", "syllable_count": 2, "sentences": [{"text": "这次班会的主题是环境保护。", "target_word": "主题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们先想好作文的主题。", "target_word": "主题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天会议的主题是什么？", "target_word": "主题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这场比赛的主题是“健康生活”。", "target_word": "主题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的发言一直没有离开主题。", "target_word": "主题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请大家围绕这个主题讨论十分钟。", "target_word": "主题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个节日活动的主题是“感谢老师”。", "target_word": "主题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文章的主题写在第一段里。", "target_word": "主题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次演讲的主题是“我的梦想”。", "target_word": "主题", "complexity_tier": "T3", "furigana": "zhè cì yǎn jiǎng de zhǔ tí shì wǒ de mèng xiǎng", "sentence_source": "generated"}, {"text": "这次展览的主题已经定下来了。", "target_word": "主题", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "文章或活动要谈的最主要内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc845970-b582-4cbd-8bfb-d42e50e4b40f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88031, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "主题", "is_correct": true, "explanation": "主题（zhǔ tí）指文章或活动最主要要说的内容，是正确答案。"}, {"text": "主体", "is_correct": false, "explanation": "tǐ（第三声）与 tí（第二声）声调不同，意思是事物的主要部分。"}, {"text": "主持", "is_correct": false, "explanation": "chí 与 tí 声母不同（ch 与 t），意思是主持会议。"}, {"text": "猪蹄", "is_correct": false, "explanation": "zhū（第一声）与 zhǔ（第三声）声调不同，意思是猪的蹄子。"}, {"text": "主食", "is_correct": false, "explanation": "shí 与 tí 声母不同（sh 与 t），意思是人每天吃的主要食物。"}, {"text": "主席", "is_correct": false, "explanation": "xí 与 tí 声母不同（x 与 t），意思是会议或组织的负责人。"}], "explanations": {"主题": "主题（zhǔ tí）指文章或活动最主要要说的内容，是正确答案。", "主体": "tǐ（第三声）与 tí（第二声）声调不同，意思是事物的主要部分。", "主持": "chí 与 tí 声母不同（ch 与 t），意思是主持会议。", "猪蹄": "zhū（第一声）与 zhǔ（第三声）声调不同，意思是猪的蹄子。", "主食": "shí 与 tí 声母不同（sh 与 t），意思是人每天吃的主要食物。", "主席": "xí 与 tí 声母不同（x 与 t），意思是会议或组织的负责人。"}, "sentence_index": null, "correct_answer": "主题"}, "level_3": {"options": [{"text": "主题", "is_correct": true, "explanation": "主题指班会要说的最主要内容，与“是环境保护”相符。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间指何时举行，不是班会要讨论的内容，“时间是环境保护”不通。"}, {"text": "地点", "is_correct": false, "explanation": "语义：地点指场所，不能作为班会讨论的内容，“地点是环境保护”不通。"}, {"text": "费用", "is_correct": false, "explanation": "搭配：“费用”说的是钱的多少、收取或支付，不能和“是＋内容”搭配。"}], "explanations": {"主题": "主题指班会要说的最主要内容，与“是环境保护”相符。", "时间": "语义：时间指何时举行，不是班会要讨论的内容，“时间是环境保护”不通。", "地点": "语义：地点指场所，不能作为班会讨论的内容，“地点是环境保护”不通。", "费用": "搭配：“费用”说的是钱的多少、收取或支付，不能和“是＋内容”搭配。"}, "sentence_index": 0, "correct_answer": "主题"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个故事的主题发生在明朝。", "explanation": "这里应该用〈背景〉。主题是文章或活动最主要要说的事，故事发生的时代和地点要用背景。"}, {"text": "这道数学主题的第二问我没做出来。", "explanation": "这里应该用〈题目〉。主题没有“第二问”，考试里的一道题有小问，要说题目。"}, {"text": "这封主题很有意思。", "explanation": "主题要用量词〈个〉；〈封〉用于信件，不能修饰主题。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fbc760a-f0a4-4dab-8306-53e9ab979a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88031, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主题", "is_correct": true, "explanation": "主题指活动的中心内容，“感谢老师”正是这个节日活动要表达的中心。"}, {"text": "外貌", "is_correct": false, "explanation": "语义：外貌指人或物的样子，活动没有外貌，不能说外貌是“感谢老师”。"}, {"text": "地址", "is_correct": false, "explanation": "语义：地址指所在的位置，不能作为活动的中心内容，句子读起来不通。"}, {"text": "时长", "is_correct": false, "explanation": "语义：时长指持续的时间，不能用来说明活动的中心，“时长是“感谢老师””不通。"}], "explanations": {"主题": "主题指活动的中心内容，“感谢老师”正是这个节日活动要表达的中心。", "外貌": "语义：外貌指人或物的样子，活动没有外貌，不能说外貌是“感谢老师”。", "地址": "语义：地址指所在的位置，不能作为活动的中心内容，句子读起来不通。", "时长": "语义：时长指持续的时间，不能用来说明活动的中心，“时长是“感谢老师””不通。"}, "sentence_index": 6, "correct_answer": "主题"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书的主题是小说。", "explanation": "这里应该用〈体裁〉。主题是作品的中心思想，小说是文体，要说体裁。"}, {"text": "这篇作文的主题有八百字。", "explanation": "这里应该用〈字数〉。主题不表示篇幅，作文的长短要说字数。"}, {"text": "这幅主题很美。", "explanation": "主题要用量词〈个〉；〈幅〉用于画作，不能修饰主题。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fbc760a-f0a4-4dab-8306-53e9ab979a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88031, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们选了一幅主题来写作文。", "corrected_sentence": "我们选了一个主题来写作文。", "error_description": "“主题”是抽象名词，量词应用“个”。“幅”用于画作，“一幅主题”是量词错误，应改为“一个主题”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fbc760a-f0a4-4dab-8306-53e9ab979a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88031, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份主题很新颖，大家都很喜欢。", "corrected_sentence": "这个主题很新颖，大家都很喜欢。", "error_description": "“主题”是抽象名词，量词应用“个”。“份”多用于文件、食物等，“这份主题”是量词错误，应改为“这个主题”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fbc760a-f0a4-4dab-8306-53e9ab979a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
