INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88032, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "文章、作品或活动所表现的中心思想。", "primary_collocate": null, "pronunciation": "zhǔ tí", "ipa": "ʈʂu˨˩ tʰi˧˥", "syllable_count": 2, "sentences": [{"text": "这部电影的主题是爱与责任。", "target_word": "主题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这首诗表现的主题很深刻。", "target_word": "主题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本小说的主题是家庭。", "target_word": "主题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的画有一个明确的主题。", "target_word": "主题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看完这个故事，你觉得它的主题是什么？", "target_word": "主题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部作品的主题让很多人想起了过去。", "target_word": "主题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐会的主题是和平。", "target_word": "主题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这幅画的主题是秋天的山。", "target_word": "主题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这首歌的主题很简单，就是想家。", "target_word": "主题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事的主题是诚实比聪明更重要。", "target_word": "主题", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "作品所表现的中心思想", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc845970-b582-4cbd-8bfb-d42e50e4b40f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88032, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "主题", "is_correct": true, "explanation": "主题（zhǔ tí）指作品所表现的中心思想，是正确答案。"}, {"text": "主体", "is_correct": false, "explanation": "tǐ（第三声）与 tí（第二声）声调不同，意思是事物的主要部分。"}, {"text": "主持", "is_correct": false, "explanation": "chí 与 tí 声母不同（ch 与 t），意思是主持会议或节目。"}, {"text": "猪蹄", "is_correct": false, "explanation": "zhū（第一声）与 zhǔ（第三声）声调不同，意思是猪的蹄子。"}, {"text": "主食", "is_correct": false, "explanation": "shí 与 tí 声母不同（sh 与 t），意思是人每天吃的主要食物。"}, {"text": "主席", "is_correct": false, "explanation": "xí 与 tí 声母不同（x 与 t），意思是会议或组织的负责人。"}], "explanations": {"主题": "主题（zhǔ tí）指作品所表现的中心思想，是正确答案。", "主体": "tǐ（第三声）与 tí（第二声）声调不同，意思是事物的主要部分。", "主持": "chí 与 tí 声母不同（ch 与 t），意思是主持会议或节目。", "猪蹄": "zhū（第一声）与 zhǔ（第三声）声调不同，意思是猪的蹄子。", "主食": "shí 与 tí 声母不同（sh 与 t），意思是人每天吃的主要食物。", "主席": "xí 与 tí 声母不同（x 与 t），意思是会议或组织的负责人。"}, "sentence_index": null, "correct_answer": "主题"}, "level_3": {"options": [{"text": "主题", "is_correct": true, "explanation": "主题指作品所表现的中心思想，“爱与责任”正是这部电影的中心思想。"}, {"text": "票价", "is_correct": false, "explanation": "搭配：“票价”说的是买票的价钱，不能和“是爱与责任”搭配。"}, {"text": "演员", "is_correct": false, "explanation": "语义：演员是参演的人，不是电影表现的中心思想，“演员是爱与责任”不通。"}, {"text": "片长", "is_correct": false, "explanation": "语义：片长指影片的时长，不能作为电影的中心思想，句子读起来不通。"}], "explanations": {"主题": "主题指作品所表现的中心思想，“爱与责任”正是这部电影的中心思想。", "票价": "搭配：“票价”说的是买票的价钱，不能和“是爱与责任”搭配。", "演员": "语义：演员是参演的人，不是电影表现的中心思想，“演员是爱与责任”不通。", "片长": "语义：片长指影片的时长，不能作为电影的中心思想，句子读起来不通。"}, "sentence_index": 0, "correct_answer": "主题"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部剧的主题是三个主角。", "explanation": "这里应该用〈角色〉。主题是作品的中心思想，剧中的人物要说角色。"}, {"text": "这篇文章的主题是议论文。", "explanation": "这里应该用〈体裁〉。议论文是文体，表示文章的类型要用体裁。"}, {"text": "这份主题很感人。", "explanation": "主题要用量词〈个〉；〈份〉多用于文件、食物等，不能修饰主题。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fbc760a-f0a4-4dab-8306-53e9ab979a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88032, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主题", "is_correct": true, "explanation": "主题指音乐会要表达的中心思想，“和平”正是音乐会的中心思想。"}, {"text": "外貌", "is_correct": false, "explanation": "语义：外貌指人或物的样子，音乐会没有外貌，“外貌是和平”不通。"}, {"text": "座位", "is_correct": false, "explanation": "语义：座位指观众坐的位置，不能作为音乐会的中心思想，句子读起来不通。"}, {"text": "乐手", "is_correct": false, "explanation": "语义：乐手是演奏的人，不是音乐会的中心思想，“乐手是和平”不通。"}], "explanations": {"主题": "主题指音乐会要表达的中心思想，“和平”正是音乐会的中心思想。", "外貌": "语义：外貌指人或物的样子，音乐会没有外貌，“外貌是和平”不通。", "座位": "语义：座位指观众坐的位置，不能作为音乐会的中心思想，句子读起来不通。", "乐手": "语义：乐手是演奏的人，不是音乐会的中心思想，“乐手是和平”不通。"}, "sentence_index": 6, "correct_answer": "主题"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试的主题是九十分。", "explanation": "这里应该用〈成绩〉。主题指中心思想，考试的得分要说成绩。"}, {"text": "这张主题很美。", "explanation": "主题要用量词〈个〉；〈张〉用于纸张、桌子等，不能修饰主题。"}, {"text": "这篇文章的主题是两千字。", "explanation": "这里应该用〈字数〉。主题不表示篇幅，文章的长短要说字数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fbc760a-f0a4-4dab-8306-53e9ab979a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88032, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这幅主题很深刻，观众都看懂了。", "corrected_sentence": "这个主题很深刻，观众都看懂了。", "error_description": "“主题”是抽象名词，量词应用“个”。“幅”用于画作，“这幅主题”是量词错误，应改为“这个主题”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fbc760a-f0a4-4dab-8306-53e9ab979a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88032, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这首主题很清楚，大家一听就懂。", "corrected_sentence": "这个主题很清楚，大家一听就懂。", "error_description": "“主题”是抽象名词，量词应用“个”。“首”用于歌曲、诗词，“这首主题”是量词错误，应改为“这个主题”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fbc760a-f0a4-4dab-8306-53e9ab979a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
