INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88033, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "大体是差不多，主要的地方是这样。", "primary_collocate": null, "pronunciation": "dà tǐ", "ipa": "ta˥˩ tʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个故事的内容我大体知道。", "target_word": "大体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的想法大体相同。", "target_word": "大体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子的样子大体和图片一样。", "target_word": "大体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事情的经过大体就是这样。", "target_word": "大体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两篇文章的意思大体一样。", "target_word": "大体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "问题大体解决了，只剩一点小事。", "target_word": "大体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们大体都同意这个办法。", "target_word": "大体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市夏天大体都很热。", "target_word": "大体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大体来说，今年比去年好。", "target_word": "大体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的回答大体符合要求。", "target_word": "大体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "大体·副词，主要方面差不多、基本相同", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03c657c1-bea8-4c65-833c-a2de6b45be3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88033, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大体", "is_correct": true, "explanation": "大体 dà tǐ：差不多，主要的地方是这样。"}, {"text": "大米", "is_correct": false, "explanation": "声母不同：mǐ 与 tǐ，大米 意思是稻米去壳后的米粒。"}, {"text": "大笔", "is_correct": false, "explanation": "声母不同：bǐ 与 tǐ，大笔 意思是数额很大，如大笔钱。"}, {"text": "大题", "is_correct": false, "explanation": "声调不同：tí 与 tǐ 的声调不同，意思是大题目、大问题。"}], "explanations": {"大体": "大体 dà tǐ：差不多，主要的地方是这样。", "大米": "声母不同：mǐ 与 tǐ，大米 意思是稻米去壳后的米粒。", "大笔": "声母不同：bǐ 与 tǐ，大笔 意思是数额很大，如大笔钱。", "大题": "声调不同：tí 与 tǐ 的声调不同，意思是大题目、大问题。"}, "sentence_index": null, "correct_answer": "大体"}, "level_3": {"options": [{"text": "大体", "is_correct": true, "explanation": "大体：差不多，主要方面如此，与“知道”搭配。"}, {"text": "故意", "is_correct": false, "explanation": "语义：“故意”表示有意去做，“知道”这种认知结果不能故意进行。"}, {"text": "仔细", "is_correct": false, "explanation": "搭配：“仔细”修饰动作，不能修饰“知道”这种状态。"}, {"text": "迅速", "is_correct": false, "explanation": "语义：“迅速”说明速度快，与“大体”所表示的大致程度不合。"}], "explanations": {"大体": "大体：差不多，主要方面如此，与“知道”搭配。", "故意": "语义：“故意”表示有意去做，“知道”这种认知结果不能故意进行。", "仔细": "搭配：“仔细”修饰动作，不能修饰“知道”这种状态。", "迅速": "语义：“迅速”说明速度快，与“大体”所表示的大致程度不合。"}, "sentence_index": 0, "correct_answer": "大体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他买了一辆大体汽车，每天开着上班。", "explanation": "这里应该用〈大型〉。大体是副词，不能直接修饰名词“汽车”。"}, {"text": "这种药的剂量必须大体配比，不能有一点误差。", "explanation": "这里应该用〈严格〉。大体表示大致，剂量要求一丝不苟时不能用它。"}, {"text": "化验时要大体称出五克药粉。", "explanation": "这里应该用〈精确〉。大体只表示大致，化验称量要求精确时不能用它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'baba176c-b06f-47ee-846e-bf158efe36e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88033, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "大体", "is_correct": true, "explanation": "大体 dà tǐ：差不多，主要的地方是这样。"}, {"text": "大题", "is_correct": false, "explanation": "声调不同：tí 与 tǐ 的声调不同，意思是大题目、大问题。"}, {"text": "答题", "is_correct": false, "explanation": "声调不同：dá tí 与 dà tǐ 的声调都不同，意思是回答问题。"}, {"text": "大礼", "is_correct": false, "explanation": "声母不同：lǐ 与 tǐ 的声母不同（l 与 t），意思是隆重的礼节。"}], "explanations": {"大体": "大体 dà tǐ：差不多，主要的地方是这样。", "大题": "声调不同：tí 与 tǐ 的声调不同，意思是大题目、大问题。", "答题": "声调不同：dá tí 与 dà tǐ 的声调都不同，意思是回答问题。", "大礼": "声母不同：lǐ 与 tǐ 的声母不同（l 与 t），意思是隆重的礼节。"}, "sentence_index": null, "correct_answer": "大体"}, "level_3": {"options": [{"text": "大体", "is_correct": true, "explanation": "大体：差不多、主要方面一致，与“都同意”搭配。"}, {"text": "偏", "is_correct": false, "explanation": "语义：“偏”表示故意与众不同，与“都同意”的一致态度相反。"}, {"text": "欢快", "is_correct": false, "explanation": "词性：“欢快”是形容词，不能充当副词修饰“都同意”。"}, {"text": "正在", "is_correct": false, "explanation": "搭配：“正在”表示动作进行中，与“都同意”这一结果不搭。"}], "explanations": {"大体": "大体：差不多、主要方面一致，与“都同意”搭配。", "偏": "语义：“偏”表示故意与众不同，与“都同意”的一致态度相反。", "欢快": "词性：“欢快”是形容词，不能充当副词修饰“都同意”。", "正在": "搭配：“正在”表示动作进行中，与“都同意”这一结果不搭。"}, "sentence_index": 6, "correct_answer": "大体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条街道很大体，两辆车并排开也没问题。", "explanation": "这里应该用〈宽敞〉。大体是副词，表示大致、基本如此，不能用来形容道路的宽阔。"}, {"text": "他很大体，遇到困难从不退缩。", "explanation": "这里应该用〈勇敢〉。大体表示大致、基本如此，不能形容人面对困难时的胆量。"}, {"text": "这台电脑很大体，外壳又厚又重。", "explanation": "这里应该用〈笨重〉。大体是副词，不能用来形容物体体积大、分量重。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'baba176c-b06f-47ee-846e-bf158efe36e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88033, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两台机器的功能大体的相同。", "corrected_sentence": "这两台机器的功能大体相同。", "error_description": "错误在“的”的使用：“大体”是副词，修饰“相同”时不能加“的”，应为“大体相同”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'baba176c-b06f-47ee-846e-bf158efe36e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88033, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些数据很大体可靠。", "corrected_sentence": "这些数据大体可靠。", "error_description": "错误在副词“很”：“大体”是副词，前面不能再加“很”，应删去，说“大体可靠”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'baba176c-b06f-47ee-846e-bf158efe36e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88037, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fbc760a-f0a4-4dab-8306-53e9ab979a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
