INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88037, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事业是一个人一生努力去做的大事。", "primary_collocate": null, "pronunciation": "shì yè", "ipa": "ʂɨ˥˩ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "他把一生都献给了自己的事业。", "target_word": "事业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷的事业做得很大。", "target_word": "事业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她为自己的事业努力了二十年。", "target_word": "事业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他年轻时就想做出一番事业。", "target_word": "事业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸说，家庭和事业都很重要。", "target_word": "事业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他放弃了工作，开始自己的事业。", "target_word": "事业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人一辈子的事业就是种树。", "target_word": "事业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的事业越来越成功。", "target_word": "事业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了事业，他很少回家。", "target_word": "事业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你打算从哪里开始你的事业？", "target_word": "事业", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "事業", "label": "繁体"}, {"form": "项", "label": "量词"}], "register": "中性", "sense_fingerprint": "个人一生奋斗的大事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc845970-b582-4cbd-8bfb-d42e50e4b40f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88037, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "事业", "is_correct": true, "explanation": "正确：事业（shì yè），指一个人一生努力去做的大事。"}, {"text": "实业", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是工业、商业等实业。"}, {"text": "失业", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，意思是失去工作。"}, {"text": "视野", "is_correct": false, "explanation": "yě（第三声）与 yè（第四声）声调不同，意思是视野，指眼睛能看到的范围。"}, {"text": "树叶", "is_correct": false, "explanation": "shù 与 shì 只有韵母不同（u 与 i），声调相同，意思是树叶。"}, {"text": "试验", "is_correct": false, "explanation": "yàn 与 yè 韵母不同（an 与 e），声调相同，意思是试验。"}], "explanations": {"事业": "正确：事业（shì yè），指一个人一生努力去做的大事。", "实业": "shí（第二声）与 shì（第四声）声调不同，意思是工业、商业等实业。", "失业": "shī（第一声）与 shì（第四声）声调不同，意思是失去工作。", "视野": "yě（第三声）与 yè（第四声）声调不同，意思是视野，指眼睛能看到的范围。", "树叶": "shù 与 shì 只有韵母不同（u 与 i），声调相同，意思是树叶。", "试验": "yàn 与 yè 韵母不同（an 与 e），声调相同，意思是试验。"}, "sentence_index": null, "correct_answer": "事业"}, "level_3": {"options": [{"text": "事业", "is_correct": true, "explanation": "正确：“献给”的对象是事业，指一生努力去做的大事，与“一生”相配。"}, {"text": "课本", "is_correct": false, "explanation": "搭配：“献给”多用于事业、生命、青春等，不能说献给课本。"}, {"text": "校车", "is_correct": false, "explanation": "语义：校车是交通工具，不能作为一生奉献的对象。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板是教室里的用具，不能用“一生都献给”来形容。"}], "explanations": {"事业": "正确：“献给”的对象是事业，指一生努力去做的大事，与“一生”相配。", "课本": "搭配：“献给”多用于事业、生命、青春等，不能说献给课本。", "校车": "语义：校车是交通工具，不能作为一生奉献的对象。", "黑板": "语义：黑板是教室里的用具，不能用“一生都献给”来形容。"}, "sentence_index": 0, "correct_answer": "事业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的事业是三节数学课。", "explanation": "这里应该用〈课程〉。学什么、上哪些课要说课程；事业指一生努力去做的大事，不能说成“三节数学课”。"}, {"text": "他的事业很优秀，每次考试都是第一名。", "explanation": "这里应该用〈学业〉。考试成绩和学习表现说的是学业；事业指一生努力去做的大事，不用于学习成绩。"}, {"text": "老师布置了很多事业，让我们放学后做。", "explanation": "这里应该用〈作业〉。老师布置、学生放学后完成的是作业；事业指一生努力去做的大事，不能布置给学生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fbc760a-f0a4-4dab-8306-53e9ab979a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88037, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "事业", "is_correct": true, "explanation": "正确：“一辈子的事业”指一生为之努力的大事，与“就是种树”相合。"}, {"text": "学业", "is_correct": false, "explanation": "语义：学业指学习的功课，与一辈子为之奋斗的追求不符。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是开门的用具，不能指一辈子的追求，句子读起来不通。"}, {"text": "年纪", "is_correct": false, "explanation": "搭配：“一辈子的年纪”搭配不通，年纪指年龄，不能与“就是种树”组成这样的说法。"}], "explanations": {"事业": "正确：“一辈子的事业”指一生为之努力的大事，与“就是种树”相合。", "学业": "语义：学业指学习的功课，与一辈子为之奋斗的追求不符。", "钥匙": "语义：钥匙是开门的用具，不能指一辈子的追求，句子读起来不通。", "年纪": "搭配：“一辈子的年纪”搭配不通，年纪指年龄，不能与“就是种树”组成这样的说法。"}, "sentence_index": 6, "correct_answer": "事业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场事业造成了很多人受伤。", "explanation": "这里应该用〈事故〉。事故指意外的不幸事件，会造成伤亡；事业指一生努力去做的大事，不会使人受伤。"}, {"text": "这家事业的董事长今天宣布辞职。", "explanation": "这里应该用〈企业〉。设董事长、宣布人事变动的是企业；事业指一生努力去做的大事，不设董事长。"}, {"text": "昨天的事业很突然。", "explanation": "这里应该用〈事件〉。事件指发生的事，可以突然发生；事业是长期努力的大事，不说突然发生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fbc760a-f0a4-4dab-8306-53e9ab979a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88037, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她决定把一生投入到这本事业中。", "corrected_sentence": "她决定把一生投入到这项事业中。", "error_description": "量词错误：事业的量词是“项”，应说“这项事业”；“本”用于书册，不能修饰事业。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fbc760a-f0a4-4dab-8306-53e9ab979a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88037, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他花了很多年才把这项事业们做起来。", "corrected_sentence": "他花了很多年才把这项事业做起来。", "error_description": "词缀错误：抽象名词“事业”后面不加“们”，应说“这项事业”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fbc760a-f0a4-4dab-8306-53e9ab979a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
