INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88038, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人们所从事的、有目标且影响较大的工作或活动。", "primary_collocate": null, "pronunciation": "shì yè", "ipa": "ʂɨ˥˩ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "他们一起做公益事业。", "target_word": "事业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国家很重视教育事业。", "target_word": "事业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医疗事业需要更多年轻人。", "target_word": "事业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这项慈善事业帮助了很多孩子。", "target_word": "事业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想为环保事业做一点事。", "target_word": "事业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "城市里的文化事业发展得很快。", "target_word": "事业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一生都在做体育事业。", "target_word": "事业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司也支持社会事业。", "target_word": "事业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的事业需要大家的帮助。", "target_word": "事业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "志愿者们为公益事业忙了一整天。", "target_word": "事业", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "事業", "label": "繁体"}, {"form": "项", "label": "量词"}], "register": "中性", "sense_fingerprint": "有目标、影响大的社会性工作或活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc845970-b582-4cbd-8bfb-d42e50e4b40f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88038, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "事业", "is_correct": true, "explanation": "正确：事业（shì yè），指社会上有目标、影响较大的工作或活动。"}, {"text": "实业", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是工业、商业等实业。"}, {"text": "失业", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，意思是失去工作。"}, {"text": "视野", "is_correct": false, "explanation": "yě（第三声）与 yè（第四声）声调不同，意思是视野，指眼睛能看到的范围。"}, {"text": "树叶", "is_correct": false, "explanation": "shù 与 shì 只有韵母不同（u 与 i），声调相同，意思是树叶。"}, {"text": "试验", "is_correct": false, "explanation": "yàn 与 yè 韵母不同（an 与 e），声调相同，意思是试验。"}], "explanations": {"事业": "正确：事业（shì yè），指社会上有目标、影响较大的工作或活动。", "实业": "shí（第二声）与 shì（第四声）声调不同，意思是工业、商业等实业。", "失业": "shī（第一声）与 shì（第四声）声调不同，意思是失去工作。", "视野": "yě（第三声）与 yè（第四声）声调不同，意思是视野，指眼睛能看到的范围。", "树叶": "shù 与 shì 只有韵母不同（u 与 i），声调相同，意思是树叶。", "试验": "yàn 与 yè 韵母不同（an 与 e），声调相同，意思是试验。"}, "sentence_index": null, "correct_answer": "事业"}, "level_3": {"options": [{"text": "事业", "is_correct": true, "explanation": "正确：“公益事业”指社会公益性的事业，与“做”搭配。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“做公益”后面不能接工资，两者不能组合。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是学生用品，不是可以“做”的公益对象。"}, {"text": "电线", "is_correct": false, "explanation": "语义：电线是导电的材料，“做公益电线”说不通。"}], "explanations": {"事业": "正确：“公益事业”指社会公益性的事业，与“做”搭配。", "工资": "搭配：“做公益”后面不能接工资，两者不能组合。", "书包": "语义：书包是学生用品，不是可以“做”的公益对象。", "电线": "语义：电线是导电的材料，“做公益电线”说不通。"}, "sentence_index": 0, "correct_answer": "事业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月的事业要在月底前交清。", "explanation": "这里应该用〈电费〉。需要在月底前交清的是费用，事业不能用“交清”来说。"}, {"text": "这场事业让很多孩子受了伤。", "explanation": "这里应该用〈事故〉。事故会让人受伤；事业是有目标的社会工作，不会造成伤害。"}, {"text": "这个事业很好笑，大家都笑了。", "explanation": "这里应该用〈笑话〉。笑话可以好笑，事业不能用“好笑”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fbc760a-f0a4-4dab-8306-53e9ab979a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88038, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "事业", "is_correct": true, "explanation": "正确：“做体育事业”指从事体育方面的事业，与“一生都在做”相合。"}, {"text": "眼镜", "is_correct": false, "explanation": "搭配：“做体育”后面不能接眼镜，两者不能组合。"}, {"text": "夜宵", "is_correct": false, "explanation": "语义：夜宵是食物，不能作为“做体育”的对象。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是用具，“做体育钥匙”说不通。"}], "explanations": {"事业": "正确：“做体育事业”指从事体育方面的事业，与“一生都在做”相合。", "眼镜": "搭配：“做体育”后面不能接眼镜，两者不能组合。", "夜宵": "语义：夜宵是食物，不能作为“做体育”的对象。", "钥匙": "语义：钥匙是用具，“做体育钥匙”说不通。"}, "sentence_index": 6, "correct_answer": "事业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家事业每年都生产很多汽车。", "explanation": "这里应该用〈企业〉。生产汽车的是企业；事业指有目标的社会性工作或活动，不负责生产产品。"}, {"text": "他这学期的事业很紧张。", "explanation": "这里应该用〈学业〉。学生这学期的功课要说学业；事业指有目标、影响较大的社会性工作或活动，不指学生的功课。"}, {"text": "这次事业的起因是一只猫打翻了牛奶。", "explanation": "这里应该用〈事件〉。事件有起因和经过；事业是有目标的长期工作，不说“起因是……”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fbc760a-f0a4-4dab-8306-53e9ab979a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88038, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本公益事业受到了很多人的支持。", "corrected_sentence": "这项公益事业受到了很多人的支持。", "error_description": "量词错误：事业的量词是“项”，应说“这项公益事业”；“本”用于书册，不能修饰事业。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fbc760a-f0a4-4dab-8306-53e9ab979a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88038, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张体育事业需要更多的支持。", "corrected_sentence": "这项体育事业需要更多的支持。", "error_description": "量词错误：事业的量词是“项”，应说“这项体育事业”；“张”用于纸张、桌子等平面物，不能修饰事业。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fbc760a-f0a4-4dab-8306-53e9ab979a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
