INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88039, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大麻是一种草，有的会让人上瘾。", "primary_collocate": null, "pronunciation": "dà má", "ipa": "ta⁵¹ ma³⁵", "syllable_count": 2, "sentences": [{"text": "这个国家不准人们吸大麻。", "target_word": "大麻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大麻会让人上瘾。", "target_word": "大麻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察发现他在卖大麻。", "target_word": "大麻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说大麻对身体不好。", "target_word": "大麻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友给他大麻，他没要。", "target_word": "大麻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人吸大麻，后来很难戒掉。", "target_word": "大麻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校告诉学生别碰大麻。", "target_word": "大麻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说大麻让他很难睡好觉。", "target_word": "大麻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在机场，他的包里查出了大麻。", "target_word": "大麻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吸大麻的人常常忘事。", "target_word": "大麻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一种会让人上瘾的草，毒品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52f58a29-0843-4b18-9594-88ac0b975df0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88039, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大麻", "is_correct": true, "explanation": "正确答案。大麻是这个词的标准形式，指毒品义的大麻。"}, {"text": "大妈", "is_correct": false, "explanation": "第二个音节 mā（第一声）与 má（第二声）声调不同，意思是年纪较大的妇女。"}, {"text": "大骂", "is_correct": false, "explanation": "第二个音节 mà（第四声）与 má（第二声）声调不同，意思是狠狠地骂人。"}, {"text": "大码", "is_correct": false, "explanation": "第二个音节 mǎ（第三声）与 má（第二声）声调不同，意思是大号的尺码。"}, {"text": "大忙", "is_correct": false, "explanation": "第二个音节 máng 比 má 多了韵尾 ng，意思是非常忙。"}, {"text": "大麦", "is_correct": false, "explanation": "第二个音节 mài（第四声）与 má 的韵母和声调都不同，意思是大麦。"}], "explanations": {"大麻": "正确答案。大麻是这个词的标准形式，指毒品义的大麻。", "大妈": "第二个音节 mā（第一声）与 má（第二声）声调不同，意思是年纪较大的妇女。", "大骂": "第二个音节 mà（第四声）与 má（第二声）声调不同，意思是狠狠地骂人。", "大码": "第二个音节 mǎ（第三声）与 má（第二声）声调不同，意思是大号的尺码。", "大忙": "第二个音节 máng 比 má 多了韵尾 ng，意思是非常忙。", "大麦": "第二个音节 mài（第四声）与 má 的韵母和声调都不同，意思是大麦。"}, "sentence_index": null, "correct_answer": "大麻"}, "level_3": {"options": [{"text": "大麻", "is_correct": true, "explanation": "正确答案。毒品义的大麻，与“吸”和“不准”搭配，符合句意。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“吸空气”指呼吸，不能成为国家禁止人们做的事，句意不通。"}, {"text": "香水", "is_correct": false, "explanation": "搭配：香水是喷在身上或闻的，“吸香水”不成立。"}, {"text": "咖啡", "is_correct": false, "explanation": "搭配：咖啡是喝的，不能说“吸咖啡”，句意不合。"}], "explanations": {"大麻": "正确答案。毒品义的大麻，与“吸”和“不准”搭配，符合句意。", "空气": "搭配：“吸空气”指呼吸，不能成为国家禁止人们做的事，句意不通。", "香水": "搭配：香水是喷在身上或闻的，“吸香水”不成立。", "咖啡": "搭配：咖啡是喝的，不能说“吸咖啡”，句意不合。"}, "sentence_index": 0, "correct_answer": "大麻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他买了一头大麻。", "explanation": "这里应该用〈包〉。〈头〉用于牛、猪等大型牲畜，大麻不能用〈头〉计量。"}, {"text": "医生给他打了大麻，他很快就睡着了。", "explanation": "这里应该用〈麻药〉。大麻是毒品或草本植物，不能用于注射麻醉；麻醉要用〈麻药〉。"}, {"text": "他买了一张大麻。", "explanation": "这里应该用〈包〉。〈张〉用于纸张、桌子等平面物件，大麻不能用〈张〉计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca9ddb30-e43a-4c63-956b-9f576adce309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88039, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大麻", "is_correct": true, "explanation": "正确答案。毒品义的大麻，学校告诉学生不要接触，符合句意。"}, {"text": "彩虹", "is_correct": false, "explanation": "语义：彩虹是光现象，无法用手去碰，与“别碰”的语境不合。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮在天上，学生不会去碰，句中“别碰”没有实际意义。"}, {"text": "阳光", "is_correct": false, "explanation": "搭配：“碰”通常接可以触摸的东西，阳光是光，不能用手碰。"}], "explanations": {"大麻": "正确答案。毒品义的大麻，学校告诉学生不要接触，符合句意。", "彩虹": "语义：彩虹是光现象，无法用手去碰，与“别碰”的语境不合。", "月亮": "语义：月亮在天上，学生不会去碰，句中“别碰”没有实际意义。", "阳光": "搭配：“碰”通常接可以触摸的东西，阳光是光，不能用手碰。"}, "sentence_index": 6, "correct_answer": "大麻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在墙上挂了一幅大麻。", "explanation": "这里应该用〈包〉。〈幅〉用于画作或挂图，毒品大麻不能用〈幅〉计量。"}, {"text": "他用大麻给手机充了电。", "explanation": "这里应该用〈充电器〉。大麻不能给手机充电，给手机充电要用〈充电器〉。"}, {"text": "他买了一台大麻，准备带走。", "explanation": "这里应该用〈包〉。〈台〉用于机器、设备，毒品大麻要按包计量，不能用〈台〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca9ddb30-e43a-4c63-956b-9f576adce309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88039, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "警察在他的包里发现了一只大麻。", "corrected_sentence": "警察在他的包里发现了一包大麻。", "error_description": "量词错误：毒品大麻应用量词〈包〉，不能用〈只〉（〈只〉多用于动物或成对物件）。正确说法是“一包大麻”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca9ddb30-e43a-4c63-956b-9f576adce309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88039, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的大麻们都被警察没收了。", "corrected_sentence": "他的大麻都被警察没收了。", "error_description": "错误：“大麻”是物质名词，不能加复数后缀“们”。正确说法：“他的大麻都被警察没收了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca9ddb30-e43a-4c63-956b-9f576adce309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
