INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88040, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一年生草本植物，茎皮纤维可制绳索；其花叶可制成毒品。", "primary_collocate": null, "pronunciation": "dà má", "ipa": "ta⁵¹ ma³⁵", "syllable_count": 2, "sentences": [{"text": "田里种着一片大麻。", "target_word": "大麻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民用大麻做绳子。", "target_word": "大麻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大麻的茎很长，皮可以做布。", "target_word": "大麻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这棵大麻有两米高。", "target_word": "大麻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前人们用大麻编鞋。", "target_word": "大麻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大麻一般在秋天收割。", "target_word": "大麻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民把大麻的皮剥下来做绳。", "target_word": "大麻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里有大麻做的衣服。", "target_word": "大麻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大麻的花和叶不能随便用。", "target_word": "大麻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在书上看到大麻的图片。", "target_word": "大麻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "棵", "label": "量词"}], "register": "中性", "sense_fingerprint": "一年生草本植物，茎皮纤维可制绳索", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52f58a29-0843-4b18-9594-88ac0b975df0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88040, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大麻", "is_correct": true, "explanation": "正确答案。植物义的大麻，茎皮纤维可以制绳。"}, {"text": "大妈", "is_correct": false, "explanation": "第二个音节 mā（第一声）与 má（第二声）声调不同，意思是大妈。"}, {"text": "大骂", "is_correct": false, "explanation": "第二个音节 mà（第四声）与 má（第二声）声调不同，意思是大骂。"}, {"text": "大码", "is_correct": false, "explanation": "第二个音节 mǎ（第三声）与 má（第二声）声调不同，意思是大号的尺码。"}, {"text": "大忙", "is_correct": false, "explanation": "第二个音节 máng 比 má 多了韵尾 ng，意思是非常忙。"}, {"text": "大麦", "is_correct": false, "explanation": "第二个音节 mài（第四声）与 má 的韵母和声调都不同，意思是大麦。"}], "explanations": {"大麻": "正确答案。植物义的大麻，茎皮纤维可以制绳。", "大妈": "第二个音节 mā（第一声）与 má（第二声）声调不同，意思是大妈。", "大骂": "第二个音节 mà（第四声）与 má（第二声）声调不同，意思是大骂。", "大码": "第二个音节 mǎ（第三声）与 má（第二声）声调不同，意思是大号的尺码。", "大忙": "第二个音节 máng 比 má 多了韵尾 ng，意思是非常忙。", "大麦": "第二个音节 mài（第四声）与 má 的韵母和声调都不同，意思是大麦。"}, "sentence_index": null, "correct_answer": "大麻"}, "level_3": {"options": [{"text": "大麻", "is_correct": true, "explanation": "正确答案。植物义的大麻，可以种在田里，符合句意。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“种”接的是植物，不能说“种手机”，与“田里种着”不合。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能种在田里，与“种着”的语境矛盾。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是乐器，不会种在田里，与“田里种着”矛盾。"}], "explanations": {"大麻": "正确答案。植物义的大麻，可以种在田里，符合句意。", "手机": "搭配：“种”接的是植物，不能说“种手机”，与“田里种着”不合。", "石头": "语义：石头不能种在田里，与“种着”的语境矛盾。", "钢琴": "语义：钢琴是乐器，不会种在田里，与“田里种着”矛盾。"}, "sentence_index": 0, "correct_answer": "大麻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "院子里摆了一本大麻。", "explanation": "这里应该用〈棵〉。〈本〉用于书籍，植株大麻应用〈棵〉计量。"}, {"text": "我家门口有一只大麻。", "explanation": "这里应该用〈棵〉。〈只〉不用于植株，植株应用〈棵〉计量。"}, {"text": "地里有一瓶大麻。", "explanation": "这里应该用〈棵〉。〈瓶〉用于液体或罐装物，植株不能用〈瓶〉计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca9ddb30-e43a-4c63-956b-9f576adce309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88040, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大麻", "is_correct": true, "explanation": "正确答案。大麻的皮可以剥下来做绳，符合句意。"}, {"text": "鸡蛋", "is_correct": false, "explanation": "语义：鸡蛋的壳不能剥下来做绳，与“做绳”的语境不合。"}, {"text": "书本", "is_correct": false, "explanation": "搭配：“书本的皮”是书皮，不能剥下来做绳，句意不通。"}, {"text": "树叶", "is_correct": false, "explanation": "语义：树叶没有可以剥下来做绳的皮，句意不合。"}], "explanations": {"大麻": "正确答案。大麻的皮可以剥下来做绳，符合句意。", "鸡蛋": "语义：鸡蛋的壳不能剥下来做绳，与“做绳”的语境不合。", "书本": "搭配：“书本的皮”是书皮，不能剥下来做绳，句意不通。", "树叶": "语义：树叶没有可以剥下来做绳的皮，句意不合。"}, "sentence_index": 6, "correct_answer": "大麻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在墙上贴了一张大麻。", "explanation": "这里应该用〈棵〉。〈张〉用于平面物件，植株大麻不能用〈张〉计量。"}, {"text": "路边停着一辆大麻。", "explanation": "这里应该用〈棵〉。〈辆〉用于车辆，植株大麻应用〈棵〉计量。"}, {"text": "院子里有三件大麻。", "explanation": "这里应该用〈棵〉。〈件〉用于衣服、事情，植株大麻应用〈棵〉计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca9ddb30-e43a-4c63-956b-9f576adce309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88040, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块地里长着两头大麻。", "corrected_sentence": "这块地里长着两棵大麻。", "error_description": "量词错误：〈头〉用于牛、猪等动物，植株大麻应用量词〈棵〉。正确说法是“两棵大麻”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca9ddb30-e43a-4c63-956b-9f576adce309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88040, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些大麻们都长得很高。", "corrected_sentence": "这些大麻都长得很高。", "error_description": "错误：“大麻”是植物名称，不能加复数后缀“们”。正确说法：“这些大麻都长得很高”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca9ddb30-e43a-4c63-956b-9f576adce309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
