INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88041, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "议论是几个人一起说自己的想法和看法。", "primary_collocate": null, "pronunciation": "yì lùn", "ipa": "i˥˩ lwən˥˩", "syllable_count": 2, "sentences": [{"text": "同学们围在一起议论这次考试。", "target_word": "议论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都在议论明天的比赛。", "target_word": "议论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们小声议论着下午的活动怎么安排。", "target_word": "议论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课后，几个同学聚在门口议论这件事。", "target_word": "议论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居们常常在楼下议论小区的事情。", "target_word": "议论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天开会，大家议论了很久，还是没有决定。", "target_word": "议论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们几个人议论着暑假去哪儿玩。", "target_word": "议论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们坐在一起，议论今年的计划。", "target_word": "议论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们围着桌子议论晚饭吃什么。", "target_word": "议论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同事们在办公室里议论周末的活动。", "target_word": "议论", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "议论了", "label": "完成体"}, {"form": "议论着", "label": "持续体"}, {"form": "议论过", "label": "经历体"}, {"form": "议论议论", "label": "重叠"}, {"form": "议论纷纷", "label": "复合词"}], "register": "中性", "sense_fingerprint": "几个人聚在一起，互相谈自己对某事的想法和看法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8adc4d6f-ebb2-4854-98ad-9066d9a002e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88041, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "议论", "is_correct": true, "explanation": "正确答案。“议论”读作 yì lùn，意思是几个人一起说自己的想法和看法。"}, {"text": "一轮", "is_correct": false, "explanation": "lún（第二声）与 lùn（第四声）声调不同，意思是“一圈、一个周期”。"}, {"text": "立论", "is_correct": false, "explanation": "lì 与 yì 声母不同（l 与 y），意思是“提出并确立论点”。"}, {"text": "试论", "is_correct": false, "explanation": "shì 与 yì 声母不同（sh 与 y），意思是“对某一问题进行初步论述”，多用于文章题目。"}], "explanations": {"议论": "正确答案。“议论”读作 yì lùn，意思是几个人一起说自己的想法和看法。", "一轮": "lún（第二声）与 lùn（第四声）声调不同，意思是“一圈、一个周期”。", "立论": "lì 与 yì 声母不同（l 与 y），意思是“提出并确立论点”。", "试论": "shì 与 yì 声母不同（sh 与 y），意思是“对某一问题进行初步论述”，多用于文章题目。"}, "sentence_index": null, "correct_answer": "议论"}, "level_3": {"options": [{"text": "议论", "is_correct": true, "explanation": "正确答案。“议论”指几个人围在一起谈看法，符合“围在一起”“这次考试”的语境。"}, {"text": "搬运", "is_correct": false, "explanation": "语义：“搬运”针对物品，不能用来搬运一次考试，与“围在一起”的语境不合。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是器物，不说“修理考试”。"}, {"text": "测量", "is_correct": false, "explanation": "搭配：“测量”的对象是长度、重量等可量化的事物，不说“测量考试”。"}], "explanations": {"议论": "正确答案。“议论”指几个人围在一起谈看法，符合“围在一起”“这次考试”的语境。", "搬运": "语义：“搬运”针对物品，不能用来搬运一次考试，与“围在一起”的语境不合。", "修理": "搭配：“修理”的对象是器物，不说“修理考试”。", "测量": "搭配：“测量”的对象是长度、重量等可量化的事物，不说“测量考试”。"}, "sentence_index": 0, "correct_answer": "议论"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一个人在家议论这件事，决定明天再说。", "explanation": "这里应该用〈考虑〉。“议论”指几个人互相交换看法，一个人在家想事情应说“考虑”。"}, {"text": "我们议论好了明天去爬山。", "explanation": "这里应该用〈商量〉。“议论”只是各自说出看法，不表示达成一致的决定，定下计划应说“商量”。"}, {"text": "两个同学在走廊里议论起来，互相推搡，差点打起来。", "explanation": "这里应该用〈争吵〉。“议论”只是交换看法，不含吵闹或动手的意思；互相推搡、差点打起来应说“争吵”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4800114-7876-4847-9a37-f4b844e70c66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88041, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "议论", "is_correct": true, "explanation": "正确答案。“议论着暑假去哪儿玩”指几个人一起谈主意，符合句意。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”是讥笑他人，与“暑假去哪儿玩”的商量语境不合。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是房间、场地等，不说“打扫暑假”。"}, {"text": "包装", "is_correct": false, "explanation": "搭配：“包装”的对象是物品，不说“包装暑假去哪儿玩”。"}], "explanations": {"议论": "正确答案。“议论着暑假去哪儿玩”指几个人一起谈主意，符合句意。", "嘲笑": "语义：“嘲笑”是讥笑他人，与“暑假去哪儿玩”的商量语境不合。", "打扫": "搭配：“打扫”的对象是房间、场地等，不说“打扫暑假”。", "包装": "搭配：“包装”的对象是物品，不说“包装暑假去哪儿玩”。"}, "sentence_index": 6, "correct_answer": "议论"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台复印机在办公室里议论周末的活动。", "explanation": "这里不这么用。“议论”的主体应是发表看法的人，机器不能议论，这里应说“同事们”。"}, {"text": "同事们在办公室里议论了一块肉。", "explanation": "这里应该用〈吃〉。“议论”的对象是人或事情，肉不能被议论。"}, {"text": "妈妈在厨房里议论了一顿饭，很快就做好了。", "explanation": "这里应该用〈做〉。“议论”是发表看法，不能表示烹饪；做一顿饭应说“做”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4800114-7876-4847-9a37-f4b844e70c66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88041, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "同学们在教室里很议论这次考试的题目。", "corrected_sentence": "同学们在教室里议论这次考试的题目。", "error_description": "错误在“很”：“很”一般修饰形容词或少数心理动词，不能直接修饰“议论”这样的动作动词，应去掉“很”。应说“同学们在教室里议论这次考试的题目”，或说“议论得很热烈”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4800114-7876-4847-9a37-f4b844e70c66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88041, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同学们在教室里议论了着暑假的计划。", "corrected_sentence": "同学们在教室里议论着暑假的计划。", "error_description": "错误在“了”和“着”的重复：“议论”后表示持续只用“着”，不能同时用“了”。应说“议论着暑假的计划”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4800114-7876-4847-9a37-f4b844e70c66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
