INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88042, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对人或事物发表意见，评论。", "primary_collocate": null, "pronunciation": "yì lùn", "ipa": "i˥˩ lwən˥˩", "syllable_count": 2, "sentences": [{"text": "请你不要在背后议论别人。", "target_word": "议论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从来不议论同事的私事。", "target_word": "议论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都在议论这篇文章写得好不好。", "target_word": "议论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上有很多人议论这部新电影。", "target_word": "议论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不喜欢议论别人的穿着。", "target_word": "议论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷喜欢看报纸，也爱议论国家大事。", "target_word": "议论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他只是随口议论了几句，没想伤人。", "target_word": "议论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别人怎么议论我，我都不在乎。", "target_word": "议论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他议论过这个电影，说结局太简单。", "target_word": "议论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事不要随便议论。", "target_word": "议论", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "议论了", "label": "完成体"}, {"form": "议论着", "label": "持续体"}, {"form": "议论过", "label": "经历体"}, {"form": "议论议论", "label": "重叠"}, {"form": "议论纷纷", "label": "复合词"}], "register": "中性", "sense_fingerprint": "对某个人或某件事发表意见、进行评论", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8adc4d6f-ebb2-4854-98ad-9066d9a002e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88042, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "议论", "is_correct": true, "explanation": "正确答案。“议论”读作 yì lùn，这里指对人或事物发表意见、进行评论。"}, {"text": "一轮", "is_correct": false, "explanation": "lún（第二声）与 lùn（第四声）声调不同，意思是“一圈、一个周期”。"}, {"text": "立论", "is_correct": false, "explanation": "lì 与 yì 声母不同（l 与 y），意思是“提出并确立论点”。"}, {"text": "试论", "is_correct": false, "explanation": "shì 与 yì 声母不同（sh 与 y），意思是“对某一问题进行初步论述”。"}], "explanations": {"议论": "正确答案。“议论”读作 yì lùn，这里指对人或事物发表意见、进行评论。", "一轮": "lún（第二声）与 lùn（第四声）声调不同，意思是“一圈、一个周期”。", "立论": "lì 与 yì 声母不同（l 与 y），意思是“提出并确立论点”。", "试论": "shì 与 yì 声母不同（sh 与 y），意思是“对某一问题进行初步论述”。"}, "sentence_index": null, "correct_answer": "议论"}, "level_3": {"options": [{"text": "议论", "is_correct": true, "explanation": "正确答案。“在背后议论别人”指背地里发表对别人的看法，符合句意。"}, {"text": "迎接", "is_correct": false, "explanation": "语义：“迎接”是当面相迎，与“在背后”的语境矛盾。"}, {"text": "运输", "is_correct": false, "explanation": "搭配：“运输”的对象是货物，不用于人，不说“运输别人”。"}, {"text": "拜访", "is_correct": false, "explanation": "语义：“拜访”需要当面登门，与“在背后”的语境不合。"}], "explanations": {"议论": "正确答案。“在背后议论别人”指背地里发表对别人的看法，符合句意。", "迎接": "语义：“迎接”是当面相迎，与“在背后”的语境矛盾。", "运输": "搭配：“运输”的对象是货物，不用于人，不说“运输别人”。", "拜访": "语义：“拜访”需要当面登门，与“在背后”的语境不合。"}, "sentence_index": 0, "correct_answer": "议论"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用手指议论了桌上的书。", "explanation": "这里应该用〈翻〉。“议论”是用语言发表看法，不能用手指完成；用手指翻桌上的书应说“翻”。"}, {"text": "他议论了一杯水，然后就去洗手了。", "explanation": "这里应该用〈喝〉。“议论”是发表看法，不能用于饮用；把一杯水喝掉应说“喝”。"}, {"text": "这张桌子议论了网上的新电影。", "explanation": "这里不这么用。“议论”的主体只能是能发表看法的人，桌子不能发表意见；应说“大家议论网上的新电影”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4800114-7876-4847-9a37-f4b844e70c66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88042, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "议论", "is_correct": true, "explanation": "正确答案。“随口议论了几句”指随便说了几句评论，符合句意。"}, {"text": "挥手", "is_correct": false, "explanation": "搭配：“随口”指说话，“挥手”不是说话，不能说“随口挥手”。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：“咳嗽”不是说话，与“随口说了几句，没想伤人”的语境不合。"}, {"text": "设计", "is_correct": false, "explanation": "语义：“设计”是有计划地构思，与“随口”的随意说话不合。"}], "explanations": {"议论": "正确答案。“随口议论了几句”指随便说了几句评论，符合句意。", "挥手": "搭配：“随口”指说话，“挥手”不是说话，不能说“随口挥手”。", "咳嗽": "语义：“咳嗽”不是说话，与“随口说了几句，没想伤人”的语境不合。", "设计": "语义：“设计”是有计划地构思，与“随口”的随意说话不合。"}, "sentence_index": 6, "correct_answer": "议论"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这款新产品很好，他立刻议论了一大箱。", "explanation": "这里应该用〈买〉。“议论”是发表看法，不能带“一大箱”这样的数量宾语；买一大箱应说“买”。"}, {"text": "这件事议论了他们。", "explanation": "这里不这么用。“议论”的施事应是发表看法的人，“这件事”不能议论人；应说“大家议论这件事”。"}, {"text": "他议论了一下门，然后关上了它。", "explanation": "这里应该用〈推〉。“议论”是发表看法，不能用于门这样的物件；把门推开应说“推”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4800114-7876-4847-9a37-f4b844e70c66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88042, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "别在背后很议论朋友，要当面说。", "corrected_sentence": "别在背后议论朋友，要当面说。", "error_description": "错误在“很”：“很”不能直接修饰“议论”这样的动作动词，应去掉“很”。应说“别在背后议论朋友，要当面说。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4800114-7876-4847-9a37-f4b844e70c66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88042, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家在背后被议论他，他一点也不在乎。", "corrected_sentence": "大家在背后议论他，他一点也不在乎。", "error_description": "错误在“被”：“议论”带宾语“他”时是主动句，前面不能加“被”，应说“议论他”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4800114-7876-4847-9a37-f4b844e70c66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
