INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88043, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "逼是让别人一定要做他不想做的事。", "primary_collocate": null, "pronunciation": "bī", "ipa": "pi˥", "syllable_count": 1, "sentences": [{"text": "别逼我，我真的不想去。", "target_word": "逼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸逼我学钢琴，我不喜欢。", "target_word": "逼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈逼着我吃药。", "target_word": "逼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板逼他今天做完工作。", "target_word": "逼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不要逼孩子学太多东西。", "target_word": "逼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想结婚，家人却天天逼他。", "target_word": "逼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友逼我唱了一首歌。", "target_word": "逼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师逼我们每天写日记。", "target_word": "逼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没有逼你，是你自己愿意的。", "target_word": "逼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他逼我说出了真话。", "target_word": "逼", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "逼着", "label": "体标"}, {"form": "逼了", "label": "体标"}], "register": "口语", "sense_fingerprint": "向别人施加压力，让对方做不想做的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5429df9e-59d2-4ea4-a29b-edbfe11afe3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88043, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "逼", "is_correct": true, "explanation": "正确答案：逼（bī），意思是迫使别人做不想做的事。"}, {"text": "比", "is_correct": false, "explanation": "bǐ（第三声）与 bī（第一声）声调不同，意思是比较。"}, {"text": "鼻", "is_correct": false, "explanation": "bí（第二声）与 bī（第一声）声调不同，意思是鼻子。"}, {"text": "闭", "is_correct": false, "explanation": "bì（第四声）与 bī（第一声）声调不同，意思是关闭。"}, {"text": "批", "is_correct": false, "explanation": "pī（第一声）与 bī（第一声）声母不同（p 与 b），意思是批准、批评。"}, {"text": "低", "is_correct": false, "explanation": "dī（第一声）与 bī（第一声）声母不同（d 与 b），意思是低。"}], "explanations": {"逼": "正确答案：逼（bī），意思是迫使别人做不想做的事。", "比": "bǐ（第三声）与 bī（第一声）声调不同，意思是比较。", "鼻": "bí（第二声）与 bī（第一声）声调不同，意思是鼻子。", "闭": "bì（第四声）与 bī（第一声）声调不同，意思是关闭。", "批": "pī（第一声）与 bī（第一声）声母不同（p 与 b），意思是批准、批评。", "低": "dī（第一声）与 bī（第一声）声母不同（d 与 b），意思是低。"}, "sentence_index": null, "correct_answer": "逼"}, "level_3": {"options": [{"text": "逼", "is_correct": true, "explanation": "正确：“别逼我”表示不要强迫我，与“我真的不想去”的语境相合。"}, {"text": "恭喜", "is_correct": false, "explanation": "语义：“别恭喜我”与“我真的不想去”的语境矛盾。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”与拒绝去的语境不相合，不能用来表达对方不要再劝说。"}, {"text": "照顾", "is_correct": false, "explanation": "语义：“照顾”是关照、照料，与“我真的不想去”的拒绝语境不合。"}], "explanations": {"逼": "正确：“别逼我”表示不要强迫我，与“我真的不想去”的语境相合。", "恭喜": "语义：“别恭喜我”与“我真的不想去”的语境矛盾。", "表扬": "语义：“表扬”与拒绝去的语境不相合，不能用来表达对方不要再劝说。", "照顾": "语义：“照顾”是关照、照料，与“我真的不想去”的拒绝语境不合。"}, "sentence_index": 0, "correct_answer": "逼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师用好奇心逼学生主动读书。", "explanation": "这里应该用〈诱导〉。逼是强迫，与“主动”矛盾，应用“诱导”让学生自愿读书。"}, {"text": "妈妈逼我多吃蔬菜，我很愿意。", "explanation": "这里应该用〈劝〉。逼是强迫别人做不想做的事，与“我很愿意”矛盾；劝是说服对方自愿去做。"}, {"text": "我被爸爸逼得非常开心地学钢琴。", "explanation": "这里应该用〈哄〉。逼是强迫，与“非常开心地”的心情矛盾；哄是用好话让人高兴地去做。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d813a9-f326-4da9-8aaf-42679c863da2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88043, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "逼", "is_correct": true, "explanation": "正确答案：逼（bī），意思是迫使别人做不想做的事。"}, {"text": "笔", "is_correct": false, "explanation": "bǐ（第三声）与 bī（第一声）声调不同，意思是笔。"}, {"text": "必", "is_correct": false, "explanation": "bì（第四声）与 bī（第一声）声调不同，意思是必须。"}, {"text": "披", "is_correct": false, "explanation": "pī（第一声）与 bī（第一声）声母不同（p 与 b），意思是披上。"}, {"text": "滴", "is_correct": false, "explanation": "dī（第一声）与 bī（第一声）声母不同（d 与 b），意思是滴下。"}], "explanations": {"逼": "正确答案：逼（bī），意思是迫使别人做不想做的事。", "笔": "bǐ（第三声）与 bī（第一声）声调不同，意思是笔。", "必": "bì（第四声）与 bī（第一声）声调不同，意思是必须。", "披": "pī（第一声）与 bī（第一声）声母不同（p 与 b），意思是披上。", "滴": "dī（第一声）与 bī（第一声）声母不同（d 与 b），意思是滴下。"}, "sentence_index": null, "correct_answer": "逼"}, "level_3": {"options": [{"text": "逼", "is_correct": true, "explanation": "正确：“朋友逼我唱歌”表示朋友强迫我，与语境相合。"}, {"text": "驱逐", "is_correct": false, "explanation": "语义：驱逐是赶走，不能用于“唱了一首歌”这种行为。"}, {"text": "悼念", "is_correct": false, "explanation": "语义：悼念是哀悼死者，与“唱歌”的语境不符。"}, {"text": "欢送", "is_correct": false, "explanation": "搭配：“欢送”的对象是离去的人，不能接“唱了一首歌”。"}], "explanations": {"逼": "正确：“朋友逼我唱歌”表示朋友强迫我，与语境相合。", "驱逐": "语义：驱逐是赶走，不能用于“唱了一首歌”这种行为。", "悼念": "语义：悼念是哀悼死者，与“唱歌”的语境不符。", "欢送": "搭配：“欢送”的对象是离去的人，不能接“唱了一首歌”。"}, "sentence_index": 6, "correct_answer": "逼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用真诚逼我放下戒心。", "explanation": "这里应该用〈说服〉。逼是强迫，与“真诚”的态度相矛盾。"}, {"text": "他诚恳地逼我参加晚会。", "explanation": "这里应该用〈邀请〉。逼是强迫，与“诚恳地”的态度相矛盾。"}, {"text": "我很想告诉他，他就逼我说出了真话。", "explanation": "这里应该用〈让〉。逼是强迫别人做不想做的事，与“我很想告诉他”矛盾；让是允许或使对方去做。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d813a9-f326-4da9-8aaf-42679c863da2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88043, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我妹妹被爸爸逼让学画画。", "corrected_sentence": "我妹妹被爸爸逼着学画画。", "error_description": "“逼”已表示使令，后面不能再加“让”，构成重复使令。应将“让”改为表示持续的“着”，写作：我妹妹被爸爸逼着学画画。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d813a9-f326-4da9-8aaf-42679c863da2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88043, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他常常逼让儿子练琴。", "corrected_sentence": "他常常逼儿子练琴。", "error_description": "“逼”已表示使令，其后不能再加“让”，构成重复使令。应去掉“让”，写作：他常常逼儿子练琴。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d813a9-f326-4da9-8aaf-42679c863da2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
