INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88044, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用强力使对方服从；强迫。", "primary_collocate": null, "pronunciation": "bī", "ipa": "pi˥", "syllable_count": 1, "sentences": [{"text": "敌人逼他交出了地图。", "target_word": "逼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坏人逼老人把钱交出来。", "target_word": "逼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "官兵逼百姓交粮食。", "target_word": "逼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用刀逼司机停车。", "target_word": "逼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察逼小偷放下了刀。", "target_word": "逼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "强盗逼着村民搬走了。", "target_word": "逼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌军逼将军投降。", "target_word": "逼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用暴力逼我签了字。", "target_word": "逼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王逼大臣说出了秘密。", "target_word": "逼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坏人用枪逼他开了门。", "target_word": "逼", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "逼着", "label": "体标"}, {"form": "逼了", "label": "体标"}], "register": "中性", "sense_fingerprint": "用强力、武力或暴力迫使对方服从", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5429df9e-59d2-4ea4-a29b-edbfe11afe3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88044, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "逼", "is_correct": true, "explanation": "正确答案：逼（bī），意思是用强力使对方服从。"}, {"text": "比", "is_correct": false, "explanation": "bǐ（第三声）与 bī（第一声）声调不同，意思是比较。"}, {"text": "鼻", "is_correct": false, "explanation": "bí（第二声）与 bī（第一声）声调不同，意思是鼻子。"}, {"text": "闭", "is_correct": false, "explanation": "bì（第四声）与 bī（第一声）声调不同，意思是关闭。"}, {"text": "批", "is_correct": false, "explanation": "pī（第一声）与 bī（第一声）声母不同（p 与 b），意思是批准、批评。"}, {"text": "低", "is_correct": false, "explanation": "dī（第一声）与 bī（第一声）声母不同（d 与 b），意思是低。"}], "explanations": {"逼": "正确答案：逼（bī），意思是用强力使对方服从。", "比": "bǐ（第三声）与 bī（第一声）声调不同，意思是比较。", "鼻": "bí（第二声）与 bī（第一声）声调不同，意思是鼻子。", "闭": "bì（第四声）与 bī（第一声）声调不同，意思是关闭。", "批": "pī（第一声）与 bī（第一声）声母不同（p 与 b），意思是批准、批评。", "低": "dī（第一声）与 bī（第一声）声母不同（d 与 b），意思是低。"}, "sentence_index": null, "correct_answer": "逼"}, "level_3": {"options": [{"text": "逼", "is_correct": true, "explanation": "正确：“敌人逼他交出地图”表示敌人用强力迫使他服从，语境相合。"}, {"text": "保护", "is_correct": false, "explanation": "语义：“保护”与敌人用强力迫使对方交出地图的意图相反。"}, {"text": "欢迎", "is_correct": false, "explanation": "搭配：“欢迎”不用于强迫对方交出东西，搭配不当。"}, {"text": "慰问", "is_correct": false, "explanation": "配价：“慰问”后不能接“交出了地图”这样的兼语小句。"}], "explanations": {"逼": "正确：“敌人逼他交出地图”表示敌人用强力迫使他服从，语境相合。", "保护": "语义：“保护”与敌人用强力迫使对方交出地图的意图相反。", "欢迎": "搭配：“欢迎”不用于强迫对方交出东西，搭配不当。", "慰问": "配价：“慰问”后不能接“交出了地图”这样的兼语小句。"}, "sentence_index": 0, "correct_answer": "逼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "特警冲进大楼，逼人质平安地离开了危险。", "explanation": "这里应该用〈解救〉。逼是强迫，此处是把人质救出，不是用强力迫使他们服从。"}, {"text": "他用糖果逼小孩上车。", "explanation": "这里应该用〈诱骗〉。逼是强迫，与“糖果”这种诱饵的手段矛盾。"}, {"text": "他心甘情愿地被逼交出了钱。", "explanation": "这里应该用〈劝〉。逼是用强力使对方服从，与“心甘情愿”矛盾；劝是说服对方自愿去做。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d813a9-f326-4da9-8aaf-42679c863da2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88044, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "逼", "is_correct": true, "explanation": "正确答案：逼（bī），意思是用强力使对方服从。"}, {"text": "笔", "is_correct": false, "explanation": "bǐ（第三声）与 bī（第一声）声调不同，意思是笔。"}, {"text": "必", "is_correct": false, "explanation": "bì（第四声）与 bī（第一声）声调不同，意思是必须。"}, {"text": "披", "is_correct": false, "explanation": "pī（第一声）与 bī（第一声）声母不同（p 与 b），意思是披上。"}, {"text": "滴", "is_correct": false, "explanation": "dī（第一声）与 bī（第一声）声母不同（d 与 b），意思是滴下。"}], "explanations": {"逼": "正确答案：逼（bī），意思是用强力使对方服从。", "笔": "bǐ（第三声）与 bī（第一声）声调不同，意思是笔。", "必": "bì（第四声）与 bī（第一声）声调不同，意思是必须。", "披": "pī（第一声）与 bī（第一声）声母不同（p 与 b），意思是披上。", "滴": "dī（第一声）与 bī（第一声）声母不同（d 与 b），意思是滴下。"}, "sentence_index": null, "correct_answer": "逼"}, "level_3": {"options": [{"text": "逼", "is_correct": true, "explanation": "正确：“敌军逼将军投降”表示敌军用强力迫使将军服从，语境相合。"}, {"text": "恭喜", "is_correct": false, "explanation": "语义：敌军恭喜将军投降，与敌军迫使对方的语境相反。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：敌军感谢将军投降不合逻辑，与敌军迫使将军服从的语境相反。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：赞美将军投降不符合敌军强迫对方的语境。"}], "explanations": {"逼": "正确：“敌军逼将军投降”表示敌军用强力迫使将军服从，语境相合。", "恭喜": "语义：敌军恭喜将军投降，与敌军迫使对方的语境相反。", "感谢": "语义：敌军感谢将军投降不合逻辑，与敌军迫使将军服从的语境相反。", "赞美": "语义：赞美将军投降不符合敌军强迫对方的语境。"}, "sentence_index": 6, "correct_answer": "逼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师用爱心逼了那个调皮的学生。", "explanation": "这里应该用〈感化〉。逼是强迫，与“用爱心”的方式矛盾。"}, {"text": "他自己很想签字，是大家逼着他签了字。", "explanation": "这里应该用〈说服〉。逼是用强力使对方服从，与“他自己很想签字”矛盾；说服是让对方自己同意去做。"}, {"text": "他高高兴兴地被逼去唱了一首歌。", "explanation": "这里应该用〈邀请〉。逼是用强力使对方服从，与“高高兴兴”的心情矛盾；邀请是客气地请对方去做。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d813a9-f326-4da9-8aaf-42679c863da2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88044, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "土匪逼让商人交出了钱。", "corrected_sentence": "土匪逼着商人交出了钱。", "error_description": "“逼”已表示使令，不能再与“让”连用，构成重复使令。应将“让”改为表示持续的“着”，写作：土匪逼着商人交出了钱。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d813a9-f326-4da9-8aaf-42679c863da2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88044, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们用刀逼让农民交出了钱。", "corrected_sentence": "他们用刀逼农民交出了钱。", "error_description": "“逼”已表示使令，其后不能再加“让”，构成重复使令。应去掉“让”，写作：他们用刀逼农民交出了钱。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d813a9-f326-4da9-8aaf-42679c863da2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
