INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88045, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "女书是以前只有女人用的一种字。", "primary_collocate": null, "pronunciation": "nǚ shū", "ipa": "ny˨˩˦ ʂu˥", "syllable_count": 2, "sentences": [{"text": "以前的女人常用女书写信。", "target_word": "女书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女书的字不像汉字，男人看不懂。", "target_word": "女书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她奶奶年轻时会写女书。", "target_word": "女书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在江永，女书是姐妹之间的秘密。", "target_word": "女书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校请老人来教孩子们写女书。", "target_word": "女书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把扇子上写着女书。", "target_word": "女书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女书用的是女人自己的字。", "target_word": "女书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想学女书，可是不知道在哪儿学。", "target_word": "女书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里有一章专门介绍女书。", "target_word": "女书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过去只有女人会读女书。", "target_word": "女书", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "过去只有女人使用的一种特别的字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52f58a29-0843-4b18-9594-88ac0b975df0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88045, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "女书", "is_correct": true, "explanation": "女书：过去只有女人使用的文字，用它写信与“以前的女人”相符。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：“电脑”是现代的工具，与“以前的女人”的时代不符。"}, {"text": "手机", "is_correct": false, "explanation": "语义：“手机”是现代通讯工具，与“以前”的语境矛盾。"}, {"text": "打印机", "is_correct": false, "explanation": "搭配：“打印机”是打印文件的设备，不说用它“写信”。"}], "explanations": {"女书": "女书：过去只有女人使用的文字，用它写信与“以前的女人”相符。", "电脑": "语义：“电脑”是现代的工具，与“以前的女人”的时代不符。", "手机": "语义：“手机”是现代通讯工具，与“以前”的语境矛盾。", "打印机": "搭配：“打印机”是打印文件的设备，不说用它“写信”。"}, "sentence_index": 0, "correct_answer": "女书"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "奶奶用女书做了一碗面条。", "explanation": "这里应该用〈面粉〉。女书是一种文字，不能用来做吃的。"}, {"text": "女书这个词在江永很常见，指的是当地人说话的一种腔调。", "explanation": "这里是把女书当成〈口音〉来用了。女书指书写用的文字，不指说话的腔调。"}, {"text": "湖南话是一种女书，很多人会说。", "explanation": "这里应该用〈方言〉。女书是文字，不是语言；湖南话属于方言，不能说它是女书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca9ddb30-e43a-4c63-956b-9f576adce309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88045, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "女书", "is_correct": true, "explanation": "女书：过去只有女人使用的字，与句中“女人自己的字”相符。"}, {"text": "甲骨文", "is_correct": false, "explanation": "语义：“甲骨文”是商代的古老文字，不是女人专用的字。"}, {"text": "篆书", "is_correct": false, "explanation": "语义：“篆书”是字体，不是女人自己使用的字。"}, {"text": "英文", "is_correct": false, "explanation": "搭配：“英文”是外语文字，不说“女人自己的字”。"}], "explanations": {"女书": "女书：过去只有女人使用的字，与句中“女人自己的字”相符。", "甲骨文": "语义：“甲骨文”是商代的古老文字，不是女人专用的字。", "篆书": "语义：“篆书”是字体，不是女人自己使用的字。", "英文": "搭配：“英文”是外语文字，不说“女人自己的字”。"}, "sentence_index": 6, "correct_answer": "女书"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "过去只有男人会读女书，女人都不认字。", "explanation": "这里应该用〈汉字〉来指过去只有男人会读的文字。女书专供过去的女性使用，说只有男人会读，与它的使用对象相反。"}, {"text": "这位老先生每天早上用女书跟路人打招呼。", "explanation": "这里应该用〈普通话〉。女书专供过去的女性使用，用来跟路人打招呼不符合它的用途，日常问候要用〈普通话〉。"}, {"text": "他在英语考试中用女书写了作文，老师看不懂。", "explanation": "这里应该用〈英文〉。女书专供过去的女性使用，英语考试的作文应用〈英文〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca9ddb30-e43a-4c63-956b-9f576adce309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88045, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师给我们讲了女书们的故事。", "corrected_sentence": "老师给我们讲了女书的故事。", "error_description": "错误：“女书”是一种文字的名称，不能加表示人的复数后缀“们”。正确说法：“女书的故事”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca9ddb30-e43a-4c63-956b-9f576adce309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88045, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我很想学女书们，可是不知道去哪儿学。", "corrected_sentence": "我很想学女书，可是不知道去哪儿学。", "error_description": "错误：“女书”是一种文字的名称，不能加复数后缀“们”。正确说法：“我很想学女书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca9ddb30-e43a-4c63-956b-9f576adce309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
