INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88046, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "流传于湖南江永一带、专供妇女使用的文字。", "primary_collocate": null, "pronunciation": "nǚ shū", "ipa": "ny˨˩˦ ʂu˥", "syllable_count": 2, "sentences": [{"text": "女书是湖南江永一带妇女用的文字。", "target_word": "女书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女书只在女人中流传，男人很少会写。", "target_word": "女书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在博物馆看到了一把写着女书的扇子。", "target_word": "女书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老奶奶会写女书，她还教过孙女。", "target_word": "女书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女书的字很细长，写起来很漂亮。", "target_word": "女书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师在研究女书。", "target_word": "女书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女书是女人写给姐妹的文字。", "target_word": "女书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用女书写了一封信。", "target_word": "女书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人不认识女书，因为它很少见。", "target_word": "女书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "江永的女书很有名，很多人去看。", "target_word": "女书", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "湖南江永一带妇女专用的文字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52f58a29-0843-4b18-9594-88ac0b975df0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88046, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "女书", "is_correct": true, "explanation": "女书：流传于湖南江永一带、专供妇女使用的文字，与句意相符。"}, {"text": "方言", "is_correct": false, "explanation": "语义：“方言”指地方话，不是写下来的文字。"}, {"text": "书法", "is_correct": false, "explanation": "语义：“书法”指写字的艺术，句子说的是一种文字，不是书写艺术。"}, {"text": "民谣", "is_correct": false, "explanation": "搭配：“民谣”是口头传唱的歌曲，不说“妇女用的文字”。"}], "explanations": {"女书": "女书：流传于湖南江永一带、专供妇女使用的文字，与句意相符。", "方言": "语义：“方言”指地方话，不是写下来的文字。", "书法": "语义：“书法”指写字的艺术，句子说的是一种文字，不是书写艺术。", "民谣": "搭配：“民谣”是口头传唱的歌曲，不说“妇女用的文字”。"}, "sentence_index": 0, "correct_answer": "女书"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈用女书做了一件新衣服。", "explanation": "这里应该用〈布〉。女书是一种文字，不能用来做衣服。"}, {"text": "湖南江永一带的人平时都说女书，这是当地的特色。", "explanation": "这里应该用〈方言〉。女书是书写用的文字，不是口头语言；当地人平时说话要用〈方言〉。"}, {"text": "他用女书在大字报上写了标语。", "explanation": "这里应该用〈汉字〉。女书只供妇女之间使用，大字报是公开张贴的，应该用汉字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca9ddb30-e43a-4c63-956b-9f576adce309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88046, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "女书", "is_correct": true, "explanation": "女书：专供妇女使用的文字，句中说的是女人写给姐妹，符合。"}, {"text": "英文", "is_correct": false, "explanation": "语义：“英文”是英语的文字，不是女人写给姐妹的专用文字。"}, {"text": "暗号", "is_correct": false, "explanation": "语义：“暗号”是事先约定的信号，不是写下来的文字。"}, {"text": "公文", "is_correct": false, "explanation": "语域：“公文”是正式的公务文书，与“写给姐妹”的私人语境不符。"}], "explanations": {"女书": "女书：专供妇女使用的文字，句中说的是女人写给姐妹，符合。", "英文": "语义：“英文”是英语的文字，不是女人写给姐妹的专用文字。", "暗号": "语义：“暗号”是事先约定的信号，不是写下来的文字。", "公文": "语域：“公文”是正式的公务文书，与“写给姐妹”的私人语境不符。"}, "sentence_index": 6, "correct_answer": "女书"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位工人每天在工地上用女书跟同事聊天，大家都听不懂。", "explanation": "这里应该用〈普通话〉。女书是专供妇女使用的书写文字，不是口头交流的语言；工地上聊天要用〈普通话〉。"}, {"text": "这张广告牌上用女书写着“打折”两个字，路人都看得懂。", "explanation": "这里应该用〈简体字〉。女书专供妇女使用，公开张贴的广告要用通行的〈简体字〉。"}, {"text": "他的作文是用女书写的，老师一个字也看不懂。", "explanation": "这里应该用〈汉字〉。女书专供妇女之间使用，学校作文应用〈汉字〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca9ddb30-e43a-4c63-956b-9f576adce309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88046, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老教授一直在研究女书们。", "corrected_sentence": "这位老教授一直在研究女书。", "error_description": "错误：“女书”是一种文字的名称，不能加复数后缀“们”。正确说法：“一直在研究女书”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca9ddb30-e43a-4c63-956b-9f576adce309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88046, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "江永的女书们很有名，很多游客想去看。", "corrected_sentence": "江永的女书很有名，很多游客想去看。", "error_description": "错误：“女书”是文字的名称，不能像可数名词那样加复数后缀“们”。正确说法：“江永的女书很有名”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca9ddb30-e43a-4c63-956b-9f576adce309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
