INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88047, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "财物是钱和值钱的东西。", "primary_collocate": null, "pronunciation": "cái wù", "ipa": "tsʰai˧˥ u˥˩", "syllable_count": 2, "sentences": [{"text": "小偷拿走了房间里的财物。", "target_word": "财物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的全部财物只有一个旧箱子。", "target_word": "财物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "离开房间前，请带好你的财物。", "target_word": "财物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒店要保护客人的财物安全。", "target_word": "财物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官要求他赔偿对方的财物损失。", "target_word": "财物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪水来了，村民们先搬走了财物。", "target_word": "财物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从来不拿别人一点财物。", "target_word": "财物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位商人把财物分给了三个孩子。", "target_word": "财物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "抢别人的财物是犯法的。", "target_word": "财物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "失火后，他们的财物全烧光了。", "target_word": "财物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "钱和值钱的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3cfd08e-3d21-43ff-b039-b447ed2d2985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88047, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "财物", "is_correct": true, "explanation": "正确：小偷拿走的是房间里的钱财和物品。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是房间里可以被拿走的财物，说不通。"}, {"text": "墙壁", "is_correct": false, "explanation": "语义：墙壁是房屋的结构，不能被小偷拿走。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：「拿走」的对象应是可以拿起的具体物品，颜色不能拿走。"}], "explanations": {"财物": "正确：小偷拿走的是房间里的钱财和物品。", "空气": "语义：空气不是房间里可以被拿走的财物，说不通。", "墙壁": "语义：墙壁是房屋的结构，不能被小偷拿走。", "颜色": "搭配：「拿走」的对象应是可以拿起的具体物品，颜色不能拿走。"}, "sentence_index": 0, "correct_answer": "财物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "春天的财物开了。", "explanation": "这里应该用〈花〉。财物指钱和值钱的东西，不能像花一样开放。"}, {"text": "外面下着大财物。", "explanation": "这里应该用〈雨〉。财物不能像雨一样从天而降。"}, {"text": "财物很新鲜。", "explanation": "这里应该用〈牛奶〉。财物指钱和值钱的东西，不能用来形容新鲜度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd21417dd-c9f1-4c61-b777-aa96f07bf1b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88047, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "财物", "is_correct": true, "explanation": "正确：她从来不拿别人的钱物。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不能被拿，「一点天空」说不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以拿的东西，句子说不通。"}, {"text": "灯光", "is_correct": false, "explanation": "搭配：「拿」的宾语应是可以拿在手里的东西，灯光不能拿。"}], "explanations": {"财物": "正确：她从来不拿别人的钱物。", "天空": "语义：天空不能被拿，「一点天空」说不通。", "天气": "语义：天气不是可以拿的东西，句子说不通。", "灯光": "搭配：「拿」的宾语应是可以拿在手里的东西，灯光不能拿。"}, "sentence_index": 6, "correct_answer": "财物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的财物叫李明。", "explanation": "这里应该用〈名字〉。财物指钱财和物品，不能用来称呼人。"}, {"text": "今天的财物很好。", "explanation": "这里应该用〈天气〉。财物不是天气，不能这样描述天气。"}, {"text": "他的财物很健康。", "explanation": "这里应该用〈身体〉。财物指钱和值钱的东西，不能用来说人的健康状况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd21417dd-c9f1-4c61-b777-aa96f07bf1b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88047, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只财物属于我们公司。", "corrected_sentence": "这笔财物属于我们公司。", "error_description": "量词错误：「只」不能用来计量财物，钱财类应用「笔」，应改为「这笔财物」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd21417dd-c9f1-4c61-b777-aa96f07bf1b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88047, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把一张财物交给了法院。", "corrected_sentence": "他把一批财物交给了法院。", "error_description": "量词错误：「张」用于纸张等，不能计量财物；财物应用「批」，应改为「一批财物」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd21417dd-c9f1-4c61-b777-aa96f07bf1b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88049, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出", "is_correct": true, "explanation": "“出”与“入”构成反义：“入”是从外面到里面，“出”是从里面到外面，与“走入”相对的是“走出”。"}, {"text": "跑", "is_correct": false, "explanation": "“跑”与“入”没有反义关系，二者不是相对的动作。"}, {"text": "坐", "is_correct": false, "explanation": "“坐”与“入”没有反义关系，二者不是相对的动作。"}, {"text": "唱", "is_correct": false, "explanation": "“唱”与“入”没有反义关系，二者不是相对的动作。"}], "correct_answer": "出", "explanations": {"出": "“出”与“入”构成反义：“入”是从外面到里面，“出”是从里面到外面，与“走入”相对的是“走出”。", "跑": "“跑”与“入”没有反义关系，二者不是相对的动作。", "坐": "“坐”与“入”没有反义关系，二者不是相对的动作。", "唱": "“唱”与“入”没有反义关系，二者不是相对的动作。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84db387b-9851-407c-b28e-aebbf04c37ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88049, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出", "is_correct": true, "explanation": "“出”与“入”构成反义：“入”是从外面到里面，“出”是从里面到外面，与“进入”相对。"}, {"text": "玩", "is_correct": false, "explanation": "“玩”与“入”没有反义关系，二者不是相对的动作。"}, {"text": "睡", "is_correct": false, "explanation": "“睡”与“入”没有反义关系，二者不是相对的动作。"}, {"text": "说", "is_correct": false, "explanation": "“说”与“入”没有反义关系，二者不是相对的动作。"}], "correct_answer": "出", "explanations": {"出": "“出”与“入”构成反义：“入”是从外面到里面，“出”是从里面到外面，与“进入”相对。", "玩": "“玩”与“入”没有反义关系，二者不是相对的动作。", "睡": "“睡”与“入”没有反义关系，二者不是相对的动作。", "说": "“说”与“入”没有反义关系，二者不是相对的动作。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84db387b-9851-407c-b28e-aebbf04c37ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88049, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "入指人、动物或交通工具自己从外面移动到里面。", "primary_collocate": null, "pronunciation": "rù", "ipa": "ʐu˥˩", "syllable_count": 1, "sentences": [{"text": "他推开门，走入教室。", "target_word": "入", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小鸟飞入树林，不见了。", "target_word": "入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子笑着跑入妈妈的怀里。", "target_word": "入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们沿着小路走入山谷。", "target_word": "入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车慢慢驶入车站。", "target_word": "入", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他从后门悄悄溜入了会场。", "target_word": "入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨停了，我们走入花园散步。", "target_word": "入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞机穿过云层，飞入蓝天。", "target_word": "入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口没人，他大步走入大厅。", "target_word": "入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里是办公室，非请勿入。", "target_word": "入", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "入口", "label": "复合"}, {"form": "入内", "label": "复合"}], "register": "书面语", "sense_fingerprint": "入：人、动物或交通工具自己从外面移动到里面（走入、飞入、驶入、请勿入）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T1: 3 words above tier T1 (max 2): 后门 (Zipf 3.75), 悄悄 (Zipf 3.95), 溜 (Zipf 3.92)']::text[], '81d15118-0c81-46f0-82ea-032f2bef765b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88049, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "入", "is_correct": true, "explanation": "入读 rù，表示从外面走到里面，与听到的音一致。"}, {"text": "如", "is_correct": false, "explanation": "rú（第二声）与 rù（第四声）声调不同，意思是如果、像。"}, {"text": "乳", "is_correct": false, "explanation": "rǔ（第三声）与 rù（第四声）声调不同，意思是乳汁。"}, {"text": "路", "is_correct": false, "explanation": "lù 与 rù 声母不同（l 与 r），声调相同，意思是道路。"}, {"text": "露", "is_correct": false, "explanation": "lù 与 rù 声母不同（l 与 r），声调相同，意思是露水。"}], "explanations": {"入": "入读 rù，表示从外面走到里面，与听到的音一致。", "如": "rú（第二声）与 rù（第四声）声调不同，意思是如果、像。", "乳": "rǔ（第三声）与 rù（第四声）声调不同，意思是乳汁。", "路": "lù 与 rù 声母不同（l 与 r），声调相同，意思是道路。", "露": "lù 与 rù 声母不同（l 与 r），声调相同，意思是露水。"}, "sentence_index": null, "correct_answer": "入"}, "level_3": {"options": [{"text": "入", "is_correct": true, "explanation": "“入”表示从外面进到里面，与“推开门”的动作相连，符合句意。"}, {"text": "管理", "is_correct": false, "explanation": "语义：“管理”指负责、掌管，与“推开门”之后的移动不相连，句意不通。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”多用于修复物品，不与人的位移动作“走”搭配。"}, {"text": "爱", "is_correct": false, "explanation": "语义：“爱”表示喜欢的情感，与“推开门”后的移动动作不合。"}], "explanations": {"入": "“入”表示从外面进到里面，与“推开门”的动作相连，符合句意。", "管理": "语义：“管理”指负责、掌管，与“推开门”之后的移动不相连，句意不通。", "修理": "搭配：“修理”多用于修复物品，不与人的位移动作“走”搭配。", "爱": "语义：“爱”表示喜欢的情感，与“推开门”后的移动动作不合。"}, "sentence_index": 0, "correct_answer": "入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从屋里走入院子外面。", "explanation": "这里的“入”表示进到里面，院子外面不是里面；表示向外走应该用〈走出〉。"}, {"text": "小猫跑入了山顶。", "explanation": "这里的“入”表示进到里面，山顶不是可以走进去的里面；此处应该用〈爬上〉。"}, {"text": "他笑入了教室。", "explanation": "这里的“入”需要与表示移动的动作搭配；“笑”不是移动动作，不能表示走进去，应该用〈走〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84db387b-9851-407c-b28e-aebbf04c37ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88049, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "入", "is_correct": true, "explanation": "入读 rù，表示从外面走到里面，与听到的音一致。"}, {"text": "鹿", "is_correct": false, "explanation": "lù 与 rù 声母不同（l 与 r），声调相同，意思是鹿。"}, {"text": "录", "is_correct": false, "explanation": "lù 与 rù 声母不同（l 与 r），声调相同，意思是记录。"}, {"text": "怒", "is_correct": false, "explanation": "nù 与 rù 声母不同（n 与 r），声调相同，意思是愤怒。"}, {"text": "日", "is_correct": false, "explanation": "rì（第四声）与 rù 韵母不同（i 与 u），意思是太阳、日子。"}], "explanations": {"入": "入读 rù，表示从外面走到里面，与听到的音一致。", "鹿": "lù 与 rù 声母不同（l 与 r），声调相同，意思是鹿。", "录": "lù 与 rù 声母不同（l 与 r），声调相同，意思是记录。", "怒": "nù 与 rù 声母不同（n 与 r），声调相同，意思是愤怒。", "日": "rì（第四声）与 rù 韵母不同（i 与 u），意思是太阳、日子。"}, "sentence_index": null, "correct_answer": "入"}, "level_3": {"options": [{"text": "入", "is_correct": true, "explanation": "“入”表示从外面进到里面，与“走”和“花园”搭配，符合句意。"}, {"text": "照顾", "is_correct": false, "explanation": "语义：“照顾”表示照料，“我们照顾花园散步”后半句不通，且“照顾”不表示走入。"}, {"text": "设计", "is_correct": false, "explanation": "语义：“设计”指规划绘图，与“雨停了”之后的散步不相连，句意不通。"}, {"text": "维护", "is_correct": false, "explanation": "语义：“维护”指保养保护，与“雨停了”之后的散步动作不合。"}], "explanations": {"入": "“入”表示从外面进到里面，与“走”和“花园”搭配，符合句意。", "照顾": "语义：“照顾”表示照料，“我们照顾花园散步”后半句不通，且“照顾”不表示走入。", "设计": "语义：“设计”指规划绘图，与“雨停了”之后的散步不相连，句意不通。", "维护": "语义：“维护”指保养保护，与“雨停了”之后的散步动作不合。"}, "sentence_index": 6, "correct_answer": "入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他睡入了教室。", "explanation": "这里的“入”表示走进去，需要移动动作；“睡”不是移动，不能与“入”搭配，应该用〈走〉。"}, {"text": "下课了，学生们走入教室外面。", "explanation": "这里的“入”表示进到里面，教室外面不是里面；表示向外走应该用〈走出〉。"}, {"text": "孩子把头探入了窗户外面。", "explanation": "这里的“入”表示进到里面，窗外不是里面；表示向外伸出应该用〈探出〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84db387b-9851-407c-b28e-aebbf04c37ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88049, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小猫悄悄走了入厨房。", "corrected_sentence": "小猫悄悄走入了厨房。", "error_description": "“了”位置错误：“了”应放在补语“入”之后，即“走入了厨房”，不能插在“走”和“入”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84db387b-9851-407c-b28e-aebbf04c37ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88049, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小狗入跑了院子。", "corrected_sentence": "小狗跑入了院子。", "error_description": "“入”位置错误：“入”是补语，应紧跟动词“跑”之后，即“跑入”，不能放在“跑”前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84db387b-9851-407c-b28e-aebbf04c37ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88050, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出", "is_correct": true, "explanation": "“出”与“入”构成反义：“入”指东西进到里面，“出”指东西到外面，与“放入”相对的是“取出”。"}, {"text": "写", "is_correct": false, "explanation": "“写”与“入”没有反义关系，二者不是相对的动作。"}, {"text": "洗", "is_correct": false, "explanation": "“洗”与“入”没有反义关系，二者不是相对的动作。"}, {"text": "喝", "is_correct": false, "explanation": "“喝”与“入”没有反义关系，二者不是相对的动作。"}], "correct_answer": "出", "explanations": {"出": "“出”与“入”构成反义：“入”指东西进到里面，“出”指东西到外面，与“放入”相对的是“取出”。", "写": "“写”与“入”没有反义关系，二者不是相对的动作。", "洗": "“洗”与“入”没有反义关系，二者不是相对的动作。", "喝": "“喝”与“入”没有反义关系，二者不是相对的动作。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84db387b-9851-407c-b28e-aebbf04c37ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88050, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出", "is_correct": true, "explanation": "“出”与“入”构成反义：“入”指东西进到里面，“出”指东西到外面，与“放入”相对。"}, {"text": "玩", "is_correct": false, "explanation": "“玩”与“入”没有反义关系，二者不是相对的动作。"}, {"text": "睡", "is_correct": false, "explanation": "“睡”与“入”没有反义关系，二者不是相对的动作。"}, {"text": "说", "is_correct": false, "explanation": "“说”与“入”没有反义关系，二者不是相对的动作。"}], "correct_answer": "出", "explanations": {"出": "“出”与“入”构成反义：“入”指东西进到里面，“出”指东西到外面，与“放入”相对。", "玩": "“玩”与“入”没有反义关系，二者不是相对的动作。", "睡": "“睡”与“入”没有反义关系，二者不是相对的动作。", "说": "“说”与“入”没有反义关系，二者不是相对的动作。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84db387b-9851-407c-b28e-aebbf04c37ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88050, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西或液体进到容器或空间的里面，与“出”相对。", "primary_collocate": null, "pronunciation": "rù", "ipa": "ʐu˥˩", "syllable_count": 1, "sentences": [{"text": "把牛奶倒入杯子里。", "target_word": "入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把盐放入汤里，再搅一搅。", "target_word": "入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水流入大海。", "target_word": "入", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他把钥匙放入口袋里。", "target_word": "入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨水从窗缝流入屋里。", "target_word": "入", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "先把鸡蛋打入碗中，再加一点盐。", "target_word": "入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把文件放入抽屉里。", "target_word": "入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把脏衣服放入洗衣机里。", "target_word": "入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水不断流入池子，很快就满了。", "target_word": "入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把照片放入信封里。", "target_word": "入", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "入口", "label": "复合"}, {"form": "出入", "label": "复合"}], "register": "书面语", "sense_fingerprint": "入：东西或液体进到里面，与「出」相对（倒入、放入、流入、打入）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T1: 3 words above tier T1 (max 2): 雨水 (Zipf 3.94), 窗 (Zipf 3.98), 缝 (Zipf 3.92)']::text[], '81d15118-0c81-46f0-82ea-032f2bef765b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88050, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "入", "is_correct": true, "explanation": "入读 rù，表示东西或液体进到里面，与听到的音一致。"}, {"text": "如", "is_correct": false, "explanation": "rú（第二声）与 rù（第四声）声调不同，意思是如果、像。"}, {"text": "乳", "is_correct": false, "explanation": "rǔ（第三声）与 rù（第四声）声调不同，意思是乳汁。"}, {"text": "怒", "is_correct": false, "explanation": "nù 与 rù 声母不同（n 与 r），声调相同，意思是愤怒。"}, {"text": "露", "is_correct": false, "explanation": "lù 与 rù 声母不同（l 与 r），声调相同，意思是露水。"}], "explanations": {"入": "入读 rù，表示东西或液体进到里面，与听到的音一致。", "如": "rú（第二声）与 rù（第四声）声调不同，意思是如果、像。", "乳": "rǔ（第三声）与 rù（第四声）声调不同，意思是乳汁。", "怒": "nù 与 rù 声母不同（n 与 r），声调相同，意思是愤怒。", "露": "lù 与 rù 声母不同（l 与 r），声调相同，意思是露水。"}, "sentence_index": null, "correct_answer": "入"}, "level_3": {"options": [{"text": "入", "is_correct": true, "explanation": "“入”表示东西进到容器里，与“倒”搭配，符合句意。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”表示丢弃，与“把牛奶”进到杯子里的注入动作不符。"}, {"text": "泼", "is_correct": false, "explanation": "搭配：“泼”多指液体溅出，与把牛奶注入杯子的动作不搭配。"}, {"text": "搅", "is_correct": false, "explanation": "语义：“搅”表示搅动，与“倒”进杯子的动作不同，句意不通。"}], "explanations": {"入": "“入”表示东西进到容器里，与“倒”搭配，符合句意。", "扔": "语义：“扔”表示丢弃，与“把牛奶”进到杯子里的注入动作不符。", "泼": "搭配：“泼”多指液体溅出，与把牛奶注入杯子的动作不搭配。", "搅": "语义：“搅”表示搅动，与“倒”进杯子的动作不同，句意不通。"}, "sentence_index": 0, "correct_answer": "入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把钥匙从口袋里入到外面。", "explanation": "这里应该用〈拿出〉。“入”表示进到里面，与“出”相对，不能表示从里面到外面。"}, {"text": "他把牛奶入到桌子上。", "explanation": "这里应该用〈倒在〉。“入”需要进入容器或空间的里面，桌面不是里面，不能用“入”。"}, {"text": "他把书放入了桌子上面。", "explanation": "这里应该用〈放在〉。“入”表示进到容器或空间的里面，桌子上面不是里面，不能用“入”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84db387b-9851-407c-b28e-aebbf04c37ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88050, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "入", "is_correct": true, "explanation": "入读 rù，表示东西或液体进到里面，与听到的音一致。"}, {"text": "路", "is_correct": false, "explanation": "lù 与 rù 声母不同（l 与 r），声调相同，意思是道路。"}, {"text": "鹿", "is_correct": false, "explanation": "lù 与 rù 声母不同（l 与 r），声调相同，意思是鹿。"}, {"text": "录", "is_correct": false, "explanation": "lù 与 rù 声母不同（l 与 r），声调相同，意思是记录。"}, {"text": "日", "is_correct": false, "explanation": "rì（第四声）与 rù 韵母不同（i 与 u），意思是太阳、日子。"}], "explanations": {"入": "入读 rù，表示东西或液体进到里面，与听到的音一致。", "路": "lù 与 rù 声母不同（l 与 r），声调相同，意思是道路。", "鹿": "lù 与 rù 声母不同（l 与 r），声调相同，意思是鹿。", "录": "lù 与 rù 声母不同（l 与 r），声调相同，意思是记录。", "日": "rì（第四声）与 rù 韵母不同（i 与 u），意思是太阳、日子。"}, "sentence_index": null, "correct_answer": "入"}, "level_3": {"options": [{"text": "入", "is_correct": true, "explanation": "“入”表示东西进到里面，“请把文件放入抽屉里”符合句意。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”表示丢弃，“放扔抽屉里”不成句，且不表示进入。"}, {"text": "撕", "is_correct": false, "explanation": "语义：“撕”表示用力分开，与“放”连用不通，句意不成立。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”表示燃烧，与“放”连用不通，也不表示进入抽屉。"}], "explanations": {"入": "“入”表示东西进到里面，“请把文件放入抽屉里”符合句意。", "扔": "语义：“扔”表示丢弃，“放扔抽屉里”不成句，且不表示进入。", "撕": "语义：“撕”表示用力分开，与“放”连用不通，句意不成立。", "烧": "语义：“烧”表示燃烧，与“放”连用不通，也不表示进入抽屉。"}, "sentence_index": 6, "correct_answer": "入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他入了一杯水。", "explanation": "这里应该用〈倒入〉。“入”不能单独表示把液体倒进去，要说“倒入”。"}, {"text": "她把水从瓶子里倒入外面。", "explanation": "这里应该用〈倒出〉。“入”表示进到里面，与“出”相对，不能表示从里面到外面。"}, {"text": "他把信入了信箱。", "explanation": "这里应该用〈投入〉。“入”不能单独表示投递，投信要说“投入”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84db387b-9851-407c-b28e-aebbf04c37ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_