INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88050, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把糖倒了入牛奶里。", "corrected_sentence": "她把糖倒入了牛奶里。", "error_description": "“了”位置错误：应为“倒入了”，“了”放在“入”之后，不能插在“倒”和“入”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84db387b-9851-407c-b28e-aebbf04c37ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88050, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把盐撒进入汤里。", "corrected_sentence": "她把盐撒入汤里。", "error_description": "多加了“进”：“入”本身已表示进到里面，前面不能再加“进”，应直接说“撒入”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84db387b-9851-407c-b28e-aebbf04c37ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88051, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "聪明", "is_correct": false, "explanation": "与“好动”没有反义关系，“聪明”说的是头脑灵活，与是否爱活动无关。"}, {"text": "好静", "is_correct": true, "explanation": "“好静”指喜欢安静，与“好动”（喜欢活动）意思相反，是词典所列的反义词。"}, {"text": "干净", "is_correct": false, "explanation": "与“好动”没有反义关系，“干净”指没有污垢，与动静无关。"}, {"text": "高兴", "is_correct": false, "explanation": "与“好动”没有反义关系，“高兴”说的是心情，与是否喜欢活动无关。"}], "correct_answer": "好静", "explanations": {"聪明": "与“好动”没有反义关系，“聪明”说的是头脑灵活，与是否爱活动无关。", "好静": "“好静”指喜欢安静，与“好动”（喜欢活动）意思相反，是词典所列的反义词。", "干净": "与“好动”没有反义关系，“干净”指没有污垢，与动静无关。", "高兴": "与“好动”没有反义关系，“高兴”说的是心情，与是否喜欢活动无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88051, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "辛苦", "is_correct": false, "explanation": "与“好动”没有反义关系，“辛苦”指费力、劳累，与性格无关。"}, {"text": "便宜", "is_correct": false, "explanation": "与“好动”没有反义关系，“便宜”指价格低，与活动多少无关。"}, {"text": "认真", "is_correct": false, "explanation": "与“好动”没有反义关系，“认真”说的是做事态度，与是否爱活动无关。"}, {"text": "好静", "is_correct": true, "explanation": "“好静”指喜欢安静，与“好动”（喜欢活动）意思相反，是词典所列的反义词。"}], "correct_answer": "好静", "explanations": {"辛苦": "与“好动”没有反义关系，“辛苦”指费力、劳累，与性格无关。", "便宜": "与“好动”没有反义关系，“便宜”指价格低，与活动多少无关。", "认真": "与“好动”没有反义关系，“认真”说的是做事态度，与是否爱活动无关。", "好静": "“好静”指喜欢安静，与“好动”（喜欢活动）意思相反，是词典所列的反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88051, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "好动是喜欢动来动去，坐不住。", "primary_collocate": null, "pronunciation": "hào dòng", "ipa": "xɑʊ˥˩ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他很好动，坐在椅子上总是动来动去。", "target_word": "好动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子太好动了，一分钟也坐不住。", "target_word": "好动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好动的小明上课时不停地动。", "target_word": "好动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟好动，吃饭时也坐不住。", "target_word": "好动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我女儿好动，看电影时总要站起来。", "target_word": "好动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不是好动的人，可以一直坐着看书。", "target_word": "好动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猴子很好动，在树上跳来跳去。", "target_word": "好动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为好动，他在教室里常常坐不住。", "target_word": "好动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好动的孩子很难坐下来写作业。", "target_word": "好动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说我小时候特别好动，一刻也停不下来。", "target_word": "好动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "好動", "label": "繁体"}], "register": "口语", "sense_fingerprint": "形容人身体总在动、坐不住、静不下来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a96547-d1a2-4444-8d6e-1252fc20d0d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88051, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "安静", "is_correct": false, "explanation": "语义：安静指不爱动、不吵闹，与“坐在椅子上总是动来动去”的意思相反。"}, {"text": "好动", "is_correct": true, "explanation": "正确：好动指喜欢动来动去、坐不住，与句中“坐在椅子上总是动来动去”相合。"}, {"text": "稳重", "is_correct": false, "explanation": "语义：稳重指举止沉着，不轻易乱动，与“总是动来动去”矛盾。"}, {"text": "文质彬彬", "is_correct": false, "explanation": "语义：文质彬彬形容举止文雅安静，与“总是动来动去”矛盾。"}], "explanations": {"安静": "语义：安静指不爱动、不吵闹，与“坐在椅子上总是动来动去”的意思相反。", "好动": "正确：好动指喜欢动来动去、坐不住，与句中“坐在椅子上总是动来动去”相合。", "稳重": "语义：稳重指举止沉着，不轻易乱动，与“总是动来动去”矛盾。", "文质彬彬": "语义：文质彬彬形容举止文雅安静，与“总是动来动去”矛盾。"}, "sentence_index": 0, "correct_answer": "好动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一向好动，坐在椅子上一动不动。", "explanation": "这里应该用〈安静〉。好动指爱动来动去、坐不住，这句写他坐在椅子上一动不动，与好动相反。"}, {"text": "这个孩子很好动，上课时规规矩矩地坐着。", "explanation": "这里应该用〈乖巧〉。好动指爱动来动去、坐不住，与“规规矩矩地坐着”相反。"}, {"text": "他很好动，一坐就是一下午。", "explanation": "这里应该用〈沉稳〉。好动指爱动来动去、坐不住，这句写他一坐就是一下午，与好动相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88051, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "老实", "is_correct": false, "explanation": "语义：老实指听话、安分，与“在树上跳来跳去”的动态形象矛盾。"}, {"text": "好动", "is_correct": true, "explanation": "正确：好动指爱活动、坐不住，与“在树上跳来跳去”一致。"}, {"text": "文静", "is_correct": false, "explanation": "语义：文静指安静温和，与“在树上跳来跳去”的意思相反。"}, {"text": "安分守己", "is_correct": false, "explanation": "语域：安分守己是书面语，多用于描写人的行为，与口语描写小猴子的语境不协调。"}], "explanations": {"老实": "语义：老实指听话、安分，与“在树上跳来跳去”的动态形象矛盾。", "好动": "正确：好动指爱活动、坐不住，与“在树上跳来跳去”一致。", "文静": "语义：文静指安静温和，与“在树上跳来跳去”的意思相反。", "安分守己": "语域：安分守己是书面语，多用于描写人的行为，与口语描写小猴子的语境不协调。"}, "sentence_index": 6, "correct_answer": "好动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很好动，放学后总是坐在书桌前写作业。", "explanation": "这里应该用〈老实〉。好动指爱动来动去、坐不住，这句写他总坐在书桌前写作业，与好动相反。"}, {"text": "她很好动，走路慢吞吞的。", "explanation": "这里应该用〈懒散〉。好动指爱动来动去、坐不住，与“走路慢吞吞”的懒散形象相反。"}, {"text": "他很好动，一天到晚躺在床上。", "explanation": "这里应该用〈懒洋洋〉。好动指爱动来动去、坐不住，与“一天到晚躺在床上”相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88051, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他好动得，走路时也蹦蹦跳跳。", "corrected_sentence": "他好动得很，走路时也蹦蹦跳跳。", "error_description": "错误在补语。“好动得”后面缺少“很”，句子不完整，应说“好动得很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88051, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我侄子好动得，一刻也闲不下来。", "corrected_sentence": "我侄子好动得很，一刻也闲不下来。", "error_description": "错误在补语。“好动得很”中的“很”不能省略，说“好动得”句子不完整，应补上“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
