INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88052, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "喜欢活动，不愿安静。", "primary_collocate": null, "pronunciation": "hào dòng", "ipa": "xɑʊ˥˩ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我弟弟很好动，从来不愿安静地坐着。", "target_word": "好动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗都很好动，一出门就到处跑。", "target_word": "好动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她女儿好动，每天放学后都要去外面玩。", "target_word": "好动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好动的孩子不喜欢待在房间里。", "target_word": "好动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就好动，爱跑爱跳。", "target_word": "好动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只小猫很好动，一刻也不想安静。", "target_word": "好动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说我儿子好动，上课时总想站起来走走。", "target_word": "好动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好动的人通常喜欢运动。", "target_word": "好动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这么好动，不如去踢足球吧。", "target_word": "好动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不好动，周末喜欢在家看书。", "target_word": "好动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "好動", "label": "繁体"}], "register": "口语", "sense_fingerprint": "形容人或动物精力旺盛、喜欢活动、不愿安静", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a96547-d1a2-4444-8d6e-1252fc20d0d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88052, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "文静", "is_correct": false, "explanation": "语义：文静指举止安静温和，与句中“从来不愿安静地坐着”的意思相反。"}, {"text": "好动", "is_correct": true, "explanation": "正确：好动指喜欢活动、不愿安静，与“从来不愿安静地坐着”相合。"}, {"text": "沉稳", "is_correct": false, "explanation": "语义：沉稳指沉着稳重、不浮躁，与“从来不愿安静地坐着”的意思矛盾。"}, {"text": "老成", "is_correct": false, "explanation": "语义：老成指举止持重、不轻浮，与“从来不愿安静地坐着”的意思矛盾。"}], "explanations": {"文静": "语义：文静指举止安静温和，与句中“从来不愿安静地坐着”的意思相反。", "好动": "正确：好动指喜欢活动、不愿安静，与“从来不愿安静地坐着”相合。", "沉稳": "语义：沉稳指沉着稳重、不浮躁，与“从来不愿安静地坐着”的意思矛盾。", "老成": "语义：老成指举止持重、不轻浮，与“从来不愿安静地坐着”的意思矛盾。"}, "sentence_index": 0, "correct_answer": "好动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很好动，一整天都坐在窗边看书。", "explanation": "这里应该用〈安静〉。好动指爱活动、不愿安静，这句写他整天坐着看书，与好动的意思相反。"}, {"text": "这孩子很好动，上课时一直坐得端端正正。", "explanation": "这里应该用〈安分〉。好动指爱活动、坐不住，与“上课时一直坐得端端正正”相反。"}, {"text": "他很好动，平时很少走动。", "explanation": "这里应该用〈好静〉。好动指爱活动、不愿安静，这句说他平时很少走动，与好动相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88052, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "安分", "is_correct": false, "explanation": "语义：安分指规规矩矩、守规矩，与“上课时总想站起来走走”的意思矛盾。"}, {"text": "好动", "is_correct": true, "explanation": "正确：好动指喜欢活动、坐不住，与“上课时总想站起来走走”一致。"}, {"text": "斯文", "is_correct": false, "explanation": "语义：斯文指文雅有礼，与“上课时总想站起来走走”的坐不住形象不合。"}, {"text": "驯服", "is_correct": false, "explanation": "语义：驯服指温顺听话、服从管束，与“上课时总想站起来走走”的坐不住形象矛盾。"}], "explanations": {"安分": "语义：安分指规规矩矩、守规矩，与“上课时总想站起来走走”的意思矛盾。", "好动": "正确：好动指喜欢活动、坐不住，与“上课时总想站起来走走”一致。", "斯文": "语义：斯文指文雅有礼，与“上课时总想站起来走走”的坐不住形象不合。", "驯服": "语义：驯服指温顺听话、服从管束，与“上课时总想站起来走走”的坐不住形象矛盾。"}, "sentence_index": 6, "correct_answer": "好动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他性格很好动，平时很少说话，总是坐着。", "explanation": "这里应该用〈稳重〉。好动指爱活动、坐不住，与“平时很少说话、总是坐着”的描述相反。"}, {"text": "她很好动，一天到晚窝在沙发上。", "explanation": "这里应该用〈懒散〉。好动指爱活动、坐不住，与“一天到晚窝在沙发上”的意思相反。"}, {"text": "他一向好动，总坐在角落里不动。", "explanation": "这里应该用〈沉默〉。好动指爱活动、不愿安静，这句写他总坐在角落里一动不动，与好动相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88052, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他好动得，周末也不愿待在家里。", "corrected_sentence": "他好动得很，周末也不愿待在家里。", "error_description": "错误在补语。“好动得”后面缺少“很”，句子不完整，应说“好动得很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88052, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我女儿好动得，放学后一刻也不愿待在家里。", "corrected_sentence": "我女儿好动得很，放学后一刻也不愿待在家里。", "error_description": "错误在补语。“好动得很”中的“很”不能省略，说“好动得”句子不完整，应补上“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
