INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88053, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "贪婪是什么都想要，要得很多很多，还不满足。", "primary_collocate": null, "pronunciation": "tān lán", "ipa": "tʰan˥ lan˧˥", "syllable_count": 2, "sentences": [{"text": "弟弟很贪婪，什么玩具都想要。", "target_word": "贪婪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个小孩太贪婪了，拿了三块蛋糕还要。", "target_word": "贪婪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "贪婪的小猴子把所有的糖都拿走了。", "target_word": "贪婪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别这么贪婪，要学会分享。", "target_word": "贪婪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故事里的国王很贪婪，想要全世界的金子。", "target_word": "贪婪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很贪婪，买了新衣服还想买包。", "target_word": "贪婪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不喜欢贪婪的人。", "target_word": "贪婪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗变得贪婪，吃完饭还要吃。", "target_word": "贪婪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "贪婪的老鼠偷了一大堆米。", "target_word": "贪婪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，贪婪的孩子没有朋友。", "target_word": "贪婪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "贪婪地", "label": "状语形式"}, {"form": "贪婪的", "label": "定语形式"}], "register": "中性", "sense_fingerprint": "什么都想要、要很多还不满足（日常、儿童语境）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be7a67a-0052-4629-80f6-eca6c3881ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88053, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "贪婪", "is_correct": true, "explanation": "正确。“什么玩具都想要”正说明“贪婪”的特点。"}, {"text": "懂事", "is_correct": false, "explanation": "语义：懂事的孩子不会什么都想要，与后半句矛盾。"}, {"text": "大方", "is_correct": false, "explanation": "语义：大方是乐于给予，与“什么玩具都想要”相反。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材，与“玩具”无关，句子说不通。"}], "explanations": {"贪婪": "正确。“什么玩具都想要”正说明“贪婪”的特点。", "懂事": "语义：懂事的孩子不会什么都想要，与后半句矛盾。", "大方": "语义：大方是乐于给予，与“什么玩具都想要”相反。", "高大": "体貌：“高大”形容身材，与“玩具”无关，句子说不通。"}, "sentence_index": 0, "correct_answer": "贪婪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "弟弟每天很贪婪，放学后就去踢球。", "explanation": "这里应该用〈贪玩〉。“贪婪”指想要得到很多东西，不用来描述爱玩。"}, {"text": "他很贪婪，敢一个人走夜路。", "explanation": "这里应该用〈勇敢〉。“贪婪”指贪得无厌，不用来形容胆量。"}, {"text": "妈妈很贪婪，每天都给我们做好吃的。", "explanation": "这里应该用〈勤劳〉。“贪婪”指贪得无厌，“每天给我们做好吃的”说的是勤劳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de6260c-2a6c-410a-9af0-ba6c08bfd103') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88053, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "贪婪", "is_correct": true, "explanation": "正确。“我不喜欢……的人”后接表示不良品性的词，“贪婪”正合。"}, {"text": "善良", "is_correct": false, "explanation": "语义：善良的人值得喜欢，与“我不喜欢”的语气相矛盾。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“空气”不是人，“空气的人”说不通，不能作“人”的定语。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“桌子”是物体，不能修饰“人”，“桌子的人”说不通。"}], "explanations": {"贪婪": "正确。“我不喜欢……的人”后接表示不良品性的词，“贪婪”正合。", "善良": "语义：善良的人值得喜欢，与“我不喜欢”的语气相矛盾。", "空气": "搭配：“空气”不是人，“空气的人”说不通，不能作“人”的定语。", "桌子": "搭配：“桌子”是物体，不能修饰“人”，“桌子的人”说不通。"}, "sentence_index": 6, "correct_answer": "贪婪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他见到老师很贪婪，每次都主动打招呼。", "explanation": "这里应该用〈礼貌〉。“贪婪”指贪得无厌，不用来描述待人有礼。"}, {"text": "老师很贪婪，上课从不说笑。", "explanation": "这里应该用〈严肃〉。“贪婪”指贪得无厌，不用来形容上课的态度。"}, {"text": "他很贪婪，见到陌生人就脸红。", "explanation": "这里应该用〈害羞〉。“贪婪”指贪得无厌，不用来描述见人脸红。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de6260c-2a6c-410a-9af0-ba6c08bfd103') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88053, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个孩子很的贪婪，见到什么都想拿。", "corrected_sentence": "这个孩子很贪婪，见到什么都想拿。", "error_description": "错误：“很”与“的”不能同时修饰形容词，“很的贪婪”应为“很贪婪”。正确：“这个孩子很贪婪”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de6260c-2a6c-410a-9af0-ba6c08bfd103') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88053, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小狗吃东西吃很贪婪。", "corrected_sentence": "小狗吃东西吃得很贪婪。", "error_description": "错误：动词后的程度补语要用“得”引出，“吃很贪婪”漏了“得”。正确：“吃得很贪婪”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de6260c-2a6c-410a-9af0-ba6c08bfd103') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
