INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88054, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "贪得无厌，不知满足。", "primary_collocate": null, "pronunciation": "tān lán", "ipa": "tʰan˥ lan˧˥", "syllable_count": 2, "sentences": [{"text": "他太贪婪了，赚了钱还想赚更多。", "target_word": "贪婪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "贪婪的商人不愿意分给工人一分钱。", "target_word": "贪婪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只狐狸又贪婪又狡猾。", "target_word": "贪婪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王的贪婪让国家越来越穷。", "target_word": "贪婪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她贪婪地看着桌上的金子。", "target_word": "贪婪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做人不能太贪婪。", "target_word": "贪婪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "贪婪的人永远不会觉得够。", "target_word": "贪婪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个老板贪婪得让人害怕。", "target_word": "贪婪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他因为贪婪，最后失去了一切。", "target_word": "贪婪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别让贪婪毁了你的生活。", "target_word": "贪婪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "贪婪地", "label": "状语形式"}, {"form": "贪婪的", "label": "定语形式"}], "register": "书面", "sense_fingerprint": "贪得无厌、永不满足的品性（含贬义）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be7a67a-0052-4629-80f6-eca6c3881ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88054, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "贪婪", "is_correct": true, "explanation": "正确。“太……了”后用“贪婪”，与“赚了钱还想赚更多”相合。"}, {"text": "慷慨", "is_correct": false, "explanation": "语义：慷慨是乐于给予，与“还想赚更多”矛盾，句子不通。"}, {"text": "善良", "is_correct": false, "explanation": "语义：善良的人不会只顾自己，与“还想赚更多”不相合。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”形容外貌，与“赚钱”无关，句子说不通。"}], "explanations": {"贪婪": "正确。“太……了”后用“贪婪”，与“赚了钱还想赚更多”相合。", "慷慨": "语义：慷慨是乐于给予，与“还想赚更多”矛盾，句子不通。", "善良": "语义：善良的人不会只顾自己，与“还想赚更多”不相合。", "漂亮": "体貌：“漂亮”形容外貌，与“赚钱”无关，句子说不通。"}, "sentence_index": 0, "correct_answer": "贪婪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他做事很贪婪，每次都要仔细想一想。", "explanation": "这里应该用〈谨慎〉。“贪婪”指贪得无厌，不用来描述做事小心。"}, {"text": "他太贪婪了，一整天都不肯起床。", "explanation": "这里应该用〈懒惰〉。“贪婪”指贪得无厌，不用来描述懒散的状态。"}, {"text": "我见到陌生人就很贪婪，一句话也说不出来。", "explanation": "这里应该用〈害羞〉。“贪婪”指想要得到很多，不用来描述羞怯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de6260c-2a6c-410a-9af0-ba6c08bfd103') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88054, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "贪婪", "is_correct": true, "explanation": "正确。“永远不会觉得够”正是贪婪之人的写照，句子意思完整。"}, {"text": "满足", "is_correct": false, "explanation": "语义：满足的人不会不停地想要更多，与“永远不会觉得够”相矛盾。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”描写身材，不能用来评价一个人的品性。"}, {"text": "干净", "is_correct": false, "explanation": "语义：干净指清洁，与“永远不会觉得够”无关，句子说不通。"}], "explanations": {"贪婪": "正确。“永远不会觉得够”正是贪婪之人的写照，句子意思完整。", "满足": "语义：满足的人不会不停地想要更多，与“永远不会觉得够”相矛盾。", "高大": "体貌：“高大”描写身材，不能用来评价一个人的品性。", "干净": "语义：干净指清洁，与“永远不会觉得够”无关，句子说不通。"}, "sentence_index": 6, "correct_answer": "贪婪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位老人很贪婪，总是把钱分给穷人。", "explanation": "这里应该用〈慷慨〉。“贪婪”指贪得无厌，与“把钱分给穷人”的态度相反。"}, {"text": "我奶奶很贪婪，每次出门都给邻居带水果。", "explanation": "这里应该用〈热心〉。“贪婪”指贪得无厌，与“给邻居带水果”的态度相反。"}, {"text": "她对每个新朋友都很贪婪。", "explanation": "这里应该用〈友好〉。“贪婪”指贪得无厌，不用来形容对待新朋友的态度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de6260c-2a6c-410a-9af0-ba6c08bfd103') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88054, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个商人的贪婪得不肯停手。", "corrected_sentence": "那个商人贪婪得不肯停手。", "error_description": "错误：“贪婪”前多了“的”，变成名词，后面不能再接“得”引出补语。正确：“贪婪得不肯停手”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de6260c-2a6c-410a-9af0-ba6c08bfd103') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88054, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的很贪婪，想要得到更多。", "corrected_sentence": "他很贪婪，想要得到更多。", "error_description": "错误：“的”误加在“很”前，“很”应直接修饰形容词。正确：“他很贪婪”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de6260c-2a6c-410a-9af0-ba6c08bfd103') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
