INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88055, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "再次是又一次，和上一次一样。", "primary_collocate": null, "pronunciation": "zài cì", "ipa": "tsai˥˩ tsʰɨ˥˩", "syllable_count": 2, "sentences": [{"text": "天气再次变冷了。", "target_word": "再次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他再次回到了老家。", "target_word": "再次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我再次给妈妈打电话。", "target_word": "再次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次我再次拿了第一。", "target_word": "再次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她再次告诉我要小心。", "target_word": "再次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车再次开动了。", "target_word": "再次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能再次帮我看一下吗？", "target_word": "再次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗再次跑到了门口。", "target_word": "再次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们再次来到这家饭馆。", "target_word": "再次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他再次站在老师面前。", "target_word": "再次", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性偏书面", "sense_fingerprint": "又一次，和上一次一样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ac39683-0e14-4009-8f9a-c5a67e844ca1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88055, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "必须", "is_correct": false, "explanation": "语义：“必须”表示必要或义务，需要行为的主体，不能用来说天气的变化。"}, {"text": "很", "is_correct": false, "explanation": "搭配：“很”修饰形容词，不修饰“变冷”这类变化动词。"}, {"text": "连忙", "is_correct": false, "explanation": "搭配：“连忙”修饰人的动作，不修饰“变冷了”这类天气变化。"}, {"text": "再次", "is_correct": true, "explanation": "“再次”表示又一次，与“天气再次变冷了”中同上一次一样的变化相符。"}], "explanations": {"必须": "语义：“必须”表示必要或义务，需要行为的主体，不能用来说天气的变化。", "很": "搭配：“很”修饰形容词，不修饰“变冷”这类变化动词。", "连忙": "搭配：“连忙”修饰人的动作，不修饰“变冷了”这类天气变化。", "再次": "“再次”表示又一次，与“天气再次变冷了”中同上一次一样的变化相符。"}, "sentence_index": 0, "correct_answer": "再次"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈先做饭，再次洗碗。", "explanation": "这里应该用“然后”，不用“再次”。“再次”表示同一动作又发生，不用于表示先后顺序。"}, {"text": "我从来没读过这本书，却再次读完了它。", "explanation": "这里不用“再次”。句中说“从来没读过”，而“再次”要求此前已经做过同样的事，前提不成立；表示初次时应说“第一次”。"}, {"text": "小狗一直再次叫个不停。", "explanation": "这里应该表达持续不断，不用“再次”。“再次”表示某个动作又发生一次，与持续不断的状态不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d65e25-72b9-4cf0-9326-67cdc132f9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88055, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "很", "is_correct": false, "explanation": "搭配：“很”修饰形容词，不能修饰“能”后面的动作，这里不成立。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示动作已经完成，与“能……帮我看一下”这种请求语境冲突。"}, {"text": "再次", "is_correct": true, "explanation": "“再次”表示又一次做同样的事，与“帮我看一下”的请求相符。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来”表示一直以来都没有，与表示请求的“能……吗”语境冲突。"}], "explanations": {"很": "搭配：“很”修饰形容词，不能修饰“能”后面的动作，这里不成立。", "已经": "语义：“已经”表示动作已经完成，与“能……帮我看一下”这种请求语境冲突。", "再次": "“再次”表示又一次做同样的事，与“帮我看一下”的请求相符。", "从来": "语义：“从来”表示一直以来都没有，与表示请求的“能……吗”语境冲突。"}, "sentence_index": 6, "correct_answer": "再次"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她第一次踢足球，却再次进了一个球。", "explanation": "这里不用“再次”。句中说“第一次踢足球”，“再次”要求此前已经做过同样的事，与“第一次”矛盾，应去掉“再次”。"}, {"text": "这个房间再次很干净。", "explanation": "这里不用“再次”。“再次”不直接修饰“很干净”这类静态形容词。"}, {"text": "他每天都再次吃早饭。", "explanation": "这里不用“再次”。“再次”指某次动作又发生一次，习惯性的重复应说“总是”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d65e25-72b9-4cf0-9326-67cdc132f9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88055, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小明第一次再次忘了带伞。", "corrected_sentence": "小明再次忘了带伞。", "error_description": "用词矛盾：“再次”表示同样的事又发生一次，不能和“第一次”同用。应去掉“第一次”。正确说法：小明再次忘了带伞。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d65e25-72b9-4cf0-9326-67cdc132f9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88055, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很再次借了我的书。", "corrected_sentence": "他再次借了我的书。", "error_description": "搭配错误：“再次”是表示重复的副词，不能受程度副词“很”修饰。应去掉“很”。正确说法：他再次借了我的书。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d65e25-72b9-4cf0-9326-67cdc132f9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88056, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d65e25-72b9-4cf0-9326-67cdc132f9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88056, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d65e25-72b9-4cf0-9326-67cdc132f9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88056, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示动作又一次发生。", "primary_collocate": null, "pronunciation": "zài cì", "ipa": "tsai˥˩ tsʰɨ˥˩", "syllable_count": 2, "sentences": [{"text": "他再次打开了门。", "target_word": "再次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们明年再次见面。", "target_word": "再次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师再次说明了作业要求。", "target_word": "再次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她再次看了看手机。", "target_word": "再次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店再次开门了。", "target_word": "再次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你再次检查一下答案。", "target_word": "再次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天他再次迟到了。", "target_word": "再次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想再次去那个城市旅游。", "target_word": "再次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛中他再次得了第一名。", "target_word": "再次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子再次哭了起来。", "target_word": "再次", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性偏书面", "sense_fingerprint": "副词，动作又一次发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ac39683-0e14-4009-8f9a-c5a67e844ca1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88056, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "必须", "is_correct": false, "explanation": "语义：“必须”表示必要或义务，指向未来或尚未发生的事，与表示已完成动作的“了”不相容。"}, {"text": "再次", "is_correct": true, "explanation": "“再次”表示动作又一次发生，与“打开了门”的已完成语义相符。"}, {"text": "很", "is_correct": false, "explanation": "搭配：“很”修饰形容词或心理动词，不修饰“打开”这类动作动词。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示动作进行中，不能与表示完成的“了”同用。"}], "explanations": {"必须": "语义：“必须”表示必要或义务，指向未来或尚未发生的事，与表示已完成动作的“了”不相容。", "再次": "“再次”表示动作又一次发生，与“打开了门”的已完成语义相符。", "很": "搭配：“很”修饰形容词或心理动词，不修饰“打开”这类动作动词。", "正在": "体貌：“正在”表示动作进行中，不能与表示完成的“了”同用。"}, "sentence_index": 0, "correct_answer": "再次"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一直再次哭个不停。", "explanation": "这里不用“再次”，应说“他一直哭个不停”。“再次”表示动作又发生一次，与“一直……个不停”的持续状态矛盾。"}, {"text": "我第一次再次去北京。", "explanation": "这里不用“再次”。句子说的是第一次去北京，“再次”要求此前已经去过同一地方，与“初次”的意思相冲突，表示初次时应换用“初次”。"}, {"text": "我每天再次吃早饭。", "explanation": "这里不用“再次”。“再次”指某次动作又发生一次，习惯性的重复应说“总是”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d65e25-72b9-4cf0-9326-67cdc132f9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88056, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "赶快", "is_correct": false, "explanation": "语义：“赶快”表示催促尽快行动，与已经发生的“迟到了”不相容。"}, {"text": "再次", "is_correct": true, "explanation": "“再次”表示又一次发生，与“今天……迟到了”的单次事件相符。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”一般与否定词“不”连用，不能修饰已经发生的“迟到了”。"}, {"text": "将要", "is_correct": false, "explanation": "语义：“将要”表示即将发生，与已经发生的“迟到了”冲突。"}], "explanations": {"赶快": "语义：“赶快”表示催促尽快行动，与已经发生的“迟到了”不相容。", "再次": "“再次”表示又一次发生，与“今天……迟到了”的单次事件相符。", "从来": "搭配：“从来”一般与否定词“不”连用，不能修饰已经发生的“迟到了”。", "将要": "语义：“将要”表示即将发生，与已经发生的“迟到了”冲突。"}, "sentence_index": 6, "correct_answer": "再次"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他先洗手，再次吃饭。", "explanation": "这里应该用“然后”，不用“再次”。“再次”表示同一动作又发生一次，不用于表示先后顺序。"}, {"text": "他第一次参加比赛，却再次拿了冠军。", "explanation": "这里不用“再次”。句中说是“第一次参加比赛”，“再次”要求此前已经发生过同样的事，与“第一次”矛盾，应去掉“再次”。"}, {"text": "这座城市我从没来过，但我再次来到了这里。", "explanation": "这里不用“再次”。“再次”要求此前已经发生过同样的动作，句中说“从没来过”，前提不成立；表示初次时应说“第一次”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d65e25-72b9-4cf0-9326-67cdc132f9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88056, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很再次关上了窗户。", "corrected_sentence": "他再次关上了窗户。", "error_description": "搭配错误：“再次”是表示动作又一次发生的副词，不能受程度副词“很”修饰。应去掉“很”。正确说法：他再次关上了窗户。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d65e25-72b9-4cf0-9326-67cdc132f9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88056, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我第一次再次去了北京。", "corrected_sentence": "我再次去了北京。", "error_description": "用词矛盾：“再次”要求此前已经做过同样的事，不能和“第一次”同用。应去掉“第一次”。正确说法：我再次去了北京。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d65e25-72b9-4cf0-9326-67cdc132f9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
