INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88057, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "姊妹是姐姐和妹妹，是同一家的女孩。", "primary_collocate": null, "pronunciation": "zǐ mèi", "ipa": "tsɨ˨˩ meɪ˥˩", "syllable_count": 2, "sentences": [{"text": "她们俩是姊妹，一个十岁，一个八岁。", "target_word": "姊妹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姊妹两个今天都穿着红裙子。", "target_word": "姊妹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家有三个女孩，我们是姊妹。", "target_word": "姊妹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这对姊妹每天一起走路上学。", "target_word": "姊妹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姊妹俩在房间里写作业。", "target_word": "姊妹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给姊妹俩各买了一本书。", "target_word": "姊妹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那两个女孩是姊妹，你看她们的眼睛。", "target_word": "姊妹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姊妹俩吵过架，不过很快就好了。", "target_word": "姊妹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她和姐姐是姊妹，长得一点也不像。", "target_word": "姊妹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小红和小花是姊妹，住在同一个家。", "target_word": "姊妹", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一对姊妹", "label": "量词"}, {"form": "姊妹花", "label": "复合"}], "register": "中性", "sense_fingerprint": "同一家的姐姐和妹妹", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa8a3557-0c41-45ec-8b3a-0a993a565589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88057, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "姊妹", "is_correct": true, "explanation": "正确：“姊妹”指同为女孩的姐姐和妹妹，与“她们俩是……一个十岁，一个八岁”相合。"}, {"text": "母女", "is_correct": false, "explanation": "语义：“母女”是母亲与女儿的关系，“一个十岁，一个八岁”的年龄不符。"}, {"text": "主仆", "is_correct": false, "explanation": "语义：“主仆”指主人与仆人的关系，与两个小孩是姐妹的关系不合。"}, {"text": "战友", "is_correct": false, "explanation": "语义：“战友”指共同作战的人，与两个孩子的关系不合。"}], "explanations": {"姊妹": "正确：“姊妹”指同为女孩的姐姐和妹妹，与“她们俩是……一个十岁，一个八岁”相合。", "母女": "语义：“母女”是母亲与女儿的关系，“一个十岁，一个八岁”的年龄不符。", "主仆": "语义：“主仆”指主人与仆人的关系，与两个小孩是姐妹的关系不合。", "战友": "语义：“战友”指共同作战的人，与两个孩子的关系不合。"}, "sentence_index": 0, "correct_answer": "姊妹"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和妈妈是姊妹，每天一起走路上学。", "explanation": "这里应该用〈母女〉。“姊妹”要求同辈，“妈妈”是长辈。"}, {"text": "我和爷爷是姊妹，每天一起去上学。", "explanation": "这里应该用〈祖孙〉。“姊妹”要求同辈，“爷爷”是长辈。"}, {"text": "这对姊妹都是男生，每天一起走路上学。", "explanation": "这里应该用〈兄弟〉。“姊妹”只指女性，“男生”不能组成“姊妹”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1afb66-c79d-40ef-a6aa-a4d63f9c1e44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88057, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "姊妹", "is_correct": true, "explanation": "正确：“姊妹”指同辈女性亲属，与“那两个女孩”和“你看她们的眼睛”相合。"}, {"text": "母子", "is_correct": false, "explanation": "语义：“母子”指母亲与儿子，不能用于两个女孩。"}, {"text": "叔侄", "is_correct": false, "explanation": "语义：“叔侄”是叔叔与侄子的关系，不能用于两个女孩。"}, {"text": "耳环", "is_correct": false, "explanation": "搭配：“女孩”指人，“耳环”是物，不能作“是”的表语。"}], "explanations": {"姊妹": "正确：“姊妹”指同辈女性亲属，与“那两个女孩”和“你看她们的眼睛”相合。", "母子": "语义：“母子”指母亲与儿子，不能用于两个女孩。", "叔侄": "语义：“叔侄”是叔叔与侄子的关系，不能用于两个女孩。", "耳环": "搭配：“女孩”指人，“耳环”是物，不能作“是”的表语。"}, "sentence_index": 6, "correct_answer": "姊妹"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小红和老师是姊妹，住在同一个家。", "explanation": "这里应该用〈师生〉。“姊妹”指同辈亲属，小红与老师是师生关系，不能说“姊妹”。"}, {"text": "小红和小猫是姊妹，住在同一个家。", "explanation": "这里应该用〈朋友〉。“姊妹”指人之间的同辈亲属，小猫不能作“姊妹”，只能说是朋友。"}, {"text": "这两把椅子是姊妹，颜色一样。", "explanation": "这里应该用〈一对〉。“姊妹”只指人之间的同辈亲属，椅子只能说“一对”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1afb66-c79d-40ef-a6aa-a4d63f9c1e44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88057, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她们俩是姊妹们，都是学生。", "corrected_sentence": "她们俩是姊妹，都是学生。", "error_description": "数量错误：“俩”已表示两人，后面不能再加“们”；两人说“姊妹”或“姊妹俩”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1afb66-c79d-40ef-a6aa-a4d63f9c1e44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88057, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那两只姊妹都很喜欢画画。", "corrected_sentence": "那两个姊妹都很喜欢画画。", "error_description": "量词错误：“姊妹”指人，应用“个”，不能用“只”（“只”用于动物或单件物品）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1afb66-c79d-40ef-a6aa-a4d63f9c1e44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
