INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88058, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "姐姐和妹妹的合称；同辈女性亲属。", "primary_collocate": null, "pronunciation": "zǐ mèi", "ipa": "tsɨ˨˩ meɪ˥˩", "syllable_count": 2, "sentences": [{"text": "她们是一对姊妹，长得很像。", "target_word": "姊妹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们姊妹三个都住在北京。", "target_word": "姊妹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姊妹之间应该互相帮助。", "target_word": "姊妹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她和姊妹们一起去旅行了。", "target_word": "姊妹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这对姊妹从小感情就很好。", "target_word": "姊妹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没有兄弟，只有两个姊妹。", "target_word": "姊妹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年的时候，姊妹们都回老家了。", "target_word": "姊妹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姊妹俩常常穿一样的衣服。", "target_word": "姊妹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她们虽然不是亲姊妹，却像一家人。", "target_word": "姊妹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姊妹几个围着奶奶说话。", "target_word": "姊妹", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一对姊妹", "label": "量词"}, {"form": "姊妹花", "label": "复合"}], "register": "中性", "sense_fingerprint": "姐姐和妹妹的合称，泛指同辈女性亲属", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa8a3557-0c41-45ec-8b3a-0a993a565589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88058, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "姊妹", "is_correct": true, "explanation": "正确：“姊妹”指同辈女性亲属，与“一对”和“长得很像”相合。"}, {"text": "兄弟", "is_correct": false, "explanation": "语义：“兄弟”指男性同辈亲属，“她们”都是女性，不能说“一对兄弟”。"}, {"text": "师徒", "is_correct": false, "explanation": "语义：“师徒”指师傅与徒弟的关系，不是同辈亲属，“她们是一对师徒”不合理。"}, {"text": "耳环", "is_correct": false, "explanation": "搭配：“一对耳环”是物品，“她们”指人，不能用“是”把两者联系起来。"}], "explanations": {"姊妹": "正确：“姊妹”指同辈女性亲属，与“一对”和“长得很像”相合。", "兄弟": "语义：“兄弟”指男性同辈亲属，“她们”都是女性，不能说“一对兄弟”。", "师徒": "语义：“师徒”指师傅与徒弟的关系，不是同辈亲属，“她们是一对师徒”不合理。", "耳环": "搭配：“一对耳环”是物品，“她们”指人，不能用“是”把两者联系起来。"}, "sentence_index": 0, "correct_answer": "姊妹"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她和哥哥是姊妹，经常一起打篮球。", "explanation": "这里应该用〈兄妹〉。“姊妹”只用于女性同辈亲属之间，“哥哥”是男性，不能组成“姊妹”。"}, {"text": "我和小猫是姊妹，常常一起玩。", "explanation": "这里应该用〈朋友〉。“姊妹”指同辈的女性亲属，不能用于动物。"}, {"text": "这两位老先生是姊妹，都七十多岁了。", "explanation": "这里应该用〈兄弟〉。“姊妹”只指女性，“老先生”是男性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1afb66-c79d-40ef-a6aa-a4d63f9c1e44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88058, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "姊妹", "is_correct": true, "explanation": "正确：“姊妹们”指同辈女性亲属，与“过年的时候回老家”相合。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是物，不会回老家。"}, {"text": "火车", "is_correct": false, "explanation": "语义：“火车”不会回老家，句中说的是人。"}, {"text": "树叶", "is_correct": false, "explanation": "语义：“树叶”不会回老家，这里说的是人。"}], "explanations": {"姊妹": "正确：“姊妹们”指同辈女性亲属，与“过年的时候回老家”相合。", "桌子": "语义：“桌子”是物，不会回老家。", "火车": "语义：“火车”不会回老家，句中说的是人。", "树叶": "语义：“树叶”不会回老家，这里说的是人。"}, "sentence_index": 6, "correct_answer": "姊妹"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "姊妹几个围着老师说话。", "explanation": "这里应该用〈同学〉。“姊妹”指同辈亲属，不能用于老师与学生之间的非亲属关系。"}, {"text": "这两块石头是姊妹，一样大小。", "explanation": "这里应该用〈一对〉。“姊妹”只指人之间的同辈亲属，石头只能说“一对”。"}, {"text": "我和爷爷是姊妹，每天一起去散步。", "explanation": "这里应该用〈祖孙〉。“姊妹”要求同辈，“爷爷”是长辈。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1afb66-c79d-40ef-a6aa-a4d63f9c1e44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88058, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们家有三只姊妹，都很漂亮。", "corrected_sentence": "我们家有三个姊妹，都很漂亮。", "error_description": "量词错误：“姊妹”指人，应用“个”，不能用“只”（“只”用于动物或单件物品）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1afb66-c79d-40ef-a6aa-a4d63f9c1e44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88058, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那两个女孩是姊妹们，你看她们的眼睛。", "corrected_sentence": "那两个女孩是姊妹，你看她们的眼睛。", "error_description": "数量错误：“那两个”已表示两人，后面不能再加“们”，应说“是姊妹”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1afb66-c79d-40ef-a6aa-a4d63f9c1e44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
