INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88065, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "跑分是让手机或电脑做测试，看看它有多快。", "primary_collocate": null, "pronunciation": "pǎo fēn", "ipa": "pʰɑʊ˨˩˦ fən˥", "syllable_count": 2, "sentences": [{"text": "我想给新手机跑分，看看它快不快。", "target_word": "跑分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台电脑昨天跑分了，成绩很不错。", "target_word": "跑分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友帮我给旧电脑跑分，结果太慢了。", "target_word": "跑分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的手机跑分以后，告诉我有多快。", "target_word": "跑分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用这个软件给平板跑分吧。", "target_word": "跑分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天晚上都给电脑跑分，真有意思。", "target_word": "跑分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机刚买回来，我就马上跑分了。", "target_word": "跑分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想知道电脑快不快，可以先跑分。", "target_word": "跑分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把新手机放在桌上，开始跑分。", "target_word": "跑分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，电脑跑分的时候不要玩游戏。", "target_word": "跑分", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "跑个分", "label": "离合"}, {"form": "跑分软件", "label": "复合词"}], "register": "口语", "sense_fingerprint": "让手机或电脑做测试，看它快不快", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3763d68d-fe1a-4cec-95df-e92983c5cf23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88065, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "跑分", "is_correct": true, "explanation": "正确：跑分指让设备做测试，与「看看它快不快」相符。"}, {"text": "翻译", "is_correct": false, "explanation": "搭配：翻译的对象是语言或文字，不能用于手机。"}, {"text": "砍价", "is_correct": false, "explanation": "语义：砍价指讨价还价买东西，与看看它快不快无关。"}, {"text": "背诵", "is_correct": false, "explanation": "搭配：背诵的对象是课文或诗词，不能用于手机。"}], "explanations": {"跑分": "正确：跑分指让设备做测试，与「看看它快不快」相符。", "翻译": "搭配：翻译的对象是语言或文字，不能用于手机。", "砍价": "语义：砍价指讨价还价买东西，与看看它快不快无关。", "背诵": "搭配：背诵的对象是课文或诗词，不能用于手机。"}, "sentence_index": 0, "correct_answer": "跑分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师给我的作文跑分了，得了九十分。", "explanation": "这里应该用〈打分〉。跑分专指让手机、电脑等设备测试性能，给作文评分要用打分。"}, {"text": "顾客吃完饭，给这家餐厅跑分了。", "explanation": "这里应该用〈评分〉。跑分只用于设备的性能测试，对餐厅、服务打分要用评分。"}, {"text": "这个学生上课说话，被老师跑分了。", "explanation": "这里应该用〈扣分〉。跑分指设备测试性能，学生违纪被减分要用扣分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be51c686-fcf4-468c-b04e-498f8f788a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88065, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "跑分", "is_correct": true, "explanation": "正确：跑分指让手机做测试，与刚买回来就去测试的情境相符。"}, {"text": "报废", "is_correct": false, "explanation": "语义：报废指作废不能再用，与「刚买回来」矛盾。"}, {"text": "挂失", "is_correct": false, "explanation": "语义：挂失用于证件或银行卡丢失，与「刚买回来」矛盾。"}, {"text": "解冻", "is_correct": false, "explanation": "搭配：解冻用于冷冻食品，不用于手机。"}], "explanations": {"跑分": "正确：跑分指让手机做测试，与刚买回来就去测试的情境相符。", "报废": "语义：报废指作废不能再用，与「刚买回来」矛盾。", "挂失": "语义：挂失用于证件或银行卡丢失，与「刚买回来」矛盾。", "解冻": "搭配：解冻用于冷冻食品，不用于手机。"}, "sentence_index": 6, "correct_answer": "跑分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "房产中介给这套老房子跑分，说值三百万。", "explanation": "这里应该用〈估价〉。跑分指设备测试性能，估计房子的价钱要用估价。"}, {"text": "工人用尺子给桌子跑分，量出了长度。", "explanation": "这里应该用〈测量〉。跑分只用于设备的性能测试，量物体的长短要用测量。"}, {"text": "医生给病人跑分，检查了身体。", "explanation": "这里应该用〈体检〉。跑分指设备测试性能，检查人的身体要用体检。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be51c686-fcf4-468c-b04e-498f8f788a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
