INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88066, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用测试软件运行并获取设备性能得分。", "primary_collocate": null, "pronunciation": "pǎo fēn", "ipa": "pʰɑʊ˨˩˦ fən˥", "syllable_count": 2, "sentences": [{"text": "他用软件给手机跑分，得了很高的分。", "target_word": "跑分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件可以给电脑跑分，也能看分数。", "target_word": "跑分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑分以后，屏幕上会出现一个分数。", "target_word": "跑分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的手机跑分只用了三分钟。", "target_word": "跑分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢给每个新手机跑分，再比较分数。", "target_word": "跑分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先下载软件，然后给平板跑分。", "target_word": "跑分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台电脑跑分的时候，风扇响得很大。", "target_word": "跑分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们在宿舍里给旧手机跑分。", "target_word": "跑分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑分前，请先关上别的软件。", "target_word": "跑分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我已经给两台电脑跑分了，分数差不多。", "target_word": "跑分", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "跑个分", "label": "离合"}, {"form": "跑分成绩", "label": "复合词"}], "register": "口语", "sense_fingerprint": "用测试软件运行设备并得到性能分数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3763d68d-fe1a-4cec-95df-e92983c5cf23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88066, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "跑分", "is_correct": true, "explanation": "正确：跑分指用软件让手机测试性能并得到分数，与「得了很高的分」相符。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：烹饪指做饭，与用软件测试手机无关。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：打扫用于房间、场地，不能用于手机。"}, {"text": "辩论", "is_correct": false, "explanation": "语义：辩论指双方争论观点，与用软件测试手机、得到分数无关。"}], "explanations": {"跑分": "正确：跑分指用软件让手机测试性能并得到分数，与「得了很高的分」相符。", "烹饪": "语义：烹饪指做饭，与用软件测试手机无关。", "打扫": "搭配：打扫用于房间、场地，不能用于手机。", "辩论": "语义：辩论指双方争论观点，与用软件测试手机、得到分数无关。"}, "sentence_index": 0, "correct_answer": "跑分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师看完我的作文，很快就给它跑分了。", "explanation": "这里应该用〈打分〉。跑分专指让手机、电脑等设备测试性能，给作文评分要用打分。"}, {"text": "顾客吃完饭，就给这家餐厅跑分了。", "explanation": "这里应该用〈评分〉。跑分只用于设备的性能测试，对餐厅、服务打分要用评分。"}, {"text": "医生给我做了一次全面的跑分。", "explanation": "这里应该用〈体检〉。跑分指设备测试性能，检查人的身体要用体检。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be51c686-fcf4-468c-b04e-498f8f788a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
