INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88069, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "工具人是总被别人拿来帮忙、却不被看重的人。", "primary_collocate": null, "pronunciation": "gōng jù rén", "ipa": "kʊŋ˥ tɕy˥˩ ʐən˧˥", "syllable_count": 3, "sentences": [{"text": "大家有事就找他，他真是个工具人。", "target_word": "工具人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每次都帮忙，却被当成工具人。", "target_word": "工具人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想当别人的工具人，也想有朋友。", "target_word": "工具人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王帮大家修电脑，成了办公室的工具人。", "target_word": "工具人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他请客、拿东西、跑腿，最后还是被当成工具人。", "target_word": "工具人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当工具人久了，他有点难过。", "target_word": "工具人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别把我当工具人，我也要休息。", "target_word": "工具人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "室友叫他买饭、取快递，他是宿舍的工具人。", "target_word": "工具人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她明白了，在他心里自己只是工具人。", "target_word": "工具人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工具人帮了很多忙，却没人看重他。", "target_word": "工具人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "口语", "sense_fingerprint": "总被拿来帮忙却不被看重的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '167a7954-97b5-4a26-941f-142692a13d69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88069, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "观众", "is_correct": false, "explanation": "语义：「观众」只看不做事，与「大家有事就找他」的意思不合。"}, {"text": "工具人", "is_correct": true, "explanation": "正确答案：工具人，指总被别人拿来帮忙、却不被看重的人。"}, {"text": "陌生人", "is_correct": false, "explanation": "语义：「陌生人」与句中“大家有事就找他”的关系矛盾。"}, {"text": "路人", "is_correct": false, "explanation": "语义：「路人」与人们有事就找他的情况不合。"}], "explanations": {"观众": "语义：「观众」只看不做事，与「大家有事就找他」的意思不合。", "工具人": "正确答案：工具人，指总被别人拿来帮忙、却不被看重的人。", "陌生人": "语义：「陌生人」与句中“大家有事就找他”的关系矛盾。", "路人": "语义：「路人」与人们有事就找他的情况不合。"}, "sentence_index": 0, "correct_answer": "工具人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大家都很尊重他的意见，他是公司的工具人。", "explanation": "这里应该用〈红人〉。工具人指被使唤、不被看重的人，与「大家都很尊重他的意见」矛盾。"}, {"text": "她是我们班的工具人，每次都被选为班长。", "explanation": "这里应该用〈干部〉。工具人指被使唤、不被看重的人，与「每次都被选为班长」矛盾；受信任的学生干部应说干部。"}, {"text": "他是我们公司的工具人，是最受器重的员工。", "explanation": "这里应该用〈骨干〉。工具人指被使唤、不被看重的人，与「最受器重」矛盾；被器重的核心员工应说骨干。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03082593-bfae-47ac-8eda-e4b23f65def1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88069, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "老师", "is_correct": false, "explanation": "语义：「别把我当老师」与「我也要休息」的抱怨不合，句子说的是被使唤。"}, {"text": "工具人", "is_correct": true, "explanation": "正确答案：工具人，指总被别人拿来帮忙、却不被看重的人。"}, {"text": "外人", "is_correct": false, "explanation": "语义：「外人」指与自己疏远的人，与句子要求被当作人看待的意思不合。"}, {"text": "小孩", "is_correct": false, "explanation": "语义：「小孩」指年幼的人，与句中成年人被使唤的处境不合。"}], "explanations": {"老师": "语义：「别把我当老师」与「我也要休息」的抱怨不合，句子说的是被使唤。", "工具人": "正确答案：工具人，指总被别人拿来帮忙、却不被看重的人。", "外人": "语义：「外人」指与自己疏远的人，与句子要求被当作人看待的意思不合。", "小孩": "语义：「小孩」指年幼的人，与句中成年人被使唤的处境不合。"}, "sentence_index": 6, "correct_answer": "工具人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是公司的核心人物，大家都很敬佩他，是个工具人。", "explanation": "这里应该用〈领袖〉。工具人指被使唤、不被看重的人，与「大家都很敬佩他」矛盾；受敬佩、起带头作用的人应说领袖。"}, {"text": "她是我们行业的权威，大家都很看重她，是个工具人。", "explanation": "这里应该用〈专家〉。工具人指被使唤、不被看重的人，与「大家都很看重她」矛盾；受看重的专业人士应说专家。"}, {"text": "他是班长，全班都听他指挥，是个工具人。", "explanation": "这里应该用〈领导〉。工具人指被使唤、不被看重的人，与「全班都听他指挥」矛盾；能指挥他人的人应说领导。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03082593-bfae-47ac-8eda-e4b23f65def1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88069, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是条工具人，大家都找他。", "corrected_sentence": "他是个工具人，大家都找他。", "error_description": "错误：「工具人」前的量词用了「条」。正确应为「个」，「条」多用于长条形物品，指人要用「个」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03082593-bfae-47ac-8eda-e4b23f65def1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88069, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他当过一只工具人，所以很理解她。", "corrected_sentence": "他当过工具人，所以很理解她。", "error_description": "错误：「一只工具人」中的量词「只」多用于动物，不能用来指人；正确：「当过工具人」，去掉量词，句意不变。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03082593-bfae-47ac-8eda-e4b23f65def1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
