INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88070, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "网络用语，指总被他人利用来办事、而自身不被重视的人。", "primary_collocate": null, "pronunciation": "gōng jù rén", "ipa": "kʊŋ˥ tɕy˥˩ ʐən˧˥", "syllable_count": 3, "sentences": [{"text": "同学们都找我帮忙，我成了工具人。", "target_word": "工具人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想再当大家的工具人了。", "target_word": "工具人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板有事才找他，他就是个工具人。", "target_word": "工具人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对她很好，可她只把我当工具人。", "target_word": "工具人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做工具人的人，常常没人看重。", "target_word": "工具人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别总让小李做工具人，他也有自己的事。", "target_word": "工具人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她发现自己只是朋友眼里的工具人。", "target_word": "工具人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工具人每天帮人拿快递，却没人说谢谢。", "target_word": "工具人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他笑着说：“我就是班里的工具人。”", "target_word": "工具人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办公室里的工具人最累，什么事都找他。", "target_word": "工具人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "口语", "sense_fingerprint": "网络用语：总被人利用办事却不被重视的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '167a7954-97b5-4a26-941f-142692a13d69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88070, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "作家", "is_correct": false, "explanation": "语义：「作家」与「同学们都找我帮忙」的处境毫无关联。"}, {"text": "工具人", "is_correct": true, "explanation": "正确答案：工具人，指总被别人拿来办事、却不被重视的人。"}, {"text": "画家", "is_correct": false, "explanation": "语义：「画家」与「同学们都找我帮忙」的处境毫无关联。"}, {"text": "小丑", "is_correct": false, "explanation": "语义：「小丑」指逗人发笑的人，与被大家找来帮忙的意思不符。"}], "explanations": {"作家": "语义：「作家」与「同学们都找我帮忙」的处境毫无关联。", "工具人": "正确答案：工具人，指总被别人拿来办事、却不被重视的人。", "画家": "语义：「画家」与「同学们都找我帮忙」的处境毫无关联。", "小丑": "语义：「小丑」指逗人发笑的人，与被大家找来帮忙的意思不符。"}, "sentence_index": 0, "correct_answer": "工具人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是公司的工具人，大家都很器重他。", "explanation": "这里应该用〈人才〉。工具人指被使唤、不被看重的人，与「大家都很器重他」矛盾；受器重、有能力的人应说人才。"}, {"text": "他是我们部门的工具人，每年都被评为优秀员工。", "explanation": "这里应该用〈模范〉。工具人指被使唤、不被看重的人，与「每年都被评为优秀员工」矛盾；受表彰的榜样应说模范。"}, {"text": "她是我们部门的工具人，大家都听她的安排。", "explanation": "这里应该用〈领导〉。工具人指被使唤、不被看重的人，与「大家都听她的安排」矛盾；能统筹安排他人的人应说领导。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03082593-bfae-47ac-8eda-e4b23f65def1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88070, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "运动员", "is_correct": false, "explanation": "语义：「运动员」是职业身份，与「只是朋友眼里的」被利用的处境无关。"}, {"text": "工具人", "is_correct": true, "explanation": "正确答案：工具人，指在朋友眼里只被拿来办事的人。"}, {"text": "敌人", "is_correct": false, "explanation": "语义：「敌人」与「朋友眼里」矛盾，不能说朋友眼里的敌人。"}, {"text": "亲人", "is_correct": false, "explanation": "语义：「亲人」指血缘或极亲近的人，与「只是朋友眼里的」所限定的身份矛盾。"}], "explanations": {"运动员": "语义：「运动员」是职业身份，与「只是朋友眼里的」被利用的处境无关。", "工具人": "正确答案：工具人，指在朋友眼里只被拿来办事的人。", "敌人": "语义：「敌人」与「朋友眼里」矛盾，不能说朋友眼里的敌人。", "亲人": "语义：「亲人」指血缘或极亲近的人，与「只是朋友眼里的」所限定的身份矛盾。"}, "sentence_index": 6, "correct_answer": "工具人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他做事很有主见，大家都把他当主心骨，是个工具人。", "explanation": "这里应该用〈主心骨〉。工具人指被使唤、不被看重的人，与「大家都把他当主心骨」矛盾。"}, {"text": "他是班里的大功臣，大家都很敬重他，是个工具人。", "explanation": "这里应该用〈榜样〉。工具人指被使唤、不被看重的人，与「大家都很敬重他」矛盾；受敬重的人应说榜样。"}, {"text": "我们的老师很有耐心，是我最敬重的工具人。", "explanation": "这里应该用〈导师〉。工具人指被使唤、不被看重的人，与「最敬重」矛盾；值得敬重的指导者应说导师。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03082593-bfae-47ac-8eda-e4b23f65def1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88070, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "同学们都说他是只工具人。", "corrected_sentence": "同学们都说他是个工具人。", "error_description": "错误：「工具人」前的量词用了「只」。正确应为「个」，「只」多用于动物或成对物品中的一个，指人要用「个」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03082593-bfae-47ac-8eda-e4b23f65def1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88070, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他总被大家当成一根工具人，心里很委屈。", "corrected_sentence": "他总被大家当成工具人，心里很委屈。", "error_description": "错误：「工具人」前的量词用了「根」。「根」用于细长物体，不能指人；正确应去掉量词，写作「当成工具人」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03082593-bfae-47ac-8eda-e4b23f65def1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
