INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88071, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "身后是人的后面，是背对着的那一边。", "primary_collocate": null, "pronunciation": "shēn hòu", "ipa": "ʂən˥ xoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "我身后站着一个陌生人。", "target_word": "身后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狗一直跟在他身后跑。", "target_word": "身后", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她回头看了看身后的路。", "target_word": "身后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有人在身后拍了我一下。", "target_word": "身后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小女孩藏在爸爸身后。", "target_word": "身后", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师站在学生身后看他写字。", "target_word": "身后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "身后传来一阵脚步声。", "target_word": "身后", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请不要站在我身后。", "target_word": "身后", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他把书包背在身后。", "target_word": "身后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走着走着，我发现身后没有人了。", "target_word": "身后", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "身後", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人背对着的那一边，后方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968af400-236c-4070-b1b0-1aaf52250aaf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88071, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "身后", "is_correct": true, "explanation": "正确：“身后”指人的背后方位，与“陌生人站在我身后”相符。"}, {"text": "书里", "is_correct": false, "explanation": "语义：“书里”指书籍的内部，人不能站在书里。"}, {"text": "碗里", "is_correct": false, "explanation": "搭配：“碗里”的空间容不下人站着，与“站着”不搭配。"}, {"text": "天上", "is_correct": false, "explanation": "语义：“天上”指空中，与地面上站着一个陌生人的情境不符。"}], "explanations": {"身后": "正确：“身后”指人的背后方位，与“陌生人站在我身后”相符。", "书里": "语义：“书里”指书籍的内部，人不能站在书里。", "碗里": "搭配：“碗里”的空间容不下人站着，与“站着”不搭配。", "天上": "语义：“天上”指空中，与地面上站着一个陌生人的情境不符。"}, "sentence_index": 0, "correct_answer": "身后"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "门身后藏着一只猫。", "explanation": "这里应该用〈后面〉。身后只指人或动物身体的后方，门不能说“身后”，应说“后面”。"}, {"text": "这个秘密的身后有很多故事。", "explanation": "这里应该用〈背后〉。身后只指人或动物身体的后方，事情隐藏的原因要说“背后”。"}, {"text": "石头身后有一只鸟。", "explanation": "这里应该用〈后面〉。身后只用于人或动物身体的后方，石头没有身体，应说“后面”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd49623de-62a6-46c9-80de-54d676cd0681') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88071, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身后", "is_correct": true, "explanation": "正确：“身后”作主语，指人的后方，与“传来脚步声”的情境相符。"}, {"text": "水杯", "is_correct": false, "explanation": "语义：“水杯”是器物，不能发出脚步声，与“传来”不相称。"}, {"text": "棉被", "is_correct": false, "explanation": "语义：“棉被”是织物，不能作为脚步声的来源。"}, {"text": "石桌", "is_correct": false, "explanation": "搭配：“石桌”是家具，不会传出脚步声，与“传来”搭配不当。"}], "explanations": {"身后": "正确：“身后”作主语，指人的后方，与“传来脚步声”的情境相符。", "水杯": "语义：“水杯”是器物，不能发出脚步声，与“传来”不相称。", "棉被": "语义：“棉被”是织物，不能作为脚步声的来源。", "石桌": "搭配：“石桌”是家具，不会传出脚步声，与“传来”搭配不当。"}, "sentence_index": 6, "correct_answer": "身后"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "箱子身后有一本书。", "explanation": "这里应该用〈后方〉。身后只用于人或动物身体的后方，箱子没有身体，应说“后方”。"}, {"text": "下课身后我们一起去吃饭。", "explanation": "这里应该用〈之后〉。身后指人或动物身体的后方，不能表示“下课以后”这样的时间。"}, {"text": "椅子身后有一只猫。", "explanation": "这里应该用〈后边〉。身后只用于人或动物身体的后方，椅子没有身体，应说“后边”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd49623de-62a6-46c9-80de-54d676cd0681') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88071, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他悄悄躲我身后。", "corrected_sentence": "他悄悄躲在我身后。", "error_description": "错误：躲我身后。正确：躲在我身后。表示处所的方位短语前要用介词“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd49623de-62a6-46c9-80de-54d676cd0681') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88071, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他走我身后站住了。", "corrected_sentence": "他走到我身后站住了。", "error_description": "错误：走我身后。正确：走到我身后。表示移动到某处要用“到”引出终点。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd49623de-62a6-46c9-80de-54d676cd0681') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
