INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88073, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "学校的行政负责人，管理整个学校。", "primary_collocate": null, "pronunciation": "xiào zhǎng", "ipa": "ɕjɑʊ˥˩ ʈʂɑŋ˨˩", "syllable_count": 2, "sentences": [{"text": "我们的校长很高。", "target_word": "校长", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "校长每天早上站在门口。", "target_word": "校长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "校长给同学们讲了一个故事。", "target_word": "校长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是我们学校的校长。", "target_word": "校长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "校长在大会上说话。", "target_word": "校长", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "同学们都很喜欢新校长。", "target_word": "校长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "校长走进教室，大家都站起来了。", "target_word": "校长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天在路上看到了校长。", "target_word": "校长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "校长对我们说：“欢迎你们。”", "target_word": "校长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "校长请老师们开会。", "target_word": "校长", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "副校长", "label": "复合词"}, {"form": "校長", "label": "繁体"}], "register": "中性", "sense_fingerprint": "管理整个学校的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc845970-b582-4cbd-8bfb-d42e50e4b40f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88073, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "校长", "is_correct": true, "explanation": "正确答案：学校里管理全校的人，读作 xiào zhǎng。"}, {"text": "县长", "is_correct": false, "explanation": "xiàn 与 xiào 声调相同，韵母不同（ian 与 iao），意思是县长（县级行政负责人）。"}, {"text": "校章", "is_correct": false, "explanation": "zhāng（第一声）与 zhǎng（第三声）声调不同，意思是校章（学校的徽章或印章）。"}, {"text": "小账", "is_correct": false, "explanation": "xiǎo（第三声）与 xiào（第四声）声调不同，zhàng（第四声）与 zhǎng（第三声）声调也不同，意思是小额账目。"}], "explanations": {"校长": "正确答案：学校里管理全校的人，读作 xiào zhǎng。", "县长": "xiàn 与 xiào 声调相同，韵母不同（ian 与 iao），意思是县长（县级行政负责人）。", "校章": "zhāng（第一声）与 zhǎng（第三声）声调不同，意思是校章（学校的徽章或印章）。", "小账": "xiǎo（第三声）与 xiào（第四声）声调不同，zhàng（第四声）与 zhǎng（第三声）声调也不同，意思是小额账目。"}, "sentence_index": null, "correct_answer": "校长"}, "level_3": {"options": [{"text": "校长", "is_correct": true, "explanation": "正确答案：“我们的校长很高”，指学校里管理全校的人。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能用“很高”来形容，句子不成立。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能用“很高”来形容，与“我们的”的语境矛盾。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“很高”不用来形容名字，“名字很高”不自然。"}], "explanations": {"校长": "正确答案：“我们的校长很高”，指学校里管理全校的人。", "颜色": "语义：颜色不能用“很高”来形容，句子不成立。", "天气": "语义：天气不能用“很高”来形容，与“我们的”的语境矛盾。", "名字": "搭配：“很高”不用来形容名字，“名字很高”不自然。"}, "sentence_index": 0, "correct_answer": "校长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们这家饭店的校长很和蔼。", "explanation": "这里应该用〈经理〉。饭店的负责人称经理，不说校长。"}, {"text": "这家工厂的校长很严格。", "explanation": "这里应该用〈厂长〉。工厂的负责人称厂长，不说校长。"}, {"text": "这个部门的校长很认真。", "explanation": "这里应该用〈主任〉。部门的负责人称主任，不说校长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fbc760a-f0a4-4dab-8306-53e9ab979a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88073, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "校长", "is_correct": true, "explanation": "正确答案：“校长走进教室”，指管理全校的人。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能“走进教室”后让大家站起来，句子不成立。"}, {"text": "桌子", "is_correct": false, "explanation": "配价：“走进”的主语需要能自主移动的人或动物，桌子不能自主走进教室。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不能“走进教室”，句子无法成立。"}], "explanations": {"校长": "正确答案：“校长走进教室”，指管理全校的人。", "空气": "语义：空气不能“走进教室”后让大家站起来，句子不成立。", "桌子": "配价：“走进”的主语需要能自主移动的人或动物，桌子不能自主走进教室。", "窗户": "语义：窗户不能“走进教室”，句子无法成立。"}, "sentence_index": 6, "correct_answer": "校长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们班的校长今天请假了。", "explanation": "这里应该用〈班长〉。班级的负责人称班长，“校长”指管理整个学校的人。"}, {"text": "这家报社的校长很忙。", "explanation": "这里应该用〈社长〉。报社的负责人称社长，不用“校长”。"}, {"text": "这家公司的校长今天来了。", "explanation": "这里应该用〈董事长〉。公司的负责人称董事长或总经理，不用“校长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fbc760a-f0a4-4dab-8306-53e9ab979a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88073, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只校长十年前来到了我们学校。", "corrected_sentence": "这位校长十年前来到了我们学校。", "error_description": "量词错误：“校长”应用量词“位”，“只”用于动物，不能用于人。应改为“这位校长”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fbc760a-f0a4-4dab-8306-53e9ab979a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
