INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88074, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "学校的最高行政负责人。", "primary_collocate": null, "pronunciation": "xiào zhǎng", "ipa": "ɕjɑʊ˥˩ ʈʂɑŋ˨˩", "syllable_count": 2, "sentences": [{"text": "她当了十年校长。", "target_word": "校长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新校长下个月来上班。", "target_word": "校长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "校长要决定学校的大事。", "target_word": "校长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这所大学的校长是一位教授。", "target_word": "校长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "校长在会上宣布了新的规定。", "target_word": "校长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师们都听校长的安排。", "target_word": "校长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有问题可以直接找校长。", "target_word": "校长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "校长要负责整个学校的工作。", "target_word": "校长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "校长每年都会参加毕业典礼。", "target_word": "校长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从老师做到了校长。", "target_word": "校长", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "副校长", "label": "复合词"}, {"form": "校長", "label": "繁体"}], "register": "中性", "sense_fingerprint": "学校的最高行政负责人，担任的职务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc845970-b582-4cbd-8bfb-d42e50e4b40f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors