INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88074, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "校长", "is_correct": true, "explanation": "正确答案：学校的最高行政负责人，读作 xiào zhǎng。"}, {"text": "县长", "is_correct": false, "explanation": "xiàn 与 xiào 声调相同，韵母不同（ian 与 iao），意思是县长（县级行政负责人）。"}, {"text": "校章", "is_correct": false, "explanation": "zhāng（第一声）与 zhǎng（第三声）声调不同，意思是校章（学校的徽章或印章）。"}, {"text": "小账", "is_correct": false, "explanation": "xiǎo（第三声）与 xiào（第四声）声调不同，zhàng（第四声）与 zhǎng（第三声）声调也不同，意思是小额账目。"}], "explanations": {"校长": "正确答案：学校的最高行政负责人，读作 xiào zhǎng。", "县长": "xiàn 与 xiào 声调相同，韵母不同（ian 与 iao），意思是县长（县级行政负责人）。", "校章": "zhāng（第一声）与 zhǎng（第三声）声调不同，意思是校章（学校的徽章或印章）。", "小账": "xiǎo（第三声）与 xiào（第四声）声调不同，zhàng（第四声）与 zhǎng（第三声）声调也不同，意思是小额账目。"}, "sentence_index": null, "correct_answer": "校长"}, "level_3": {"options": [{"text": "校长", "is_correct": true, "explanation": "正确答案：“当了十年校长”，指担任学校最高行政负责人的职务。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能被“当”成职务，“当了十年天气”不成立。"}, {"text": "书包", "is_correct": false, "explanation": "配价：“当”后应接职务或身份，书包不是职务。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不能担任职务，句子无法成立。"}], "explanations": {"校长": "正确答案：“当了十年校长”，指担任学校最高行政负责人的职务。", "天气": "语义：天气不能被“当”成职务，“当了十年天气”不成立。", "书包": "配价：“当”后应接职务或身份，书包不是职务。", "窗户": "语义：窗户不能担任职务，句子无法成立。"}, "sentence_index": 0, "correct_answer": "校长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂的校长去年换了人。", "explanation": "这里应该用〈厂长〉。工厂的负责人称厂长，不说校长。"}, {"text": "我们班的校长是个女生。", "explanation": "这里应该用〈班长〉。班级的负责人称班长，“校长”指学校的最高负责人。"}, {"text": "这个科室的校长很能干。", "explanation": "这里应该用〈科长〉。科室的负责人称科长，不说校长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fbc760a-f0a4-4dab-8306-53e9ab979a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88074, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "校长", "is_correct": true, "explanation": "正确答案：“直接找校长”，指学校的最高行政负责人。"}, {"text": "河流", "is_correct": false, "explanation": "搭配：“找”后接的应是能解答问题的人或部门，“找河流”不成立。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不能回答学生的问题，与“有问题找”的语境矛盾。"}, {"text": "电线", "is_correct": false, "explanation": "语义：电线不能解答问题，句子无法成立。"}], "explanations": {"校长": "正确答案：“直接找校长”，指学校的最高行政负责人。", "河流": "搭配：“找”后接的应是能解答问题的人或部门，“找河流”不成立。", "月亮": "语义：月亮不能回答学生的问题，与“有问题找”的语境矛盾。", "电线": "语义：电线不能解答问题，句子无法成立。"}, "sentence_index": 6, "correct_answer": "校长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个村的校长很热心。", "explanation": "这里应该用〈村长〉。村的负责人称村长，不用“校长”。"}, {"text": "我们这家饭店的校长很温柔。", "explanation": "这里应该用〈经理〉。饭店的负责人称经理，不说校长。"}, {"text": "这个镇的校长很亲切。", "explanation": "这里应该用〈镇长〉。镇的负责人称镇长，不用“校长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fbc760a-f0a4-4dab-8306-53e9ab979a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88074, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只校长上任以后改变了学校的制度。", "corrected_sentence": "这位校长上任以后改变了学校的制度。", "error_description": "量词错误：“校长”应用量词“位”，“只”用于动物，不能用于人。应改为“这位校长”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fbc760a-f0a4-4dab-8306-53e9ab979a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88074, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我见过这本校长两次。", "corrected_sentence": "我见过这位校长两次。", "error_description": "量词错误：“校长”应用量词“位”，“本”用于书籍等物品，不能用于人。应改为“这位校长”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fbc760a-f0a4-4dab-8306-53e9ab979a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
