INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88075, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "国外是自己国家的外面。", "primary_collocate": null, "pronunciation": "guó wài", "ipa": "kwɔ˧˥ waɪ˥˩", "syllable_count": 2, "sentences": [{"text": "国内的天气好，国外的天气不太好。", "target_word": "国外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他常常出差，一年有半年在国外。", "target_word": "国外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，国内和国外的习惯不一样。", "target_word": "国外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从来没去过国外，想先学好外语。", "target_word": "国外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说他年轻时在国外生活过。", "target_word": "国外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国外寄来的信，一个星期才到。", "target_word": "国外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的客人大多来自国外。", "target_word": "国外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把钱寄到了国外。", "target_word": "国外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在国外，很多人周末喜欢开车出去玩。", "target_word": "国外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的家人都在国外，不在国内。", "target_word": "国外", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "國外", "label": "繁体"}], "register": "中性", "sense_fingerprint": "国外：自己国家的外面，与国内相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe9756ff-4b06-4a9a-9345-22a235fc21d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88075, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国外", "is_correct": true, "explanation": "正确：与前句的“国内”相对，“国外”指自己国家的外面，句意通顺。"}, {"text": "国内", "is_correct": false, "explanation": "语义：前句已说“国内的天气好”，这里再用“国内”就失去了与“国外”的对比，句意不通。"}, {"text": "室内", "is_correct": false, "explanation": "搭配：“天气”不用来形容“室内”，“室内的天气”说不通。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“厨房”不谈天气，“厨房的天气”说不通。"}], "explanations": {"国外": "正确：与前句的“国内”相对，“国外”指自己国家的外面，句意通顺。", "国内": "语义：前句已说“国内的天气好”，这里再用“国内”就失去了与“国外”的对比，句意不通。", "室内": "搭配：“天气”不用来形容“室内”，“室内的天气”说不通。", "厨房": "搭配：“厨房”不谈天气，“厨房的天气”说不通。"}, "sentence_index": 0, "correct_answer": "国外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "国外的首都是北京。", "explanation": "这里应该用〈中国〉。“国外”泛指国家以外的地方，没有具体的首都，不能说“国外的首都”。"}, {"text": "这位国外人会说中文。", "explanation": "这里应该用〈外国人〉。“国外”指地方，不能用来指人。"}, {"text": "这个国外的人口有十亿。", "explanation": "这里应该用〈国家〉。“国外”不是具体的国家，不能用“这个”来指它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54eb874-fdd6-49ea-9453-a002bd5ff0d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88075, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国外", "is_correct": true, "explanation": "正确：“来自”后接地点，“国外”指本国以外，句意通顺。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“来自”不能接“桌子”，客人不会来自桌子。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：客人不会来自月亮，句子失去现实意义。"}, {"text": "课本", "is_correct": false, "explanation": "搭配：客人不会来自课本，“来自课本”说不通。"}], "explanations": {"国外": "正确：“来自”后接地点，“国外”指本国以外，句意通顺。", "桌子": "搭配：“来自”不能接“桌子”，客人不会来自桌子。", "月亮": "语义：客人不会来自月亮，句子失去现实意义。", "课本": "搭配：客人不会来自课本，“来自课本”说不通。"}, "sentence_index": 6, "correct_answer": "国外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他买了一台国外，用得很顺手。", "explanation": "这里应该用〈电脑〉。“国外”指地方，不是可以用量词“台”来数的机器，“买了一台电脑”才通顺。"}, {"text": "她读了一本国外，觉得很有意思。", "explanation": "这里应该用〈书〉。“国外”指地方，不是书，不能用量词“本”来数，“读了一本书”才通顺。"}, {"text": "他拿了一把国外，走出了房间。", "explanation": "这里应该用〈雨伞〉。“国外”指地方，不是有柄的器具，不能用量词“把”来数，“拿了一把雨伞”才通顺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54eb874-fdd6-49ea-9453-a002bd5ff0d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88075, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他常常出差，一年有半年待国外。", "corrected_sentence": "他常常出差，一年有半年待在国外。", "error_description": "“待”后面接地点时要加“在”，“待国外”应改为“待在国外”，错在漏掉了“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54eb874-fdd6-49ea-9453-a002bd5ff0d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88075, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那家餐厅的顾客大多国外。", "corrected_sentence": "那家餐厅的顾客大多来自国外。", "error_description": "“国外”作来源地点时，要由“来自”引出，应说“来自国外”，错在漏掉了“来自”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54eb874-fdd6-49ea-9453-a002bd5ff0d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
