INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88077, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "年关是快要过年的那几天。", "primary_collocate": null, "pronunciation": "nián guān", "ipa": "njɛn˧˥ kwan˥", "syllable_count": 2, "sentences": [{"text": "年关快到了，街上到处是买年货的人。", "target_word": "年关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每到年关，火车票特别难买。", "target_word": "年关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年关那几天，超市里人很多。", "target_word": "年关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "临近年关，妈妈开始打扫房子。", "target_word": "年关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司年关前最忙。", "target_word": "年关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年关了，外面打工的人都往家里赶。", "target_word": "年关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年关的时候，街上挂满了红灯笼。", "target_word": "年关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年年关，我要回老家陪父母。", "target_word": "年关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了年关，家家户户都做好吃的。", "target_word": "年关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年关前，爸爸买了很多鞭炮和对联。", "target_word": "年关", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "年關", "label": "繁体"}], "register": "中性", "sense_fingerprint": "快要过春节前的那几天", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a96547-d1a2-4444-8d6e-1252fc20d0d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88077, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "中秋", "is_correct": false, "explanation": "语义：中秋是八月十五的节日，与“街上到处是买年货的人”的语境不合。"}, {"text": "年关", "is_correct": true, "explanation": "正确：年关指快要过年的那几天，与“街上到处是买年货的人”相合。"}, {"text": "夏天", "is_correct": false, "explanation": "语义：夏天与“买年货”的春节气氛不合，句意不通。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“快到了”多用于时间或节日，不能说“天气快到了”。"}], "explanations": {"中秋": "语义：中秋是八月十五的节日，与“街上到处是买年货的人”的语境不合。", "年关": "正确：年关指快要过年的那几天，与“街上到处是买年货的人”相合。", "夏天": "语义：夏天与“买年货”的春节气氛不合，句意不通。", "天气": "搭配：“快到了”多用于时间或节日，不能说“天气快到了”。"}, "sentence_index": 0, "correct_answer": "年关"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "元宵节是一年中最热闹的年关。", "explanation": "这里应该用〈节日〉。年关指快要过年的那几天，不能指元宵节这个节日本身。"}, {"text": "春节过后，年关的工作又开始了，大家都忙起来了。", "explanation": "这里应该用〈年后〉。年关指快要过年的那几天，在春节之前，不能放在春节之后。"}, {"text": "今年的年关整整持续了半年，大家都很累。", "explanation": "这里应该用〈工期〉。年关只指快过年的那几天，不能指长达半年的时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88077, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "课间", "is_correct": false, "explanation": "语义：课间是上课之间的休息，与街上挂满红灯笼的景象无关。"}, {"text": "年关", "is_correct": true, "explanation": "正确：年关指快过年的那几天，与“街上挂满了红灯笼”的节日景象相合。"}, {"text": "暑假", "is_correct": false, "explanation": "语义：暑假是夏天的假期，与“红灯笼”的春节景象不合。"}, {"text": "天色", "is_correct": false, "explanation": "搭配：“的时候”前应接时间词，“天色”不能这样用。"}], "explanations": {"课间": "语义：课间是上课之间的休息，与街上挂满红灯笼的景象无关。", "年关": "正确：年关指快过年的那几天，与“街上挂满了红灯笼”的节日景象相合。", "暑假": "语义：暑假是夏天的假期，与“红灯笼”的春节景象不合。", "天色": "搭配：“的时候”前应接时间词，“天色”不能这样用。"}, "sentence_index": 6, "correct_answer": "年关"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们一起去年关旅游，玩了三天。", "explanation": "这里应该用〈北京〉。年关是一段时间，不是可以前往的地方。"}, {"text": "今天是年关，我们放学后去公园玩。", "explanation": "这里应该用〈周末〉。年关指快过年的那几天，不是普通的某一天。"}, {"text": "妈妈去超市买了很多年关。", "explanation": "这里应该用〈年货〉。年关指一段时间，不是可以买的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88077, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "临近着年关，奶奶开始准备年货。", "corrected_sentence": "临近年关，奶奶开始准备年货。", "error_description": "错误在体标。“临近年关”表示时间将到，“临近”后不能加“着”，应说“临近年关”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88077, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们一定要年关过好。", "corrected_sentence": "我们一定要把年关过好。", "error_description": "错误在缺少“把”。“年关”是“过好”的宾语，要用把字句把它提到动词前，应说“把年关过好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
