INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88078, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88078, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指临近春节的时候，旧时是还债的难关。", "primary_collocate": null, "pronunciation": "nián guān", "ipa": "njɛn˧˥ kwan˥", "syllable_count": 2, "sentences": [{"text": "旧时，穷人最怕过年关。", "target_word": "年关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年关到了，欠债的人睡不着觉。", "target_word": "年关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他欠了很多钱，年关难过。", "target_word": "年关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前，农民一到年关就要还债。", "target_word": "年关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说，过年关像过一道难关。", "target_word": "年关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年关将近，债主天天上门要钱。", "target_word": "年关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那一年，他家没钱还债，年关很难过。", "target_word": "年关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过不了年关的人，只好离开家乡。", "target_word": "年关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧社会的年关，对穷人来说很可怕。", "target_word": "年关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷说，他父亲每到年关就躲出去。", "target_word": "年关", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "年關", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "旧时临近春节、欠债人必须还债的难关", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a96547-d1a2-4444-8d6e-1252fc20d0d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88078, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "年关", "is_correct": true, "explanation": "正确：年关指旧时临近春节、欠债人必须还债的难关，与“旧时，穷人最怕”的语境相合。"}, {"text": "周末", "is_correct": false, "explanation": "语义：周末是现代的休息制度，与“旧时”的时代背景不合。"}, {"text": "圣诞节", "is_correct": false, "explanation": "语义：圣诞节是西方节日，与“旧时”穷人的处境无关，句意不通。"}, {"text": "学费", "is_correct": false, "explanation": "搭配：“过”后接节日或时段，不能说“过学费”，句意不通。"}], "explanations": {"年关": "正确：年关指旧时临近春节、欠债人必须还债的难关，与“旧时，穷人最怕”的语境相合。", "周末": "语义：周末是现代的休息制度，与“旧时”的时代背景不合。", "圣诞节": "语义：圣诞节是西方节日，与“旧时”穷人的处境无关，句意不通。", "学费": "搭配：“过”后接节日或时段，不能说“过学费”，句意不通。"}, "sentence_index": 0, "correct_answer": "年关"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场年关很激烈，选手们都拼尽全力。", "explanation": "这里应该用〈比赛〉。年关指旧时临近春节时欠债人要还的难关，不能指体育比赛。"}, {"text": "这场年关很难，他复习到深夜。", "explanation": "这里应该用〈考试〉。年关指还债的难关或临近春节的时候，不能指考试。"}, {"text": "春节是中国最重要的年关。", "explanation": "这里应该用〈节日〉。年关指旧时春节前欠债人还债的难关，不能指春节这个节日本身。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88078, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "学期", "is_correct": false, "explanation": "语义：学期是学校的学习阶段，与“没钱还债”的处境无关，句意不通。"}, {"text": "年关", "is_correct": true, "explanation": "正确：年关指旧时还债的难关，与“那一年，他家没钱还债”的处境相合。"}, {"text": "运动会", "is_correct": false, "explanation": "语义：运动会是学校的体育活动，与“没钱还债”的处境不相干。"}, {"text": "课本", "is_correct": false, "explanation": "搭配：“难过”用于人或处境，不能说“课本很难过”。"}], "explanations": {"学期": "语义：学期是学校的学习阶段，与“没钱还债”的处境无关，句意不通。", "年关": "正确：年关指旧时还债的难关，与“那一年，他家没钱还债”的处境相合。", "运动会": "语义：运动会是学校的体育活动，与“没钱还债”的处境不相干。", "课本": "搭配：“难过”用于人或处境，不能说“课本很难过”。"}, "sentence_index": 6, "correct_answer": "年关"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他欠了一大笔年关，每天都睡不着觉。", "explanation": "这里应该用〈债务〉。年关指一段难关，不是欠下的钱。"}, {"text": "这场洪水是村里的一场大年关。", "explanation": "这里应该用〈灾难〉。年关特指旧时春节前的还债难关，不泛指自然灾害。"}, {"text": "春假是学生们最期待的年关。", "explanation": "这里应该用〈假期〉。年关指旧时还债的难关，不是一段可以休假的时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88078, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "临近着年关，债主天天上门要钱。", "corrected_sentence": "临近年关，债主天天上门要钱。", "error_description": "错误在体标。“临近年关”表示时间将到，“临近”后不能加“着”，应说“临近年关”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88078, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那一年，他正在过过年关。", "corrected_sentence": "那一年，他正在过年关。", "error_description": "错误在体标。“正在”表示动作正在进行，不能与经历体“过过”同用，应说“正在过年关”，去掉多余的“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
