INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88079, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "转学生是从别的学校来到这个学校读书的孩子。", "primary_collocate": null, "pronunciation": "zhuǎn xué shēng", "ipa": "ʈʂwan˨˩˦ ɕɥe˧˥ ʂʌŋ˥˥", "syllable_count": 3, "sentences": [{"text": "我们班来了一个转学生。", "target_word": "转学生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "转学生今天第一次来上课。", "target_word": "转学生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个转学生很安静，不太说话。", "target_word": "转学生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让转学生坐在我旁边。", "target_word": "转学生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "转学生是从北京来的。", "target_word": "转学生", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我想和新来的转学生做朋友。", "target_word": "转学生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个转学生还不认识班里的同学。", "target_word": "转学生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都很喜欢那个转学生。", "target_word": "转学生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们班的转学生会说英语。", "target_word": "转学生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师带着转学生去看新教室。", "target_word": "转学生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "轉學生", "label": "繁体"}], "register": "中性", "sense_fingerprint": "从别的学校来到本校读书的孩子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d850554-45f7-4ce0-b18d-6b02b303fbf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88079, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "转学生", "is_correct": true, "explanation": "符合语境：从别的学校转来、刚到班里的学生。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“来了”说人到来，作业不会来到班里。"}, {"text": "苹果", "is_correct": false, "explanation": "语义：苹果是水果，不会“来到”班里，“我们班来了一个苹果”说不通。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是地点，不会“来到”班里，“我们班来了”说不通。"}], "explanations": {"转学生": "符合语境：从别的学校转来、刚到班里的学生。", "作业": "语义：“来了”说人到来，作业不会来到班里。", "苹果": "语义：苹果是水果，不会“来到”班里，“我们班来了一个苹果”说不通。", "教室": "语义：教室是地点，不会“来到”班里，“我们班来了”说不通。"}, "sentence_index": 0, "correct_answer": "转学生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们学校来了一个转学生，他是教数学的，刚从别的学校调过来。", "explanation": "这里应该用〈新老师〉。转学生指从别的学校转来的学生，不能指教课的老师；从别校调来的老师是新老师。"}, {"text": "我今年刚上小学，是一年级的转学生。", "explanation": "这里应该用〈新生〉。刚入学的学生是新生；转学生指从别的学校转来的学生。"}, {"text": "我从没离开过这所学校，一直都是转学生。", "explanation": "这里应该用〈在校生〉。一直在本校就读、从未转来的学生是在校生；转学生指从别的学校转来的学生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5186a37-f9e3-4c52-8db2-317d96357b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88079, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "转学生", "is_correct": true, "explanation": "符合语境：刚转来，所以还不认识班里的同学。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板是物品，不会“还不认识”同学。"}, {"text": "猫", "is_correct": false, "explanation": "语义：猫不会上学，也不会“认识班里的同学”。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是物品，不会“认识班里的同学”。"}], "explanations": {"转学生": "符合语境：刚转来，所以还不认识班里的同学。", "黑板": "语义：黑板是物品，不会“还不认识”同学。", "猫": "语义：猫不会上学，也不会“认识班里的同学”。", "桌子": "语义：桌子是物品，不会“认识班里的同学”。"}, "sentence_index": 6, "correct_answer": "转学生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他因为成绩不好，只能留在原年级，成了转学生。", "explanation": "这里应该用〈留级生〉。因成绩不及格而留在原年级的学生是留级生；转学生是从别的学校转来的学生。"}, {"text": "这个班的转学生，大家都是从小学一年级就一起长大的。", "explanation": "这里应该用〈同届生〉。从小学一年级起就同班长大的同学是同届生；转学生指从别的学校转来的学生。"}, {"text": "他在这个班已经读了三年，是班里的转学生。", "explanation": "这里应该用〈老生〉。在班里已经读了很久的学生是老生；转学生指刚从别的学校转来的学生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5186a37-f9e3-4c52-8db2-317d96357b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88079, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他上学期转学生到北京了。", "corrected_sentence": "他上学期转学到北京了。", "error_description": "词类错误：“转学生”是名词，不能当动词用；表示转学这个动作应说“转学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5186a37-f9e3-4c52-8db2-317d96357b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88079, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师带着那只转学生去看新教室。", "corrected_sentence": "老师带着那个转学生去看新教室。", "error_description": "量词错误：指人的名词“转学生”应用量词“个”，不能用“只”（“只”多用于动物等）。应改为“那个转学生”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5186a37-f9e3-4c52-8db2-317d96357b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
