INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88080, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "从原来的学校转到另一所学校就读的学生。", "primary_collocate": null, "pronunciation": "zhuǎn xué shēng", "ipa": "ʈʂwan˨˩˦ ɕɥe˧˥ ʂʌŋ˥˥", "syllable_count": 3, "sentences": [{"text": "学校里有三个转学生。", "target_word": "转学生", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个学期班上多了两个转学生。", "target_word": "转学生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "转学生需要先办手续。", "target_word": "转学生", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "转学生的成绩单要交给老师。", "target_word": "转学生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是去年才来的转学生。", "target_word": "转学生", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这位转学生以前在上海读书。", "target_word": "转学生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师请转学生介绍一下自己。", "target_word": "转学生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "转学生刚到学校，什么都不熟悉。", "target_word": "转学生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校为转学生准备了新课本。", "target_word": "转学生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "班长帮转学生把书搬到了教室。", "target_word": "转学生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "轉學生", "label": "繁体"}], "register": "中性", "sense_fingerprint": "办理转学手续、转入另一所学校的学生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d850554-45f7-4ce0-b18d-6b02b303fbf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88080, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "转学生", "is_correct": true, "explanation": "符合语境：三名从别的学校转来的学生。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能作为“学校里有三个”的可数对象。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不可数，“三个空气”说不通。"}, {"text": "牛奶", "is_correct": false, "explanation": "语义：牛奶是饮料，不能说“学校里有三个牛奶”。"}], "explanations": {"转学生": "符合语境：三名从别的学校转来的学生。", "天气": "语义：天气是自然现象，不能作为“学校里有三个”的可数对象。", "空气": "语义：空气不可数，“三个空气”说不通。", "牛奶": "语义：牛奶是饮料，不能说“学校里有三个牛奶”。"}, "sentence_index": 0, "correct_answer": "转学生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校来了一位转学生，他是刚从别的学校调来的校长。", "explanation": "这里应该用〈新校长〉。转学生指学生，不能用来称呼校长；从别校调来的校长是新校长。"}, {"text": "今天陪我来办转学手续的转学生是我爸爸。", "explanation": "这里应该用〈家长〉。转学生指学生本人，陪孩子来办手续的是家长。"}, {"text": "我从小学一年级起就在这所学校，所以我是转学生。", "explanation": "这里应该用〈本校学生〉。一直在本校就读的学生不是转学生；转学生指从别的学校转来的学生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5186a37-f9e3-4c52-8db2-317d96357b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88080, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "转学生", "is_correct": true, "explanation": "符合语境：可以请刚转来的人上台自我介绍。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不会说话，不能“介绍一下自己”。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不是人，“介绍自己”说不通。"}, {"text": "老鼠", "is_correct": false, "explanation": "配价：“请……介绍一下自己”要求能开口的人作宾语，老鼠不符合。"}], "explanations": {"转学生": "符合语境：可以请刚转来的人上台自我介绍。", "桌子": "语义：桌子不会说话，不能“介绍一下自己”。", "窗户": "语义：窗户不是人，“介绍自己”说不通。", "老鼠": "配价：“请……介绍一下自己”要求能开口的人作宾语，老鼠不符合。"}, "sentence_index": 6, "correct_answer": "转学生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他因为成绩不好，只能留在原年级，成了转学生。", "explanation": "这里应该用〈留级生〉。因成绩不及格留在原年级的学生是留级生，转学生指从别的学校转来。"}, {"text": "我们班的转学生都是从小学一年级就一起读上来的。", "explanation": "这里应该用〈同届生〉。一起从小学一年级读上来的同学是同届生；转学生指从别的学校转来的学生。"}, {"text": "这位转学生在学校已经毕业三年了。", "explanation": "这里应该用〈校友〉。已经毕业多年的人是校友；转学生指正在就读、刚从别的学校转来的学生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5186a37-f9e3-4c52-8db2-317d96357b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88080, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他去年转学生到上海了。", "corrected_sentence": "他去年转学到上海了。", "error_description": "词类错误：“转学生”是名词，不能当动词用；表示转学这个动作应说“转学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5186a37-f9e3-4c52-8db2-317d96357b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88080, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只转学生昨天来了。", "corrected_sentence": "这位转学生昨天来了。", "error_description": "量词错误：指人的名词“转学生”应用量词“位”或“个”，不能用“只”（“只”多用于动物等）。应改为“这位转学生”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5186a37-f9e3-4c52-8db2-317d96357b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
