INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88081, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "款是一笔钱。", "primary_collocate": null, "pronunciation": "kuǎn", "ipa": "kʰuan˨˩˦", "syllable_count": 1, "sentences": [{"text": "这笔款明天会到账。", "target_word": "款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校收到了一笔款。", "target_word": "款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行里的那笔款是我的。", "target_word": "款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把那笔款存进了银行。", "target_word": "款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔款要用来修路。", "target_word": "款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给我寄了一笔款。", "target_word": "款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司还没有付这笔款。", "target_word": "款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔款一共两万块。", "target_word": "款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你查一下这笔款到了没有。", "target_word": "款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿着那笔款去买房子。", "target_word": "款", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "笔", "label": "量词"}, {"form": "款项", "label": "复合词"}, {"form": "款子", "label": "复合词"}], "register": "中性", "sense_fingerprint": "一笔用于支付、汇入或收到的钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a541dc3-3520-4439-b5c6-163a85c00558') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88081, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "款", "is_correct": true, "explanation": "正确：款（kuǎn），指一笔钱。"}, {"text": "管", "is_correct": false, "explanation": "管（guǎn）与款声母不同（g 与 k），意思是管子。"}, {"text": "宽", "is_correct": false, "explanation": "宽（kuān）与款声调不同（第一声），意思是宽广。"}, {"text": "砍", "is_correct": false, "explanation": "砍（kǎn）去掉了 u 介音，意思是用刀劈。"}], "explanations": {"款": "正确：款（kuǎn），指一笔钱。", "管": "管（guǎn）与款声母不同（g 与 k），意思是管子。", "宽": "宽（kuān）与款声调不同（第一声），意思是宽广。", "砍": "砍（kǎn）去掉了 u 介音，意思是用刀劈。"}, "sentence_index": null, "correct_answer": "款"}, "level_3": {"options": [{"text": "款", "is_correct": true, "explanation": "正确：款是一笔钱，可以到账，符合语境。"}, {"text": "货", "is_correct": false, "explanation": "语义：货不是钱，不会到账。"}, {"text": "书", "is_correct": false, "explanation": "搭配：书的量词是「本」，不说「这笔书」。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不是钱，不会到账。"}], "explanations": {"款": "正确：款是一笔钱，可以到账，符合语境。", "货": "语义：货不是钱，不会到账。", "书": "搭配：书的量词是「本」，不说「这笔书」。", "房子": "语义：房子不是钱，不会到账。"}, "sentence_index": 0, "correct_answer": "款"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很爱款。", "explanation": "这里应该用〈钱〉。「款」指一笔确定的数额，不能泛指钱，所以不能说「爱款」。"}, {"text": "他拿着一本款去买房子。", "explanation": "这里应该用〈笔〉。款用「笔」来量，「本」用于书册。"}, {"text": "我买了一只款。", "explanation": "这里应该用〈笔〉。款用「笔」来量，「只」多用于动物或成对器物中的一个。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b17db4-da70-4ffb-9036-e059ac3a09c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88081, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "款", "is_correct": true, "explanation": "正确：款（kuǎn），指一笔钱。"}, {"text": "馆", "is_correct": false, "explanation": "馆（guǎn）与款声母不同（g 与 k），意思是房屋或场所，如博物馆。"}, {"text": "看", "is_correct": false, "explanation": "看（kàn）去掉了 u 介音，声调也不同，意思是观看。"}, {"text": "矿", "is_correct": false, "explanation": "矿（kuàng）与款韵母 an 与 ang 不同，声调也不同，意思是矿石。"}], "explanations": {"款": "正确：款（kuǎn），指一笔钱。", "馆": "馆（guǎn）与款声母不同（g 与 k），意思是房屋或场所，如博物馆。", "看": "看（kàn）去掉了 u 介音，声调也不同，意思是观看。", "矿": "矿（kuàng）与款韵母 an 与 ang 不同，声调也不同，意思是矿石。"}, "sentence_index": null, "correct_answer": "款"}, "level_3": {"options": [{"text": "款", "is_correct": true, "explanation": "正确：款是需要支付的一笔钱，符合「公司还没有付」的语境。"}, {"text": "故事", "is_correct": false, "explanation": "语义：故事不是钱，不能用来支付。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业不是钱，不能支付。"}, {"text": "考试", "is_correct": false, "explanation": "搭配：考试的量词是「场」或「次」，不说「这笔考试」。"}], "explanations": {"款": "正确：款是需要支付的一笔钱，符合「公司还没有付」的语境。", "故事": "语义：故事不是钱，不能用来支付。", "作业": "语义：作业不是钱，不能支付。", "考试": "搭配：考试的量词是「场」或「次」，不说「这笔考试」。"}, "sentence_index": 6, "correct_answer": "款"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司一共欠我一台款。", "explanation": "这里应该用〈笔〉。款用「笔」来量，「台」多用于机器设备。"}, {"text": "爸爸给我买了一双款。", "explanation": "这里应该用〈笔〉。款用「笔」来量，「双」多用于成对的物件，如鞋子。"}, {"text": "这笔款很好看，我们都很喜欢。", "explanation": "这里的〈款〉被当成了式样，但它指一笔钱，不能用来形容好看；形容式样应该用〈式样〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b17db4-da70-4ffb-9036-e059ac3a09c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
