INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88082, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "款项；一笔钱。", "primary_collocate": null, "pronunciation": "kuǎn", "ipa": "kʰuan˨˩˦", "syllable_count": 1, "sentences": [{"text": "这笔款是用来买书的。", "target_word": "款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说这笔款不能乱花。", "target_word": "款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里拿到了一笔款，修了新路。", "target_word": "款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那笔款已经汇给你了。", "target_word": "款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在等这笔款。", "target_word": "款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把这笔款分成了三份。", "target_word": "款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔款不多，但是很有用。", "target_word": "款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说那笔款要还给朋友。", "target_word": "款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔款是谁给学校的？", "target_word": "款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这笔款交给王老师。", "target_word": "款", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "笔", "label": "量词"}, {"form": "款项", "label": "复合词"}, {"form": "款子", "label": "复合词"}], "register": "中性", "sense_fingerprint": "有指定用途或来源的一笔款项", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a541dc3-3520-4439-b5c6-163a85c00558') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88082, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "款", "is_correct": true, "explanation": "正确：款（kuǎn），指有指定用途或来源的一笔款项。"}, {"text": "管", "is_correct": false, "explanation": "管（guǎn）与款声母不同（g 与 k），意思是管子。"}, {"text": "宽", "is_correct": false, "explanation": "宽（kuān）与款声调不同（第一声），意思是宽广。"}, {"text": "看", "is_correct": false, "explanation": "看（kàn）去掉了 u 介音，声调也不同，意思是观看。"}], "explanations": {"款": "正确：款（kuǎn），指有指定用途或来源的一笔款项。", "管": "管（guǎn）与款声母不同（g 与 k），意思是管子。", "宽": "宽（kuān）与款声调不同（第一声），意思是宽广。", "看": "看（kàn）去掉了 u 介音，声调也不同，意思是观看。"}, "sentence_index": null, "correct_answer": "款"}, "level_3": {"options": [{"text": "款", "is_correct": true, "explanation": "正确：款是有指定用途的一笔钱，可以用来买书，符合语境。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料不是钱，不能用来买书。"}, {"text": "书", "is_correct": false, "explanation": "搭配：书的量词是「本」，不说「这笔书」。"}, {"text": "木头", "is_correct": false, "explanation": "语义：木头不是钱，不能用来买书。"}], "explanations": {"款": "正确：款是有指定用途的一笔钱，可以用来买书，符合语境。", "饮料": "语义：饮料不是钱，不能用来买书。", "书": "搭配：书的量词是「本」，不说「这笔书」。", "木头": "语义：木头不是钱，不能用来买书。"}, "sentence_index": 0, "correct_answer": "款"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这款手机已经汇给你了。", "explanation": "这里的〈款〉指产品的式样，不指一笔钱，「汇」的对象只能是钱。"}, {"text": "那本款已经汇给你了。", "explanation": "这里应该用〈笔〉。款用「笔」来量，「本」用于书册。"}, {"text": "那只款已经汇给你了。", "explanation": "这里应该用〈笔〉。款用「笔」来量，「只」多用于动物或成对器物中的一个。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b17db4-da70-4ffb-9036-e059ac3a09c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88082, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "款", "is_correct": true, "explanation": "正确：款（kuǎn），指有指定用途或来源的一笔款项。"}, {"text": "馆", "is_correct": false, "explanation": "馆（guǎn）与款声母不同（g 与 k），意思是房屋或场所，如博物馆。"}, {"text": "砍", "is_correct": false, "explanation": "砍（kǎn）去掉了 u 介音，意思是用刀劈。"}, {"text": "矿", "is_correct": false, "explanation": "矿（kuàng）与款韵母 an 与 ang 不同，声调也不同，意思是矿石。"}], "explanations": {"款": "正确：款（kuǎn），指有指定用途或来源的一笔款项。", "馆": "馆（guǎn）与款声母不同（g 与 k），意思是房屋或场所，如博物馆。", "砍": "砍（kǎn）去掉了 u 介音，意思是用刀劈。", "矿": "矿（kuàng）与款韵母 an 与 ang 不同，声调也不同，意思是矿石。"}, "sentence_index": null, "correct_answer": "款"}, "level_3": {"options": [{"text": "款", "is_correct": true, "explanation": "正确：款也可以说「不多，但是很有用」，符合语境。"}, {"text": "咖啡", "is_correct": false, "explanation": "搭配：咖啡的量词是「杯」，不说「这笔咖啡」。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道不能用「笔」来计量，也谈不上「有用」。"}, {"text": "椅子", "is_correct": false, "explanation": "搭配：椅子的量词是「把」，不说「这笔椅子」。"}], "explanations": {"款": "正确：款也可以说「不多，但是很有用」，符合语境。", "咖啡": "搭配：咖啡的量词是「杯」，不说「这笔咖啡」。", "味道": "语义：味道不能用「笔」来计量，也谈不上「有用」。", "椅子": "搭配：椅子的量词是「把」，不说「这笔椅子」。"}, "sentence_index": 6, "correct_answer": "款"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请把这台款交给王老师。", "explanation": "这里应该用〈笔〉。款用「笔」来量，「台」多用于机器设备。"}, {"text": "请把这块款交给王老师。", "explanation": "这里应该用〈笔〉。款用「笔」来量，「块」多用于块状的东西。"}, {"text": "请把这本款交给王老师。", "explanation": "这里应该用〈笔〉。款用「笔」来量，「本」用于书册。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b17db4-da70-4ffb-9036-e059ac3a09c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88082, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那本款我们已经收到了。", "corrected_sentence": "那笔款我们已经收到了。", "error_description": "量词错误：款应该用量词「笔」，「本」用于书册。应说「那笔款我们已经收到了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b17db4-da70-4ffb-9036-e059ac3a09c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88082, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本款我们明天就寄出去。", "corrected_sentence": "这笔款我们明天就寄出去。", "error_description": "量词错误：款应该用量词「笔」，「本」用于书册。应说「这笔款我们明天就寄出去」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b17db4-da70-4ffb-9036-e059ac3a09c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
