INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88083, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "多年是很多个年头，时间很久。", "primary_collocate": null, "pronunciation": "duō nián", "ipa": "tuɔ˥ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "他和我是多年的好朋友。", "target_word": "多年", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爷爷在这里住了多年。", "target_word": "多年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多年的老习惯，他很难改。", "target_word": "多年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她多年的梦想终于成真了。", "target_word": "多年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店开了多年，很多人都认识。", "target_word": "多年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在国外工作多年，今年才回家。", "target_word": "多年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们是多年的老邻居。", "target_word": "多年", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "多年的努力，让他当上了经理。", "target_word": "多年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师教书多年，学生都很喜欢她。", "target_word": "多年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台旧电脑我已经用了多年。", "target_word": "多年", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "多年前", "label": "复合"}, {"form": "多年后", "label": "复合"}], "register": "中性", "sense_fingerprint": "多年：很多个年头，常作定语或表示时间长度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14b344bf-0d85-4cad-8e3c-b481bef5b4ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88083, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "多年", "is_correct": true, "explanation": "正确：多年（duō nián），意思是很多年。"}, {"text": "大年", "is_correct": false, "explanation": "dà（第四声）与 duō（第一声）声母相同，韵母和声调都不同，意思是丰收的年份，与“多年”不同。"}, {"text": "多难", "is_correct": false, "explanation": "多难读 duō nàn，nàn（第四声）与 nián（第二声）介音和声调都不同，意思是灾难很多，与“多年”不同。"}, {"text": "多言", "is_correct": false, "explanation": "yán 与 nián 只差声母 n，意思是话多，与“多年”不同。"}], "explanations": {"多年": "正确：多年（duō nián），意思是很多年。", "大年": "dà（第四声）与 duō（第一声）声母相同，韵母和声调都不同，意思是丰收的年份，与“多年”不同。", "多难": "多难读 duō nàn，nàn（第四声）与 nián（第二声）介音和声调都不同，意思是灾难很多，与“多年”不同。", "多言": "yán 与 nián 只差声母 n，意思是话多，与“多年”不同。"}, "sentence_index": null, "correct_answer": "多年"}, "level_3": {"options": [{"text": "多年", "is_correct": true, "explanation": "正确：“多年”表示很多年，与“好朋友”的长期关系相符。"}, {"text": "当天", "is_correct": false, "explanation": "语义：“当天”指同一天，与“好朋友”的长期关系矛盾。"}, {"text": "早晨", "is_correct": false, "explanation": "搭配：“早晨”是一个时间点，不能用来说明交情持续的时间。"}, {"text": "一夜", "is_correct": false, "explanation": "语义：“一夜”指一个晚上，不能说明长期的友谊。"}], "explanations": {"多年": "正确：“多年”表示很多年，与“好朋友”的长期关系相符。", "当天": "语义：“当天”指同一天，与“好朋友”的长期关系矛盾。", "早晨": "搭配：“早晨”是一个时间点，不能用来说明交情持续的时间。", "一夜": "语义：“一夜”指一个晚上，不能说明长期的友谊。"}, "sentence_index": 0, "correct_answer": "多年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这次去北京出差，只待了多年。", "explanation": "这里应该用〈几天〉。多年指很长时间，不能用来描述短期出差。"}, {"text": "他洗一个苹果用了多年。", "explanation": "这里应该用〈几分钟〉。多年指很长时间，不能用来说洗一个苹果这样的短时间小事。"}, {"text": "你等多年，我马上就来。", "explanation": "这里应该用〈一会儿〉。多年指很长时间，与“马上就来”的意思矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723ce58d-f234-47cd-bfc4-2683846ec4d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88083, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多年", "is_correct": true, "explanation": "正确：“多年”表示很多年，与“老邻居”的长期关系相符。"}, {"text": "当晚", "is_correct": false, "explanation": "语义：“当晚”指当天晚上，与“老邻居”的长期关系矛盾。"}, {"text": "午间", "is_correct": false, "explanation": "搭配：“午间”是中午的时段，不能用来说明邻居关系的时长。"}, {"text": "半天", "is_correct": false, "explanation": "语义：“半天”指很短的时间，与“老邻居”矛盾。"}], "explanations": {"多年": "正确：“多年”表示很多年，与“老邻居”的长期关系相符。", "当晚": "语义：“当晚”指当天晚上，与“老邻居”的长期关系矛盾。", "午间": "搭配：“午间”是中午的时段，不能用来说明邻居关系的时长。", "半天": "语义：“半天”指很短的时间，与“老邻居”矛盾。"}, "sentence_index": 6, "correct_answer": "多年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在车站等了多年，火车就来了。", "explanation": "这里应该用〈半小时〉。多年指很长时间，与“就来了”的短时间矛盾。"}, {"text": "这道菜只要煮多年就好了。", "explanation": "这里应该用〈一刻钟〉。多年指很长时间，不能用来说明做菜所需的短时间。"}, {"text": "这个任务我多年就完成了。", "explanation": "这里应该用〈一天〉。多年指很长时间，与“就完成了”的快速完成矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723ce58d-f234-47cd-bfc4-2683846ec4d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88083, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们俩是一多年的老同学。", "corrected_sentence": "他们俩是多年的老同学。", "error_description": "错误：“多年”前面加了数词“一”。正确：应直接说“多年的老同学”，“多年”本身已经表示很多年，不能再加“一”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723ce58d-f234-47cd-bfc4-2683846ec4d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88083, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他当多年老师，很有经验。", "corrected_sentence": "他当了多年老师，很有经验。", "error_description": "错误：“当”后面缺少表示完成的“了”。正确：应说“当了多年老师”，表示已经完成的经历。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723ce58d-f234-47cd-bfc4-2683846ec4d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
