INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88084, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "许多年；很长一段时间。", "primary_collocate": null, "pronunciation": "duō nián", "ipa": "tuɔ˥ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "我们多年没见面了。", "target_word": "多年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多年以后，他又回到了这里。", "target_word": "多年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多年前，这里只有一条小路。", "target_word": "多年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过了多年，她还记得那天的事。", "target_word": "多年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多年不下雪，今年冬天却下了大雪。", "target_word": "多年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事已经过去多年了。", "target_word": "多年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多年不见，你一点儿都没变。", "target_word": "多年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多年后，我们在北京又见面了。", "target_word": "多年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他多年没回老家，那里变化很大。", "target_word": "多年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多年过去了，小城的样子完全变了。", "target_word": "多年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "多年前", "label": "复合"}, {"form": "多年后", "label": "复合"}], "register": "中性", "sense_fingerprint": "多年：许多年，一段很长的时间，常作时间词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14b344bf-0d85-4cad-8e3c-b481bef5b4ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88084, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "多年", "is_correct": true, "explanation": "正确：多年（duō nián），意思是很多年。"}, {"text": "大年", "is_correct": false, "explanation": "dà（第四声）与 duō（第一声）声母相同，韵母和声调都不同，意思是丰收的年份，与“多年”不同。"}, {"text": "多难", "is_correct": false, "explanation": "多难读 duō nàn，nàn（第四声）与 nián（第二声）介音和声调都不同，意思是灾难很多，与“多年”不同。"}, {"text": "多言", "is_correct": false, "explanation": "yán 与 nián 只差声母 n，意思是话多，与“多年”不同。"}], "explanations": {"多年": "正确：多年（duō nián），意思是很多年。", "大年": "dà（第四声）与 duō（第一声）声母相同，韵母和声调都不同，意思是丰收的年份，与“多年”不同。", "多难": "多难读 duō nàn，nàn（第四声）与 nián（第二声）介音和声调都不同，意思是灾难很多，与“多年”不同。", "多言": "yán 与 nián 只差声母 n，意思是话多，与“多年”不同。"}, "sentence_index": null, "correct_answer": "多年"}, "level_3": {"options": [{"text": "多年", "is_correct": true, "explanation": "正确：“多年”表示很长时间，与“没见面了”相符。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示马上，与长时间没见面的意思矛盾。"}, {"text": "刚刚", "is_correct": false, "explanation": "搭配：“刚刚”通常用于刚发生的事，不能用来说明没见面的时长。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示次数少，与“没见面”的长时间状态矛盾。"}], "explanations": {"多年": "正确：“多年”表示很长时间，与“没见面了”相符。", "立刻": "语义：“立刻”表示马上，与长时间没见面的意思矛盾。", "刚刚": "搭配：“刚刚”通常用于刚发生的事，不能用来说明没见面的时长。", "偶尔": "语义：“偶尔”表示次数少，与“没见面”的长时间状态矛盾。"}, "sentence_index": 0, "correct_answer": "多年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他来这儿只住了多年，就走了。", "explanation": "这里应该用〈几天〉。多年指很长时间，与“就走了”的短暂停留矛盾。"}, {"text": "这场雨下了多年就停了。", "explanation": "这里应该用〈几分钟〉。多年指很长时间，不能用于一场很快停下的雨。"}, {"text": "请你稍等多年，我马上过来。", "explanation": "这里应该用〈一会儿〉。多年指很长时间，与“马上过来”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723ce58d-f234-47cd-bfc4-2683846ec4d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88084, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多年", "is_correct": true, "explanation": "正确：“多年”表示很长时间，与“不见”和“一点儿都没变”的对比相符。"}, {"text": "每天", "is_correct": false, "explanation": "语义：“每天”表示天天，与“不见”的长时间状态矛盾。"}, {"text": "仅仅", "is_correct": false, "explanation": "搭配：“仅仅”后面一般接数量或动作，不能直接用来修饰“不见”。"}, {"text": "每周", "is_correct": false, "explanation": "语义：“每周”表示按周重复，与“不见”的意思矛盾。"}], "explanations": {"多年": "正确：“多年”表示很长时间，与“不见”和“一点儿都没变”的对比相符。", "每天": "语义：“每天”表示天天，与“不见”的长时间状态矛盾。", "仅仅": "搭配：“仅仅”后面一般接数量或动作，不能直接用来修饰“不见”。", "每周": "语义：“每周”表示按周重复，与“不见”的意思矛盾。"}, "sentence_index": 6, "correct_answer": "多年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张画我只用了多年就画完了。", "explanation": "这里应该用〈半小时〉。多年指很长时间，与“就画完了”的快速完成矛盾。"}, {"text": "这个汤只要炖多年就行了。", "explanation": "这里应该用〈一刻钟〉。多年指很长时间，不能用于炖汤这种短时间的事。"}, {"text": "这份报告我多年就写完了。", "explanation": "这里应该用〈一天〉。多年指很长时间，与“就写完了”的快速完成矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723ce58d-f234-47cd-bfc4-2683846ec4d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88084, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座小城变了很多，我离开它已经一多年了。", "corrected_sentence": "这座小城变了很多，我离开它已经多年了。", "error_description": "错误：“多年”前面加了数词“一”。正确：应直接说“已经多年了”，“多年”本身已经表示很长时间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723ce58d-f234-47cd-bfc4-2683846ec4d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88084, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在这家工厂干着多年。", "corrected_sentence": "我在这家工厂干了多年。", "error_description": "错误：“干”后面用了“着”，表示持续的状态，与表示经历时长的“多年”不搭。正确：应说“干了多年”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723ce58d-f234-47cd-bfc4-2683846ec4d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88085, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "微弱", "is_correct": true, "explanation": "微弱与“强力”意思相反，形容力量小。"}, {"text": "干净", "is_correct": false, "explanation": "干净指没有污垢，与“强力”没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚指清晰、明白，与“强力”没有反义关系。"}, {"text": "聪明", "is_correct": false, "explanation": "聪明形容头脑好，与“强力”没有反义关系。"}], "correct_answer": "微弱", "explanations": {"微弱": "微弱与“强力”意思相反，形容力量小。", "干净": "干净指没有污垢，与“强力”没有反义关系。", "清楚": "清楚指清晰、明白，与“强力”没有反义关系。", "聪明": "聪明形容头脑好，与“强力”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbe15dbf-f1e9-4fde-88dd-68c177b9c4ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88085, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "微弱", "is_correct": true, "explanation": "微弱与“强力”意思相反，形容力量小。"}, {"text": "美丽", "is_correct": false, "explanation": "美丽形容外表好看，与“强力”没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "安静指没有声音或不吵闹，与“强力”没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮形容光线强，与“强力”没有反义关系。"}], "correct_answer": "微弱", "explanations": {"微弱": "微弱与“强力”意思相反，形容力量小。", "美丽": "美丽形容外表好看，与“强力”没有反义关系。", "安静": "安静指没有声音或不吵闹，与“强力”没有反义关系。", "明亮": "明亮形容光线强，与“强力”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbe15dbf-f1e9-4fde-88dd-68c177b9c4ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88085, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "强力是力量很大。", "primary_collocate": null, "pronunciation": "qiáng lì", "ipa": "tɕʰjɑŋ˧˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "这是一台强力的吸尘器。", "target_word": "强力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种强力喷水枪能把墙洗干净。", "target_word": "强力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台强力水泵能抽很多水。", "target_word": "强力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "强力的海风把帽子吹走了。", "target_word": "强力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只强力的机器手臂能举起一吨重的东西。", "target_word": "强力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "强力的拖车把坏车拉走了。", "target_word": "强力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的强力水流冲走了小桥。", "target_word": "强力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了一块强力的磁铁。", "target_word": "强力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台强力发动机跑得很快。", "target_word": "强力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "强力的风扇把纸吹得到处都是。", "target_word": "强力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "强力胶", "label": "复合"}, {"form": "強力", "label": "繁体"}], "register": "中性", "sense_fingerprint": "形容机器、风、水流等力量很大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43e9cbc-284b-4337-94c6-a22041e14477') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88085, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "甜美", "is_correct": false, "explanation": "搭配：“甜美”多形容声音、味道或笑容，不能说“甜美的吸尘器”。"}, {"text": "强力", "is_correct": true, "explanation": "强力表示力量很大，与吸尘器的吸力相符。"}, {"text": "冷淡", "is_correct": false, "explanation": "语义：“冷淡”形容人的态度，不能用来修饰吸尘器。"}, {"text": "清脆", "is_correct": false, "explanation": "语义：“清脆”形容声音，吸尘器不能是清脆的。"}], "explanations": {"甜美": "搭配：“甜美”多形容声音、味道或笑容，不能说“甜美的吸尘器”。", "强力": "强力表示力量很大，与吸尘器的吸力相符。", "冷淡": "语义：“冷淡”形容人的态度，不能用来修饰吸尘器。", "清脆": "语义：“清脆”形容声音，吸尘器不能是清脆的。"}, "sentence_index": 0, "correct_answer": "强力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对这件事有强力的不满。", "explanation": "这里应该用〈强烈〉。强力指物理上的力量大，不用来形容情感。"}, {"text": "这是一个强力的国家，在国际上很有地位。", "explanation": "这里应该用〈强大〉。强力指物理上的力量大，不用来形容国家的综合实力。"}, {"text": "他是一个数学成绩强力的学生，考试总是全班第一。", "explanation": "这里应该用〈优秀〉。强力指物理上的力量大，不用来形容成绩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbe15dbf-f1e9-4fde-88dd-68c177b9c4ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88085, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "缓慢", "is_correct": false, "explanation": "语义：缓慢的水流冲不走小桥，与“冲走了小桥”矛盾。"}, {"text": "强力", "is_correct": true, "explanation": "强力表示力量很大，水流强劲才能冲走小桥，与句意相符。"}, {"text": "温和", "is_correct": false, "explanation": "语义：温和的水流冲不走小桥，与句意矛盾。"}, {"text": "平静", "is_correct": false, "explanation": "语义：平静的水流不会冲走小桥，句意矛盾。"}], "explanations": {"缓慢": "语义：缓慢的水流冲不走小桥，与“冲走了小桥”矛盾。", "强力": "强力表示力量很大，水流强劲才能冲走小桥，与句意相符。", "温和": "语义：温和的水流冲不走小桥，与句意矛盾。", "平静": "语义：平静的水流不会冲走小桥，句意矛盾。"}, "sentence_index": 6, "correct_answer": "强力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司有强力的资金，足够支持三年的研发。", "explanation": "这里应该用〈雄厚〉。强力指力量大，不用来形容资金多。"}, {"text": "他有一手强力的技术，全班没人能比。", "explanation": "这里应该用〈高超〉。强力多指力量大，不用来形容技术水平。"}, {"text": "她有强力的生命力，病了一个月还是很快好了。", "explanation": "这里应该用〈旺盛〉。强力不用来形容生命力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbe15dbf-f1e9-4fde-88dd-68c177b9c4ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88085, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "厨房里装了一台强力地抽油烟机。", "corrected_sentence": "厨房里装了一台强力的抽油烟机。", "error_description": "错误：“强力地抽油烟机”；正确：“强力的抽油烟机”。修饰名词用“的”，“地”只用在动词前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbe15dbf-f1e9-4fde-88dd-68c177b9c4ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88085, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他强力的拉开了大门。", "corrected_sentence": "他强力地拉开了大门。", "error_description": "错误：“强力的拉开”；正确：“强力地拉开”。修饰动词的状语要用“地”，不用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbe15dbf-f1e9-4fde-88dd-68c177b9c4ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88086, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "温和", "is_correct": true, "explanation": "温和与“强力”意思相反，指力度小、不激烈。"}, {"text": "聪明", "is_correct": false, "explanation": "聪明形容头脑好，与“强力”没有反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "干净指没有污垢，与“强力”没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮形容光线强，与“强力”没有反义关系。"}], "correct_answer": "温和", "explanations": {"温和": "温和与“强力”意思相反，指力度小、不激烈。", "聪明": "聪明形容头脑好，与“强力”没有反义关系。", "干净": "干净指没有污垢，与“强力”没有反义关系。", "明亮": "明亮形容光线强，与“强力”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbe15dbf-f1e9-4fde-88dd-68c177b9c4ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88086, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "温和", "is_correct": true, "explanation": "温和与“强力”意思相反，指力度小、不激烈。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚指清晰、明白，与“强力”没有反义关系。"}, {"text": "美丽", "is_correct": false, "explanation": "美丽形容外表好看，与“强力”没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "安静指不吵闹，与“强力”没有反义关系。"}], "correct_answer": "温和", "explanations": {"温和": "温和与“强力”意思相反，指力度小、不激烈。", "清楚": "清楚指清晰、明白，与“强力”没有反义关系。", "美丽": "美丽形容外表好看，与“强力”没有反义关系。", "安静": "安静指不吵闹，与“强力”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbe15dbf-f1e9-4fde-88dd-68c177b9c4ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88086, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "力量强大的；用力很大的。", "primary_collocate": null, "pronunciation": "qiáng lì", "ipa": "tɕʰjɑŋ˧˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "政府采取了强力措施。", "target_word": "强力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他给了对方一次强力的反击。", "target_word": "强力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察对犯罪行为进行强力打击。", "target_word": "强力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一脚强力射门，球进了。", "target_word": "强力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次改革得到了市民的强力支持。", "target_word": "强力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台吸尘器的吸力非常强力。", "target_word": "强力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生给他用了强力的药。", "target_word": "强力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商场推出了强力的促销活动。", "target_word": "强力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对手的强力进攻让我们很难挡住。", "target_word": "强力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司对迟到的员工采取了强力的管理措施。", "target_word": "强力", "complexity_tier": "T3", "furigana": "gōngsī duì chídào de yuángōng cǎiqǔ le qiánglì de guǎnlǐ cuòshī.", "sentence_source": "generated"}], "morphological_forms": [{"form": "強力", "label": "繁体"}], "register": "中性", "sense_fingerprint": "形容措施、行动、支持等力度大，或用力很大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43e9cbc-284b-4337-94c6-a22041e14477') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88086, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "湿润", "is_correct": false, "explanation": "语义：“湿润”形容空气或皮肤，与措施无关。"}, {"text": "强力", "is_correct": true, "explanation": "强力表示力度大，与“采取措施”的语境相符。"}, {"text": "可爱", "is_correct": false, "explanation": "搭配：“措施”不能说“可爱”。"}, {"text": "香甜", "is_correct": false, "explanation": "语义：“香甜”形容味道，与措施无关。"}], "explanations": {"湿润": "语义：“湿润”形容空气或皮肤，与措施无关。", "强力": "强力表示力度大，与“采取措施”的语境相符。", "可爱": "搭配：“措施”不能说“可爱”。", "香甜": "语义：“香甜”形容味道，与措施无关。"}, "sentence_index": 0, "correct_answer": "强力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她轻轻地拍着孩子，动作很强力。", "explanation": "这里应该用〈温柔〉。强力指用力大，不能用来形容轻轻拍孩子的动作。"}, {"text": "她强力地微笑着，让人安心。", "explanation": "这里应该用〈温和〉。强力指力度大，不用来形容微笑。"}, {"text": "这个问题很强力，大家讨论了一整天也没有结果。", "explanation": "这里应该用〈棘手〉。强力指力量大，不用来形容问题的难度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbe15dbf-f1e9-4fde-88dd-68c177b9c4ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88086, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冰冷", "is_correct": false, "explanation": "语义：“冰冷”形容温度或态度，不能用来修饰药。"}, {"text": "强力", "is_correct": true, "explanation": "强力表示药效强，与“医生用药”的语境相符。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：“热闹”形容场面，不说“热闹的药”。"}, {"text": "清脆", "is_correct": false, "explanation": "语义：“清脆”形容声音，不能用来修饰药。"}], "explanations": {"冰冷": "语义：“冰冷”形容温度或态度，不能用来修饰药。", "强力": "强力表示药效强，与“医生用药”的语境相符。", "热闹": "搭配：“热闹”形容场面，不说“热闹的药”。", "清脆": "语义：“清脆”形容声音，不能用来修饰药。"}, "sentence_index": 6, "correct_answer": "强力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家超市的商品种类很强力，几乎什么都能买到。", "explanation": "这里应该用〈丰富〉。强力指力量大，不用来形容商品种类的多少。"}, {"text": "这碗汤的分量很强力，一个人根本喝不完。", "explanation": "这里应该用〈足〉。强力指力度大，不用来形容分量。"}, {"text": "他今天的心情很强力，一整天都很开心。", "explanation": "这里应该用〈愉快〉。强力指力量大，不用来形容心情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbe15dbf-f1e9-4fde-88dd-68c177b9c4ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88086, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他强力的反击了对方。", "corrected_sentence": "他强力地反击了对方。", "error_description": "错误：“强力的反击”；正确：“强力地反击”。修饰动词“反击”的状语要用“地”，不用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbe15dbf-f1e9-4fde-88dd-68c177b9c4ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88086, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "警察强力的打击了这个犯罪团伙。", "corrected_sentence": "警察强力地打击了这个犯罪团伙。", "error_description": "错误：“强力的打击了”；正确：“强力地打击了”。修饰动词“打击”的状语要用“地”，不用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbe15dbf-f1e9-4fde-88dd-68c177b9c4ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
