INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88087, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "造就是用好办法培养人，让他变成有本事的人。", "primary_collocate": null, "pronunciation": "zào jiù", "ipa": "tsɑʊ̯⁵¹ tɕjoʊ̯⁵¹", "syllable_count": 2, "sentences": [{"text": "好老师能造就好学生。", "target_word": "造就", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "严格的训练造就了他。", "target_word": "造就", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校想造就更多有用的人才。", "target_word": "造就", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老师造就了一批优秀的医生。", "target_word": "造就", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "苦难也能造就一个坚强的人。", "target_word": "造就", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们用心造就下一代。", "target_word": "造就", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这所大学造就过许多科学家。", "target_word": "造就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老校长一生都在造就年轻人。", "target_word": "造就", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国家需要造就一批能干的工人。", "target_word": "造就", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "师傅把他造就成了一名好厨师。", "target_word": "造就", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "造就了", "label": "体标"}, {"form": "造就过", "label": "体标"}], "register": "书面", "sense_fingerprint": "培养人，使其成为有本事的人才", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d977b55-e838-4148-b0e4-160dae9a063e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88087, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "造就", "is_correct": true, "explanation": "造就（zào jiù）指培养人，使其成为有本事的人，是本词的读音和意思。"}, {"text": "早就", "is_correct": false, "explanation": "zǎo（第三声）与 zào（第四声）声调不同，意思是“已经”。"}, {"text": "造酒", "is_correct": false, "explanation": "jiǔ（第三声）与 jiù（第四声）声调不同，意思是酿造酒。"}, {"text": "照旧", "is_correct": false, "explanation": "zhào 与 zào 声调相同（第四声），仅声母不同（zh 与 z），意思是照旧、依旧。"}], "explanations": {"造就": "造就（zào jiù）指培养人，使其成为有本事的人，是本词的读音和意思。", "早就": "zǎo（第三声）与 zào（第四声）声调不同，意思是“已经”。", "造酒": "jiǔ（第三声）与 jiù（第四声）声调不同，意思是酿造酒。", "照旧": "zhào 与 zào 声调相同（第四声），仅声母不同（zh 与 z），意思是照旧、依旧。"}, "sentence_index": null, "correct_answer": "造就"}, "level_3": {"options": [{"text": "造就", "is_correct": true, "explanation": "造就指培养人才，与“好老师能……好学生”的语境相符。"}, {"text": "造成", "is_correct": false, "explanation": "搭配：“造成”多用于损失、后果等，不能说“造成好学生”。"}, {"text": "打扮", "is_correct": false, "explanation": "语义：打扮是把人装扮得好看，不能用来培养学生。"}, {"text": "欺负", "is_correct": false, "explanation": "语义：欺负与“好老师”的身份相矛盾，句子说的是培养学生。"}], "explanations": {"造就": "造就指培养人才，与“好老师能……好学生”的语境相符。", "造成": "搭配：“造成”多用于损失、后果等，不能说“造成好学生”。", "打扮": "语义：打扮是把人装扮得好看，不能用来培养学生。", "欺负": "语义：欺负与“好老师”的身份相矛盾，句子说的是培养学生。"}, "sentence_index": 0, "correct_answer": "造就"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工厂造就了很多汽车。", "explanation": "这里应该用〈制造〉。造就用于培养人才或促成成就，不能用于汽车这类产品。"}, {"text": "这场大雨造就了严重的损失。", "explanation": "这里应该用〈造成〉。造就多指培养人才或促成好的成就，不能跟“损失”搭配。"}, {"text": "工人们造就了一座大桥。", "explanation": "这里应该用〈建造〉。造就不用于建筑物，桥是修建出来的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a169f408-7f3b-4f23-b06f-b4e4a7f7c625') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88087, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "造就", "is_correct": true, "explanation": "造就指培养人才，与“这所大学……过许多科学家”的语境相符。"}, {"text": "雕刻", "is_correct": false, "explanation": "语义：雕刻是把材料刻成形状，不能用于培养科学家。"}, {"text": "出售", "is_correct": false, "explanation": "搭配：“出售”的对象是商品，不能说“出售科学家”。"}, {"text": "喷洒", "is_correct": false, "explanation": "语义：喷洒是把液体散开，不能施用于人。"}], "explanations": {"造就": "造就指培养人才，与“这所大学……过许多科学家”的语境相符。", "雕刻": "语义：雕刻是把材料刻成形状，不能用于培养科学家。", "出售": "搭配：“出售”的对象是商品，不能说“出售科学家”。", "喷洒": "语义：喷洒是把液体散开，不能施用于人。"}, "sentence_index": 6, "correct_answer": "造就"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司每年造就了五千台电脑。", "explanation": "这里应该用〈生产〉。造就用于培养人或促成成就，不用于批量生产的产品，电脑应说“生产”。"}, {"text": "我们小区造就了一个新的快递柜。", "explanation": "这里应该用〈安装〉。造就用于培养人或促成成就，不用于设施设备，快递柜应说“安装”。"}, {"text": "他用一个下午造就了一份报告。", "explanation": "这里应该用〈写〉。造就不用于文件，写报告要用“写”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a169f408-7f3b-4f23-b06f-b4e4a7f7c625') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88087, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这所学校造就了过很多优秀的工程师。", "corrected_sentence": "这所学校造就过很多优秀的工程师。", "error_description": "“了”和“过”同时出现了。错误形式是“造就了过”，正确形式是“造就过”，只用“过”表示曾经培养过。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a169f408-7f3b-4f23-b06f-b4e4a7f7c625') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88087, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这所学校造就了了一批有本事的年轻人。", "corrected_sentence": "这所学校造就了一批有本事的年轻人。", "error_description": "“了”用了两次。错误形式是“造就了了”，正确形式是“造就了”，“了”只需用一次，紧跟动词“造就”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a169f408-7f3b-4f23-b06f-b4e4a7f7c625') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
