INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88089, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "文件是写着重要事情的纸。", "primary_collocate": null, "pronunciation": "wén jiàn", "ipa": "wən˨˥ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "桌子上有一份重要的文件。", "target_word": "文件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理让我把文件交给他。", "target_word": "文件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些文件很重要，请放好。", "target_word": "文件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在办公室里看文件。", "target_word": "文件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你签完字的文件在这里。", "target_word": "文件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我把文件放进了红色的袋子里。", "target_word": "文件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份文件要明天交给老师。", "target_word": "文件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "文件上写着他的名字。", "target_word": "文件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在文件的最后一页签名。", "target_word": "文件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他找了半天，没找到那份文件。", "target_word": "文件", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "文件夹", "label": "复合词"}, {"form": "文件袋", "label": "复合词"}], "register": "中性", "sense_fingerprint": "写有重要内容的纸质材料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc845970-b582-4cbd-8bfb-d42e50e4b40f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88089, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "文件", "is_correct": true, "explanation": "正确答案：写着重要事情的纸，读作 wén jiàn。"}, {"text": "稳健", "is_correct": false, "explanation": "wěn（第三声）与 wén（第二声）声调不同，意思是稳健（稳当可靠）。"}, {"text": "文教", "is_correct": false, "explanation": "jiào 与 jiàn 韵尾不同（o 与 n），意思是文化教育。"}, {"text": "文献", "is_correct": false, "explanation": "xiàn（第四声）与 jiàn（第四声）声母不同（x 与 j），意思是文献（书面资料）。"}], "explanations": {"文件": "正确答案：写着重要事情的纸，读作 wén jiàn。", "稳健": "wěn（第三声）与 wén（第二声）声调不同，意思是稳健（稳当可靠）。", "文教": "jiào 与 jiàn 韵尾不同（o 与 n），意思是文化教育。", "文献": "xiàn（第四声）与 jiàn（第四声）声母不同（x 与 j），意思是文献（书面资料）。"}, "sentence_index": null, "correct_answer": "文件"}, "level_3": {"options": [{"text": "文件", "is_correct": true, "explanation": "正确答案：“一份重要的文件”，指写着重要事情的纸。"}, {"text": "城市", "is_correct": false, "explanation": "搭配：“份”用于文件、报纸这类可以按份计的东西，不能计量城市；桌子上也放不下城市。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海不能放在桌子上，与“桌子上有”的语境矛盾。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“一份”不能计量天气，“重要的天气”也不成立。"}], "explanations": {"文件": "正确答案：“一份重要的文件”，指写着重要事情的纸。", "城市": "搭配：“份”用于文件、报纸这类可以按份计的东西，不能计量城市；桌子上也放不下城市。", "大海": "语义：大海不能放在桌子上，与“桌子上有”的语境矛盾。", "天气": "搭配：“一份”不能计量天气，“重要的天气”也不成立。"}, "sentence_index": 0, "correct_answer": "文件"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份文件很甜。", "explanation": "这里应该用〈甘蔗〉。“甜”用于甘蔗、水果等食物，“文件”不能用“甜”形容。"}, {"text": "这个文件很好听。", "explanation": "这里应该用〈故事〉。“故事”才能“好听”，“文件”不能用“好听”形容。"}, {"text": "这个文件很辣。", "explanation": "这里应该用〈菜〉。“辣”用于菜、辣椒等食物，“文件”不能用“辣”形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fbc760a-f0a4-4dab-8306-53e9ab979a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88089, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "文件", "is_correct": true, "explanation": "正确答案：“这份文件要明天交给老师”，指纸质的材料。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不能被交给老师，与“交给老师”的语境矛盾。"}, {"text": "小猫", "is_correct": false, "explanation": "搭配：“份”用于纸质材料，不能计量小猫。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园不能交给老师，句子无法成立。"}], "explanations": {"文件": "正确答案：“这份文件要明天交给老师”，指纸质的材料。", "月亮": "语义：月亮不能被交给老师，与“交给老师”的语境矛盾。", "小猫": "搭配：“份”用于纸质材料，不能计量小猫。", "花园": "语义：花园不能交给老师，句子无法成立。"}, "sentence_index": 6, "correct_answer": "文件"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个文件要在月底前付清。", "explanation": "这里应该用〈账单〉。“付清”用于账单、欠款，“文件”不能付清。"}, {"text": "这张文件要去冲洗。", "explanation": "这里应该用〈照片〉。“冲洗”用于照片，“文件”不需要也不能冲洗。"}, {"text": "这里的文件很壮观。", "explanation": "这里应该用〈瀑布〉。“壮观”用于瀑布、山川等景象，“文件”不能用“壮观”形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fbc760a-f0a4-4dab-8306-53e9ab979a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88089, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把那只文件带回了家。", "corrected_sentence": "他把那份文件带回了家。", "error_description": "量词错误：“文件”应用量词“份”，“只”用于动物，不能用于文件。正确说法是“那份文件”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fbc760a-f0a4-4dab-8306-53e9ab979a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88089, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我以前看过这些文件们。", "corrected_sentence": "我以前看过这些文件。", "error_description": "词缀错误：“文件”后面不加“们”，应说“这些文件”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fbc760a-f0a4-4dab-8306-53e9ab979a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
