INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88090, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "机关团体之间传达或处理公事的书面材料。", "primary_collocate": null, "pronunciation": "wén jiàn", "ipa": "wən˨˥ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "市政府发了一份新文件。", "target_word": "文件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份文件通知大家下周开会。", "target_word": "文件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校收到了教育局的文件。", "target_word": "文件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司的文件要由经理签字。", "target_word": "文件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "文件里写明了新的规定。", "target_word": "文件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "秘书正在整理今年的文件。", "target_word": "文件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "各部门要认真学习这份文件。", "target_word": "文件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "文件规定，工作人员必须准时上班。", "target_word": "文件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个文件是上个月发给各单位的。", "target_word": "文件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他负责保管公司的重要文件。", "target_word": "文件", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "文件夹", "label": "复合词"}, {"form": "红头文件", "label": "复合词"}], "register": "书面", "sense_fingerprint": "机关单位用来传达、处理公事的公文", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc845970-b582-4cbd-8bfb-d42e50e4b40f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88090, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "文件", "is_correct": true, "explanation": "正确答案：机关之间传达或处理公事的书面材料，读作 wén jiàn。"}, {"text": "稳健", "is_correct": false, "explanation": "wěn（第三声）与 wén（第二声）声调不同，意思是稳健（稳当可靠）。"}, {"text": "文教", "is_correct": false, "explanation": "jiào 与 jiàn 韵尾不同（o 与 n），意思是文化教育。"}, {"text": "文献", "is_correct": false, "explanation": "xiàn（第四声）与 jiàn（第四声）声母不同（x 与 j），意思是文献（书面资料）。"}], "explanations": {"文件": "正确答案：机关之间传达或处理公事的书面材料，读作 wén jiàn。", "稳健": "wěn（第三声）与 wén（第二声）声调不同，意思是稳健（稳当可靠）。", "文教": "jiào 与 jiàn 韵尾不同（o 与 n），意思是文化教育。", "文献": "xiàn（第四声）与 jiàn（第四声）声母不同（x 与 j），意思是文献（书面资料）。"}, "sentence_index": null, "correct_answer": "文件"}, "level_3": {"options": [{"text": "文件", "is_correct": true, "explanation": "正确答案：“发了一份新文件”，指机关发出的公文。"}, {"text": "城市", "is_correct": false, "explanation": "语义：市政府不能发出一座城市，“发”后不能接城市。"}, {"text": "花园", "is_correct": false, "explanation": "语义：政府发出的不能是花园，句子不成立。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“新”和“一份”都不能搭配“天气”，“发天气”也不成立。"}], "explanations": {"文件": "正确答案：“发了一份新文件”，指机关发出的公文。", "城市": "语义：市政府不能发出一座城市，“发”后不能接城市。", "花园": "语义：政府发出的不能是花园，句子不成立。", "天气": "搭配：“新”和“一份”都不能搭配“天气”，“发天气”也不成立。"}, "sentence_index": 0, "correct_answer": "文件"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个文件很好玩。", "explanation": "这里应该用〈游戏〉。“游戏”才能“好玩”，“文件”是机关之间传达公事的书面材料，不能用“好玩”形容。"}, {"text": "这种文件很辣。", "explanation": "这里应该用〈辣椒〉。“辣”用于辣椒、菜等食物，“文件”不能用“辣”形容。"}, {"text": "院子里的文件长得很高。", "explanation": "这里应该用〈树〉。“树”才会“长得很高”，“文件”不会生长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fbc760a-f0a4-4dab-8306-53e9ab979a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88090, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "文件", "is_correct": true, "explanation": "正确答案：“学习这份文件”，指机关下发的公文。"}, {"text": "大海", "is_correct": false, "explanation": "语义：“学习”的对象应是文件或知识，大海不能被学习。"}, {"text": "小猫", "is_correct": false, "explanation": "搭配：“份”不能计量小猫，“学习小猫”也不成立。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不能被学习，句子无法成立。"}], "explanations": {"文件": "正确答案：“学习这份文件”，指机关下发的公文。", "大海": "语义：“学习”的对象应是文件或知识，大海不能被学习。", "小猫": "搭配：“份”不能计量小猫，“学习小猫”也不成立。", "月亮": "语义：月亮不能被学习，句子无法成立。"}, "sentence_index": 6, "correct_answer": "文件"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈煮的文件很咸。", "explanation": "这里应该用〈汤〉。“咸”用于汤、菜等食物，“文件”不能用“咸”形容。"}, {"text": "这种文件很甜。", "explanation": "这里应该用〈牛奶〉。“甜”用于牛奶、糖等食物，“文件”不能用“甜”形容。"}, {"text": "这个文件很响亮。", "explanation": "这里应该用〈声音〉。“响亮”用于声音，“文件”不能用“响亮”形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fbc760a-f0a4-4dab-8306-53e9ab979a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88090, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "秘书把这条文件送到了经理办公室。", "corrected_sentence": "秘书把这份文件送到了经理办公室。", "error_description": "量词错误：“文件”应用量词“份”，“条”用于细长的东西或消息，不能修饰文件。应说“这份文件”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fbc760a-f0a4-4dab-8306-53e9ab979a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88090, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们收到了一只新文件。", "corrected_sentence": "我们收到了一份新文件。", "error_description": "量词错误：“文件”应用量词“份”，“只”用于动物或成对东西中的一个，不能用于文件。应说“一份新文件”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fbc760a-f0a4-4dab-8306-53e9ab979a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
