INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88091, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "心想是在心里想，没有说出来。", "primary_collocate": null, "pronunciation": "xīn xiǎng", "ipa": "ɕin˥ ɕjɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他没开口，心想：这件事不能让妈妈知道。", "target_word": "心想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我嘴上没说，心想他今天怎么这么高兴。", "target_word": "心想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看着空空的冰箱，她心想该去买菜了。", "target_word": "心想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟低着头，心想这次考试肯定完了。", "target_word": "心想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我笑了笑，没回答，心想他说得也有道理。", "target_word": "心想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板没出声，心想这个价钱太高了。", "target_word": "心想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "站在门口，小李心想：我是不是忘了带钥匙？", "target_word": "心想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她没告诉别人，心想明天一定要早点儿起床。", "target_word": "心想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶看着照片，心想孙子现在在做什么呢。", "target_word": "心想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没告诉他，心想让他自己发现吧。", "target_word": "心想", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "想法只在心里，没有说出口", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52f58a29-0843-4b18-9594-88ac0b975df0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88091, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "心想", "is_correct": true, "explanation": "正确答案。“心想”表示心里想，没有说出来，与“没开口”相符。"}, {"text": "说", "is_correct": false, "explanation": "语义：“没开口”与“说”矛盾，句中要表示的是没有说出来的想法。"}, {"text": "喊", "is_correct": false, "explanation": "语义：“喊”是大声说出口，与“没开口”矛盾。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”接的是歌词，不能接“这件事不能让妈妈知道”这样的陈述句。"}], "explanations": {"心想": "正确答案。“心想”表示心里想，没有说出来，与“没开口”相符。", "说": "语义：“没开口”与“说”矛盾，句中要表示的是没有说出来的想法。", "喊": "语义：“喊”是大声说出口，与“没开口”矛盾。", "唱": "搭配：“唱”接的是歌词，不能接“这件事不能让妈妈知道”这样的陈述句。"}, "sentence_index": 0, "correct_answer": "心想"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "弟弟大声心想：这次考试肯定完了。", "explanation": "〈心想〉只表示心里想，不出声，不能与〈大声〉搭配。要说出口应用〈说〉。"}, {"text": "弟弟对妈妈心想：这次考试肯定完了。", "explanation": "〈心想〉不带对象，不能对某人进行。对妈妈说话应用〈对……说〉。"}, {"text": "弟弟和朋友心想出了一个办法。", "explanation": "这里应该用〈商量〉。〈心想〉是暗自想，不能和朋友一起进行；一起想办法要用〈商量〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca9ddb30-e43a-4c63-956b-9f576adce309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88091, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "心想", "is_correct": true, "explanation": "正确答案。“心想”表示心里想，没有说出口，后接想法的内容，符合句意。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”是对人表示接待，无法接“我是不是忘了带钥匙”这样的问句。"}, {"text": "大笑", "is_correct": false, "explanation": "配价：“大笑”是不及物动词，不能带后面的内容句。"}, {"text": "出发", "is_correct": false, "explanation": "语义：“出发”指动身离开，与“站在门口想钥匙”的语境不合。"}], "explanations": {"心想": "正确答案。“心想”表示心里想，没有说出口，后接想法的内容，符合句意。", "欢迎": "语义：“欢迎”是对人表示接待，无法接“我是不是忘了带钥匙”这样的问句。", "大笑": "配价：“大笑”是不及物动词，不能带后面的内容句。", "出发": "语义：“出发”指动身离开，与“站在门口想钥匙”的语境不合。"}, "sentence_index": 6, "correct_answer": "心想"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我对他心想：让他自己发现吧。", "explanation": "〈心想〉不带对象，不能对某人进行。对他说话应用〈对……说〉。"}, {"text": "我和同学心想出一个方案。", "explanation": "这里应该用〈商量〉。〈心想〉只能暗自想，不能和同学一起进行；一起想办法要用〈商量〉。"}, {"text": "我心想他：让他自己发现吧。", "explanation": "〈心想〉不能带人作宾语。劝别人应用〈劝〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca9ddb30-e43a-4c63-956b-9f576adce309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
