INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88092, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "心里想；暗自思量。", "primary_collocate": null, "pronunciation": "xīn xiǎng", "ipa": "ɕin˥ ɕjɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他看了看天，没说话，心想：要下雨了。", "target_word": "心想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我心想，他一定不会来了。", "target_word": "心想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈看着我，心想孩子长大了。", "target_word": "心想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师没出声，心想这个学生真聪明。", "target_word": "心想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我尝了一口，心想：这个菜怎么这么咸？", "target_word": "心想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他心想，现在走还来得及。", "target_word": "心想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到那么多人，我心想今天进不去了。", "target_word": "心想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王心想：我得快点儿跑才行。", "target_word": "心想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机看了看路，心想前面可能堵车了。", "target_word": "心想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到敲门声，他心想会是谁呢。", "target_word": "心想", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "心里暗自想，不说出口，后面常接想法的内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52f58a29-0843-4b18-9594-88ac0b975df0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
