INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88092, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "心想", "is_correct": true, "explanation": "正确答案。“心想”表示心里暗自想，后面接想法的内容，符合句意。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”是对人表示接待，不能接“今天进不去了”这样的内容。"}, {"text": "拒绝", "is_correct": false, "explanation": "配价：“拒绝”要求接一个具体的对象，不能接一个想法性的句子，句意不通。"}, {"text": "出发", "is_correct": false, "explanation": "语义：“出发”指动身离开，与“进不去”的语境不合。"}], "explanations": {"心想": "正确答案。“心想”表示心里暗自想，后面接想法的内容，符合句意。", "欢迎": "语义：“欢迎”是对人表示接待，不能接“今天进不去了”这样的内容。", "拒绝": "配价：“拒绝”要求接一个具体的对象，不能接一个想法性的句子，句意不通。", "出发": "语义：“出发”指动身离开，与“进不去”的语境不合。"}, "sentence_index": 6, "correct_answer": "心想"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "听到敲门声，他跟同事心想出一个方案。", "explanation": "这里应该用〈商量〉。〈心想〉是暗自想，不能和同事一起进行；一起想办法要用〈商量〉。"}, {"text": "听到敲门声，他走过去对我心想：会是谁呢？", "explanation": "〈心想〉不带对象，不能对某人进行；对人说话要用〈对……说〉。"}, {"text": "听到敲门声，他大声心想：会是谁呢。", "explanation": "〈心想〉只表示暗自想，不出声。这里表示出声，应用〈喊〉，不能用〈心想〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca9ddb30-e43a-4c63-956b-9f576adce309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
