INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88094, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在棋局中迫使对方接受和棋。", "primary_collocate": null, "pronunciation": "bī hé", "ipa": "pi˥ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "老张在比赛中逼和了对手。", "target_word": "逼和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红方没有赢，只好逼和黑方。", "target_word": "逼和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他下棋时一直想逼和对方。", "target_word": "逼和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对手太强，我只能努力逼和他。", "target_word": "逼和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李用这个办法逼和了老师。", "target_word": "逼和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这盘棋是他逼和的，不是我赢的。", "target_word": "逼和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国际象棋里，怎样逼和对手呢？", "target_word": "逼和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他连输三局，第四局终于逼和了对手。", "target_word": "逼和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥把对手逼和了，大家都很高兴。", "target_word": "逼和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下棋时，他最爱逼和比自己强的人。", "target_word": "逼和", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "逼和了", "label": "体标（了）"}, {"form": "逼和过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "下棋时迫使对手接受和棋", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ca57c2-ac8c-47f7-b168-f786db53d8e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88094, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "逼和", "is_correct": true, "explanation": "正确：逼和指迫使对手下成和棋，与“比赛中”的语境相合。"}, {"text": "抄袭", "is_correct": false, "explanation": "语义：「抄袭」指照抄别人的作品，与比赛中的对手无关。"}, {"text": "救活", "is_correct": false, "explanation": "搭配：「救活」用于人或生命，不能说在比赛中救活对手。"}, {"text": "逮捕", "is_correct": false, "explanation": "语义：「逮捕」是公安机关拘捕嫌疑人，与比赛无关。"}], "explanations": {"逼和": "正确：逼和指迫使对手下成和棋，与“比赛中”的语境相合。", "抄袭": "语义：「抄袭」指照抄别人的作品，与比赛中的对手无关。", "救活": "搭配：「救活」用于人或生命，不能说在比赛中救活对手。", "逮捕": "语义：「逮捕」是公安机关拘捕嫌疑人，与比赛无关。"}, "sentence_index": 0, "correct_answer": "逼和"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "调解人员把吵架的两个孩子逼和了。", "explanation": "「逼和」只用于下棋，指迫使对手接受和棋；孩子吵架后言归于好应说〈和好〉。"}, {"text": "他一气之下，把棋盘逼和了。", "explanation": "「逼和」的对象是对手，不是棋盘；把棋盘翻过来应说〈掀翻〉。"}, {"text": "他一步步逼和对手的阵地。", "explanation": "「逼和」指在棋局中迫使对方接受和棋，不能用于阵地；向对方阵地靠近应说〈逼近〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccc5e7bc-2959-4a75-819f-2881da3639e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88094, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "逼和", "is_correct": true, "explanation": "正确：问如何迫使对手下成和棋，与国际象棋的语境相合。"}, {"text": "雇佣", "is_correct": false, "explanation": "语义：「雇佣」指出钱请人做事，与下棋的语境不合。"}, {"text": "收养", "is_correct": false, "explanation": "语义：「收养」指领养孩子，与国际象棋无关。"}, {"text": "喂饱", "is_correct": false, "explanation": "搭配：「喂饱」说的是让人吃饱，不能用来对付棋手。"}], "explanations": {"逼和": "正确：问如何迫使对手下成和棋，与国际象棋的语境相合。", "雇佣": "语义：「雇佣」指出钱请人做事，与下棋的语境不合。", "收养": "语义：「收养」指领养孩子，与国际象棋无关。", "喂饱": "搭配：「喂饱」说的是让人吃饱，不能用来对付棋手。"}, "sentence_index": 6, "correct_answer": "逼和"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我终于逼和了那个比我强的人，他输得心服口服。", "explanation": "「逼和」指迫使对方和棋，不是战胜对方；这里说对方“输”，应说〈击败〉。"}, {"text": "他每天都逼和家里的孩子去学习。", "explanation": "「逼和」只用于下棋，不能用于督促孩子学习；这里应说〈逼迫〉。"}, {"text": "我把他的袜子逼和了，他很生气。", "explanation": "「逼和」的对象是对手，不能用于袜子；这里应说〈洗〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccc5e7bc-2959-4a75-819f-2881da3639e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88094, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明天的比赛，他一定要逼和了对手。", "corrected_sentence": "明天的比赛，他一定要逼和对手。", "error_description": "体标错误：“一定要”表示还没发生的打算，动词后不能加“了”，应说“一定要逼和对手”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccc5e7bc-2959-4a75-819f-2881da3639e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88094, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他连输两局，第三局才勉强把逼和对手。", "corrected_sentence": "他连输两局，第三局才勉强逼和对手。", "error_description": "把字句误用：「把」后须接受事成分再接动词，「把逼和对手」不成立，应删去「把」，说「勉强逼和对手」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccc5e7bc-2959-4a75-819f-2881da3639e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
