INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88096, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "这一次；本次。", "primary_collocate": null, "pronunciation": "cǐ cì", "ipa": "/tsʰɨ˨˩˦ tsʰɨ˥˩/", "syllable_count": 2, "sentences": [{"text": "此次考试一共有三个部分。", "target_word": "此次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此次会议在北京举行。", "target_word": "此次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此次活动很成功。", "target_word": "此次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谢谢大家参加此次比赛。", "target_word": "此次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此次旅行我们去了三个城市。", "target_word": "此次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此次的作业比上次难。", "target_word": "此次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师对此次考试很满意。", "target_word": "此次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此次出差，他带了两个箱子。", "target_word": "此次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此次比赛的第一名是小王。", "target_word": "此次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此次来中国，我想学做饭。", "target_word": "此次", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "指这一次、本次（书面）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4e807c9-c27f-4438-82f2-649eff8684c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88096, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "此次", "is_correct": true, "explanation": "正确。“此次”指这一次，即目标词。"}, {"text": "此字", "is_correct": false, "explanation": "“此字”与“此次”第二个音节声母不同（z 与 c），声调相同，意思是这个字，不指这一次。"}, {"text": "此词", "is_correct": false, "explanation": "“此词”与“此次”第二个音节只差声调（cí 与 cì），意思是这个词，不指这一次。"}, {"text": "此事", "is_correct": false, "explanation": "“此事”与“此次”第二个音节声母不同（sh 与 c），意思是这件事，不指这一次。"}], "explanations": {"此次": "正确。“此次”指这一次，即目标词。", "此字": "“此字”与“此次”第二个音节声母不同（z 与 c），声调相同，意思是这个字，不指这一次。", "此词": "“此词”与“此次”第二个音节只差声调（cí 与 cì），意思是这个词，不指这一次。", "此事": "“此事”与“此次”第二个音节声母不同（sh 与 c），意思是这件事，不指这一次。"}, "sentence_index": null, "correct_answer": "此次"}, "level_3": {"options": [{"text": "此次", "is_correct": true, "explanation": "正确。“此次考试”指这一次的考试，与句中“一共有三个部分”相符。"}, {"text": "此人", "is_correct": false, "explanation": "语义：“此人”指某个人，不能修饰“考试”，句子说的是考试的构成。"}, {"text": "此物", "is_correct": false, "explanation": "语义：“此物”指事物，不能修饰“考试”，句子说的是考试的构成。"}, {"text": "本人", "is_correct": false, "explanation": "语义：“本人”指说话人自己，不能修饰“考试”，句意不通。"}], "explanations": {"此次": "正确。“此次考试”指这一次的考试，与句中“一共有三个部分”相符。", "此人": "语义：“此人”指某个人，不能修饰“考试”，句子说的是考试的构成。", "此物": "语义：“此物”指事物，不能修饰“考试”，句子说的是考试的构成。", "本人": "语义：“本人”指说话人自己，不能修饰“考试”，句意不通。"}, "sentence_index": 0, "correct_answer": "此次"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "此次我正在吃饭。", "explanation": "这里应该用〈此时〉。“此次”指一次活动或事件，不表示当下的时刻。"}, {"text": "此次的房间很大，大家都很喜欢。", "explanation": "这里应该用〈这间〉。“此次”只修饰活动、事件，修饰房间这类具体事物要用“这间”。"}, {"text": "此次我们去年去了北京。", "explanation": "这里应该用〈上次〉。“此次”指当前这一次，指过去的一次要说“上次”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '699b38f6-7f64-4e1a-858e-e74385b56d51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88096, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "此次", "is_correct": true, "explanation": "正确。“对此次考试很满意”指对这一次考试满意，与句意相符。"}, {"text": "此刻", "is_correct": false, "explanation": "语义：“此刻”指当下的时刻，不能用来指一次具体的考试。"}, {"text": "当初", "is_correct": false, "explanation": "体貌：“当初”指过去的起始时间，与句中对已经进行的考试的评价不符。"}, {"text": "下次", "is_correct": false, "explanation": "语义：“下次”指尚未发生的考试，老师不可能对它表示满意。"}], "explanations": {"此次": "正确。“对此次考试很满意”指对这一次考试满意，与句意相符。", "此刻": "语义：“此刻”指当下的时刻，不能用来指一次具体的考试。", "当初": "体貌：“当初”指过去的起始时间，与句中对已经进行的考试的评价不符。", "下次": "语义：“下次”指尚未发生的考试，老师不可能对它表示满意。"}, "sentence_index": 6, "correct_answer": "此次"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "咱们此次去吃火锅吧！", "explanation": "语域：“此次”是书面语，用于正式场合；口语邀请里应说“这次”，这里的用法不对。"}, {"text": "此次的书包很重，我背不动。", "explanation": "这里应该用〈这个〉。“此次”只修饰活动、事件，修饰书包这类物品要用“这个”。"}, {"text": "此次我去年就到了中国。", "explanation": "这里应该用〈上次〉。“此次”指当前这一次，指过去的一次要说“上次”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '699b38f6-7f64-4e1a-858e-e74385b56d51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88096, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一个此次会议很重要，请大家准时参加。", "corrected_sentence": "此次会议很重要，请大家准时参加。", "error_description": "错误：“此次”已含“这一次”的指示意义，前面不能再加“一个”。应说“此次会议”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '699b38f6-7f64-4e1a-858e-e74385b56d51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88096, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同学们对那此次活动很满意。", "corrected_sentence": "同学们对此次活动很满意。", "error_description": "错误：“此次”已含指示意义，前面不能再加“那”。两个指示词不能并用，应说“对此次活动很满意”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '699b38f6-7f64-4e1a-858e-e74385b56d51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88098, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "昨天", "is_correct": true, "explanation": "正确：“昨天”与“明天”是时间方向相反的一对反义词。"}, {"text": "去年", "is_correct": false, "explanation": "“去年”与“明天”不构成反义关系，它只指过去的一年。"}, {"text": "夜晚", "is_correct": false, "explanation": "“夜晚”与“明天”不构成反义关系，它指一天中的时段。"}, {"text": "星期", "is_correct": false, "explanation": "“星期”与“明天”不构成反义关系，它指一周的单位。"}], "correct_answer": "昨天", "explanations": {"昨天": "正确：“昨天”与“明天”是时间方向相反的一对反义词。", "去年": "“去年”与“明天”不构成反义关系，它只指过去的一年。", "夜晚": "“夜晚”与“明天”不构成反义关系，它指一天中的时段。", "星期": "“星期”与“明天”不构成反义关系，它指一周的单位。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08bae48c-bdbd-4008-9ada-ec916504e82b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88098, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "昨天", "is_correct": true, "explanation": "正确：“昨天”与“明天”是时间方向相反的一对反义词。"}, {"text": "早晨", "is_correct": false, "explanation": "“早晨”与“明天”不构成反义关系，它指一天中的时段。"}, {"text": "下午", "is_correct": false, "explanation": "“下午”与“明天”不构成反义关系，它指一天中的时段。"}, {"text": "春天", "is_correct": false, "explanation": "“春天”与“明天”不构成反义关系，它指一个季节。"}], "correct_answer": "昨天", "explanations": {"昨天": "正确：“昨天”与“明天”是时间方向相反的一对反义词。", "早晨": "“早晨”与“明天”不构成反义关系，它指一天中的时段。", "下午": "“下午”与“明天”不构成反义关系，它指一天中的时段。", "春天": "“春天”与“明天”不构成反义关系，它指一个季节。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08bae48c-bdbd-4008-9ada-ec916504e82b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88098, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "今天的下一天。", "primary_collocate": null, "pronunciation": "míng tiān", "ipa": "miŋ˧˥ tʰjɛn˥", "syllable_count": 2, "sentences": [{"text": "今天是五号，明天是六号。", "target_word": "明天", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "明天我要去医院看奶奶。", "target_word": "明天", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "明天早上七点，我们在校门口见。", "target_word": "明天", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气预报说，明天会下大雨。", "target_word": "明天", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你明天有时间吗？", "target_word": "明天", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他明天坐飞机去上海。", "target_word": "明天", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "明天是妈妈的生日，我想买花。", "target_word": "明天", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "作业明天再写，今天太累了。", "target_word": "明天", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "明天的会议改到下午三点了。", "target_word": "明天", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我今天去买菜，明天去买衣服。", "target_word": "明天", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "时间名词，今天之后的那一天", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7334b5cb-6336-4b25-86db-f1f85bdb5c03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88098, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "明天", "is_correct": true, "explanation": "正确：“明天”指今天之后的那一天，与“今天是五号”形成对比。"}, {"text": "去年", "is_correct": false, "explanation": "语义：“去年”指年份，不能与日期“六号”对应。"}, {"text": "上午", "is_correct": false, "explanation": "搭配：“是……号”搭配的是日期，“上午”不能用来指号数。"}, {"text": "夜晚", "is_correct": false, "explanation": "语义：“夜晚”指一天中的时段，不能指某个日期。"}], "explanations": {"明天": "正确：“明天”指今天之后的那一天，与“今天是五号”形成对比。", "去年": "语义：“去年”指年份，不能与日期“六号”对应。", "上午": "搭配：“是……号”搭配的是日期，“上午”不能用来指号数。", "夜晚": "语义：“夜晚”指一天中的时段，不能指某个日期。"}, "sentence_index": 0, "correct_answer": "明天"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每个明天都去跑步。", "explanation": "这里应该用〈每天〉。“明天”指今天之后的那一天，只有一个，不能用“每个”表示重复。"}, {"text": "我们给明天打了个电话。", "explanation": "这里“明天”是时间，不是人，不能接电话，应该给朋友打电话。“明天”只表示今天之后的那一天。"}, {"text": "我想吃一碗明天。", "explanation": "这里“明天”是时间，不是食物，不能用量词“碗”计量，它不能被吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08bae48c-bdbd-4008-9ada-ec916504e82b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88098, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "明天", "is_correct": true, "explanation": "正确：“明天”作主语，表示生日的那一天，与句意相合。"}, {"text": "星期", "is_correct": false, "explanation": "搭配：“星期”要和数字连用（如星期一），不能作为生日的日期。"}, {"text": "早晨", "is_correct": false, "explanation": "语义：“早晨”指一天的时段，不能指生日所在的那一天。"}, {"text": "下午", "is_correct": false, "explanation": "语义：“下午”指一天的时段，不能指生日所在的那一天。"}], "explanations": {"明天": "正确：“明天”作主语，表示生日的那一天，与句意相合。", "星期": "搭配：“星期”要和数字连用（如星期一），不能作为生日的日期。", "早晨": "语义：“早晨”指一天的时段，不能指生日所在的那一天。", "下午": "语义：“下午”指一天的时段，不能指生日所在的那一天。"}, "sentence_index": 6, "correct_answer": "明天"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我想用明天换一辆自行车。", "explanation": "这里“明天”是时间，不是可以交换的物品，不能用来换自行车。"}, {"text": "我每天都在明天里等你。", "explanation": "“明天”是时间，不是地点，不能用“在……里”。这里应该说“等到明天”。"}, {"text": "他把明天送给了朋友。", "explanation": "“明天”是时间名词，不能作为物品送人。“把……送给”只能用于具体的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08bae48c-bdbd-4008-9ada-ec916504e82b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88098, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他明天的去上海出差。", "corrected_sentence": "他明天去上海出差。", "error_description": "错误形式：“明天”后多加“的”，写成“明天的去”，“的”使“明天”变成修饰语，句子不通。正确形式：“他明天去上海出差”，“明天”直接作时间状语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08bae48c-bdbd-4008-9ada-ec916504e82b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88098, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师明天了要检查作业。", "corrected_sentence": "老师明天要检查作业。", "error_description": "错误形式：“明天”后加了“了”，写成“明天了”。正确形式：“老师明天要检查作业”，“明天”是时间词，不能带“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08bae48c-bdbd-4008-9ada-ec916504e82b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
