INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88099, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "戏曲是一边唱一边演的老式戏，像京剧。", "primary_collocate": null, "pronunciation": "xì qǔ", "ipa": "ɕi˥˩ tɕʰy˨˩˦", "syllable_count": 2, "sentences": [{"text": "爷爷喜欢听戏曲，也爱看京剧。", "target_word": "戏曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "戏曲是一边唱一边演的。", "target_word": "戏曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末公园里有老人在听戏曲。", "target_word": "戏曲", "complexity_tier": "T3", "furigana": "zhōu mò gōng yuán lǐ yǒu lǎo rén zài tīng xì qǔ", "sentence_source": "generated"}, {"text": "奶奶每天晚上都看戏曲频道。", "target_word": "戏曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "京剧是中国有名的戏曲。", "target_word": "戏曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人很少看戏曲，更喜欢流行歌。", "target_word": "戏曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小学戏曲，现在是演员。", "target_word": "戏曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "戏曲里的人穿着漂亮的衣服。", "target_word": "戏曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我听不懂戏曲，但是觉得很好看。", "target_word": "戏曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人们坐在一起听戏曲，很开心。", "target_word": "戏曲", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "戲曲", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一边唱一边演的传统老式戏，如京剧", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a96547-d1a2-4444-8d6e-1252fc20d0d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88099, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "戏曲", "is_correct": true, "explanation": "正确。“戏曲”指一边唱一边演的传统戏，与“听”搭配，符合句意。"}, {"text": "报纸", "is_correct": false, "explanation": "搭配：“听”用于声音类的表演，报纸是印刷品，不能说“听报纸”。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是学生要完成的功课，不是可以欣赏的表演，与“喜欢听”不合。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是学习用书，不是可以听的内容，与后半句“也爱看京剧”的文艺欣赏语境不合。"}], "explanations": {"戏曲": "正确。“戏曲”指一边唱一边演的传统戏，与“听”搭配，符合句意。", "报纸": "搭配：“听”用于声音类的表演，报纸是印刷品，不能说“听报纸”。", "作业": "语义：作业是学生要完成的功课，不是可以欣赏的表演，与“喜欢听”不合。", "课本": "语义：课本是学习用书，不是可以听的内容，与后半句“也爱看京剧”的文艺欣赏语境不合。"}, "sentence_index": 0, "correct_answer": "戏曲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天晚上在茶馆里说戏曲，大家都很爱听。", "explanation": "这里应该用〈评书〉。戏曲以唱和演为主，不能用“说”；说的是评书、相声这类曲艺。"}, {"text": "他在剧院里演唱意大利戏曲，观众鼓掌很久。", "explanation": "这里应该用〈歌剧〉。戏曲特指中国传统的戏剧形式，西方的歌剧不能叫戏曲。"}, {"text": "这部戏曲不唱歌，只用说白，观众很喜欢。", "explanation": "这里应该用〈话剧〉。戏曲以唱为主，话剧只用说白，这里不能用“戏曲”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88099, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "戏曲", "is_correct": true, "explanation": "正确。“学戏曲”是学习这门传统艺术，与“演员”的职业相符。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“学”不直接接“汽车”，应说“学开车”或“学修车”。"}, {"text": "报纸", "is_correct": false, "explanation": "搭配：“学报纸”不成立，报纸是读物，不是要学的技艺。"}, {"text": "财务", "is_correct": false, "explanation": "语义：财务是会计类工作，与句末“现在是演员”所指的表演职业无关，句意矛盾。"}], "explanations": {"戏曲": "正确。“学戏曲”是学习这门传统艺术，与“演员”的职业相符。", "汽车": "搭配：“学”不直接接“汽车”，应说“学开车”或“学修车”。", "报纸": "搭配：“学报纸”不成立，报纸是读物，不是要学的技艺。", "财务": "语义：财务是会计类工作，与句末“现在是演员”所指的表演职业无关，句意矛盾。"}, "sentence_index": 6, "correct_answer": "戏曲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在家里跳戏曲，跳得很好看。", "explanation": "这里应该用〈舞〉。“跳”配舞蹈，戏曲要靠唱和演，不能用“跳”。"}, {"text": "他会弹戏曲，弹得很好听。", "explanation": "这里应该用〈琵琶〉。“弹”配琵琶等乐器，戏曲是剧种，不是乐器，不能用“弹”。"}, {"text": "他会打戏曲，打得很好。", "explanation": "这里应该用〈鼓〉。“打”配鼓、球等，戏曲不能用“打”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88099, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶每天晚上都看一只戏曲。", "corrected_sentence": "奶奶每天晚上都看一出戏曲。", "error_description": "量词用错：“戏曲”作为演出，量词应用“出”，“只”多用于动物，不能用于戏曲，应说“看一出戏曲”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88099, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我听不懂这根戏曲，但是觉得很好看。", "corrected_sentence": "我听不懂这出戏曲，但是觉得很好看。", "error_description": "量词用错：“戏曲”作为演出，量词应用“出”，“根”多用于条状的东西，不能用于戏曲，应说“这出戏曲”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
