INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88100, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "中国传统的以歌唱、舞蹈、念白相结合的戏剧，如京剧。", "primary_collocate": null, "pronunciation": "xì qǔ", "ipa": "ɕi˥˩ tɕʰy˨˩˦", "syllable_count": 2, "sentences": [{"text": "戏曲是中国传统的艺术。", "target_word": "戏曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "戏曲把唱歌、跳舞和说话放在一起。", "target_word": "戏曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国有很多种戏曲，比如京剧和越剧。", "target_word": "戏曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学戏曲要学唱，也要学跳舞。", "target_word": "戏曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在大学里研究中国戏曲。", "target_word": "戏曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学戏曲的人要会唱歌，会跳舞，还要会念白。", "target_word": "戏曲", "complexity_tier": "T3", "furigana": "xué xì qǔ de rén yào huì chàng gē, huì tiào wǔ, hái yào huì niàn bái.", "sentence_source": "generated"}, {"text": "这所学校的学生都要学戏曲。", "target_word": "戏曲", "complexity_tier": "T3", "furigana": "zhè suǒ xué xiào de xué shēng dōu yào xué xì qǔ.", "sentence_source": "generated"}, {"text": "外国朋友对中国戏曲很感兴趣。", "target_word": "戏曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个地方都有自己的戏曲。", "target_word": "戏曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们去剧院看了一场戏曲表演。", "target_word": "戏曲", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "戲曲", "label": "繁体"}], "register": "中性", "sense_fingerprint": "中国传统的歌唱、舞蹈、念白相结合的戏剧艺术形式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a96547-d1a2-4444-8d6e-1252fc20d0d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88100, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "戏曲", "is_correct": true, "explanation": "正确。“戏曲”是中国传统的歌唱、舞蹈、念白相结合的戏剧艺术，符合句意。"}, {"text": "足球", "is_correct": false, "explanation": "语义：足球是体育运动，不是中国传统艺术，与句意不符。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是现代通讯工具，不属于传统艺术。"}, {"text": "方便面", "is_correct": false, "explanation": "语义：方便面是食品，不是中国传统艺术，与句意不符。"}], "explanations": {"戏曲": "正确。“戏曲”是中国传统的歌唱、舞蹈、念白相结合的戏剧艺术，符合句意。", "足球": "语义：足球是体育运动，不是中国传统艺术，与句意不符。", "手机": "语义：手机是现代通讯工具，不属于传统艺术。", "方便面": "语义：方便面是食品，不是中国传统艺术，与句意不符。"}, "sentence_index": 0, "correct_answer": "戏曲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们去戏曲看了一场演出，观众很多。", "explanation": "这里应该用〈剧院〉。戏曲是剧种，不是场所，不能说“去戏曲”。"}, {"text": "他会吹戏曲，吹得很好听。", "explanation": "这里应该用〈笛子〉。“吹”配笛子、唢呐等乐器，戏曲是剧种，不能用“吹”。"}, {"text": "他是一位很厉害的戏曲，大家都很佩服他。", "explanation": "这里应该用〈演员〉。戏曲是剧种，不能指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88100, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "戏曲", "is_correct": true, "explanation": "正确。“学戏曲”是学习这门传统艺术，与“学生都要学”的语境相符。"}, {"text": "午饭", "is_correct": false, "explanation": "搭配：“学”不跟“午饭”搭配，应说“吃午饭”。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“学”不直接接“房子”，应说“盖房子”。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾不是可以学习的知识或技艺，与“学”的对象不合。"}], "explanations": {"戏曲": "正确。“学戏曲”是学习这门传统艺术，与“学生都要学”的语境相符。", "午饭": "搭配：“学”不跟“午饭”搭配，应说“吃午饭”。", "房子": "搭配：“学”不直接接“房子”，应说“盖房子”。", "垃圾": "语义：垃圾不是可以学习的知识或技艺，与“学”的对象不合。"}, "sentence_index": 6, "correct_answer": "戏曲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们去剧院看了一场戏曲，演员们只说话，一句也不唱。", "explanation": "这里应该用〈话剧〉。戏曲以唱为主，只说不唱的是话剧。"}, {"text": "我们去电影院看了一场戏曲，是一部美国新片。", "explanation": "这里应该用〈电影〉。电影院放的美国新片是电影，不是中国传统戏曲。"}, {"text": "我们去体育馆看了一场戏曲，两个队踢得很精彩。", "explanation": "这里应该用〈足球赛〉。两个队踢的是球赛，戏曲是唱演结合的戏剧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88100, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她学戏曲学很快，老师很满意。", "corrected_sentence": "她学戏曲学得很快，老师很满意。", "error_description": "补语标记遗漏：“学”后接程度补语“很快”时要用结构助词“得”，应说“她学戏曲学得很快”，不能说“她学戏曲学很快”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88100, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们去年看过一只戏曲。", "corrected_sentence": "我们去年看过一出戏曲。", "error_description": "量词用错：“戏曲”作为演出，量词应用“出”，不能用“只”，应说“看过一出戏曲”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
