INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88101, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "选听是自己选一些来听。", "primary_collocate": null, "pronunciation": "xuǎn tīng", "ipa": "ɕɥɛn˨˩˦ tʰɪŋ˥", "syllable_count": 2, "sentences": [{"text": "这么多音乐，我只选听了几首。", "target_word": "选听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请从这些录音里选听你需要的部分。", "target_word": "选听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人早上总是选听新闻节目。", "target_word": "选听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他选听了三段英语对话。", "target_word": "选听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试前，我选听了老师推荐的几个讲座。", "target_word": "选听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些录音很长，你选听一两段就行。", "target_word": "选听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不喜欢全听，只选听最有意思的节目。", "target_word": "选听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们选听了不同国家的民歌。", "target_word": "选听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上有很多课程，你可以自己选听。", "target_word": "选听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们选听了几场关于健康的报告。", "target_word": "选听", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "选听了", "label": "完成体"}, {"form": "选听过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "自己挑选一些来听", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3cfd08e-3d21-43ff-b039-b447ed2d2985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88101, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "选听", "is_correct": true, "explanation": "正确：“选听”表示自己挑选一些来听，与“只……了几首”相合。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能以“音乐”“几首”作宾语。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”不能用于音乐。"}, {"text": "穿", "is_correct": false, "explanation": "语义：“穿”指穿戴衣物，与音乐无关。"}], "explanations": {"选听": "正确：“选听”表示自己挑选一些来听，与“只……了几首”相合。", "吃": "搭配：“吃”不能以“音乐”“几首”作宾语。", "煮": "搭配：“煮”不能用于音乐。", "穿": "语义：“穿”指穿戴衣物，与音乐无关。"}, "sentence_index": 0, "correct_answer": "选听"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他选听了三双新鞋。", "explanation": "选听的对象应是可以听的内容，鞋不能听，挑鞋要用〈挑选〉。"}, {"text": "他选听了整场演唱会，一首歌都没有漏。", "explanation": "这里应该用〈听完〉。“选听”只听一部分，“整场”和“一首都没有漏”与之矛盾，应说“听完了整场演唱会”。"}, {"text": "她在博物馆里选听了几幅画。", "explanation": "这里应该用〈欣赏〉。画是用来看的，不能听；“选听”的对象必须是可以听的内容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd21417dd-c9f1-4c61-b777-aa96f07bf1b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88101, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "选听", "is_correct": true, "explanation": "正确：“选听”表示只挑选最有意思的节目来听，与“不喜欢全听”相合。"}, {"text": "闻", "is_correct": false, "explanation": "语义：“闻”指用鼻子感知，与听节目不符。"}, {"text": "熬", "is_correct": false, "explanation": "搭配：“熬”不能接“节目”作宾语。"}, {"text": "修", "is_correct": false, "explanation": "搭配：“修”用于器物，不能接“节目”作宾语。"}], "explanations": {"选听": "正确：“选听”表示只挑选最有意思的节目来听，与“不喜欢全听”相合。", "闻": "语义：“闻”指用鼻子感知，与听节目不符。", "熬": "搭配：“熬”不能接“节目”作宾语。", "修": "搭配：“修”用于器物，不能接“节目”作宾语。"}, "sentence_index": 6, "correct_answer": "选听"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会议上，他认真选听了每个人的意见。", "explanation": "这里应该用〈听取〉。“选听”指挑选部分来听，与“认真”和“每个人”的全面听取不符。"}, {"text": "同学们选听了几份午餐。", "explanation": "这里应该用〈选择〉。“午餐”不能听，“选听”的对象是课程、节目等可听的内容，挑选午餐应说“选择”。"}, {"text": "这幅画他选听了一遍。", "explanation": "这里应该用〈观赏〉。画是用来看的，不能听；“选听”的对象必须是可以听的内容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd21417dd-c9f1-4c61-b777-aa96f07bf1b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88101, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "周末我想选听过几段英语广播。", "corrected_sentence": "周末我想选听几段英语广播。", "error_description": "错误：“过”表示经历，与“想”表示的打算不搭。正确应去掉“过”，说“想选听几段英语广播”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd21417dd-c9f1-4c61-b777-aa96f07bf1b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88101, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天没选听了那两段录音。", "corrected_sentence": "我昨天没选听那两段录音。", "error_description": "错误：用“没”否定动作时，动词后面不能再带“了”。应去掉“了”，说“没选听那两段录音”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd21417dd-c9f1-4c61-b777-aa96f07bf1b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
