INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88102, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "选择性地听（课或节目）。", "primary_collocate": null, "pronunciation": "xuǎn tīng", "ipa": "ɕɥɛn˨˩˦ tʰɪŋ˥", "syllable_count": 2, "sentences": [{"text": "这个学期我选听了一门历史课。", "target_word": "选听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他报了名，只是选听了几节课。", "target_word": "选听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校允许学生选听其他专业的课程。", "target_word": "选听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天选听自己喜欢的广播节目。", "target_word": "选听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想选听明天下午的那场讲座。", "target_word": "选听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，你可以先选听这门课的第一周。", "target_word": "选听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些节目太多了，我只能选听一部分。", "target_word": "选听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他选听过一次中文写作课。", "target_word": "选听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们可以按兴趣选听不同的讲座。", "target_word": "选听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学生常常选听别的院系的课。", "target_word": "选听", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "选听了", "label": "完成体"}, {"form": "选听过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "有选择地听课或节目", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3cfd08e-3d21-43ff-b039-b447ed2d2985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88102, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "选听", "is_correct": true, "explanation": "正确：“选听”表示有选择地听课，与“一门历史课”相合。"}, {"text": "听写", "is_correct": false, "explanation": "搭配：“听写”指把听到的内容写下来，不能用于一门课。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能用于一门历史课。"}, {"text": "闻", "is_correct": false, "explanation": "语义：“闻”指用鼻子感知气味，不能用于课程。"}], "explanations": {"选听": "正确：“选听”表示有选择地听课，与“一门历史课”相合。", "听写": "搭配：“听写”指把听到的内容写下来，不能用于一门课。", "唱": "搭配：“唱”的对象是歌曲，不能用于一门历史课。", "闻": "语义：“闻”指用鼻子感知气味，不能用于课程。"}, "sentence_index": 0, "correct_answer": "选听"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从很多衣服里选听了一件。", "explanation": "这里应该用〈挑选〉。“选听”的对象是课程、节目、录音等可以听的内容，挑衣服要用“挑选”。"}, {"text": "他选听了那场音乐会，从头到尾一首都没漏。", "explanation": "这里应该用〈听完〉。“选听”只听其中一部分，此句说“从头到尾一首都没漏”，应说“听完了那场音乐会”。"}, {"text": "他没报名，只能去选听。", "explanation": "这里应该用〈旁听〉。“旁听”指不报名、只听课；“选听”以可以选择为前提，没报名就谈不上选择。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd21417dd-c9f1-4c61-b777-aa96f07bf1b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88102, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "选听", "is_correct": true, "explanation": "正确：“选听”表示挑选部分来听，与“只能……一部分”相合。"}, {"text": "背诵", "is_correct": false, "explanation": "搭配：“背诵”用于文章、课文，不用于节目。"}, {"text": "拆", "is_correct": false, "explanation": "搭配：“拆”指拆开包装或器物，不能用于节目。"}, {"text": "闻", "is_correct": false, "explanation": "语义：“闻”指用鼻子感知气味，与听节目不符。"}], "explanations": {"选听": "正确：“选听”表示挑选部分来听，与“只能……一部分”相合。", "背诵": "搭配：“背诵”用于文章、课文，不用于节目。", "拆": "搭配：“拆”指拆开包装或器物，不能用于节目。", "闻": "语义：“闻”指用鼻子感知气味，与听节目不符。"}, "sentence_index": 6, "correct_answer": "选听"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这门课是必修课，我只能选听它。", "explanation": "这里应该用〈上〉。“选听”以可以挑选为前提，必修课没有选择余地，应说“只能上这门课”。"}, {"text": "我每天都选听自己的朋友。", "explanation": "这里应该用〈选择〉。“选听”的对象是课程、节目等内容，不能用于指人，选朋友应说“选择”。"}, {"text": "他把这学期的课全部选听了一遍。", "explanation": "“选听”指挑选其中一部分来听，“全部”与之矛盾，全部听课应说“全部听完”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd21417dd-c9f1-4c61-b777-aa96f07bf1b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88102, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "周末我想选听了一场英语讲座。", "corrected_sentence": "周末我想选听一场英语讲座。", "error_description": "错误：“想”表示打算，其后的动作不能带“了”。正确应说“想选听一场英语讲座”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd21417dd-c9f1-4c61-b777-aa96f07bf1b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88102, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我上学期选听了过一门心理学课。", "corrected_sentence": "我上学期选听过一门心理学课。", "error_description": "错误：“了”与“过”叠加使用，二者不能同时出现。正确应只用“过”，说“选听过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd21417dd-c9f1-4c61-b777-aa96f07bf1b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
