INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88104, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "将书刊、钱币等发出售卖或流通。", "primary_collocate": null, "pronunciation": "fā xíng", "ipa": "fa˥ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "中国人民银行今年发行了新版人民币。", "target_word": "发行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家报社每天发行二十万份。", "target_word": "发行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种杂志只在北京发行。", "target_word": "发行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新邮票明天开始发行。", "target_word": "发行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书在国外也发行。", "target_word": "发行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司发行了一千张纪念卡。", "target_word": "发行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书店里正卖着刚发行的新书。", "target_word": "发行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套钱币只发行了一年。", "target_word": "发行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的报纸发行得很广。", "target_word": "发行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本小说发行后，很多人都买了。", "target_word": "发行", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "发行了", "label": "体标"}, {"form": "发行过", "label": "体标"}, {"form": "发行量", "label": "复合"}], "register": "正式", "sense_fingerprint": "把报刊、钱币等发出去售卖或流通", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b08fec9-be23-4df3-b23e-efdc278f5158') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88104, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "发行", "is_correct": true, "explanation": "正确：发行（fā xíng）意思是把报刊、钱币发出去售卖或流通。"}, {"text": "发明", "is_correct": false, "explanation": "fā míng 与 fā xíng 的 xíng 声母不同（m 与 x），意思是创造新事物。"}, {"text": "发型", "is_correct": false, "explanation": "fà（第四声）与 fā（第一声）声调不同，意思是头发的样式。"}, {"text": "发信", "is_correct": false, "explanation": "fā xìn 与 fā xíng 的韵母不同（in 与 ing），意思是寄出信件。"}], "explanations": {"发行": "正确：发行（fā xíng）意思是把报刊、钱币发出去售卖或流通。", "发明": "fā míng 与 fā xíng 的 xíng 声母不同（m 与 x），意思是创造新事物。", "发型": "fà（第四声）与 fā（第一声）声调不同，意思是头发的样式。", "发信": "fā xìn 与 fā xíng 的韵母不同（in 与 ing），意思是寄出信件。"}, "sentence_index": null, "correct_answer": "发行"}, "level_3": {"options": [{"text": "发行", "is_correct": true, "explanation": "正确：“发行新版人民币”符合句意，指银行推出新钞。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是器物，人民币不能说修理。"}, {"text": "宣读", "is_correct": false, "explanation": "语义：“宣读”的对象是文件或文字，人民币不能被宣读。"}, {"text": "游览", "is_correct": false, "explanation": "语义：“游览”指参观风景或名胜，人民币不能被游览。"}], "explanations": {"发行": "正确：“发行新版人民币”符合句意，指银行推出新钞。", "修理": "搭配：“修理”的对象是器物，人民币不能说修理。", "宣读": "语义：“宣读”的对象是文件或文字，人民币不能被宣读。", "游览": "语义：“游览”指参观风景或名胜，人民币不能被游览。"}, "sentence_index": 0, "correct_answer": "发行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校发行了奖状。", "explanation": "这里应该用〈颁发〉。奖状要用颁发，发行用于报刊、钱币等。"}, {"text": "国务院发行了一项新规定。", "explanation": "这里应该用〈颁布〉。规定、法规要用颁布，发行用于报刊、钱币等。"}, {"text": "志愿者发行了一批口罩。", "explanation": "这里应该用〈分发〉。口罩是物品，要用分发，发行用于书刊、钱币等出版物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85f4f39b-4a90-4385-8473-0c6242caa654') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88104, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发行", "is_correct": true, "explanation": "正确：“刚发行的新书”是常用说法，指刚推出的书。"}, {"text": "访问", "is_correct": false, "explanation": "语义：“访问”的对象是人或机构，书不能被访问。"}, {"text": "入住", "is_correct": false, "explanation": "搭配：“入住”用于住所，新书不能入住。"}, {"text": "饲养", "is_correct": false, "explanation": "搭配：“饲养”的对象是动物，新书不能被饲养。"}], "explanations": {"发行": "正确：“刚发行的新书”是常用说法，指刚推出的书。", "访问": "语义：“访问”的对象是人或机构，书不能被访问。", "入住": "搭配：“入住”用于住所，新书不能入住。", "饲养": "搭配：“饲养”的对象是动物，新书不能被饲养。"}, "sentence_index": 6, "correct_answer": "发行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工厂发行了一批汽车。", "explanation": "这里应该用〈生产〉。汽车要用生产，发行用于报刊、钱币等。"}, {"text": "爱迪生发行了电灯。", "explanation": "这里应该用〈发明〉。电灯这类新事物要用发明，发行用于报刊、钱币等。"}, {"text": "学校发行了奖学金。", "explanation": "这里应该用〈发放〉。奖学金要用发放，发行指向大众推出书刊、钱币。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85f4f39b-4a90-4385-8473-0c6242caa654') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88104, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新版纪念钞明天开始发行过。", "corrected_sentence": "新版纪念钞明天开始发行。", "error_description": "错误在“过”。“过”表示曾经经历，与“明天开始”这样的将来时间不能搭配；应去掉“过”，说“明天开始发行”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85f4f39b-4a90-4385-8473-0c6242caa654') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88104, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份年鉴发行的很广。", "corrected_sentence": "这份年鉴发行得很广。", "error_description": "错误在补语的助词。描述动作结果的补语要用“得”，不能用“的”；应说“发行得很广”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85f4f39b-4a90-4385-8473-0c6242caa654') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
