INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88105, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "打扮是把自己弄得漂亮，穿好看的衣服。", "primary_collocate": null, "pronunciation": "dǎ bàn", "ipa": "ta˨˩ pan˥˩", "syllable_count": 2, "sentences": [{"text": "姐姐打扮好了，我们出发吧。", "target_word": "打扮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天有面试，你要打扮得整齐一点。", "target_word": "打扮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对着镜子打扮自己，还涂了口红。", "target_word": "打扮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不太会打扮，总穿一样的衣服。", "target_word": "打扮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小女孩打扮得像个公主，真可爱。", "target_word": "打扮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你打扮一下，晚上我们去吃饭。", "target_word": "打扮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她打扮过以后，看起来年轻了很多。", "target_word": "打扮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门以前，他总要打扮很久。", "target_word": "打扮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶也喜欢打扮，常常穿红衣服。", "target_word": "打扮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们打扮得漂漂亮亮，去看表演。", "target_word": "打扮", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "打扮了", "label": "完成体"}, {"form": "打扮过", "label": "经历体"}, {"form": "打扮打扮", "label": "重叠"}], "register": "口语", "sense_fingerprint": "把自己弄漂亮，穿好看的衣服", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f19caa3-16e4-4fcd-a031-4c3dbc5187f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88105, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "打扮", "is_correct": true, "explanation": "dǎ bàn 打扮（第三声、第四声）：把自己弄漂亮，穿好看的衣服。"}, {"text": "大半", "is_correct": false, "explanation": "dà bàn 与 dǎ bàn 第一个音节声调不同（第四声与第三声），意思是大部分。"}, {"text": "大班", "is_correct": false, "explanation": "dà bān 与 dǎ bàn 两个音节的声调都不同，意思是幼儿园的大班。"}, {"text": "搭伴", "is_correct": false, "explanation": "dā bàn 与 dǎ bàn 第一个音节声调不同（第一声），意思是结伴同行。"}, {"text": "打板", "is_correct": false, "explanation": "dǎ bǎn 与 dǎ bàn 第二个音节声调不同（第三声），意思是打板子。"}], "explanations": {"打扮": "dǎ bàn 打扮（第三声、第四声）：把自己弄漂亮，穿好看的衣服。", "大半": "dà bàn 与 dǎ bàn 第一个音节声调不同（第四声与第三声），意思是大部分。", "大班": "dà bān 与 dǎ bàn 两个音节的声调都不同，意思是幼儿园的大班。", "搭伴": "dā bàn 与 dǎ bàn 第一个音节声调不同（第一声），意思是结伴同行。", "打板": "dǎ bǎn 与 dǎ bàn 第二个音节声调不同（第三声），意思是打板子。"}, "sentence_index": null, "correct_answer": "打扮"}, "level_3": {"options": [{"text": "打扮", "is_correct": true, "explanation": "打扮：准备出门前把自己弄整齐、漂亮，与“出发吧”衔接。"}, {"text": "装修", "is_correct": false, "explanation": "搭配：“装修”用于房屋，不用于人，“姐姐装修好了”不成立。"}, {"text": "修补", "is_correct": false, "explanation": "语义：修补用于破损的东西，与出门前的准备不符。"}, {"text": "挖", "is_correct": false, "explanation": "语义：挖的动作与“出发”前的准备无关，句意不通。"}], "explanations": {"打扮": "打扮：准备出门前把自己弄整齐、漂亮，与“出发吧”衔接。", "装修": "搭配：“装修”用于房屋，不用于人，“姐姐装修好了”不成立。", "修补": "语义：修补用于破损的东西，与出门前的准备不符。", "挖": "语义：挖的动作与“出发”前的准备无关，句意不通。"}, "sentence_index": 0, "correct_answer": "打扮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把作业打扮了一下，就交给了老师。", "explanation": "这里应该用〈整理〉。打扮只用于人的外表与衣着，作业要用“整理”。"}, {"text": "她打扮了一条红裙子，穿着去上学。", "explanation": "这里应该用〈换〉。打扮是修饰人的整体形象，不能直接以衣服为宾语，换衣服要用“换”。"}, {"text": "他打扮了一个笑话，逗得大家都笑了。", "explanation": "这里应该用〈讲〉（讲笑话）。打扮只用于人的外表与衣着，笑话要用“讲”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51a08e03-4a4a-4188-8898-bd0763341232') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88105, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "打扮", "is_correct": true, "explanation": "dǎ bàn 打扮（第三声、第四声）：把自己弄漂亮，穿好看的衣服。"}, {"text": "大办", "is_correct": false, "explanation": "dà bàn 与 dǎ bàn 第一个音节声调不同，意思是隆重地办（如大办婚事）。"}, {"text": "搭班", "is_correct": false, "explanation": "dā bān 与 dǎ bàn 两个音节的声调都不同，意思是同台合作（搭班子）。"}, {"text": "打版", "is_correct": false, "explanation": "dǎ bǎn 与 dǎ bàn 第二个音节声调不同（第三声），意思是服装制版。"}], "explanations": {"打扮": "dǎ bàn 打扮（第三声、第四声）：把自己弄漂亮，穿好看的衣服。", "大办": "dà bàn 与 dǎ bàn 第一个音节声调不同，意思是隆重地办（如大办婚事）。", "搭班": "dā bān 与 dǎ bàn 两个音节的声调都不同，意思是同台合作（搭班子）。", "打版": "dǎ bǎn 与 dǎ bàn 第二个音节声调不同（第三声），意思是服装制版。"}, "sentence_index": null, "correct_answer": "打扮"}, "level_3": {"options": [{"text": "打扮", "is_correct": true, "explanation": "打扮：修饰外表之后，人会显得年轻，与句意相符。"}, {"text": "撕", "is_correct": false, "explanation": "语义：撕过以后不会看起来年轻，句意不通。"}, {"text": "哭", "is_correct": false, "explanation": "语义：哭过以后看起来年轻，与常理相反。"}, {"text": "写", "is_correct": false, "explanation": "配价：“写”需要所写的对象，“写过以后”缺少宾语，表达不完整。"}], "explanations": {"打扮": "打扮：修饰外表之后，人会显得年轻，与句意相符。", "撕": "语义：撕过以后不会看起来年轻，句意不通。", "哭": "语义：哭过以后看起来年轻，与常理相反。", "写": "配价：“写”需要所写的对象，“写过以后”缺少宾语，表达不完整。"}, "sentence_index": 6, "correct_answer": "打扮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她认真打扮了一下这篇文章。", "explanation": "这里应该用〈修饰〉。打扮只用于人的外表与衣着，文章要用“修饰”。"}, {"text": "她打扮了一点淡妆，很自然。", "explanation": "这里应该用〈化〉（化妆）。“淡妆”要用“化”，打扮不能直接接“淡妆”。"}, {"text": "他打扮了一件新衣服，就出门了。", "explanation": "这里应该用〈换〉。打扮不能直接以衣服为宾语，换衣服要用“换”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51a08e03-4a4a-4188-8898-bd0763341232') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88105, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈打扮了好，我们出发吧。", "corrected_sentence": "妈妈打扮好了，我们出发吧。", "error_description": "错误：“打扮了好”。正确：“打扮好了”。结果补语“好”要紧跟在动词“打扮”后面，“了”放在补语后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51a08e03-4a4a-4188-8898-bd0763341232') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88105, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把妹妹打扮很漂亮。", "corrected_sentence": "我们把妹妹打扮得很漂亮。", "error_description": "错误：“打扮很漂亮”。正确：“打扮得很漂亮”。描述动作结果的程度时，动词后要用助词“得”再接补语，不能直接用“很”接在动词后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51a08e03-4a4a-4188-8898-bd0763341232') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
