INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88106, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "修饰容貌、衣着，使之好看。", "primary_collocate": null, "pronunciation": "dǎ bàn", "ipa": "ta˨˩ pan˥˩", "syllable_count": 2, "sentences": [{"text": "她今天打扮得很漂亮。", "target_word": "打扮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女儿正在房间里打扮自己。", "target_word": "打扮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打扮了半天，才出门。", "target_word": "打扮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末要去约会，她好好打扮了一下。", "target_word": "打扮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不用打扮，穿平时的衣服就行。", "target_word": "打扮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年时，大家都把自己打扮得很漂亮。", "target_word": "打扮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈很爱打扮，每天都化妆。", "target_word": "打扮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喜欢打扮，衣服换了又换。", "target_word": "打扮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从来不打扮，总是穿旧衣服。", "target_word": "打扮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们打扮好了，就去参加婚礼。", "target_word": "打扮", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "打扮了", "label": "完成体"}, {"form": "打扮过", "label": "经历体"}, {"form": "打扮打扮", "label": "重叠"}], "register": "口语", "sense_fingerprint": "修饰容貌和衣着，使之好看", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f19caa3-16e4-4fcd-a031-4c3dbc5187f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88106, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "打扮", "is_correct": true, "explanation": "dǎ bàn 打扮（第三声、第四声）：修饰容貌、衣着，使之好看。"}, {"text": "大半", "is_correct": false, "explanation": "dà bàn 与 dǎ bàn 第一个音节声调不同（第四声与第三声），意思是大部分。"}, {"text": "大班", "is_correct": false, "explanation": "dà bān 与 dǎ bàn 两个音节的声调都不同，意思是幼儿园的大班。"}, {"text": "搭伴", "is_correct": false, "explanation": "dā bàn 与 dǎ bàn 第一个音节声调不同（第一声），意思是结伴同行。"}, {"text": "打板", "is_correct": false, "explanation": "dǎ bǎn 与 dǎ bàn 第二个音节声调不同（第三声），意思是打板子。"}], "explanations": {"打扮": "dǎ bàn 打扮（第三声、第四声）：修饰容貌、衣着，使之好看。", "大半": "dà bàn 与 dǎ bàn 第一个音节声调不同（第四声与第三声），意思是大部分。", "大班": "dà bān 与 dǎ bàn 两个音节的声调都不同，意思是幼儿园的大班。", "搭伴": "dā bàn 与 dǎ bàn 第一个音节声调不同（第一声），意思是结伴同行。", "打板": "dǎ bǎn 与 dǎ bàn 第二个音节声调不同（第三声），意思是打板子。"}, "sentence_index": null, "correct_answer": "打扮"}, "level_3": {"options": [{"text": "打扮", "is_correct": true, "explanation": "打扮：修饰人的容貌，与“漂亮”的描述相符。"}, {"text": "装修", "is_correct": false, "explanation": "搭配：“装修”用于房屋、店面，不用于人的容貌。"}, {"text": "吵", "is_correct": false, "explanation": "搭配：“吵”不能描述人的外貌，“吵得很漂亮”不成立。"}, {"text": "锻炼", "is_correct": false, "explanation": "语义：锻炼指身体练习，句子读作“锻炼得很漂亮”不通。"}], "explanations": {"打扮": "打扮：修饰人的容貌，与“漂亮”的描述相符。", "装修": "搭配：“装修”用于房屋、店面，不用于人的容貌。", "吵": "搭配：“吵”不能描述人的外貌，“吵得很漂亮”不成立。", "锻炼": "语义：锻炼指身体练习，句子读作“锻炼得很漂亮”不通。"}, "sentence_index": 0, "correct_answer": "打扮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他打扮了一个问题，老师就回答了。", "explanation": "这里应该用〈提〉（提问题）。打扮是修饰容貌、衣着，问题不能打扮。"}, {"text": "她打扮了一件红裙子，去上学。", "explanation": "这里应该用〈穿〉。打扮是修饰人的整体形象，不能直接以衣服为宾语。"}, {"text": "她打扮了淡妆，就出门了。", "explanation": "这里应该用〈化〉（化妆）。“淡妆”要用“化”，打扮不能直接接“淡妆”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51a08e03-4a4a-4188-8898-bd0763341232') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88106, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "打扮", "is_correct": true, "explanation": "dǎ bàn 打扮（第三声、第四声）：修饰容貌、衣着，使之好看。"}, {"text": "大办", "is_correct": false, "explanation": "dà bàn 与 dǎ bàn 第一个音节声调不同，意思是隆重地办（如大办婚事）。"}, {"text": "搭班", "is_correct": false, "explanation": "dā bān 与 dǎ bàn 两个音节的声调都不同，意思是同台合作（搭班子）。"}, {"text": "打版", "is_correct": false, "explanation": "dǎ bǎn 与 dǎ bàn 第二个音节声调不同（第三声），意思是服装制版。"}], "explanations": {"打扮": "dǎ bàn 打扮（第三声、第四声）：修饰容貌、衣着，使之好看。", "大办": "dà bàn 与 dǎ bàn 第一个音节声调不同，意思是隆重地办（如大办婚事）。", "搭班": "dā bān 与 dǎ bàn 两个音节的声调都不同，意思是同台合作（搭班子）。", "打版": "dǎ bǎn 与 dǎ bàn 第二个音节声调不同（第三声），意思是服装制版。"}, "sentence_index": null, "correct_answer": "打扮"}, "level_3": {"options": [{"text": "打扮", "is_correct": true, "explanation": "打扮：爱修饰外表，与“每天都化妆”的描述相符。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“很爱睡”与“每天都化妆”的习惯不相符，句意不通。"}, {"text": "数", "is_correct": false, "explanation": "语义：“数”指数数，与“化妆”的习惯无关，句子不通。"}, {"text": "搬", "is_correct": false, "explanation": "配价：“搬”需要搬运的对象，“很爱搬”的表达不完整。"}], "explanations": {"打扮": "打扮：爱修饰外表，与“每天都化妆”的描述相符。", "睡": "语义：“很爱睡”与“每天都化妆”的习惯不相符，句意不通。", "数": "语义：“数”指数数，与“化妆”的习惯无关，句子不通。", "搬": "配价：“搬”需要搬运的对象，“很爱搬”的表达不完整。"}, "sentence_index": 6, "correct_answer": "打扮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他认真打扮了一下这篇文章。", "explanation": "这里应该用〈修饰〉。打扮只用于人的外表与衣着，文章要用“修饰”。"}, {"text": "他打扮了一个借口，就提前走了。", "explanation": "这里应该用〈找〉（找借口）。打扮只用于人的外表与衣着，借口不能打扮。"}, {"text": "他打扮了一下计划，就去上班了。", "explanation": "这里应该用〈调整〉。打扮只用于人的外表与衣着，计划要用“调整”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51a08e03-4a4a-4188-8898-bd0763341232') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88106, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从没打扮了自己。", "corrected_sentence": "他从没打扮过自己。", "error_description": "“从没”表示从未有过的经历，应与“过”搭配；“了”表示完成，与“从没”不能同用。正确说法是“从没打扮过自己”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51a08e03-4a4a-4188-8898-bd0763341232') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88106, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把女儿打扮很漂亮。", "corrected_sentence": "妈妈把女儿打扮得很漂亮。", "error_description": "缺少补语标记“得”。“打扮”后面接状态补语“很漂亮”时，中间须加“得”，正确说法是“打扮得很漂亮”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51a08e03-4a4a-4188-8898-bd0763341232') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
