INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88108, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "选点是在很多地方里选出一个合适的地方。", "primary_collocate": null, "pronunciation": "xuǎn diǎn", "ipa": "ɕɥɛn˨˩˦ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "我们要为这次野餐选点。", "target_word": "选点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们花了两天时间在山里选点。", "target_word": "选点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们一起为周末聚会选点，最后选了公园。", "target_word": "选点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们先选点，再想怎么布置。", "target_word": "选点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "拍照以前，摄影师先在河边选点。", "target_word": "选点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司准备开新店，经理正在选点。", "target_word": "选点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们想去露营，正在网上选点。", "target_word": "选点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "选点以前，大家先看了很多地图。", "target_word": "选点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们已经选点了，就在学校后面的小山上。", "target_word": "选点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸带着地图，在郊外选点。", "target_word": "选点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "选点了", "label": "完成体"}, {"form": "选点过", "label": "经历体"}, {"form": "选点工作", "label": "复合词"}], "register": "中性", "sense_fingerprint": "从多个地方中挑出一个合适的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8adc4d6f-ebb2-4854-98ad-9066d9a002e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88108, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "选点", "is_correct": true, "explanation": "“选点”指在多个地方中挑出一个合适的地方，符合“为这次野餐选点”。"}, {"text": "写作", "is_correct": false, "explanation": "语义：写作指写文章，与为野餐挑选地方无关。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：修理的对象是坏了的东西，“为野餐修理”说不通。"}, {"text": "出生", "is_correct": false, "explanation": "语义：出生指人或动物降生，不能用于为野餐做准备。"}], "explanations": {"选点": "“选点”指在多个地方中挑出一个合适的地方，符合“为这次野餐选点”。", "写作": "语义：写作指写文章，与为野餐挑选地方无关。", "修理": "搭配：修理的对象是坏了的东西，“为野餐修理”说不通。", "出生": "语义：出生指人或动物降生，不能用于为野餐做准备。"}, "sentence_index": 0, "correct_answer": "选点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们为这个方案选点了好久，还是没定下来。", "explanation": "这里应该用〈选择〉。选点只用于挑地方，方案不是地方，应说“选择方案”。"}, {"text": "老师为班会的内容选点了半天。", "explanation": "这里应该用〈斟酌〉。选点只用于挑地方，班会内容不是地方，应说“斟酌内容”。"}, {"text": "她为新裙子选点了半天，还是没决定。", "explanation": "这里应该用〈挑〉。选点只用于挑地方，裙子不是地方，应说“挑裙子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4800114-7876-4847-9a37-f4b844e70c66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88108, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "选点", "is_correct": true, "explanation": "“选点”指挑选合适的地点，符合“正在网上选点”找露营地的语境。"}, {"text": "收割", "is_correct": false, "explanation": "语义：收割指收庄稼，与在网上找露营地无关。"}, {"text": "修剪", "is_correct": false, "explanation": "搭配：修剪用于树木、头发等，不能说“在网上修剪”。"}, {"text": "烧制", "is_correct": false, "explanation": "语义：烧制指烧陶瓷等器物，与露营找地点无关。"}], "explanations": {"选点": "“选点”指挑选合适的地点，符合“正在网上选点”找露营地的语境。", "收割": "语义：收割指收庄稼，与在网上找露营地无关。", "修剪": "搭配：修剪用于树木、头发等，不能说“在网上修剪”。", "烧制": "语义：烧制指烧陶瓷等器物，与露营找地点无关。"}, "sentence_index": 6, "correct_answer": "选点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他为了比赛的成绩选点了一整天。", "explanation": "这里应该用〈计算〉。选点只用于挑地方，比赛成绩不是地方，应说“计算成绩”。"}, {"text": "妈妈为晚饭的做法选点很久。", "explanation": "这里应该用〈研究〉。选点只用于挑地方，做法不是地方，应说“研究做法”。"}, {"text": "老板为新员工的培训内容选点，讨论到深夜。", "explanation": "这里应该用〈商讨〉。选点只用于挑地方，培训内容不是地方，应说“商讨内容”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4800114-7876-4847-9a37-f4b844e70c66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88108, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在商店里选点了一件新衣服。", "corrected_sentence": "她在商店里挑了一件新衣服。", "error_description": "“选点”只用于挑选地方，衣服不是地方，应该用“挑”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4800114-7876-4847-9a37-f4b844e70c66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88108, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在书店里选点了两本小说。", "corrected_sentence": "我在书店里挑了两本小说。", "error_description": "“选点”只用于挑选地方，小说不是地方，应该用“挑”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4800114-7876-4847-9a37-f4b844e70c66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
