INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88110, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "选择合适的地点。", "primary_collocate": null, "pronunciation": "xuǎn diǎn", "ipa": "ɕɥɛn˨˩˦ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "他们正在为婚礼选点。", "target_word": "选点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想开一家咖啡店，先去商业街选点。", "target_word": "选点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们给运动会选点，要大一点的地方。", "target_word": "选点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导游在山上选点，准备让大家休息。", "target_word": "选点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "摄影师选点后，才开始拍照。", "target_word": "选点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校为新校区选点，已经看过三个地方。", "target_word": "选点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们打算在哪儿选点开会？", "target_word": "选点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人先选点，再挖井。", "target_word": "选点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们拿着地图到公园选点，准备搭帐篷。", "target_word": "选点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他选点时很认真，一直看到天黑。", "target_word": "选点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "选点了", "label": "完成体"}, {"form": "选点过", "label": "经历体"}, {"form": "选点工作", "label": "复合词"}], "register": "中性", "sense_fingerprint": "为某件事或某项活动挑选合适的地点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8adc4d6f-ebb2-4854-98ad-9066d9a002e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88110, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "选点", "is_correct": true, "explanation": "“选点”指选择合适的地点，符合“为婚礼选点”。"}, {"text": "摔倒", "is_correct": false, "explanation": "语义：摔倒指身体跌落，不能用于为婚礼做准备。"}, {"text": "出版", "is_correct": false, "explanation": "搭配：出版的对象是书报，不能说“为婚礼出版”。"}, {"text": "报废", "is_correct": false, "explanation": "语义：报废指器物不能再用，与为婚礼准备无关。"}], "explanations": {"选点": "“选点”指选择合适的地点，符合“为婚礼选点”。", "摔倒": "语义：摔倒指身体跌落，不能用于为婚礼做准备。", "出版": "搭配：出版的对象是书报，不能说“为婚礼出版”。", "报废": "语义：报废指器物不能再用，与为婚礼准备无关。"}, "sentence_index": 0, "correct_answer": "选点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "导游为这次旅行的行程选点了半天，还是没决定。", "explanation": "这里应该用〈选择〉。选点只用于挑地点，行程不是地点，应说“选择行程”。"}, {"text": "导游为出发时间选点，一直拖到中午。", "explanation": "这里应该用〈定〉。选点只用于挑地点，出发时间不是地点，应说“定时间”。"}, {"text": "导游为午饭的菜单选点很久，大家都饿了。", "explanation": "这里应该用〈挑选〉。选点只用于挑地点，菜单不是地点，应说“挑选菜单”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4800114-7876-4847-9a37-f4b844e70c66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88110, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "选点", "is_correct": true, "explanation": "“选点”指挑选合适的地点，符合“在哪儿选点开会”的语境。"}, {"text": "冲洗", "is_correct": false, "explanation": "搭配：冲洗多用于照片、器皿，不能说“在哪儿冲洗开会”。"}, {"text": "发烧", "is_correct": false, "explanation": "语义：发烧指身体发热，与挑选地点开会无关。"}, {"text": "入睡", "is_correct": false, "explanation": "配价：入睡是不及物动词，后面不能带“开会”作宾语。"}], "explanations": {"选点": "“选点”指挑选合适的地点，符合“在哪儿选点开会”的语境。", "冲洗": "搭配：冲洗多用于照片、器皿，不能说“在哪儿冲洗开会”。", "发烧": "语义：发烧指身体发热，与挑选地点开会无关。", "入睡": "配价：入睡是不及物动词，后面不能带“开会”作宾语。"}, "sentence_index": 6, "correct_answer": "选点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他为了考试的成绩选点了一整天。", "explanation": "这里应该用〈核对〉。选点只用于挑地点，考试成绩不是地点，应说“核对成绩”。"}, {"text": "妈妈为晚饭的做法选点，想了很久。", "explanation": "这里应该用〈推敲〉。选点只用于挑地点，做法不是地点，应说“推敲做法”。"}, {"text": "老板为新员工的培训安排选点，开会开到深夜。", "explanation": "这里应该用〈商讨〉。选点只用于挑地点，培训安排不是地点，应说“商讨安排”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4800114-7876-4847-9a37-f4b844e70c66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88110, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈在超市里选点了一些水果。", "corrected_sentence": "妈妈在超市里挑了一些水果。", "error_description": "“选点”只用于挑选地点，水果不是地点，应该用“挑”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4800114-7876-4847-9a37-f4b844e70c66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88110, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他花了很久为女朋友选点一份礼物。", "corrected_sentence": "他花了很久为女朋友挑一份礼物。", "error_description": "“选点”只用于挑选地点，礼物不是地点，应该用“挑”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4800114-7876-4847-9a37-f4b844e70c66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
