INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88111, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "评论是对一件事说出自己的想法和看法。", "primary_collocate": null, "pronunciation": "píng lùn", "ipa": "pʰiŋ˧˥ lu̯ən˥˩", "syllable_count": 2, "sentences": [{"text": "这篇评论写得很好。", "target_word": "评论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我看了他的评论。", "target_word": "评论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网上有很多人写了评论。", "target_word": "评论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影的评论都不太好。", "target_word": "评论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天都读报纸上的新闻评论。", "target_word": "评论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的评论让我想了很久。", "target_word": "评论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在下面留下你的评论。", "target_word": "评论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条评论说得很有道理。", "target_word": "评论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看了朋友的评论，我决定买这本书。", "target_word": "评论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写的足球评论很受欢迎。", "target_word": "评论", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一篇评论", "label": "量词"}, {"form": "一条评论", "label": "量词"}, {"form": "评论员", "label": "复合"}, {"form": "評論", "label": "繁体"}], "register": "中性", "sense_fingerprint": "对一件事说出的想法和看法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2634a1f-e0ef-4c1b-853c-f701f33e6317') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88111, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "评论", "is_correct": true, "explanation": "正确。“评论”是对一件事说出的看法，可以“写”，也可以用量词“篇”。"}, {"text": "电话", "is_correct": false, "explanation": "语义：“电话”不能被“写”，句子语义不通。"}, {"text": "椅子", "is_correct": false, "explanation": "搭配：量词“篇”和动词“写”只用于文章，不能用于椅子。"}, {"text": "汤", "is_correct": false, "explanation": "语义：汤不能被“写”，此处语义不通。"}], "explanations": {"评论": "正确。“评论”是对一件事说出的看法，可以“写”，也可以用量词“篇”。", "电话": "语义：“电话”不能被“写”，句子语义不通。", "椅子": "搭配：量词“篇”和动词“写”只用于文章，不能用于椅子。", "汤": "语义：汤不能被“写”，此处语义不通。"}, "sentence_index": 0, "correct_answer": "评论"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我写了一只评论，朋友们都很喜欢。", "explanation": "这里应该用〈篇〉或〈条〉。“只”用于动物，“评论”要用“篇”或“条”来计量。"}, {"text": "这首评论很好听，我每天都听。", "explanation": "这里“评论”指对事情的看法，不是歌曲；“首”用于歌曲，与“评论”的词义不符。"}, {"text": "这篇评论的颜色很漂亮，我把它挂在墙上了。", "explanation": "这里应该用〈画〉。“评论”是文字，没有颜色可以欣赏，也不能挂在墙上；这里说的是画。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7583ec12-e2fe-4986-a7f0-f7d7e08f100b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88111, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "评论", "is_correct": true, "explanation": "正确。“留下评论”指在下面写下自己的看法，符合语境。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能被“留下”在留言区，句子不通。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油不是可以留在留言里的内容，语义不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“留下”用于留言、签名等，不能与“冰箱”组合在留言语境中使用。"}], "explanations": {"评论": "正确。“留下评论”指在下面写下自己的看法，符合语境。", "天气": "语义：天气不能被“留下”在留言区，句子不通。", "汽油": "语义：汽油不是可以留在留言里的内容，语义不通。", "冰箱": "搭配：“留下”用于留言、签名等，不能与“冰箱”组合在留言语境中使用。"}, "sentence_index": 6, "correct_answer": "评论"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他设计的足球评论很受欢迎。", "explanation": "这里应该用〈游戏〉。“评论”是文字看法，不能被设计；设计的是游戏、程序等。"}, {"text": "他喝掉的足球评论很受欢迎。", "explanation": "这里应该用〈读〉。“评论”是文字，不能被喝掉；读的是评论。"}, {"text": "他的足球评论昨天被我修好了。", "explanation": "这里应该用〈自行车〉。“评论”是文字看法，不是能坏、能修的东西；被修好的应该是自行车这类物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7583ec12-e2fe-4986-a7f0-f7d7e08f100b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88111, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我读了一只很有意思的评论。", "corrected_sentence": "我读了一篇很有意思的评论。", "error_description": "“评论”的量词应用“篇”或“条”，不能用“只”（“只”用于动物等）。应说“一篇很有意思的评论”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7583ec12-e2fe-4986-a7f0-f7d7e08f100b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88111, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这篇很精彩评论写得不错。", "corrected_sentence": "这篇很精彩的评论写得不错。", "error_description": "“很精彩”修饰“评论”时中间要加“的”，应说“很精彩的评论”，不能直接说“很精彩评论”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7583ec12-e2fe-4986-a7f0-f7d7e08f100b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
