INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88112, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对人或事物发表意见、作出评价。", "primary_collocate": null, "pronunciation": "píng lùn", "ipa": "pʰiŋ˧˥ lu̯ən˥˩", "syllable_count": 2, "sentences": [{"text": "大家都在评论这部新电影。", "target_word": "评论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师认真地评论了每个同学的作文。", "target_word": "评论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不喜欢评论别人。", "target_word": "评论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "记者请专家评论一下这件事。", "target_word": "评论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛结束后，电视里的人开始评论球员的表现。", "target_word": "评论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你评论一下我的画儿。", "target_word": "评论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网友们纷纷评论这位歌手的新歌。", "target_word": "评论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对这个问题，我不想随便评论。", "target_word": "评论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板当着大家的面评论了他的工作。", "target_word": "评论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她常常在网上评论朋友们发的照片。", "target_word": "评论", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "评论了", "label": "体标"}, {"form": "评论过", "label": "体标"}, {"form": "评论评论", "label": "重叠"}, {"form": "評論", "label": "繁体"}], "register": "中性", "sense_fingerprint": "对人或事发表意见、作出评价", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2634a1f-e0ef-4c1b-853c-f701f33e6317') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88112, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "评论", "is_correct": true, "explanation": "正确。“评论”表示对电影发表意见，符合“大家都在……这部新电影”的语境。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象不能是电影，这句话语义不通。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”搭配房间、场地等，不能搭配“电影”。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”只用于饮品，不能用于电影。"}], "explanations": {"评论": "正确。“评论”表示对电影发表意见，符合“大家都在……这部新电影”的语境。", "吃": "语义：“吃”的对象不能是电影，这句话语义不通。", "打扫": "搭配：“打扫”搭配房间、场地等，不能搭配“电影”。", "喝": "语义：“喝”只用于饮品，不能用于电影。"}, "sentence_index": 0, "correct_answer": "评论"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师评论了他的作业，却一个字也没说。", "explanation": "这里应该用〈批改〉。“评论”要求说出看法，句中却说“一个字也没说”，前后矛盾；只是批改作业时，不需要发表议论。"}, {"text": "他评论了那只杯子，结果杯子摔碎了。", "explanation": "这里应该用〈碰〉。“评论”只是发表看法，不会使杯子摔碎；造成破损要用“碰”这类动作动词。"}, {"text": "老师评论了这扇窗，结果玻璃碎了一地。", "explanation": "这里应该用〈砸〉。“评论”是发表看法，不会使玻璃碎裂；造成碎裂要用“砸”这类动作动词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7583ec12-e2fe-4986-a7f0-f7d7e08f100b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88112, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "评论", "is_correct": true, "explanation": "正确。“评论”表示对歌手的新歌发表意见，符合语境。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”的对象应是衣物或身体，不能用于歌曲。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”的对象是食物，不能用于歌曲，句子不通。"}, {"text": "切", "is_correct": false, "explanation": "语义：“切”指把东西分开，用在歌曲上语义不通。"}], "explanations": {"评论": "正确。“评论”表示对歌手的新歌发表意见，符合语境。", "洗": "语义：“洗”的对象应是衣物或身体，不能用于歌曲。", "煮": "语义：“煮”的对象是食物，不能用于歌曲，句子不通。", "切": "语义：“切”指把东西分开，用在歌曲上语义不通。"}, "sentence_index": 6, "correct_answer": "评论"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她把这篇文章评论成了英文，朋友们都看懂了。", "explanation": "这里应该用〈翻译〉。“评论”指发表看法，不能改变文字的语言；把文章变成另一种语言要用“翻译”。"}, {"text": "她在网上评论了那只碗，结果碗摔碎了。", "explanation": "这里应该用〈碰〉。“评论”只是发表看法，不会使碗摔碎；造成破损要用“碰”这类动作动词。"}, {"text": "她把坏了的手机评论好了，又放回了桌子上。", "explanation": "这里应该用〈修〉。“评论”指发表看法，不能使器物恢复正常；修好手机要用“修”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7583ec12-e2fe-4986-a7f0-f7d7e08f100b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88112, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天评论了过这部电影。", "corrected_sentence": "我昨天评论过这部电影。", "error_description": "“评论”后面的体标只能用一个：表示曾经发生用“过”，不能同时用“了”和“过”。应说“评论过这部电影”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7583ec12-e2fe-4986-a7f0-f7d7e08f100b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88112, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把老师的文章评论。", "corrected_sentence": "她把老师的文章评论了一遍。", "error_description": "“把”字句中的动词后面要有补语或其他成分说明结果，“评论”后应加“了一遍”，不能只说“她把老师的文章评论”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7583ec12-e2fe-4986-a7f0-f7d7e08f100b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88113, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "打滑", "is_correct": true, "explanation": "“打滑”是“抓地”的反义：车轮与地面失去附着，容易滑动。"}, {"text": "行驶", "is_correct": false, "explanation": "“行驶”只表示车在路上走，与“抓地”的附着状态没有反义关系。"}, {"text": "减速", "is_correct": false, "explanation": "“减速”指速度降低，与“抓地”所说的车轮附着程度不构成反义。"}, {"text": "熄火", "is_correct": false, "explanation": "“熄火”指发动机停止工作，与“抓地”不是反义关系。"}], "correct_answer": "打滑", "explanations": {"打滑": "“打滑”是“抓地”的反义：车轮与地面失去附着，容易滑动。", "行驶": "“行驶”只表示车在路上走，与“抓地”的附着状态没有反义关系。", "减速": "“减速”指速度降低，与“抓地”所说的车轮附着程度不构成反义。", "熄火": "“熄火”指发动机停止工作，与“抓地”不是反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca9ddb30-e43a-4c63-956b-9f576adce309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88113, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "打滑", "is_correct": true, "explanation": "“打滑”是“抓地”的反义：车轮与地面失去附着，容易滑动。"}, {"text": "停车", "is_correct": false, "explanation": "“停车”指车停下来，与“抓地”的附着状态没有反义关系。"}, {"text": "刮擦", "is_correct": false, "explanation": "“刮擦”指擦碰，与“抓地”所说的附着性能不构成反义。"}, {"text": "转弯", "is_correct": false, "explanation": "“转弯”指改变行驶方向，与“抓地”不是反义关系。"}], "correct_answer": "打滑", "explanations": {"打滑": "“打滑”是“抓地”的反义：车轮与地面失去附着，容易滑动。", "停车": "“停车”指车停下来，与“抓地”的附着状态没有反义关系。", "刮擦": "“刮擦”指擦碰，与“抓地”所说的附着性能不构成反义。", "转弯": "“转弯”指改变行驶方向，与“抓地”不是反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca9ddb30-e43a-4c63-956b-9f576adce309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88113, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "抓地是车轮紧紧贴着地，不容易滑。", "primary_collocate": null, "pronunciation": "zhuā dì", "ipa": "ʈʂua˥ ti˥˩", "syllable_count": 2, "sentences": [{"text": "新轮胎抓地很好，下雨也不怕。", "target_word": "抓地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种轮胎很抓地，转弯时车不会滑。", "target_word": "抓地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪地里，轮胎不抓地，车很容易打滑。", "target_word": "抓地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车胎太旧了，已经不抓地了。", "target_word": "抓地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的越野车轮胎很抓地，上山也不怕。", "target_word": "抓地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种轮胎花纹深，路面有水时也很抓地。", "target_word": "抓地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路面有水，车轮就不太抓地了。", "target_word": "抓地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "换了新轮胎以后，车转弯时更抓地了。", "target_word": "抓地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "赛车的轮胎特别抓地，所以跑得快。", "target_word": "抓地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑山路时，我喜欢抓地好的车。", "target_word": "抓地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "车轮紧贴地面，行驶时不容易打滑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52f58a29-0843-4b18-9594-88ac0b975df0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88113, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "抓地", "is_correct": true, "explanation": "抓地：车轮紧贴地面，不容易打滑。"}, {"text": "刷地", "is_correct": false, "explanation": "声母不同：shuā（sh）与 zhuā（zh）只差一个声母，意思是用刷子擦地面，不是车轮的抓地性能。"}, {"text": "砖地", "is_correct": false, "explanation": "韵母不同：zhuān（-ān）与 zhuā（-a）只差韵母，意思是铺砖的地面。"}, {"text": "抓力", "is_correct": false, "explanation": "声母不同：lì（l）与 dì（d）只差声母，意思是抓握的力量，不是轮胎与路面的附着。"}], "explanations": {"抓地": "抓地：车轮紧贴地面，不容易打滑。", "刷地": "声母不同：shuā（sh）与 zhuā（zh）只差一个声母，意思是用刷子擦地面，不是车轮的抓地性能。", "砖地": "韵母不同：zhuān（-ān）与 zhuā（-a）只差韵母，意思是铺砖的地面。", "抓力": "声母不同：lì（l）与 dì（d）只差声母，意思是抓握的力量，不是轮胎与路面的附着。"}, "sentence_index": null, "correct_answer": "抓地"}, "level_3": {"options": [{"text": "抓地", "is_correct": true, "explanation": "抓地：车轮紧贴地面，与“很好”“下雨也不怕”的语境相符。"}, {"text": "冒烟", "is_correct": false, "explanation": "语义：“冒烟”指车冒出烟，与“很好、下雨也不怕”的评价相反。"}, {"text": "漏气", "is_correct": false, "explanation": "搭配：“漏气”说的是轮胎的缺陷，不能用“很好”来评价轮胎的性能。"}, {"text": "爆胎", "is_correct": false, "explanation": "语义：“爆胎”是事故，与句中“很好、不怕下雨”的积极评价矛盾。"}], "explanations": {"抓地": "抓地：车轮紧贴地面，与“很好”“下雨也不怕”的语境相符。", "冒烟": "语义：“冒烟”指车冒出烟，与“很好、下雨也不怕”的评价相反。", "漏气": "搭配：“漏气”说的是轮胎的缺陷，不能用“很好”来评价轮胎的性能。", "爆胎": "语义：“爆胎”是事故，与句中“很好、不怕下雨”的积极评价矛盾。"}, "sentence_index": 0, "correct_answer": "抓地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这篇文章的论证很抓地，读者很容易被说服。", "explanation": "这里应该用〈有力〉。抓地只指车轮、鞋底与地面紧贴、不打滑，说论证的有力程度要用“有力”。"}, {"text": "这首诗的节奏很抓地，念起来很有劲。", "explanation": "这里应该用〈抓人〉。抓地只指车轮、鞋底与地面紧贴，说节奏吸引人要用“抓人”。"}, {"text": "这碗汤的味道很抓地，喝一口就忘不了。", "explanation": "这里应该用〈浓郁〉。抓地只指车轮、鞋底与地面紧贴、不打滑，说汤的味道浓要用“浓郁”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca9ddb30-e43a-4c63-956b-9f576adce309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88113, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抓地", "is_correct": true, "explanation": "抓地：路面有水时车轮与路面的附着变差，正是“不太抓地了”的意思。"}, {"text": "刹车", "is_correct": false, "explanation": "搭配：“刹车”是驾驶员的操作，不能说车轮“不太刹车了”。"}, {"text": "鸣笛", "is_correct": false, "explanation": "语义：“鸣笛”是按喇叭发声，与车轮的附着能力无关。"}, {"text": "倒车", "is_correct": false, "explanation": "语义：“倒车”指车向后行驶，与“路面有水”导致的抓地变化没有关系。"}], "explanations": {"抓地": "抓地：路面有水时车轮与路面的附着变差，正是“不太抓地了”的意思。", "刹车": "搭配：“刹车”是驾驶员的操作，不能说车轮“不太刹车了”。", "鸣笛": "语义：“鸣笛”是按喇叭发声，与车轮的附着能力无关。", "倒车": "语义：“倒车”指车向后行驶，与“路面有水”导致的抓地变化没有关系。"}, "sentence_index": 6, "correct_answer": "抓地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两块木板互相抓地，发出吱吱的声音。", "explanation": "这里应该用〈摩擦〉。抓地只用于车轮等与路面紧贴、不打滑的情况，两块木板互相作用要说“摩擦”。"}, {"text": "这段话的情绪很抓地，读的人都哭了。", "explanation": "这里应该用〈感人〉。抓地只指车轮、鞋底与地面紧贴、不打滑，说文字让人动情要用“感人”。"}, {"text": "这把剪刀的刀刃很抓地，剪布很利落。", "explanation": "这里应该用〈锋利〉。抓地只指车轮、鞋底与地面紧贴，说刀刃的锐利要用“锋利”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca9ddb30-e43a-4c63-956b-9f576adce309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88113, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这套新雪胎抓地路面很好，雪地里不打滑。", "corrected_sentence": "这套新雪胎抓地很好，雪地里不打滑。", "error_description": "错误：“抓地”是不及物的动词性短语，后面不能直接带处所宾语“路面”。正确说法：“这套新雪胎抓地很好”，“抓地”后直接接谓语，不带宾语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca9ddb30-e43a-4c63-956b-9f576adce309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88113, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种轮胎抓地了很好，转弯时车不会滑。", "corrected_sentence": "这种轮胎抓地很好，转弯时车不会滑。", "error_description": "错误：“了”插在“抓地”和“很好”之间，体标位置不对。“抓地”后不能加“了”，应直接说“抓地很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca9ddb30-e43a-4c63-956b-9f576adce309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88114, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "打滑", "is_correct": true, "explanation": "“打滑”是“抓地”的反义：车轮或鞋底与地面失去附着，容易滑动。"}, {"text": "加速", "is_correct": false, "explanation": "“加速”指车速变快，与“抓地”不构成反义关系。"}, {"text": "转弯", "is_correct": false, "explanation": "“转弯”指改变行驶方向，与“抓地”的附着状态没有反义关系。"}, {"text": "倒车", "is_correct": false, "explanation": "“倒车”指车向后行驶，与“抓地”不是反义关系。"}], "correct_answer": "打滑", "explanations": {"打滑": "“打滑”是“抓地”的反义：车轮或鞋底与地面失去附着，容易滑动。", "加速": "“加速”指车速变快，与“抓地”不构成反义关系。", "转弯": "“转弯”指改变行驶方向，与“抓地”的附着状态没有反义关系。", "倒车": "“倒车”指车向后行驶，与“抓地”不是反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca9ddb30-e43a-4c63-956b-9f576adce309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88114, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "打滑", "is_correct": true, "explanation": "“打滑”是“抓地”的反义：车轮与地面失去附着，容易滑动。"}, {"text": "停车", "is_correct": false, "explanation": "“停车”指车停下来，与“抓地”的附着状态没有反义关系。"}, {"text": "刮擦", "is_correct": false, "explanation": "“刮擦”指擦碰，与“抓地”所说的附着性能不构成反义。"}, {"text": "熄火", "is_correct": false, "explanation": "“熄火”指发动机停止工作，与“抓地”不是反义关系。"}], "correct_answer": "打滑", "explanations": {"打滑": "“打滑”是“抓地”的反义：车轮与地面失去附着，容易滑动。", "停车": "“停车”指车停下来，与“抓地”的附着状态没有反义关系。", "刮擦": "“刮擦”指擦碰，与“抓地”所说的附着性能不构成反义。", "熄火": "“熄火”指发动机停止工作，与“抓地”不是反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca9ddb30-e43a-4c63-956b-9f576adce309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88114, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "（轮胎等）与地面紧密接触、不易打滑。", "primary_collocate": null, "pronunciation": "zhuā dì", "ipa": "ʈʂua˥ ti˥˩", "syllable_count": 2, "sentences": [{"text": "这款自行车胎很抓地，下坡也安心。", "target_word": "抓地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "轮胎磨平了就不抓地，雨天很危险。", "target_word": "抓地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "登山鞋的鞋底非常抓地，走石头路不滑。", "target_word": "抓地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车速太快时，轮胎就不抓地了。", "target_word": "抓地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天要换雪地胎，因为它在冰面上更抓地。", "target_word": "抓地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双跑鞋抓地，我跑步时不怕滑。", "target_word": "抓地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "轮胎气压太低，车就不太抓地。", "target_word": "抓地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的车抓地很稳，过弯一点儿也不飘。", "target_word": "抓地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨天路滑，要选抓地好的轮胎。", "target_word": "抓地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条赛道上，轮胎不抓地就会冲出去。", "target_word": "抓地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "轮胎、鞋底等与地面紧密接触而不易打滑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52f58a29-0843-4b18-9594-88ac0b975df0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88114, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抓地", "is_correct": true, "explanation": "抓地：车胎与地面紧贴、不打滑，与“下坡也安心”相符。"}, {"text": "漏气", "is_correct": false, "explanation": "语义：“漏气”说车胎出了毛病，与“下坡也安心”的评价相反。"}, {"text": "发热", "is_correct": false, "explanation": "语义：“发热”指温度升高，句子评价的是车胎的附着性能，不能用它。"}, {"text": "变形", "is_correct": false, "explanation": "搭配：“变形”说形状改变，不用来形容车胎与地面的附着程度。"}], "explanations": {"抓地": "抓地：车胎与地面紧贴、不打滑，与“下坡也安心”相符。", "漏气": "语义：“漏气”说车胎出了毛病，与“下坡也安心”的评价相反。", "发热": "语义：“发热”指温度升高，句子评价的是车胎的附着性能，不能用它。", "变形": "搭配：“变形”说形状改变，不用来形容车胎与地面的附着程度。"}, "sentence_index": 0, "correct_answer": "抓地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个新闻很抓地，几分钟就传遍了全城。", "explanation": "这里应该用〈吸引人〉。抓地只指车胎、鞋底与地面紧贴、不打滑，说新闻引人关注要用“吸引人”。"}, {"text": "这次演讲的开场很抓地，台下一下子就安静了。", "explanation": "这里应该用〈精彩〉。抓地只指车胎等与路面紧贴、不打滑，说开场引人入胜要用“精彩”。"}, {"text": "这首歌的旋律很抓地，听一遍就记住了。", "explanation": "这里应该用〈好听〉。抓地只指车胎、鞋底与地面紧贴、不打滑，说旋律动听要用“好听”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca9ddb30-e43a-4c63-956b-9f576adce309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88114, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抓地", "is_correct": true, "explanation": "抓地：气压太低时车胎与地面的贴合变差，正是“不太抓地”的意思。"}, {"text": "鸣笛", "is_correct": false, "explanation": "语义：“鸣笛”是按喇叭，与“气压太低”导致的抓地变差无关。"}, {"text": "加油", "is_correct": false, "explanation": "语义：“加油”指给车补充燃料，与“气压太低”导致的抓地变差无关。"}, {"text": "掉头", "is_correct": false, "explanation": "搭配：“掉头”指车调转方向，不能用来描述车胎的抓地性能。"}], "explanations": {"抓地": "抓地：气压太低时车胎与地面的贴合变差，正是“不太抓地”的意思。", "鸣笛": "语义：“鸣笛”是按喇叭，与“气压太低”导致的抓地变差无关。", "加油": "语义：“加油”指给车补充燃料，与“气压太低”导致的抓地变差无关。", "掉头": "搭配：“掉头”指车调转方向，不能用来描述车胎的抓地性能。"}, "sentence_index": 6, "correct_answer": "抓地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两根木棍互相抓地，冒出了火星。", "explanation": "这里应该用〈摩擦〉。抓地只用于车胎等与路面紧贴、不打滑的情况，两根木棍互相作用要说“摩擦”。"}, {"text": "这盏灯的光很抓地，照得满屋都亮。", "explanation": "这里应该用〈明亮〉。抓地只指车胎、鞋底与地面紧贴、不打滑，说光线亮要用“明亮”。"}, {"text": "这条裤子的拉链很抓地，拉起来很顺。", "explanation": "这里应该用〈顺滑〉。抓地只指车胎、鞋底与地面紧贴、不打滑，说拉链滑动顺畅要用“顺滑”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca9ddb30-e43a-4c63-956b-9f576adce309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88114, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这双登山鞋抓地碎石路很好，走碎石路不滑。", "corrected_sentence": "这双登山鞋抓地很好，走碎石路不滑。", "error_description": "错误：“抓地”是不及物的动词性短语，后面不能直接带处所宾语“碎石路”。正确说法：“这双登山鞋抓地很好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca9ddb30-e43a-4c63-956b-9f576adce309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88114, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这辆老车抓地着很稳，过弯一点儿也不飘。", "corrected_sentence": "这辆老车抓地很稳，过弯一点儿也不飘。", "error_description": "错误：“着”不能放在“抓地”之后，“抓地”后直接接“很稳”。正确说法：“这辆老车抓地很稳”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca9ddb30-e43a-4c63-956b-9f576adce309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
