INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88115, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd21417dd-c9f1-4c61-b777-aa96f07bf1b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88115, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "重又是又一次，再一次。", "primary_collocate": null, "pronunciation": "chóng yòu", "ipa": "ʈʂʰʊŋ˧˥ joʊ˥˩", "syllable_count": 2, "sentences": [{"text": "他看了看信，重又笑了起来。", "target_word": "重又", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨停了，天空重又亮了。", "target_word": "重又", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，树上重又长出了绿叶。", "target_word": "重又", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他沉默了一会儿，重又开口说话。", "target_word": "重又", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她擦干眼泪，重又站了起来。", "target_word": "重又", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐停了，大家重又安静下来。", "target_word": "重又", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病好了以后，他重又回到了学校。", "target_word": "重又", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯灭了一会儿，重又亮了。", "target_word": "重又", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人坐下来，重又讲起了过去的事。", "target_word": "重又", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水退去，村子重又热闹起来。", "target_word": "重又", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "又一次，再一次", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3cfd08e-3d21-43ff-b039-b447ed2d2985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88115, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "重又", "is_correct": true, "explanation": "正确：“重又”表示又一次恢复，前文“看了看信”之后重新笑起来，与之相合。"}, {"text": "从未", "is_correct": false, "explanation": "语义：“从未”表示从来没有，与“笑了起来”表示开始做某事相矛盾。"}, {"text": "总是", "is_correct": false, "explanation": "搭配：“总是”表示习惯，不能与“笑了起来”这种一次性开始的动作搭配。"}, {"text": "从不", "is_correct": false, "explanation": "语法：“从不”表示经常性否定，不能与已发生的“笑了起来”连用。"}], "explanations": {"重又": "正确：“重又”表示又一次恢复，前文“看了看信”之后重新笑起来，与之相合。", "从未": "语义：“从未”表示从来没有，与“笑了起来”表示开始做某事相矛盾。", "总是": "搭配：“总是”表示习惯，不能与“笑了起来”这种一次性开始的动作搭配。", "从不": "语法：“从不”表示经常性否定，不能与已发生的“笑了起来”连用。"}, "sentence_index": 0, "correct_answer": "重又"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这所学校去年才建成，学生们重又在这里上课。", "explanation": "这里应该用〈首次〉。“重又”表示恢复先前的状态，学校去年才建成，没有先前的上课经历，应说“首次在这里上课”。"}, {"text": "他第一次来到这座城市，重又参观了博物馆。", "explanation": "这里应该用〈也〉。“重又”预设此前已有过同样的经历，“第一次来到”说明没有先前经历，应说“也参观了博物馆”或去掉“重又”。"}, {"text": "这个小镇从来没有通电，去年接上电网后，居民们重又用上了电灯。", "explanation": "这里应该用〈首次〉。“重又”表示恢复先前的状态，小镇从来没有通过电，应说“首次用上了电灯”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd21417dd-c9f1-4c61-b777-aa96f07bf1b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88115, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重又", "is_correct": true, "explanation": "正确：“病好了以后”暗示之前中断过，“重又”表示再次回到学校，与之相合。"}, {"text": "一直", "is_correct": false, "explanation": "语义：“一直”表示持续不断，与“病好了以后”暗示的中断相冲突。"}, {"text": "始终", "is_correct": false, "explanation": "语义：“始终”表示从头到尾不变，与“病好了以后”暗示的变化不符。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”多与否定或“过”连用，不能直接接已完成的“回到了学校”。"}], "explanations": {"重又": "正确：“病好了以后”暗示之前中断过，“重又”表示再次回到学校，与之相合。", "一直": "语义：“一直”表示持续不断，与“病好了以后”暗示的中断相冲突。", "始终": "语义：“始终”表示从头到尾不变，与“病好了以后”暗示的变化不符。", "从来": "搭配：“从来”多与否定或“过”连用，不能直接接已完成的“回到了学校”。"}, "sentence_index": 6, "correct_answer": "重又"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一直在写作，重又拿起了笔。", "explanation": "这里应该用〈接着〉。“重又”预设此前中断过，“一直在写作”说明没有中断，此处应说“接着拿起了笔”。"}, {"text": "他从未来过这里，重又走进了这座房子。", "explanation": "这里应该用〈终于〉。“重又”预设此前来过，“从未来过这里”与之矛盾，应说“终于走进了这座房子”。"}, {"text": "这家店刚开张，重又营业了。", "explanation": "这里应该用〈开始〉。“重又”预设此前停过业，这家店刚开张，应说“开始营业了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd21417dd-c9f1-4c61-b777-aa96f07bf1b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88115, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他退休以后，重又再回到了讲台。", "corrected_sentence": "他退休以后，重又回到了讲台。", "error_description": "错误：“重又”与“再”都表示再次，不能叠用。正确应去掉“再”，说“重又回到了讲台”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd21417dd-c9f1-4c61-b777-aa96f07bf1b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88115, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们重又了开始游戏。", "corrected_sentence": "孩子们重又开始游戏。", "error_description": "错误：“了”插在副词“重又”与动词“开始”之间，位置不对。“了”是动态助词，应放在动词之后；本句不需要“了”，应说“孩子们重又开始游戏”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd21417dd-c9f1-4c61-b777-aa96f07bf1b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
