INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88116, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示重新、再一次。", "primary_collocate": null, "pronunciation": "chóng yòu", "ipa": "ʈʂʰʊŋ˧˥ joʊ˥˩", "syllable_count": 2, "sentences": [{"text": "离开三年后，他重又回到了这座城市。", "target_word": "重又", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把杯子洗干净，重又倒满了水。", "target_word": "重又", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争结束了，人们重又过上了平静的生活。", "target_word": "重又", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他失败了，却重又站到了起点。", "target_word": "重又", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳从云后出来，大地重又暖和起来。", "target_word": "重又", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他合上本子，重又陷入了沉思。", "target_word": "重又", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哭了一阵，孩子重又睡着了。", "target_word": "重又", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说完，教室里重又响起了笑声。", "target_word": "重又", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过修理，旧钟重又走了起来。", "target_word": "重又", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风小了，小船重又向前走去。", "target_word": "重又", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "重新、再一次", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3cfd08e-3d21-43ff-b039-b447ed2d2985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88116, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "重又", "is_correct": true, "explanation": "正确：“离开三年后”暗示中断，“重又”表示再次回到这座城市，与之相合。"}, {"text": "向来", "is_correct": false, "explanation": "语义：“向来”表示一贯如此，与“离开三年后”的间隔相冲突。"}, {"text": "立即", "is_correct": false, "explanation": "语义：“立即”表示马上，与“离开三年后”的长时间间隔相矛盾。"}, {"text": "一向", "is_correct": false, "explanation": "搭配：“一向”多接习惯性动词，不宜接“回到这座城市”这种一次性动作。"}], "explanations": {"重又": "正确：“离开三年后”暗示中断，“重又”表示再次回到这座城市，与之相合。", "向来": "语义：“向来”表示一贯如此，与“离开三年后”的间隔相冲突。", "立即": "语义：“立即”表示马上，与“离开三年后”的长时间间隔相矛盾。", "一向": "搭配：“一向”多接习惯性动词，不宜接“回到这座城市”这种一次性动作。"}, "sentence_index": 0, "correct_answer": "重又"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司刚成立，重又开始招聘了。", "explanation": "这里应该用〈就〉。“重又”预设此前招聘过又停止过，公司刚成立没有这个前提，应说“刚成立就开始招聘了”。"}, {"text": "他第一次来到海边，重又看见了大海。", "explanation": "这里应该用〈终于〉。“重又”表示再次看见，此前并未看见过，这是第一次，应说“终于看见了大海”。"}, {"text": "这是我们第一次见面，他重又向我介绍了自己。", "explanation": "这里应该用〈首先〉。“重又”预设此前见过面，这是第一次见面，应说“首先向我介绍了自己”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd21417dd-c9f1-4c61-b777-aa96f07bf1b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88116, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重又", "is_correct": true, "explanation": "正确：“哭了一阵”之后孩子再次入睡，“重又”表示再次恢复睡着的状态，与之相合。"}, {"text": "早已", "is_correct": false, "explanation": "语义：“早已”指很久以前已经，与“哭了一阵”的先后顺序相矛盾。"}, {"text": "从不", "is_correct": false, "explanation": "搭配：“从不”表示从未如此，不能与“睡着了”这一已完成的结果搭配。"}, {"text": "老是", "is_correct": false, "explanation": "语法：“老是”表示经常、反复发生，不能修饰“睡着了”这种一次性的完成结果。"}], "explanations": {"重又": "正确：“哭了一阵”之后孩子再次入睡，“重又”表示再次恢复睡着的状态，与之相合。", "早已": "语义：“早已”指很久以前已经，与“哭了一阵”的先后顺序相矛盾。", "从不": "搭配：“从不”表示从未如此，不能与“睡着了”这一已完成的结果搭配。", "老是": "语法：“老是”表示经常、反复发生，不能修饰“睡着了”这种一次性的完成结果。"}, "sentence_index": 6, "correct_answer": "重又"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小船一刻也没停过，重又向前驶去。", "explanation": "这里应该用〈继续〉。“重又”表示恢复中断的行动，“一刻也没停过”说明没有中断，应说“继续向前驶去”。"}, {"text": "他从未离开过这片海，重又回到了岸边。", "explanation": "这里应该用〈走到〉。“重又回到”预设此前离开过，与“从未离开过”矛盾，应说“走到了岸边”。"}, {"text": "这艘小船是新造的，下水以后，它重又驶向了远方。", "explanation": "这里应该用〈直接〉。“重又”预设此前有过相同的状态，这艘船是新造的，应说“直接驶向了远方”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd21417dd-c9f1-4c61-b777-aa96f07bf1b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88116, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨停以后，孩子们重又笑了下来。", "corrected_sentence": "雨停以后，孩子们重又笑了起来。", "error_description": "错误：表示开始的“笑”后应接“起来”，“下来”不表示开始的笑。正确应说“笑了起来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd21417dd-c9f1-4c61-b777-aa96f07bf1b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88116, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座桥修好后，车辆重又通行着了。", "corrected_sentence": "这座桥修好后，车辆重又通行了。", "error_description": "错误：“着”表示动作进行，与表示完成的“了”叠加，语义不通。正确应只用“了”，说“重又通行了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd21417dd-c9f1-4c61-b777-aa96f07bf1b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
