INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88124, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "云层放电时发出的强烈而短暂的亮光。", "primary_collocate": null, "pronunciation": "shǎn diàn", "ipa": "ʂan˨˩˦ tjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "闪电是云层放电时发出的亮光。", "target_word": "闪电", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "闪电的光很强,但时间很短。", "target_word": "闪电", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "云层放电会产生闪电。", "target_word": "闪电", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨时，我们总是先看到闪电，后听到雷声。", "target_word": "闪电", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里的闪电让整个城市亮了一下。", "target_word": "闪电", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家研究闪电是怎么形成的。", "target_word": "闪电", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机有时会遇到闪电。", "target_word": "闪电", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "闪电的温度比太阳表面还高。", "target_word": "闪电", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "强烈的闪电可能会引起火灾。", "target_word": "闪电", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高楼顶上装着避雷针，可以把闪电引入大地。", "target_word": "闪电", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "道", "label": "量词"}], "register": "中性", "sense_fingerprint": "云层放电发出的强烈短暂亮光", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ca57c2-ac8c-47f7-b168-f786db53d8e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88124, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "彩虹", "is_correct": false, "explanation": "语义：彩虹是雨后的光现象，不是云层放电产生的亮光。"}, {"text": "大地", "is_correct": false, "explanation": "语义：大地是地面，不是云层放电时发出的亮光。"}, {"text": "电话", "is_correct": false, "explanation": "语义：电话是通讯工具，不是自然界中的放电现象。"}, {"text": "闪电", "is_correct": true, "explanation": "正确：闪电是云层放电时发出的强烈亮光，符合定义。"}], "explanations": {"彩虹": "语义：彩虹是雨后的光现象，不是云层放电产生的亮光。", "大地": "语义：大地是地面，不是云层放电时发出的亮光。", "电话": "语义：电话是通讯工具，不是自然界中的放电现象。", "闪电": "正确：闪电是云层放电时发出的强烈亮光，符合定义。"}, "sentence_index": 0, "correct_answer": "闪电"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "闪电在远处轰轰地响。", "explanation": "这里应该用〈雷〉。闪电是光，不会“轰轰地响”，发出响声的是雷声。"}, {"text": "早晨的闪电很温暖。", "explanation": "这里应该用〈阳光〉。闪电是云层放电时一闪而过的亮光，不会带来持续的温暖感，“温暖”描述的是阳光。"}, {"text": "天空中划过一把闪电。", "explanation": "这里应该用〈道〉。“把”用于有柄的东西，闪电的量词是“道”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccc5e7bc-2959-4a75-819f-2881da3639e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88124, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "老鼠", "is_correct": false, "explanation": "语义：老鼠是小动物，飞机不会“遇到”老鼠。"}, {"text": "饼干", "is_correct": false, "explanation": "搭配：“遇到”的对象应是天气、事件等，不能说“遇到饼干”。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是学习用品，飞机不会在飞行中“遇到”书包。"}, {"text": "闪电", "is_correct": true, "explanation": "正确：飞机飞行时有时会遇到闪电等恶劣天气，符合句意。"}], "explanations": {"老鼠": "语义：老鼠是小动物，飞机不会“遇到”老鼠。", "饼干": "搭配：“遇到”的对象应是天气、事件等，不能说“遇到饼干”。", "书包": "语义：书包是学习用品，飞机不会在飞行中“遇到”书包。", "闪电": "正确：飞机飞行时有时会遇到闪电等恶劣天气，符合句意。"}, "sentence_index": 6, "correct_answer": "闪电"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "高楼上空划过一座闪电。", "explanation": "这里应该用〈道〉。“座”用于山、桥、楼房等大型固定的东西，闪电的量词是“道”。"}, {"text": "我看见一副闪电。", "explanation": "这里应该用〈道〉。“副”用于成对的东西，闪电的量词是“道”。"}, {"text": "云层里有一张闪电。", "explanation": "这里应该用〈道〉。“张”用于扁平的东西，不能用于闪电。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccc5e7bc-2959-4a75-819f-2881da3639e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88124, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "远处的天空突然划过一把闪电。", "corrected_sentence": "远处的天空突然划过一道闪电。", "error_description": "量词错误：闪电的量词是“道”，应说“一道闪电”，不能用“把”（“把”用于有柄的东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccc5e7bc-2959-4a75-819f-2881da3639e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88124, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "飞机遇到过一张闪电。", "corrected_sentence": "飞机遇到过一道闪电。", "error_description": "量词错误：闪电的量词是“道”，应说“一道闪电”，不能用“张”（“张”用于扁平的东西）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccc5e7bc-2959-4a75-819f-2881da3639e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
