INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88125, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "镇是比村子大、比城小的一个地方。", "primary_collocate": null, "pronunciation": "zhèn", "ipa": "ʈʂən˥˩", "syllable_count": 1, "sentences": [{"text": "这个镇很小，只有一条路。", "target_word": "镇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家在镇上，不在城里。", "target_word": "镇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "镇里有一所小学和一家医院。", "target_word": "镇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天坐车去镇上上班。", "target_word": "镇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个镇离大城市很远。", "target_word": "镇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "镇的中间有一条河。", "target_word": "镇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们镇有一家很大的菜市场。", "target_word": "镇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个镇的人都很热情。", "target_word": "镇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶住在山下的镇里。", "target_word": "镇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们去镇上买了很多水果。", "target_word": "镇", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "鎮", "label": "繁体"}], "register": "中性", "sense_fingerprint": "镇：比村大、比城小的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cda74fbf-1808-476c-b0e7-6f1b5b85d218') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88125, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "镇", "is_correct": true, "explanation": "镇：比村子大、比城小的地方，这里指小城镇。"}, {"text": "站", "is_correct": false, "explanation": "zhàn（第四声）与 zhèn 韵母不同（an/en），意思是车站。"}, {"text": "真", "is_correct": false, "explanation": "zhēn（第一声）与 zhèn 声调不同，意思是真实。"}, {"text": "枕", "is_correct": false, "explanation": "zhěn（第三声）与 zhèn 声调不同，意思是枕头。"}], "explanations": {"镇": "镇：比村子大、比城小的地方，这里指小城镇。", "站": "zhàn（第四声）与 zhèn 韵母不同（an/en），意思是车站。", "真": "zhēn（第一声）与 zhèn 声调不同，意思是真实。", "枕": "zhěn（第三声）与 zhèn 声调不同，意思是枕头。"}, "sentence_index": null, "correct_answer": "镇"}, "level_3": {"options": [{"text": "镇", "is_correct": true, "explanation": "正确：“这个镇”指一个比村大、比城小的地方，与“很小、只有一条路”相符。"}, {"text": "房间", "is_correct": false, "explanation": "语义：房间里没有路，与“只有一条路”矛盾。"}, {"text": "盒子", "is_correct": false, "explanation": "语义：盒子里不会有路，与“只有一条路”矛盾。"}, {"text": "人", "is_correct": false, "explanation": "配价：“只有一条路”需要地方作主语，“人”不能这样搭配。"}], "explanations": {"镇": "正确：“这个镇”指一个比村大、比城小的地方，与“很小、只有一条路”相符。", "房间": "语义：房间里没有路，与“只有一条路”矛盾。", "盒子": "语义：盒子里不会有路，与“只有一条路”矛盾。", "人": "配价：“只有一条路”需要地方作主语，“人”不能这样搭配。"}, "sentence_index": 0, "correct_answer": "镇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一个大镇的市长。", "explanation": "这里应该用〈城市〉。镇的行政负责人是镇长，“市长”只用于城市，所以“大镇的市长”不成立。"}, {"text": "北京是中国最大的镇之一。", "explanation": "这里应该用〈城市〉。北京是大城市，镇比城市小得多，不能用“镇”指北京。"}, {"text": "上海是一个有两千多万人口的大镇。", "explanation": "这里应该用〈城市〉。上海是大城市，两千多万人口远超镇的规模，“镇”比城市小，不能用来指上海。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d27b6-2776-49a0-9ed9-3975b461f9a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88125, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "镇", "is_correct": true, "explanation": "镇：比村子大、比城小的地方，这里指小城镇。"}, {"text": "战", "is_correct": false, "explanation": "zhàn（第四声）与 zhèn 韵母不同（an/en），意思是战争。"}, {"text": "针", "is_correct": false, "explanation": "zhēn（第一声）与 zhèn 声调不同，意思是针。"}, {"text": "正", "is_correct": false, "explanation": "zhèng（第四声）与 zhèn 韵母不同（eng/en），意思是正确。"}], "explanations": {"镇": "镇：比村子大、比城小的地方，这里指小城镇。", "战": "zhàn（第四声）与 zhèn 韵母不同（an/en），意思是战争。", "针": "zhēn（第一声）与 zhèn 声调不同，意思是针。", "正": "zhèng（第四声）与 zhèn 韵母不同（eng/en），意思是正确。"}, "sentence_index": null, "correct_answer": "镇"}, "level_3": {"options": [{"text": "镇", "is_correct": true, "explanation": "正确：“我们镇”指我们居住的小城镇，可以有菜市场，符合语境。"}, {"text": "班", "is_correct": false, "explanation": "语义：班级里不会有一家菜市场，与“有一家很大的菜市场”矛盾。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包里不会有一家菜市场，与语境矛盾。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“有一家很大的菜市场”需要能容纳市场的地方作主语，“手机”不能这样搭配。"}], "explanations": {"镇": "正确：“我们镇”指我们居住的小城镇，可以有菜市场，符合语境。", "班": "语义：班级里不会有一家菜市场，与“有一家很大的菜市场”矛盾。", "书包": "语义：书包里不会有一家菜市场，与语境矛盾。", "手机": "搭配：“有一家很大的菜市场”需要能容纳市场的地方作主语，“手机”不能这样搭配。"}, "sentence_index": 6, "correct_answer": "镇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个镇的省长很有名。", "explanation": "这里应该用〈省〉。省长负责省级行政区，镇比省小得多，不能用“镇”指这样的地方。"}, {"text": "这个镇有一千万人口。", "explanation": "这里应该用〈城市〉。一千万人口的规模属于城市，镇比城市小，不能用“镇”指这样的地方。"}, {"text": "这个镇的大学有三十所。", "explanation": "这里应该用〈城市〉。三十所大学的规模属于城市，镇比城市小，不能用“镇”指这样的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d27b6-2776-49a0-9ed9-3975b461f9a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUD